import fs from "node:fs";
import path from "node:path";

type RemoteRow = { version: string; name: string };

const remote: RemoteRow[] = JSON.parse(
  fs.readFileSync(path.join(process.cwd(), ".remediation/remote-migrations.json"), "utf8"),
);

const migDir = path.join(process.cwd(), "supabase/migrations");
const localFiles = fs.readdirSync(migDir).filter((f) => /^\d{14}_.+\.sql$/.test(f)).sort();

const localVersions = localFiles
  .map((f) => f.match(/^(\d{14})_/)?.[1])
  .filter((v): v is string => !!v);

const localByVersion = new Map<string, { file: string; name: string }>();
const duplicateLocalVersions: Record<string, string[]> = {};
for (const f of localFiles) {
  const m = f.match(/^(\d{14})_(.+)\.sql$/);
  if (!m) continue;
  const version = m[1]!;
  const entry = { file: f, name: m[2]! };
  if (localByVersion.has(version)) {
    const arr = duplicateLocalVersions[version] ?? [localByVersion.get(version)!.file];
    arr.push(f);
    duplicateLocalVersions[version] = arr;
  }
  localByVersion.set(version, entry);
}

const localVersionSet = new Set(localVersions);
const remoteByVersion = new Map(remote.map((r) => [r.version, r]));

// Versions on remote without a local file (MCP ghosts blocking db push)
const revertVersions = remote
  .map((r) => r.version)
  .filter((v) => !localVersionSet.has(v))
  .sort();

// After reverting ghosts, local versions missing from remote need repair applied
// except true pending (never applied to DB)
const TRUE_PENDING = new Set(["20260704130100"]);

const remoteVersionsAfterRevert = new Set(
  remote.map((r) => r.version).filter((v) => localVersionSet.has(v)),
);

// Name mismatches at same version (anomaly report)
const versionNameMismatch = [...localByVersion.entries()]
  .filter(([v, l]) => {
    const r = remoteByVersion.get(v);
    return r && r.name !== l.name;
  })
  .map(([v, l]) => ({
    version: v,
    local_name: l.name,
    remote_name: remoteByVersion.get(v)!.name,
  }));

// Force-revert same-version wrong remote name (login_resolve at 20260603120000)
const forceRevertSameVersion = versionNameMismatch
  .filter((m) => m.remote_name !== m.local_name)
  .map((m) => m.version);

const revertAll = [...new Set([...revertVersions, ...forceRevertSameVersion])].sort();

// Recompute applied after force reverts
const remoteAfter = new Set(
  remote.map((r) => r.version).filter((v) => !revertAll.includes(v)),
);
const appliedAll = localVersions
  .filter((v) => !remoteAfter.has(v) && !TRUE_PENDING.has(v))
  .sort();

const plan = {
  summary: {
    local_valid: localFiles.length,
    remote_total: remote.length,
    revert_count: revertAll.length,
    applied_repair_count: appliedAll.length,
    true_pending_push: [...TRUE_PENDING],
  },
  kept_local_migrations: localFiles,
  revert_versions: revertAll,
  repair_applied_versions: appliedAll,
  true_pending_push: localFiles.filter((f) => f.startsWith("20260704130100_")),
  version_name_mismatch: versionNameMismatch,
  duplicate_local_timestamps: duplicateLocalVersions,
  recent_local_gte_20260704120000: localFiles.filter((f) => f >= "20260704120000"),
};

fs.writeFileSync(
  path.join(process.cwd(), ".remediation/migration-alignment-plan.json"),
  JSON.stringify(plan, null, 2),
);

console.log(JSON.stringify(plan.summary, null, 2));
console.log("\nREVERT", revertAll.length);
console.log("APPLIED REPAIR", appliedAll.length);
console.log("PENDING PUSH", plan.true_pending_push);

import { cookies } from "next/headers";
import { Geist, Geist_Mono } from "next/font/google";
import { AppProviders } from "@/components/app-providers";
import { getServerSession } from "@/src/lib/auth/get-server-session";
import {
  CAB_THEME_STORAGE_KEY,
  resolveServerThemeMode,
} from "@/lib/theme/cab-theme-storage";
import {
  CAB_APP_BOOT_CRITICAL_STYLE,
  CAB_APP_BOOT_INLINE_SCRIPT,
} from "@/lib/theme/app-boot-inline";
import {
  CAB_THEME_BOOT_INLINE_SCRIPT,
  CAB_THEME_CRITICAL_INLINE_STYLE,
} from "@/lib/theme/theme-boot-inline-script";
import { CAB_BRANDING_BOOT_INLINE_SCRIPT } from "@/lib/theme/branding-boot-inline-script";
import { CAB_CURSOR_AUTOMATION_DOM_SHIELD_INLINE_SCRIPT } from "@/lib/theme/cursor-automation-dom-shield-inline-script";
import { CAB_TURBOPACK_CSS_HMR_RECOVERY_INLINE_SCRIPT } from "@/lib/theme/turbopack-css-hmr-recovery-inline-script";
import { lazyLogBootServer } from "@/lib/observability/boot-investigation-lazy";
import "./globals-core.css";

export { siteMetadata as metadata } from "@/lib/site/site-metadata";
export { siteViewport as viewport } from "@/lib/site/site-viewport";

const geistSans = Geist({
  variable: "--font-geist-sans",
  subsets: ["latin"],
});

const geistMono = Geist_Mono({
  variable: "--font-geist-mono",
  subsets: ["latin"],
});

export default async function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  const initialAuthSnapshot = await getServerSession();
  const cookieStore = await cookies();
  const serverTheme = resolveServerThemeMode(cookieStore.get(CAB_THEME_STORAGE_KEY)?.value);

  lazyLogBootServer("BOOT", "rsc_root_layout", {
    hasUser: Boolean(initialAuthSnapshot?.user?.id),
    userId: initialAuthSnapshot?.user?.id ?? null,
    sessionExpiresAt: initialAuthSnapshot?.session?.expiresAt ?? null,
    configurationError: initialAuthSnapshot?.configurationError ?? null,
  });

  return (
    <html
      lang="it"
      suppressHydrationWarning
      className={`${geistSans.variable} ${geistMono.variable} h-full min-h-[var(--cab-app-height,100dvh)] w-full min-w-0 max-w-full bg-[var(--cab-bg-app)] antialiased${serverTheme === "dark" ? " dark" : ""}`}
      style={{ colorScheme: serverTheme }}
    >
      <head suppressHydrationWarning>
        <style
          id="cab-theme-critical"
          dangerouslySetInnerHTML={{ __html: CAB_THEME_CRITICAL_INLINE_STYLE }}
        />
        <style
          id="cab-app-boot-critical"
          dangerouslySetInnerHTML={{ __html: CAB_APP_BOOT_CRITICAL_STYLE }}
        />
        <script
          id="cab-theme-boot"
          suppressHydrationWarning
          dangerouslySetInnerHTML={{ __html: CAB_THEME_BOOT_INLINE_SCRIPT }}
        />
        <script
          id="cab-branding-boot"
          suppressHydrationWarning
          dangerouslySetInnerHTML={{ __html: CAB_BRANDING_BOOT_INLINE_SCRIPT }}
        />
        <script
          id="cab-app-boot"
          suppressHydrationWarning
          dangerouslySetInnerHTML={{ __html: CAB_APP_BOOT_INLINE_SCRIPT }}
        />
        {process.env.NODE_ENV === "development" ? (
          <>
            <script
              id="cab-turbopack-css-hmr-recovery"
              suppressHydrationWarning
              dangerouslySetInnerHTML={{ __html: CAB_TURBOPACK_CSS_HMR_RECOVERY_INLINE_SCRIPT }}
            />
            <script
              id="cab-cursor-automation-dom-shield"
              suppressHydrationWarning
              dangerouslySetInnerHTML={{ __html: CAB_CURSOR_AUTOMATION_DOM_SHIELD_INLINE_SCRIPT }}
            />
          </>
        ) : null}
      </head>
      <body
        suppressHydrationWarning
        className="gestionale-scrollbar flex h-[var(--cab-app-height,100dvh)] min-h-[var(--cab-app-height,100dvh)] w-full min-w-0 max-w-full flex-col overflow-x-hidden bg-[var(--cab-bg-app)] font-sans antialiased"
      >
        <div
          id="cab-app-boot"
          role="status"
          aria-live="polite"
          aria-busy="true"
          suppressHydrationWarning
        >
          {/* ponytail: src statico pre-React — logo senza next/image per primo paint immediato */}
          <img src="/cab-logo.png" alt="C.A.B." width={196} height={56} />
          <div className="cab-app-boot-spinner" aria-hidden="true" />
          <p id="cab-app-boot-msg" suppressHydrationWarning>
            Avvio del gestionale...
          </p>
        </div>
        <AppProviders initialAuthSnapshot={initialAuthSnapshot}>{children}</AppProviders>
      </body>
    </html>
  );
}

