              <SettingsNavSidebar
                section={section}
                onPickSection={pickSection}
                variant="page"
              />
            </aside>
          ) : (
          <aside
            className={
              `${desktopNavOpen ? "md:flex" : "md:hidden"} hidden w-[15rem] shrink-0 flex-col border-[color:var(--cab-border)] bg-[var(--cab-card)] border-r lg:w-[16rem]`
