"use client";

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { useAuth } from "@/context/auth-context";
import { buildGestionaleNav, type GestionaleNavResolvedItem } from "@/components/gestionale/gestionale-nav-config";
import { defaultHomePathForRole, resolveFirstAccessiblePageHrefFromResolved } from "@/lib/auth/rbac";
import { useRbac } from "@/src/hooks/use-rbac";
import { useRbacNavAccess } from "@/src/hooks/use-rbac-nav-access";
import { ProfileSheetProvider } from "@/components/profile/profile-sheet-context";
import { useGestionaleShellLayoutSync } from "@/lib/ui/use-gestionale-shell-layout-sync";
import { useGestionaleShellContentWidth } from "@/lib/ui/use-gestionale-shell-content-width";
import { GestionaleShellTierProvider } from "@/context/gestionale-shell-layout-context";
import { MobileNavShellProvider } from "@/context/mobile-nav-shell-context";
import { AppShellSidebar } from "@/components/gestionale/app-shell-sidebar";
import { AppShellMain } from "@/components/gestionale/app-shell-main";
import { isNavTargetCurrent } from "@/src/lib/navigation/route-transition";
import { useGestionaleScrollEnd } from "@/lib/ui/use-gestionale-scroll-end";
import { healBodyScrollLockState } from "@/lib/ui/body-scroll-lock-manager";
import { cabAppViewportFillClass, syncAppViewportFill } from "@/lib/ui/viewport-fill-sync";
import { isGestionaleOverlayActive, useSidebarHoverExpand } from "@/lib/ui/use-sidebar-collapsed";
import { useBootInvestigationMount } from "@/lib/observability/use-boot-investigation-mount";
import { useNavDrawerGesture } from "@/lib/ui/use-nav-drawer-gesture";
import { deriveMainInert, useNavDrawerMachine } from "@/lib/ui/mobile-nav-drawer-machine";
import { useNavigationBootInstrumentation } from "@/lib/observability/use-navigation-boot-instrumentation";
import { subscribeGestionaleViewport } from "@/lib/ui/gestionale-viewport-orchestrator";
import { ListSurfaceCookieSync } from "@/lib/ui/list-surface-cookie-sync";
import { useLastRouteRestore } from "@/src/hooks/use-last-route-restore";

export function AppShell({ children }: { children: React.ReactNode }) {
  useBootInvestigationMount("AppShell");
  const edgeDragAtRef = useRef(0);
  const drawer = useNavDrawerMachine(edgeDragAtRef);
  const { flags, open, forceClose, onPointerCancel, onVisibilityHidden, onResize } = drawer;
  const [overlayActive, setOverlayActive] = useState(false);
  const [edgeSnapVisuallyClosed, setEdgeSnapVisuallyClosed] = useState(false);
  const [dismissVisuallyClosed, setDismissVisuallyClosed] = useState(false);
  const shellRef = useRef<HTMLDivElement>(null);
  const sidebarAsideRef = useRef<HTMLElement>(null);
  const shellColRef = useRef<HTMLDivElement>(null);
  const mainScrollRef = useRef<HTMLElement | null>(null);
  const shellTier = useGestionaleShellLayoutSync({
    shellRef,
    shellColRef,
    mainRef: mainScrollRef,
  });
  const shellContentWidth = useGestionaleShellContentWidth();
  const { isCompactShell, tier } = shellTier;
  const showMobileNavOpen = isCompactShell && shellContentWidth > 0;
  useNavigationBootInstrumentation(showMobileNavOpen);
  useGestionaleScrollEnd(mainScrollRef);
  const {
    collapsed,
    sidebarExpanded,
    collapseSidebar,
    onSidebarMouseEnter,
    onSidebarMouseLeave,
    onSidebarNavIntent,
    onSidebarFocusCapture,
    onSidebarBlurCapture,
  } = useSidebarHoverExpand();
  const routeTransitionStartRef = useRef<number | null>(null);
  const routePathnameRef = useRef("");
  const { user } = useAuth();
  const rbac = useRbac();
  const { navAccess, snapshot, isNavLoading } = useRbacNavAccess();
  const homePath = useMemo(() => {
    if (snapshot?.resolved) {
      return resolveFirstAccessiblePageHrefFromResolved(snapshot.resolved);
    }
    return defaultHomePathForRole(user, { rolePageAccess: rbac.effectivePermissions?.rolePageAccess });
  }, [snapshot?.resolved, user, rbac.effectivePermissions?.rolePageAccess]);

  useLastRouteRestore({
    userId: user?.id,
    navAccess,
    snapshot,
    isNavLoading,
    homePath,
  });

  useLayoutEffect(() => {
    healBodyScrollLockState("app-shell-mount");
    syncAppViewportFill();
  }, []);

  useEffect(() => {
    const sync = () => setOverlayActive(isGestionaleOverlayActive());
    sync();
    window.addEventListener("cab:gestionale-overlay-opened", sync);
    window.addEventListener("cab:gestionale-overlay-closed", sync);
    return () => {
      window.removeEventListener("cab:gestionale-overlay-opened", sync);
      window.removeEventListener("cab:gestionale-overlay-closed", sync);
    };
  }, []);

  const navGesture = useNavDrawerGesture({
    enabled: isCompactShell && (flags.canEdgeSwipe || flags.canDismiss) && !overlayActive,
    drawerState: flags.state,
    drawerMounted: flags.mounted,
    overlayActive,
    canEdgeSwipe: flags.canEdgeSwipe,
    canDismiss: flags.canDismiss,
    onEdgeDragStart: () => {
      edgeDragAtRef.current = Date.now();
      drawer.dispatch("EDGE_DRAG_START");
    },
    onEdgeDragCommit: () => drawer.dispatch("EDGE_DRAG_END_COMMIT"),
    onEdgeDragCancel: () => drawer.dispatch("EDGE_DRAG_END_CANCEL"),
    onEdgeSnapClosed: () => setEdgeSnapVisuallyClosed(true),
    onDismissDragStart: () => drawer.dispatch("DISMISS_DRAG_START"),
    onDismissDragCommit: () => {
      setDismissVisuallyClosed(true);
      drawer.dispatch("DISMISS_DRAG_END_COMMIT");
    },
    onDismissDragCancel: () => drawer.dispatch("DISMISS_DRAG_END_CANCEL"),
    onPointerCancel,
    onDragProgress: () => {
      edgeDragAtRef.current = Date.now();
    },
  });

  useEffect(() => {
    if (!isCompactShell) forceClose();
  }, [forceClose, isCompactShell]);

  useEffect(() => {
    function onVisibility() {
      if (document.hidden) onVisibilityHidden();
    }
    document.addEventListener("visibilitychange", onVisibility);
    return () => document.removeEventListener("visibilitychange", onVisibility);
  }, [onVisibilityHidden]);

  useEffect(() => {
    if (!isCompactShell) return;
    return subscribeGestionaleViewport(() => {
      onResize();
    });
  }, [isCompactShell, onResize]);

  const navItems = useMemo(() => {
    if (!navAccess || !snapshot?.resolved) return [] as GestionaleNavResolvedItem[];
    return buildGestionaleNav(snapshot.resolved, {
      hidePageKey: (pageKey) => navAccess.shouldHidePageKey(pageKey),
    });
  }, [navAccess, snapshot?.resolved]);

  const beginRouteTransition = useCallback(
    (href: string) => {
      if (isNavTargetCurrent(routePathnameRef.current, href)) {
        return;
      }
      collapseSidebar();
      routeTransitionStartRef.current = performance.now();
    },
    [collapseSidebar],
  );

  return (
    <GestionaleShellTierProvider value={shellTier}>
    <ProfileSheetProvider>
    <MobileNavShellProvider
      openMobileNav={open}
      isNavDrawerOpen={flags.navDrawerVisible}
    >
    <div
      ref={shellRef}
      data-mobile-nav-visible={showMobileNavOpen ? "" : undefined}
      className={`cab-app-shell flex min-h-0 flex-col ${cabAppViewportFillClass} max-w-full overflow-hidden bg-[var(--cab-bg-app)] text-[color:var(--cab-text)]`}
    >
      <ListSurfaceCookieSync />
      <AppShellSidebar
        homePath={homePath}
        navItems={navItems}
        isNavLoading={isNavLoading}
        isCompactShell={isCompactShell}
        collapsed={collapsed}
        sidebarExpanded={sidebarExpanded}
        asideRef={sidebarAsideRef}
        onSidebarMouseEnter={onSidebarMouseEnter}
        onSidebarMouseLeave={onSidebarMouseLeave}
        onSidebarFocusCapture={onSidebarFocusCapture}
        onSidebarBlurCapture={onSidebarBlurCapture}
        onSidebarNavIntent={onSidebarNavIntent}
        collapseSidebar={collapseSidebar}
        beginRouteTransition={beginRouteTransition}
        routeTransitionStartRef={routeTransitionStartRef}
        routePathnameRef={routePathnameRef}
        drawer={drawer}
        navGesturePanelProps={navGesture.panelProps}
        navGestureBackdropProps={navGesture.backdropProps}
        navGesturePanelRef={navGesture.panelRef}
        navGestureBackdropRef={navGesture.backdropRef}
        edgeSnapVisuallyClosed={edgeSnapVisuallyClosed}
        dismissVisuallyClosed={dismissVisuallyClosed}
        onEdgeSnapConsumed={() => setEdgeSnapVisuallyClosed(false)}
        onDismissSnapConsumed={() => setDismissVisuallyClosed(false)}
        navGestureResetDrag={navGesture.resetDrag}
      />

      <AppShellMain
        shellColRef={shellColRef}
        mainScrollRef={mainScrollRef}
        isCompactShell={isCompactShell}
        shellTier={tier}
        mainInert={deriveMainInert(flags.state)}
      >
        {children}
      </AppShellMain>
    </div>
    </MobileNavShellProvider>
    </ProfileSheetProvider>
    </GestionaleShellTierProvider>
  );
}

"use client";

import { useMemo } from "react";
import { buildMonthDays, formatMonthLabel } from "@/lib/dipendenti/timesheet-month";
import { computeMonthTotals, entryToCellValue } from "@/lib/dipendenti/timesheet-totals";
import type { TipoAssenzaConfig } from "@/lib/dipendenti/tipi-assenza-model";
import type {
  DipendenteTimesheetEmployeeRow,
  DipendenteTimesheetEntryRow,
  TimesheetMonthKey,
} from "@/lib/dipendenti/types";
import { GestionaleModalScrollBody } from "@/components/gestionale/mobile-modal-scroll-body";
import { GestionaleModalShell } from "@/components/gestionale/gestionale-modal";
import { erpBtnAccent, erpBtnNeutral } from "@/components/report/report-buttons";
import { GlobalTableHead } from "@/components/gestionale/global-table";
import { gestionaleListTableTd } from "@/lib/ui/gestionale-list-table";

export function DipendenteDetailModal({
  open,
  onClose,
  employee,
  monthKey,
  entries,
  tipiAssenza: _tipiAssenza,
}: {
  open: boolean;
  onClose: () => void;
  employee: DipendenteTimesheetEmployeeRow | null;
  monthKey: TimesheetMonthKey;
  entries: readonly DipendenteTimesheetEntryRow[];
  tipiAssenza: readonly TipoAssenzaConfig[];
}) {
  const days = useMemo(() => buildMonthDays(monthKey), [monthKey]);
  const empEntries = useMemo(
    () => (employee ? entries.filter((e) => e.dipendente_id === employee.id) : []),
    [employee, entries],
  );
  const totals = useMemo(() => computeMonthTotals(empEntries), [empEntries]);

  if (!open || !employee) return null;

  return (
    <GestionaleModalShell
      modalSize="info"
      onRequestClose={onClose}
      title={employee.display_name}
      subtitle={formatMonthLabel(monthKey)}
    >
      <GestionaleModalScrollBody className="py-3">
        <div className="mb-4 grid grid-cols-2 gap-2 text-center sm:grid-cols-4">
          <div className="rounded-lg border border-[color:var(--cab-border)] bg-[var(--cab-surface)] p-2">
            <p className="text-[10px] uppercase text-[color:var(--cab-text-muted)]">Ordinarie</p>
            <p className="text-lg font-semibold tabular-nums">{totals.oreOrdinarie} h</p>
          </div>
          <div className="rounded-lg border border-[color:var(--cab-border)] bg-[var(--cab-surface)] p-2">
            <p className="text-[10px] uppercase text-[color:var(--cab-text-muted)]">Straordinarie</p>
            <p className="text-lg font-semibold tabular-nums">{totals.oreStraordinarie} h</p>
          </div>
          <div className="rounded-lg border border-[color:var(--cab-border)] bg-[var(--cab-surface)] p-2">
            <p className="text-[10px] uppercase text-[color:var(--cab-text-muted)]">Assenze</p>
            <p className="text-lg font-semibold tabular-nums">{totals.oreAssenza} h</p>
          </div>
          <div className="rounded-lg border border-[color:var(--cab-border)] bg-[var(--cab-surface)] p-2">
            <p className="text-[10px] uppercase text-[color:var(--cab-text-muted)]">Lavorato</p>
            <p className="text-lg font-semibold tabular-nums">{totals.totaleLavorato} h</p>
          </div>
        </div>
        <table className="w-full text-xs">
          <GlobalTableHead>
            <tr className="border-b border-[color:var(--cab-border)] text-left text-[color:var(--cab-text-muted)]">
              <th className="py-1.5 pr-2">Giorno</th>
              <th className="py-1.5 px-1 text-center">Ord.</th>
              <th className="py-1.5 px-1 text-center">Str.</th>
              <th className="py-1.5 px-1 text-center">Ass.</th>
              <th className="py-1.5 pl-2">Tipo / Note</th>
            </tr>
          </GlobalTableHead>
          <tbody>
            {days.map((d) => {
              const cell = entryToCellValue(empEntries.find((e) => e.work_date === d.dateYmd));
              const hasData = cell.oreOrdinarie > 0 || cell.oreStraordinarie > 0 || cell.oreAssenza > 0;
              return (
                <tr key={d.dateYmd} className="border-b border-[color:color-mix(in_srgb,var(--cab-border)_60%,transparent)]">
                  <td className={gestionaleListTableTd}>
                    {String(d.day).padStart(2, "0")} {d.weekdayShort}
                  </td>
                  <td className={`${gestionaleListTableTd} text-center tabular-nums`}>{cell.oreOrdinarie || "—"}</td>
                  <td className={`${gestionaleListTableTd} text-center tabular-nums`}>{cell.oreStraordinarie || "—"}</td>
                  <td className={`${gestionaleListTableTd} text-center tabular-nums`}>{cell.oreAssenza || "—"}</td>
                  <td className={gestionaleListTableTd}>
                    {hasData
                      ? [cell.tipoAssenzaLabel, cell.motivoCustom, cell.note].filter(Boolean).join(" · ") || "—"
                      : "—"}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </GestionaleModalScrollBody>
      <div className="flex shrink-0 min-w-0 justify-end gap-2 border-t border-[color:var(--cab-border)] px-4 py-3 sm:px-5">
        <button type="button" className={erpBtnNeutral} onClick={onClose}>
          Chiudi
        </button>
        <button type="button" className={erpBtnAccent} onClick={onClose}>
          OK
        </button>
      </div>
    </GestionaleModalShell>
  );
}

"use client";

import { Tooltip } from "@/components/ui";
import { useMemo } from "react";
import { DipendentiEmptyState, DipendentiQueryErrorBanner } from "@/components/gestionale/dipendenti/dipendenti-empty-state";
import { formatMonthLabel } from "@/lib/dipendenti/timesheet-month";
import type { DipendenteTimesheetEmployeeRow, TimesheetMonthKey } from "@/lib/dipendenti/types";
import { GlobalTableHead, GlobalTableHeadLabel } from "@/components/gestionale/global-table";
import { gestionaleListTableClass, gestionaleListTableTd } from "@/lib/ui/gestionale-list-table";
import { useDipendenteAnnualHistory } from "@/src/hooks/use-dipendente-annual-history";

export function DipendentiStoricoSection({
  monthKey,
  employees,
  filterEmployeeId,
  hasAddetti,
  onOpenDetail,
}: {
  monthKey: TimesheetMonthKey;
  employees: readonly DipendenteTimesheetEmployeeRow[];
  filterEmployeeId: string;
  hasAddetti: boolean;
  onOpenDetail: (employee: DipendenteTimesheetEmployeeRow) => void;
}) {
  const employee = useMemo(
    () => (filterEmployeeId ? employees.find((e) => e.id === filterEmployeeId) ?? null : null),
    [employees, filterEmployeeId],
  );

  const { year, months, yearTotals, isLoading, isError, errorMessage, refetch } = useDipendenteAnnualHistory(
    employee?.id ?? null,
    monthKey,
  );

  const maxLavorato = useMemo(() => Math.max(1, ...months.map((m) => m.totaleLavorato)), [months]);

  if (!hasAddetti) {
    return <DipendentiEmptyState variant="no-addetti" />;
  }

  if (employees.length === 0) {
    return <DipendentiEmptyState variant="no-employees" readOnly />;
  }

  if (!employee) {
    return <DipendentiEmptyState variant="select-employee" />;
  }

  if (isError) {
    return (
      <DipendentiQueryErrorBanner
        title="Impossibile caricare lo storico annuale"
        message={errorMessage ?? "Errore durante il caricamento dei dati."}
        onRetry={() => refetch()}
      />
    );
  }

  if (isLoading) {
    return <p className="text-sm text-[color:var(--cab-text-muted)]">Caricamento storico {year}…</p>;
  }

  return (
    <div className="space-y-4">
      <div className="flex min-w-0 items-center justify-between gap-2 flex-nowrap sm:flex-wrap">
        <p className="text-sm text-[color:var(--cab-text)]">
          <strong>{employee.display_name}</strong> — riepilogo anno {year}
        </p>
        <button
          type="button"
          className="text-xs font-medium text-[color:var(--cab-primary)] hover:underline"
          onClick={() => onOpenDetail(employee)}
        >
          Dettaglio mese corrente
        </button>
      </div>

      <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
        <StatChip label="Ordinarie" value={`${yearTotals.oreOrdinarie} h`} />
        <StatChip label="Straordinarie" value={`${yearTotals.oreStraordinarie} h`} />
        <StatChip label="Assenze" value={`${yearTotals.oreAssenza} h`} />
        <StatChip label="Giorni assenza" value={String(yearTotals.giorniAssenza)} unit="" />
      </div>

      <div className="space-y-1">
        <p className="text-[10px] font-semibold uppercase tracking-wide text-[color:var(--cab-text-muted)]">
          Andamento ore lavorate ({year})
        </p>
        <div className="flex min-w-0 h-24 items-end gap-1 rounded-[var(--ds-radius-lg)] border border-[color:var(--cab-border)] bg-[var(--cab-surface)] px-2 py-2">
          {months.map((m) => {
            const h = m.totaleLavorato > 0 ? Math.max(8, (m.totaleLavorato / maxLavorato) * 100) : 4;
            return (
              <Tooltip content={`${m.monthLabel}: ${m.totaleLavorato} h`}><div key={m.monthKey} className="flex min-w-0 flex-1 flex-col items-center gap-1">
                <div className="w-full rounded-t bg-[color:var(--cab-primary)] opacity-80" style={{ height: `${h}%` }}/>
                <span className="text-[9px] tabular-nums text-[color:var(--cab-text-muted)]">
                  {String(m.month).padStart(2, "0")}
                </span>
              </div></Tooltip>
            );
          })}
        </div>
      </div>

      <div className="overflow-x-auto">
        <table className={gestionaleListTableClass}>
          <GlobalTableHead>
              <GlobalTableHeadLabel label="Mese" />
              <GlobalTableHeadLabel label="Ord." align="center" />
              <GlobalTableHeadLabel label="Str." align="center" />
              <GlobalTableHeadLabel label="Ass." align="center" />
              <GlobalTableHeadLabel label="Lavorato" align="center" />
          </GlobalTableHead>
          <tbody>
            {months.map((m) => (
              <tr key={m.monthKey} className="border-b border-[color:var(--cab-border)]">
                <td className={gestionaleListTableTd}>{formatMonthLabel(m.monthKey)}</td>
                <td className={`${gestionaleListTableTd} text-center tabular-nums`}>{m.oreOrdinarie || "—"}</td>
                <td className={`${gestionaleListTableTd} text-center tabular-nums`}>{m.oreStraordinarie || "—"}</td>
                <td className={`${gestionaleListTableTd} text-center tabular-nums`}>{m.oreAssenza || "—"}</td>
                <td className={`${gestionaleListTableTd} text-center font-semibold tabular-nums`}>
                  {m.totaleLavorato || "—"}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function StatChip({ label, value, unit = "h" }: { label: string; value: string; unit?: string }) {
  return (
    <div className="rounded-[var(--ds-radius-lg)] border border-[color:var(--cab-border)] bg-[var(--cab-surface)] p-2 text-center">
      <p className="text-[10px] uppercase text-[color:var(--cab-text-muted)]">{label}</p>
      <p className="text-lg font-semibold tabular-nums text-[color:var(--cab-text)]">
        {value}
        {unit ? <span className="ml-0.5 text-xs font-normal text-[color:var(--cab-text-muted)]">{unit}</span> : null}
      </p>
    </div>
  );
}

