export function cycleLavorazioniTableSort<T extends string>(
  curCol: T | null,
  setCol: (c: T | null) => void,
  setPhase: Dispatch<SetStateAction<"asc" | "desc" | "natural">>,
  k: T,
) {
  if (curCol !== k) {
    setCol(k);
    setPhase(() => "asc");
    return;
  }
  setPhase((prev) => {
    if (prev === "asc") return "desc";
    if (prev === "desc") {
      setCol(null);
      return "natural";
    }
    return "asc";
  });
}

