export function LavorazioniMezzoIdentStack({
  targa,
  matricola,
  nScuderia,
}: {
  targa: string;
  matricola: string;
  nScuderia?: string;
}) {
  const norm = (value: string) => {
    const t = value.trim();
    return t && t !== "—" ? t : "";
