            scoreSearchDocumentWithPrepared(
              preparedSearch,
              lavHaystackForRow(row, lavHaystackIndex, schedeStore),
            ).score,
          )
        : null;
    rows.sort((a, b) => {
      if (scoreMap) {
        const rel = compareSearchRelevanceWithScoreMap(a, b, scoreMap);
        if (rel !== 0) return rel;
      }
      if (sortPhaseA === "natural" || sortColA === null) {
        // Ordine naturale: piò vecchia in alto, nuova in fondo.
        const ta = new Date(a.data_ingresso ?? a.created_at).getTime();
        const tb = new Date(b.data_ingresso ?? b.created_at).getTime();
        if (ta !== tb) return ta - tb;
        return a.id.localeCompare(b.id);
      }
      const p = cmpAtt(a, b, sortColA, sortPhaseA, schedeSortIndex, statoOrderIds);
      if (p !== 0) return p;
      const ta = new Date(a.data_ingresso ?? a.created_at).getTime();
      const tb = new Date(b.data_ingresso ?? b.created_at).getTime();
      if (ta !== tb) return ta - tb;
      return a.id.localeCompare(b.id);
    });
    return rows;
  }, [attiveRowsFiltered, sortColA, sortPhaseA, schedeSortIndex, statoOrderIds, searchApplied, schedeStore, lavHaystackIndex, preparedSearch]);

