      if (sortPhaseC === "natural" || sortColC === null) {
        const ta = new Date(dataCompletamentoIso(a)).getTime();
        const tb = new Date(dataCompletamentoIso(b)).getTime();
        if (tb !== ta) return tb - ta;
        return b.id.localeCompare(a.id);
