                      <p className="break-all font-mono text-xs font-medium tabular-nums tracking-wide text-zinc-500 dark:text-zinc-400">
                        {p.codiceFornitoreOriginaleSecondario}
                      </p>
                    ) : null}
                    {compatModels ? (
                      <p className="line-clamp-2 text-xs leading-snug text-zinc-500 dark:text-zinc-400">
                        {compatModels}
                      </p>
                    ) : null}
                  </div>
                  <div className="flex shrink-0 flex-col items-center gap-1">
                    <MagazzinoScortaDisplayBadge
                      ricambioId={p.id}
                      ricambioLabel={p.descrizione}
                      fallbackScorta={p.scorta}
                      low={low}
                      variant="mobile"
                    />
                    <MagazzinoScortaBadge value={p.scortaMinima} kind="minima" variant="mobile" />
                  </div>
                </div>
                <dl className="mt-2 grid grid-cols-3 gap-x-2 gap-y-1.5 text-[11px]">
                  <div className="min-w-0">
                    <dt className="text-zinc-500 dark:text-zinc-400">Categoria</dt>
                    <dd className="truncate font-medium text-zinc-900 dark:text-zinc-100">{p.categoria}</dd>
                  </div>
                  <div className="min-w-0">
                    <dt className="text-zinc-500 dark:text-zinc-400">P. vendita</dt>
                    <dd className="truncate font-medium tabular-nums text-zinc-900 dark:text-zinc-100">{eur(p.prezzoVendita)}</dd>
                  </div>
                  <div className="min-w-0">
                    <dt className="text-zinc-500 dark:text-zinc-400">Consumo medio</dt>
                    <dd className="font-medium tabular-nums text-zinc-700 dark:text-zinc-300">
                      <span className="inline-block max-w-full truncate">
                        {avgM != null ? formatAvgMonthlyMagazzinoIt(avgM) : "—"}
                      </span>
                    </dd>
                  </div>
                </dl>
                <div className="mt-auto flex w-full min-w-0 shrink-0 items-end justify-between gap-2 border-t border-zinc-200/90 pt-2.5 dark:border-zinc-700/80">
                  <div
                    className={`min-w-0 flex-1 text-xs font-medium text-[color:var(--cab-text-muted)] ${
                      staleModifica
                        ? "rounded-md bg-amber-50/95 px-1.5 py-0.5 ring-1 ring-amber-200/80 dark:bg-amber-950/35 dark:ring-amber-800/55"
                        : ""
                    }`}
                  >
                    <div className="flex min-w-0 items-center gap-1">
                      {staleModifica ? (
                        <span
                          className="shrink-0 text-[11px] leading-none text-amber-700 dark:text-amber-300"
                          aria-hidden
                        >
                          ÔÜá
                        </span>
                      ) : null}
                      <p className="truncate tabular-nums leading-tight">
                        {formatMagazzinoUltimaModificaMobileDate(p.dataUltimaModifica)}
                      </p>
                    </div>
                    <p className="truncate leading-tight">
                      {formatMagazzinoUltimaModificaMobileAutore(p.autoreUltimaModifica)}
                    </p>
                  </div>
                  <div
                    className={`${gestionaleListTableActionsGroupEnd} shrink-0 flex-nowrap`}
                    role="group"
                    aria-label="Azioni"
                  >
                  <IconActionButton
                    label="Info"
                    tooltipForce
                    tooltipContent="Apri scheda ricambio"
                    className={dsTableActionBtnInfo}
                    onClick={() => openInfo(p)}
                  >
                    <IconInfoMagazzino />
                  </IconActionButton>
                  <MagazzinoScortaAdjustActionsCell
                    ricambioId={p.id}
                    ricambioLabel={p.descrizione}
                    fallbackScorta={p.scorta}
                    canAdjust={magCanCreateRicambio}
                    modalitaModifica={modalitaModifica}
                  />
                  </div>
                </div>
              </CardMobile>
            );
          })}
        </div>
        )}
        {showPager ? (
          <TablePagination page={page} pageCount={pageCount} onPageChange={setPage} label={label} />
        ) : null}
        </MagazzinoTableSection>
        </SkeletonBoundary>
      </ShellCard>

      {newOpen && modalChunkMountedKey !== "new" ? (
        <GestionaleModalShell
          modalSize="formMedium"
          title="Nuovo ricambio"
          titleId="new-ricambio-title"
          onRequestClose={closeNewRicambioModal}
        >
          <LoadingFormSkeleton sections={3} />
        </GestionaleModalShell>
      ) : null}

      {newOpen ? (
        <RicambioNewModal
          marche={marche}
          categorie={categorie}
          fornitori={fornitoriGlobal}
          produttori={produttoriGlobal}
          mezziListePrefs={mezziListePrefs}
          authorName={authorName}
          prodotti={prodotti}
          magCanCreateRicambio={magCanCreateRicambio}
          onClose={closeNewRicambioModal}
          onMounted={() => setModalChunkMountedKey("new")}
          onSaveError={(message) => toastError(message, { module: "magazzino", action: "create" })}
          onVaiAlRicambioDuplicato={(id) => focusRicambioInTable(id)}
          onSaved={(ui) => {
            registerOrderIndex(ui.id);
            patchProdotti((prev) => [ui, ...prev]);
            completeMagazzinoSave(ui.id, "Ricambio creato in magazzino.", "entity_created");
          }}
        />
      ) : null}

      {detail && detailRicambio && detail.mode === "info" && modalChunkMountedKey !== `${detail.id}-info` ? (
        <GestionaleModalShell
          modalSize="info"
          modalHeight="standard"
          title="Scheda ricambio"
          titleId="detail-ricambio-title"
          onRequestClose={closeDetail}
        >
          <LoadingFormSkeleton sections={3} />
        </GestionaleModalShell>
      ) : null}

      {detail && detailRicambio && detail.mode === "info" ? (
        <MagazzinoRicambioInfoModal
          ricambio={detailRicambio}
          compatDisplay={compatDisplayFor(detailRicambio)}
          consumo={consumoMap.get(detailRicambio.id)}
          formatEur={eur}
          magCanCreateRicambio={magCanCreateRicambio}
          magCanReadRicambio={magPerm.canRead}
          logTimeline={infoTimeline}
          logLoading={magLogFeedLoading}
          onClose={closeDetail}
          onMounted={() => setModalChunkMountedKey(`${detail.id}-info`)}
          onEdit={startEditFromInfo}
          onImageEvent={(ev) => logImageEvent(ev, detailRicambio)}
          onDismissLogEntry={removeMagazzinoLogEntry}
          canAdjustScorta={magCanCreateRicambio}
          modalitaModifica={modalitaModifica}
          scortaFlash={flashRowId === detailRicambio.id}
          stockPolicyRaw={stockPolicyRaw}
          onUndoStockMovement={undoStockMovement}
          undoStockPending={undoStockPending}
        />
      ) : null}

      {detail && detailRicambio && detail.mode === "edit" && modalChunkMountedKey !== `${detail.id}-edit` ? (
        <GestionaleModalShell
          modalSize="formMedium"
          title="Modifica ricambio"
          onRequestClose={closeDetail}
        >
          <LoadingFormSkeleton sections={3} />
        </GestionaleModalShell>
      ) : null}

      {detail && detailRicambio && detail.mode === "edit" ? (
        <RicambioEditModal
          ricambioId={detail.id}
          ricambio={detailRicambio}
          mezziListePrefs={mezziListePrefs}
          marche={marche}
          categorie={categorie}
          fornitori={fornitoriGlobal}
          produttori={produttoriGlobal}
          authorName={authorName}
          onMounted={() => setModalChunkMountedKey(`${detail.id}-edit`)}
          magCanCreateRicambio={magCanCreateRicambio}
          magCanDeleteRicambio={magCanDeleteRicambio}
          onClose={closeDetail}
          onCancel={cancelEditBackToInfo}
          onRequestDelete={requestEliminaRicambio}
          onSaveError={(message) => toastError(message, { module: "magazzino", action: "update" })}
          modalitaModifica={modalitaModifica}
          onSaved={(ui, message) => {
            patchProdotti((prev) => prev.map((p) => (p.id === ui.id ? touch(ui) : p)));
            completeMagazzinoSave(ui.id, message);
          }}
          onImageEvent={(ev) => logImageEvent(ev, detailRicambio)}
        />
      ) : null}

      {manualLabelOpen ? <MagazzinoManualLabelModal onClose={() => setManualLabelOpen(false)} /> : null}

      <GestionaleModalGate open={logOpen}>
        <MagazzinoLogDrawer
          open={logOpen}
          onClose={() => setLogOpen(false)}
          feed={magLogFeed}
          loading={magLogFeedLoading}
          pagedFeed={pagedMagLogFeed}
          showPager={showMagLogDrawerPager}
          page={magLogDrawerPage}
          pageCount={magLogDrawerPageCount}
          pagerLabel={magLogDrawerPagerLabel}
          onPageChange={setMagLogDrawerPage}
          onFocusRicambio={focusRicambioInTable}
          onDismissLocal={removeMagazzinoLogEntry}
        />
      </GestionaleModalGate>

      {dupCheckModalOpen ? (
        <MagazzinoDupCodesModal
          groups={archivioDupCodeGroups}
          onClose={() => setDupCheckModalOpen(false)}
          onOpenRicambio={(id) => focusRicambioInTable(id)}
        />
      ) : null}
      <SettingsEliminaConfirmDialog
        open={deleteGeneratedOpen}
        pending={deleteGeneratedLoading}
        itemLabel={`${generatedListinoCount} ricambi generati da listino`}
        detail="Verranno eliminati solo i ricambi creati automaticamente da import listino, esclusi quelli con movimenti collegati."
        onCancel={() => setDeleteGeneratedOpen(false)}
        onConfirm={() => void executeDeleteGeneratedListinoRicambi()}
      />
      <SettingsEliminaConfirmDialog
        open={eliminaRicambioTarget != null}
        itemLabel={eliminaRicambioTarget?.descrizione}
        detail="Il ricambio verrà rimosso dal magazzino."
        onCancel={() => setEliminaRicambioTarget(null)}
        onConfirm={() => void executeEliminaRicambio()}
      />
      {confirmDialog}
    </div>
    </MagazzinoDebouncedScortaProvider>
    </GestionaleSectionGate>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState, type FormEvent, type ReactElement } from "react";
import { useBeforeUnloadWhenDirty } from "@/lib/forms/use-before-unload-when-dirty";
import {
  GestionaleModalFooterActions,
  GestionaleModalFooterCancelButton,
  GestionaleModalFooterDeleteButton,
  GestionaleModalFooterSaveButton,
} from "@/components/design-system";
import { DisabledElementTooltip } from "@/components/ui";
import { GestionaleConfirmDialog } from "@/components/gestionale/gestionale-confirm-dialog";
import { GestionaleModalShell } from "@/components/gestionale/gestionale-modal";
import { GestionaleModalScrollBody } from "@/components/gestionale/mobile-modal-scroll-body";
import { useFormEngine } from "@/lib/forms/form-engine";
import { RicambioFormFields } from "@/components/gestionale/magazzino/ricambio-form-fields";
import { RicambioFormOptionsProvider } from "@/components/gestionale/magazzino/ricambio-form-options-context";
import { RicambioCollapsibleSection, ricambioModalFormScrollClass } from "@/components/gestionale/magazzino/ricambio-modal-ui";
import { RecordImageManager, type RecordImageLogEvent } from "@/components/gestionale/media/record-image-manager";
import {
  ricambioFormIsDirty,
  ricambioFormImportantWarnings,
  ricambioFromFormLenient,
  ricambioLenientPlaceholderFlags,
  ricambioScortaDeltaFromBaseline,
  toFormDraft,
  validateRicambioListFields,
  type RicambioFormState,
} from "@/lib/magazzino/form";
import {
  gateBeginSubmit,
  gateFormSubmit,
} from "@/lib/form-ux-migration/form-ux-boundary-gate";
import type { RicambioMagazzino } from "@/lib/magazzino/types";
import type { MezziListePrefs } from "@/lib/mezzi/mezzi-liste-prefs-storage";
import { gestionaleModalBodyFlexClass } from "@/lib/ui/modal-max-width-class";
import { READONLY_PERMISSION_HINT } from "@/src/lib/auth/permissions";
import { incrementHealthCounter } from "@/lib/observability/runtime-health";
import { ricambioUiToMagazzinoUpdate } from "@/lib/magazzino/magazzino-db-ui-adapter";
import { runStockAdjustPipeline } from "@/lib/magazzino/stock-pipeline-execute";
import { magazzinoEntry } from "@/lib/domain/magazzino-entry";
import { ricambioUiFromMagazzinoRow } from "@/lib/magazzino/magazzino-list-cache";
import { useQueryClient } from "@tanstack/react-query";
import { buildRicambioCompatExpandOptions } from "@/lib/magazzino/resolve-mezzi-liste-for-compat";
import { useGlobalOptions } from "@/src/hooks/use-global-options";
import { cabModalZConfirm } from "@/lib/ui/mobile-modal-behavior";

const RICAMBIO_EDIT_FORM_ID = "ricambio-edit-form";

export function RicambioEditModal({
  ricambioId,
  ricambio,
  mezziListePrefs,
  marche,
  categorie,
  fornitori,
  produttori,
  authorName,
  magCanCreateRicambio,
  magCanDeleteRicambio,
  onClose,
  onCancel,
  onRequestDelete,
  onSaved,
  onSaveError,
  onImageEvent,
  modalitaModifica = false,
  onMounted,
}: {
  ricambioId: string;
  ricambio: RicambioMagazzino;
  mezziListePrefs: MezziListePrefs;
  marche: string[];
  categorie: string[];
  fornitori: string[];
  produttori: string[];
  authorName: string;
  magCanCreateRicambio: boolean;
  magCanDeleteRicambio: boolean;
  onClose: () => void;
  onCancel: () => void;
  onRequestDelete: () => void;
  onSaved: (ui: RicambioMagazzino, message: string) => void;
  onSaveError: (message: string) => void;
  onImageEvent?: (event: RecordImageLogEvent) => void;
  /** Se true, variazioni scorta contano nelle statistiche. */
  modalitaModifica?: boolean;
  onMounted?: () => void;
}) {
  const queryClient = useQueryClient();
  const { mezziListe: mergedMezziListe } = useGlobalOptions({ debugTag: "RicambioEditModal" });

  useEffect(() => {
    onMounted?.();
  }, [onMounted]);
  const compatExpand = useMemo(
    () =>
      buildRicambioCompatExpandOptions({
        mezziListe: mezziListePrefs,
        mezziListeMerged: mergedMezziListe,
      }),
    [mergedMezziListe, mezziListePrefs],
  );
  const baselineForm = useMemo(
    () => toFormDraft(ricambio, mergedMezziListe, { prefsListe: mezziListePrefs }),
    [ricambio, mergedMezziListe, mezziListePrefs],
  );
  const formEngine = useFormEngine<RicambioFormState>({
    initial: baselineForm,
  });
  const { value: editDraft, setValue, reset, runSubmit, formProps } = formEngine;
  const [listFieldInvalid, setListFieldInvalid] = useState(false);
  const [saveBusy, setSaveBusy] = useState(false);
  const [discardConfirmOpen, setDiscardConfirmOpen] = useState(false);
  const [pendingExit, setPendingExit] = useState<"close" | "cancel" | null>(null);
  const isDirty = useMemo(() => ricambioFormIsDirty(editDraft, baselineForm), [editDraft, baselineForm]);
  const prevRicambioIdRef = useRef(ricambioId);

  useEffect(() => {
    const ricambioChanged = prevRicambioIdRef.current !== ricambioId;
    prevRicambioIdRef.current = ricambioId;
    if (!ricambioChanged && isDirty) return;
    reset(baselineForm);
    setListFieldInvalid(false);
    setDiscardConfirmOpen(false);
    setPendingExit(null);
  }, [ricambioId, baselineForm, isDirty, reset]);

  useBeforeUnloadWhenDirty(isDirty, "Hai modifiche non salvate nel ricambio.");

  const setEditForm = useCallback(
    (action: React.SetStateAction<RicambioFormState>) => {
      setValue(action);
    },
    [setValue],
  );

  const performExit = useCallback(
    (kind: "close" | "cancel") => {
      setDiscardConfirmOpen(false);
      setPendingExit(null);
      reset(baselineForm);
      setListFieldInvalid(false);
      if (kind === "close") onClose();
      else onCancel();
    },
    [baselineForm, onCancel, onClose, reset],
  );

  const beforeBack = useCallback(async () => {
    if (saveBusy) return false;
    if (discardConfirmOpen) {
      setDiscardConfirmOpen(false);
      setPendingExit(null);
      return false;
    }
    if (isDirty) {
      setPendingExit("close");
      setDiscardConfirmOpen(true);
      return false;
    }
    return true;
  }, [discardConfirmOpen, isDirty, saveBusy]);

  const requestExit = useCallback(
    (kind: "close" | "cancel") => {
      if (saveBusy) return;
      if (discardConfirmOpen) {
        setDiscardConfirmOpen(false);
        setPendingExit(null);
        return;
      }
      if (isDirty) {
        setPendingExit(kind);
        setDiscardConfirmOpen(true);
        return;
      }
      performExit(kind);
    },
    [discardConfirmOpen, isDirty, performExit, saveBusy],
  );

  const handleRequestClose = useCallback(() => {
    requestExit("close");
  }, [requestExit]);

  async function saveEdit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (!magCanCreateRicambio || saveBusy) return;

    await runSubmit(e.currentTarget, async (currentDraft) => {
      const submitToken = gateBeginSubmit("ricambio");
      const reconciledDraft = gateFormSubmit("ricambio", currentDraft, submitToken);
      const listErr = validateRicambioListFields(reconciledDraft, {
        marche,
        categorie,
        fornitori,
        produttori,
        mezziListe: compatExpand.mezziListe,
      });
      if (listErr) {
        setListFieldInvalid(true);
        onSaveError(listErr);
        return;
      }
      setListFieldInvalid(false);
      const next = ricambioFromFormLenient(reconciledDraft, ricambioId, authorName, compatExpand);
      const incompleteWarnings = ricambioFormImportantWarnings(reconciledDraft);
      if (incompleteWarnings.length > 0) incrementHealthCounter("ricambioSaveIncompleteFields");
      const placeholderFlags = ricambioLenientPlaceholderFlags(next);
      if (placeholderFlags.marcaPlaceholder) incrementHealthCounter("ricambioSavePlaceholderMarca");
      if (placeholderFlags.descrizionePlaceholder) incrementHealthCounter("ricambioSavePlaceholderDescrizione");
      if (placeholderFlags.categoriaPlaceholder) incrementHealthCounter("ricambioSavePlaceholderCategoria");
      const scortaDelta = ricambioScortaDeltaFromBaseline(baselineForm, reconciledDraft);
      setSaveBusy(true);
      try {
        if (scortaDelta !== 0) {
          const stats = modalitaModifica;
          const moved = await runStockAdjustPipeline(queryClient, {
            ricambioId,
            delta: scortaDelta,
            contaStatistiche: stats,
            origine: stats ? "manual_adjustment" : "inventario",
            causale: stats
              ? scortaDelta > 0
                ? "carico_manuale"
                : "scarico_manuale"
              : "rettifica_inventario",
          });
          if (!moved.ok) {
            onSaveError(moved.error ?? "Aggiornamento scorta non riuscito.");
            return;
          }
          next.scorta = moved.data.quantita;
        }
        const patch = ricambioUiToMagazzinoUpdate(next, mezziListePrefs);
        const updated = await magazzinoEntry.update(ricambioId, patch);
        if (!updated.success || !updated.data) {
          onSaveError(updated.error ?? "Salvataggio non riuscito.");
          return;
        }
        const ui = ricambioUiFromMagazzinoRow(updated.data, authorName, mergedMezziListe);
        reset(toFormDraft(ui, mezziListePrefs));
        const lenientHint =
          placeholderFlags.marcaPlaceholder ||
          placeholderFlags.descrizionePlaceholder ||
          placeholderFlags.categoriaPlaceholder
            ? " Salvato con campi segnaposto — completa l'anagrafica quando possibile."
            : "";
        onSaved(ui, `Modifiche salvate.${lenientHint}`);
      } catch (e) {
        if (process.env.NODE_ENV === "development") {
          console.error("[ricambio-edit] save threw", e);
        }
        onSaveError(e instanceof Error ? e.message : "Salvataggio non riuscito.");
      } finally {
        setSaveBusy(false);
      }
    });
  }

  return (
    <>
      <GestionaleModalShell
        modalSize="formMedium"
        beforeBack={beforeBack}
        onRequestClose={handleRequestClose}
      title="Modifica ricambio"
      titleId="detail-ricambio-title"
      footer={
        <div className="w-full min-w-0">
          <div className="grid grid-cols-2 gap-2 sm:hidden">
            <GestionaleModalFooterSaveButton
              type="submit"
              form={RICAMBIO_EDIT_FORM_ID}
              loading={saveBusy}
              loadingLabel="Salvataggio…"
              className="col-span-2 w-full justify-center disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-45"
            />
            <GestionaleModalFooterCancelButton
              className="w-full justify-center"
              onClick={() => requestExit("cancel")}
            />
            <DisabledElementTooltip content={READONLY_PERMISSION_HINT} disabled={!magCanDeleteRicambio}>
              <GestionaleModalFooterDeleteButton
                className="w-full justify-center"
                onClick={onRequestDelete}
                disabled={!magCanDeleteRicambio}
              >
                Elimina
              </GestionaleModalFooterDeleteButton>
            </DisabledElementTooltip>
          </div>
          <GestionaleModalFooterActions className="hidden min-w-0 items-center justify-between gap-2 sm:flex">
            <DisabledElementTooltip content={READONLY_PERMISSION_HINT} disabled={!magCanDeleteRicambio}>
              <GestionaleModalFooterDeleteButton
                className="shrink-0 justify-center"
                onClick={onRequestDelete}
                disabled={!magCanDeleteRicambio}
              >
                Elimina
              </GestionaleModalFooterDeleteButton>
            </DisabledElementTooltip>
            <div className="flex shrink-0 items-center gap-2">
              <GestionaleModalFooterCancelButton
                className="justify-center"
                onClick={() => requestExit("cancel")}
              />
              <GestionaleModalFooterSaveButton
                type="submit"
                form={RICAMBIO_EDIT_FORM_ID}
                loading={saveBusy}
                loadingLabel="Salvataggio…"
                className="shrink-0 justify-center disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-45"
              />
            </div>
          </GestionaleModalFooterActions>
        </div>
      }
    >
      <RicambioFormOptionsProvider>
        <form
          {...formProps}
          id={RICAMBIO_EDIT_FORM_ID}
          data-form-ux-id="ricambio"
          onSubmit={saveEdit}
          className={`${gestionaleModalBodyFlexClass} min-h-0 overflow-hidden`}
        >
          <GestionaleModalScrollBody className={ricambioModalFormScrollClass}>
            <RicambioFormFields
              form={editDraft}
              setForm={setEditForm}
              formResetKey={ricambioId}
              formMode="edit"
              listFieldForceInvalid={listFieldInvalid}
              relaxHtmlValidation
            />
            <RicambioCollapsibleSection title="Foto" defaultCollapsed>
              <RecordImageManager
                scope="magazzino"
                recordId={ricambioId}
                canEdit={magCanCreateRicambio}
                hubCardLayout
                onImageEvent={onImageEvent}
              />
            </RicambioCollapsibleSection>
          </GestionaleModalScrollBody>
        </form>
      </RicambioFormOptionsProvider>
    </GestionaleModalShell>
      <GestionaleConfirmDialog
        open={discardConfirmOpen}
        title="Modifiche non salvate"
        message="Hai inserito dati non salvati. Vuoi uscire senza salvare?"
        cancelLabel="Continua a modificare"
        confirmLabel="Esci senza salvare"
        destructive
        layerClassName={cabModalZConfirm}
        onCancel={() => {
          setDiscardConfirmOpen(false);
          setPendingExit(null);
        }}
        onConfirm={() => performExit(pendingExit ?? "close")}
      />
    </>
  );
}

