import {
  Q_MEZZI_HUB,
  Q_MEZZI_HUB_TAB,
  Q_MEZZI_VIEW,
  Q_TAGLIANDI_HIGHLIGHT,
  Q_TAGLIANDI_PRESET,
  Q_TAGLIANDI_SECTION,
  Q_TAGLIANDI_STATO,
  parseMezziViewFromSearchParam,
  parseTagliandiSectionFromSearchParam,
  parseTagliandoStatoFilter,
  type TagliandiSectionParam,
} from "@/lib/navigation/mezzi-tagliandi-links";
