          />

          {labelMode ? (
            <MezziBulkQrLabelToolbar selection={qrSelection} onClearSelection={qrSelection.clear} />
          ) : null}

          {mezziError ? (
            <LoadingErrorState
              title="Impossibile caricare i mezzi"
              description={mezziErr?.message ?? "Errore caricamento mezzi."}
              onRetry={() => void refetchMezzi()}
              className="mt-4"
