          </FormField>
          ) : null}
          {!hideRichiedenteFirma ? (
          <RichiedenteFirmaCaptureModal
            open={firmaModalOpen}
            initialDataUrl={value.richiedenteFirma ?? ""}
            onClose={() => setFirmaModalOpen(false)}
            onSave={(dataUrl) => onPatch({ richiedenteFirma: dataUrl })}
          />
          ) : null}
        </FormSection>
        )
      ) : null}
    </>
  );
}

export const SchedaIngressoAnagraficaFields = memo(
  SchedaIngressoAnagraficaFieldsInner,
  (prev, next) => {
    if (prev.disabled !== next.disabled) return false;
    if (prev.surface !== next.surface) return false;
    if (prev.onPatch !== next.onPatch) return false;
    if (prev.mezzi !== next.mezzi) return false;
    if (prev.sections !== next.sections) return false;
    if (prev.onExactMezzoMatch !== next.onExactMezzoMatch) return false;
    if (prev.onMezzoIdentMatch !== next.onMezzoIdentMatch) return false;
    if (prev.onAmbiguousMezzoMatch !== next.onAmbiguousMezzoMatch) return false;
    if (prev.dismissedMezzoIds !== next.dismissedMezzoIds) return false;
    if (prev.mezzoInlineHint !== next.mezzoInlineHint) return false;
    if (prev.mezzoCatalogFieldDrifts !== next.mezzoCatalogFieldDrifts) return false;
    if (prev.onUseMezzoFromHint !== next.onUseMezzoFromHint) return false;
    if (prev.onDismissMezzoHint !== next.onDismissMezzoHint) return false;
    if (prev.onDismissAmbiguousHint !== next.onDismissAmbiguousHint) return false;
    if (prev.onNotifyPermanentFieldUserEdit !== next.onNotifyPermanentFieldUserEdit) return false;
    if (prev.onVerifyMezzoConflict !== next.onVerifyMezzoConflict) return false;
    if (prev.clienteRequired !== next.clienteRequired) return false;
    if (prev.marcaAttrezzaturaRequired !== next.marcaAttrezzaturaRequired) return false;
    if (prev.mezzoLinked !== next.mezzoLinked) return false;
    if (prev.mezzoId !== next.mezzoId) return false;
    if (prev.captureHints !== next.captureHints) return false;
    if (prev.onApplyCaptureHint !== next.onApplyCaptureHint) return false;
    if (prev.onOreLavoroPatch !== next.onOreLavoroPatch) return false;
    if (prev.hideSectionTitles !== next.hideSectionTitles) return false;
    if (prev.hideRichiedenteFirma !== next.hideRichiedenteFirma) return false;
    if (prev.bareSection !== next.bareSection) return false;
    if (prev.value.oreLavoroPto !== next.value.oreLavoroPto) return false;
    return schedaIngressoFieldsSliceEqual(
      prev.value,
      next.value,
      SCHEDA_INGRESSO_ANAGRAFICA_FIELD_KEYS,
    );
  },
);

"use client";

import {
  globalAutocompleteOptionClass,
  globalAutocompleteOptionPillClass,
} from "@/lib/ui/global-input";
import { normListSelectValue } from "@/lib/ui/list-select-utils";
import type { ListSelectItem } from "@/lib/ui/list-select-items";
import type { CSSProperties, ReactNode } from "react";
import type { SelectorOptionRenderContext } from "@/components/gestionale/selector/selector-listbox";
import { HighlightSearchMatch } from "@/components/gestionale/global-input/highlight-search-match";
import { createSelectorSheetTapSelectHandlers } from "@/lib/selector-interaction/selector-sheet-tap-select";

const SHEET_OPTION_TOUCH_CLASS = "touch-pan-y";

export type DefaultStringRenderOptionParams = {
  highlightQuery?: string;
  highlightSearch?: boolean;
  onPointerSelect: (e: React.PointerEvent, select: () => void) => void;
  /** Sheet mobile: tap-vs-scroll invece di select su pointerdown. */
  sheetTapSelect?: boolean;
};

export function defaultStringRenderOption(
  params: DefaultStringRenderOptionParams,
): (ctx: SelectorOptionRenderContext<string>) => ReactNode {
  const { highlightQuery = "", highlightSearch = true, onPointerSelect, sheetTapSelect = false } = params;
  return ({ item, active, selected, optionId, onSelect, onMouseEnter }) => {
    const sheetTap = sheetTapSelect ? createSelectorSheetTapSelectHandlers(onSelect) : null;
    return (
      <div key={item} role="presentation" className="py-0.5">
        <button
          id={optionId}
          type="button"
          role="option"
          aria-selected={selected}
          className={`${globalAutocompleteOptionClass(active, selected)}${sheetTapSelect ? ` ${SHEET_OPTION_TOUCH_CLASS}` : ""}`}
          onPointerDown={
            sheetTap
              ? sheetTap.onPointerDown
              : (e) => onPointerSelect(e, onSelect)
          }
          onPointerMove={sheetTap?.onPointerMove}
          onPointerUp={sheetTap?.onPointerUp}
          onPointerCancel={sheetTap?.onPointerCancel}
          onClick={(e) => {
            e.preventDefault();
            e.stopPropagation();
          }}
          onMouseEnter={onMouseEnter}
        >
          {highlightSearch && highlightQuery.trim() ? (
            <HighlightSearchMatch text={item} query={highlightQuery} />
          ) : (
            item
          )}
        </button>
      </div>
    );
  };
}

export type DefaultItemRenderOptionParams = {
  value: string;
  coloredOptions?: boolean;
  highlightQuery?: string;
  highlightSearch?: boolean;
  onPointerSelect: (e: React.PointerEvent, select: () => void) => void;
  sheetTapSelect?: boolean;
};

export function defaultItemRenderOption(
  params: DefaultItemRenderOptionParams,
): (ctx: SelectorOptionRenderContext<ListSelectItem & { pillStyle?: CSSProperties }>) => ReactNode {
  const {
    value,
    coloredOptions = false,
    highlightQuery = "",
    highlightSearch = true,
    onPointerSelect,
    sheetTapSelect = false,
  } = params;
  return ({ item, active, optionId, onSelect, onMouseEnter }) => {
    const isSelected = item.value === value;
    const btnClass =
      coloredOptions && item.pillStyle
        ? globalAutocompleteOptionPillClass(active, isSelected, item.pillStyle)
        : globalAutocompleteOptionClass(active, isSelected);
    const sheetTap = sheetTapSelect ? createSelectorSheetTapSelectHandlers(onSelect) : null;
    return (
      <div key={item.value} role="presentation" className="py-0.5">
        <button
          id={optionId}
          type="button"
          role="option"
          aria-selected={isSelected}
          style={coloredOptions ? item.pillStyle : undefined}
          className={`${btnClass}${sheetTapSelect ? ` ${SHEET_OPTION_TOUCH_CLASS}` : ""}`}
          onPointerDown={
            sheetTap
              ? sheetTap.onPointerDown
              : (e) => onPointerSelect(e, onSelect)
          }
          onPointerMove={sheetTap?.onPointerMove}
          onPointerUp={sheetTap?.onPointerUp}
          onPointerCancel={sheetTap?.onPointerCancel}
          onClick={(e) => {
            e.preventDefault();
            e.stopPropagation();
          }}
          onMouseEnter={onMouseEnter}
        >
          {highlightSearch && highlightQuery.trim() ? (
            <HighlightSearchMatch text={item.label} query={highlightQuery} />
          ) : (
            item.label
          )}
        </button>
      </div>
    );
  };
}

export function normOptionSelected(option: string, selectedValue: string): boolean {
  return normListSelectValue(option) === normListSelectValue(selectedValue);
}

