  }

  return (
    <div className="mt-2 grid grid-cols-1 gap-2 md:grid-cols-2">
      {bundles.map(({ row, fields }) => {
        return (
          <LavorazioneMobileCardShell key={row.id} className="min-w-0 h-full">
