}

function LavorazioniSection({
  listSurface,
  sectionLabel,
  bundles,
  variant,
  statiOpts,
  colStyles,
  addettoColors,
  addettiRecords,
  emptyDefault,
  filtersActive,
  sortColumn,
  sortPhase,
  onSort,
  onIngresso,
  onQr,
  schedeStore,
}: {
  listSurface: ListSurface;
  /** Etichetta accessibilità (titolo visibile sulla ShellCard). */
  sectionLabel: string;
  bundles: RowBundle[];
  variant: "active" | "archive";
  statiOpts: { id: string; label: string; color?: string }[];
  colStyles: LavorazioniListTableColStyles;
  addettoColors: Record<string, string | undefined>;
  addettiRecords: readonly AddettoRecord[];
  schedeStore: LavorazioneSchedeStore;
  emptyDefault: string;
  filtersActive: boolean;
  sortColumn: ClientPortalSortKey | null;
  sortPhase: GlobalTableSortPhase;
  onSort: (k: ClientPortalSortKey) => void;
  onIngresso: (row: LavorazioneListRow) => void;
  onQr: (row: LavorazioneListRow) => void;
}) {
  const emptyMessage = filtersActive ? "Nessun risultato con i filtri attuali." : emptyDefault;

  return (
    <section className="min-w-0" aria-label={sectionLabel}>
      {listSurface === "table" ? (
      <DesktopTable
        bundles={bundles}
        variant={variant}
        statiOpts={statiOpts}
        colStyles={colStyles}
        addettoColors={addettoColors}
        addettiRecords={addettiRecords}
        emptyMessage={emptyMessage}
        sortColumn={sortColumn}
        sortPhase={sortPhase}
        onSort={onSort}
        onIngresso={onIngresso}
        onQr={onQr}
      />
      ) : (
      <MobileCards
        bundles={bundles}
        variant={variant}
        statiOpts={statiOpts}
        addettoColors={addettoColors}
        addettiRecords={addettiRecords}
        schedeStore={schedeStore}
        emptyMessage={emptyMessage}
        onIngresso={onIngresso}
        onQr={onQr}
      />
      )}
    </section>
  );
}

const CLIENT_PORTAL_SCHEde_SORT_KEYS = new Set<ClientPortalSortKey>([
  "cantiere",
  "attrezzatura",
  "nScuderia",
  "targa",
  "matricola",
  "addetto",
]);

function clientPortalSortAllowed(key: ClientPortalSortKey, lsdDegraded: boolean): boolean {
  return !lsdDegraded || !CLIENT_PORTAL_SCHEde_SORT_KEYS.has(key);
}

function buildRowBundles(
  rows: readonly LavorazioneListRow[],
  schedeStore: LavorazioneSchedeStore,
  addettiGlobali: readonly string[],
  addettiRecords: readonly AddettoRecord[],
  logsByLavorazioneId: ReadonlyMap<string, readonly LogModificaRow[]>,
): RowBundle[] {
  return rows.map((row) => ({
    row,
    fields: buildClientPortalRowFields(
      row,
      schedeStore,
      addettiGlobali,
      addettiRecords,
      logsByLavorazioneId,
    ),
  }));
}

export function ClientLavorazioniView({ listSurface: serverListSurface, listTier = "xl" }: GestionaleListPageProps) {
  const listSurface = useListSurface(serverListSurface);
  useGestionaleSyncScope({
    scopeId: "client-portal-lavorazioni-list",
    domain: "portale",
    route: "/lavorazioni-clienti",
    tables: CLIENT_PORTAL_SYNC_TABLES,
  });
  const [archivioExpanded, setArchivioExpanded] = useState(false);
  const o = useClientPortalPageOrchestrator({ listSurface, archivioExpanded });
  const { user, authorName } = useAuth();
  const { isCliente } = useRbac();
  const {
    canRender,
    accessDenied,
    contract,
    persistence,
    archivioListEnabled,
  } = o;

  const { filters, searchInput, setSearchInput, patchFilters, resetFilters } = persistence;
  const l0 = contract.l0;
  // eslint-disable-next-line react-hooks/exhaustive-deps -- lint phase2: stable hook contract
  const schedeStore = contract.l1?.schedeStore ?? {};

  const statiOpts = useMemo(
    () => filterClientPortalStatiOptions(l0?.statiOpts ?? []),
    [l0?.statiOpts],
  );
  const statoOrderIds = useMemo(() => statiOpts.map((s) => s.id), [statiOpts]);
  // eslint-disable-next-line react-hooks/exhaustive-deps -- lint phase2: stable hook contract
  const addettiGlobali = l0?.addettiGlobali ?? [];
  // eslint-disable-next-line react-hooks/exhaustive-deps -- lint phase2: stable hook contract
  const addettiRecords = l0?.addettiRecords ?? [];
  const colStyles = useLavorazioniListTableColStyles(statiOpts, [], addettiGlobali);
  const addettoColors = l0?.addettoColors ?? {};
  const lsdMode = contract.lsdMode;
  const lsdDegraded = lsdMode === "degraded";
  const lsdPaginated = lsdMode === "paginated";

  const [qrRow, setQrRow] = useState<LavorazioneListRow | null>(null);
  const [ingressoRow, setIngressoRow] = useState<LavorazioneListRow | null>(null);
  const [contattaciOpen, setContattaciOpen] = useState(false);
  const { logQuery: lavModificheLogQuery } = useUndoableLog("lavorazioni", {
    enabled: ingressoRow != null,
  });
  const logsByLavorazioneId = useMemo(
    () => (ingressoRow ? groupLavorazioniLogsById(lavModificheLogQuery.data ?? []) : new Map()),
    [ingressoRow, lavModificheLogQuery.data],
  );

  useEffect(() => {
    const t = window.setTimeout(() => patchFilters({ search: searchInput.trim() }), SEARCH_DEBOUNCE_MS);
    return () => window.clearTimeout(t);
  }, [searchInput, patchFilters]);

  const [filtriEspansi, setFiltriEspansi] = useCollapsiblePreference(
    collapsibleExpandedBoolPref(false, {
      scope: "client-lavorazioni",
      key: "filters",
      userId: user?.id ?? null,
    }),
  );

  const [sortInCorsoCol, setSortInCorsoCol] = useState<ClientPortalSortKey | null>(null);
  const [sortInCorsoPhase, setSortInCorsoPhase] = useState<GlobalTableSortPhase>("natural");
  const [sortArchivioCol, setSortArchivioCol] = useState<ClientPortalSortKey | null>(null);
  const [sortArchivioPhase, setSortArchivioPhase] = useState<GlobalTableSortPhase>("natural");

  const filtersActive = clientPortalFiltersActive(filters);

  const allInCorsoBundles = useMemo(
    () => buildRowBundles(l0?.inCorsoRows ?? [], schedeStore, addettiGlobali, addettiRecords, logsByLavorazioneId),
    [l0?.inCorsoRows, schedeStore, addettiGlobali, addettiRecords, logsByLavorazioneId],
  );

  const allArchivioBundles = useMemo(
    () => buildRowBundles(l0?.archivioRows ?? [], schedeStore, addettiGlobali, addettiRecords, logsByLavorazioneId),
    [l0?.archivioRows, schedeStore, addettiGlobali, addettiRecords, logsByLavorazioneId],
  );

  const filterCatalog = useMemo(() => {
    return buildClientPortalFilterCatalog(
      [...allInCorsoBundles, ...allArchivioBundles],
      schedeStore,
      addettiGlobali,
    );
  }, [allInCorsoBundles, allArchivioBundles, schedeStore, addettiGlobali]);

  const inCorsoBundles = useMemo(
    () => filterClientPortalBundles(allInCorsoBundles, filters, schedeStore, "in_corso"),
    [allInCorsoBundles, filters, schedeStore],
  );

  const archivioBundles = useMemo(
    () => filterClientPortalBundles(allArchivioBundles, filters, schedeStore, "archivio"),
    [allArchivioBundles, filters, schedeStore],
  );

  const profileUserIds = useMemo(() => {
    const ids = new Set<string>();
    const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
    for (const row of [...(l0?.inCorsoRows ?? []), ...(l0?.archivioRows ?? [])]) {
      if (row.updated_by?.trim()) ids.add(row.updated_by.trim());
      if (row.created_by?.trim()) ids.add(row.created_by.trim());
      const schedaUpdatedBy = schedeStore[row.id]?.ingresso?.updatedBy?.trim();
      if (schedaUpdatedBy && uuidRe.test(schedaUpdatedBy)) ids.add(schedaUpdatedBy);
    }
    if (ingressoRow) {
      for (const log of lavModificheLogQuery.data ?? []) {
        const id = log.autore_id?.trim();
        if (id) ids.add(id);
      }
    }
    return [...ids];
  }, [ingressoRow, l0?.archivioRows, l0?.inCorsoRows, lavModificheLogQuery.data, schedeStore]);
  const lazyProfileNames = useLavorazioneProfileNamesQuery(profileUserIds, canRender);
  const logAutoreByLavorazioneId = useMemo(
    () =>
      buildClientPortalLogAutoreByLavorazioneId(lavModificheLogQuery.data ?? [], {
        lazyProfileNames,
        currentUserId: user?.id ?? null,
        currentUserDisplayName: authorName,
        omitUnresolvedAutore: true,
      }),
    [authorName, lavModificheLogQuery.data, lazyProfileNames, user?.id],
  );
  const resolveClientPortalProfile = useCallback(
    (row: LavorazioneListRow) =>
      mergeLazyProfileNamesIntoResolver(
        buildLavorazioneRowProfileResolver(row, user?.id ?? null, authorName),
        lazyProfileNames,
      ),
    [authorName, lazyProfileNames, user?.id],
  );

  useEffect(() => {
    if (accessDenied || !l0) return;
    logClientPortalPipelineDebug({
      inCorsoRaw: l0.inCorsoRows.length,
      archivioRaw: l0.archivioRows.length,
      bundlesInCorso: allInCorsoBundles.length,
      bundlesArchivio: allArchivioBundles.length,
      filteredInCorso: inCorsoBundles.length,
      filteredArchivio: archivioBundles.length,
      filters,
      filtersActive,
    });
  }, [
    accessDenied,
    allArchivioBundles.length,
    allInCorsoBundles.length,
    filters,
    filtersActive,
    inCorsoBundles.length,
    archivioBundles.length,
    l0,
  ]);

  const sortedInCorsoBundles = useMemo(
    () =>
      sortClientPortalBundles(inCorsoBundles, sortInCorsoCol, sortInCorsoPhase, "active", statoOrderIds),
    [inCorsoBundles, sortInCorsoCol, sortInCorsoPhase, statoOrderIds],
  );

  const sortedArchivioBundles = useMemo(
    () =>
      sortClientPortalBundles(archivioBundles, sortArchivioCol, sortArchivioPhase, "archive", statoOrderIds),
    [archivioBundles, sortArchivioCol, sortArchivioPhase, statoOrderIds],
  );

  const archivioCountQuery = useClientLavorazioniArchivioCountQuery(
    canRender && filters.section !== "in_corso" && !archivioExpanded && !archivioListEnabled,
  );

  const archivioHeadCount =
    archivioCountQuery.data !== undefined ? archivioCountQuery.data : null;

  const archivioFilteredCount = archivioListEnabled
    ? contract.archivioQ.isPending && archivioHeadCount !== null
      ? archivioHeadCount
      : sortedArchivioBundles.length
    : archivioHeadCount;

  const archivioCardTitle =
    archivioFilteredCount === null
      ? "Lavorazioni completate (…)"
      : `Lavorazioni completate (${archivioFilteredCount})`;

  const onSortInCorso = useCallback(
    (k: ClientPortalSortKey) => {
      if (!clientPortalSortAllowed(k, lsdDegraded)) return;
      cycleLavorazioniTableSort(sortInCorsoCol, setSortInCorsoCol, setSortInCorsoPhase, k);
    },
    [lsdDegraded, sortInCorsoCol],
  );

  const onSortArchivio = useCallback(
    (k: ClientPortalSortKey) => {
      if (!clientPortalSortAllowed(k, lsdDegraded)) return;
      cycleLavorazioniTableSort(sortArchivioCol, setSortArchivioCol, setSortArchivioPhase, k);
    },
    [lsdDegraded, sortArchivioCol],
  );

  const showInCorso = filters.section !== "archivio";
  const showArchivio = filters.section !== "in_corso";

  const totalResults =
    (showInCorso ? inCorsoBundles.length : 0) +
    (showArchivio ? (archivioFilteredCount ?? 0) : 0);

  const resetRicerca = useCallback(() => {
    setSearchInput("");
    patchFilters({ search: "" });
  }, [patchFilters, setSearchInput]);

  const resetFiltri = useCallback(() => {
    resetFilters();
    setFiltriEspansi(false);
  // eslint-disable-next-line react-hooks/exhaustive-deps -- lint phase2: stable hook contract
  }, [resetFilters]);

  if (accessDenied) {
    return (
      <div className={dsStackPage}>
          <ShellCard>
            <p className="text-sm text-zinc-600 dark:text-zinc-400">
              Non hai permesso per consultare il portale clienti. Contatta un amministratore per assegnare il ruolo Cliente.
            </p>
            <Link href={CLIENTE_HOME_PATH} className={`mt-4 inline-flex ${dsBtnNeutral}`}>
              Torna al portale
            </Link>
          </ShellCard>
        </div>
    );
  }

  const listError = contract.l0Status === "error" ? contract.error : null;

  let listBody: ReactNode;
  if (lsdPaginated) {
    listBody = (
      <ShellCard>
        <p className="text-sm text-[color:var(--cab-text)]">
          Lo storico lavorazioni supera la soglia consultabile dal portale. Contatta CAB per assistenza.
        </p>
      </ShellCard>
    );
  } else if (listError) {
    listBody = (
      <ShellCard>
        <LoadingErrorState
          title="Impossibile caricare le lavorazioni"
          description="Controlla la connessione e riprova."
          onRetry={() => {
            void contract.retryL0();
          }}
        />
      </ShellCard>
    );
  } else {
    listBody = (
      <>
        {showInCorso ? (
          <ShellCard
            title={`Lavorazioni in corso (${sortedInCorsoBundles.length})`}
            collapsible
            defaultCollapsed={false}
            persistScope="client-lavorazioni"
            persistKey="attive"
          >
            <LavorazioniSection
              listSurface={listSurface}
              sectionLabel="Lavorazioni in corso"
              bundles={sortedInCorsoBundles}
              variant="active"
              statiOpts={statiOpts}
              colStyles={colStyles}
              addettoColors={addettoColors}
              addettiRecords={addettiRecords}
              schedeStore={schedeStore}
              emptyDefault="Nessuna lavorazione in corso."
              filtersActive={filtersActive}
              sortColumn={sortInCorsoCol}
              sortPhase={sortInCorsoPhase}
              onSort={onSortInCorso}
              onIngresso={setIngressoRow}
              onQr={setQrRow}
            />
          </ShellCard>
        ) : null}
        {showArchivio ? (
          <ShellCard
            title={archivioCardTitle}
            collapsible
            defaultCollapsed
            persistScope="client-lavorazioni"
            persistKey="archivio"
            persist={false}
            onCollapsedChange={(collapsed) => setArchivioExpanded(!collapsed)}
          >
            <LavorazioniSection
              listSurface={listSurface}
              sectionLabel="Lavorazioni completate"
              bundles={sortedArchivioBundles}
              variant="archive"
              statiOpts={statiOpts}
              colStyles={colStyles}
              addettoColors={addettoColors}
              addettiRecords={addettiRecords}
              schedeStore={schedeStore}
              emptyDefault="Nessuna lavorazione in archivio."
              filtersActive={filtersActive}
              sortColumn={sortArchivioCol}
              sortPhase={sortArchivioPhase}
              onSort={onSortArchivio}
              onIngresso={setIngressoRow}
              onQr={setQrRow}
            />
          </ShellCard>
        ) : null}
      </>
    );
  }

  return (
    <div className={`lavorazioni-scroll-scope ${layoutPageRoot} ${gestionaleListTierClass(listTier)}`.trim()}>
    <>
      <div className={clientPortalPageStack}>
        {!canRender ? (
          <div className="min-h-[12rem]" role="status" aria-busy="true" aria-label="Caricamento lavorazioni" />
        ) : (
          <>
            {lsdDegraded ? (
              <ShellCard>
                <p className="text-sm text-[color:var(--cab-text-muted)]">
                  Storico ampio: ordinamento su colonne scheda disabilitato per mantenere la pagina reattiva.
                </p>
              </ShellCard>
            ) : null}
            <ShellCard>
              <section aria-label="Azioni e filtri lavorazioni clienti">
                <PageToolbar
                  primaryAction={
                    <ClientContattaciButton variant="primary" onClick={() => setContattaciOpen(true)} />
                  }
                  search={
                    <GestionaleSearchField
                      id="client-lavorazioni-search"
                      value={searchInput}
                      onChange={(e) => setSearchInput(e.target.value)}
                      onKeyDown={(e) => {
                        if (e.key === "Enter") {
                          e.preventDefault();
                          patchFilters({ search: searchInput.trim() });
                        }
                      }}
                      placeholder={GESTIONALE_SEARCH_PLACEHOLDER}
                      aria-label="Cerca lavorazioni clienti"
                      wrapperClassName="min-w-0 flex-1 sm:min-w-[12rem]"
                    />
                  }
                  filtersExpanded={filtriEspansi}
                  onFiltersToggle={() => setFiltriEspansi((o) => !o)}
                  filtersActive={filtersActive}
                  filtersPanel={
                    <LavorazioniAdvancedFilterPanel
                      filters={filters}
                      onChange={patchFilters}
                      catalog={filterCatalog}
                      variant="clientPortal"
                      restrictUtilizzatoriToCatalog={isCliente}
                    />
                  }
                  onFilterReset={resetFiltri}
                  meta={
                    <PageToolbarResultCount
                      count={totalResults}
                      filtersActive={lavorazioniAdvancedFiltersActive(filters)}
                      searchActive={filters.search.trim().length > 0 || searchInput.trim().length > 0}
                      onSearchReset={resetRicerca}
                      onFilterReset={resetFiltri}
                    />
                  }
                />
              </section>
            </ShellCard>

            {listBody}
          </>
        )}
      </div>

      {qrRow ? (
        <ClientLavorazioneQrDialog
          open
          onClose={() => setQrRow(null)}
          lavorazioneId={qrRow.id}
          refLabel={lavorazioneRefLabel(qrRow.id, qrRow.codice)}
        />
      ) : null}

      {ingressoRow ? (
        <ClientLavorazioneIngressoDialog
          open
          onClose={() => setIngressoRow(null)}
          row={ingressoRow}
          schedeStore={schedeStore}
          addettiGlobali={addettiGlobali}
          addettiRecords={addettiRecords}
          autoreLog={logAutoreByLavorazioneId.get(ingressoRow.id) ?? ""}
          resolveUserId={resolveClientPortalProfile(ingressoRow)}
        />
      ) : null}

      {contattaciOpen ? <ClientContattaciDialog open onClose={() => setContattaciOpen(false)} /> : null}
    </>
    </div>
  );
}

"use client";

import { OptionalTooltip } from "@/components/ui";
import { CardMobile, CardMobileActions, IconActionButton } from "@/components/design-system";
import type { ListSurface } from "@/lib/ui/resolve-list-surface";
import {
  GestionaleListTable,
  GestionaleListTableActionsHead,
  GlobalTableHeadLabel,
} from "@/components/gestionale/global-table";
import {
  dsBtnPrimary,
  dsHubModalMetaChip,
  dsScrollbar,
  dsTableActionBtnPrimary,
  dsTableActionGlyph,
  dsTableActionTextBtnPrimary,
  dsTableActionsGroup,
  dsTableRow,
  dsTableTdActions,
} from "@/lib/ui/design-system";
import type { PreventivoRecord } from "@/lib/preventivi/types";
import {
  fmtPreventivoDataTabella,
  fmtPreventivoMarcaModello,
} from "@/lib/preventivi/preventivi-per-macchina";
import { gestionaleListTableTd } from "@/lib/ui/gestionale-list-table";

/** Allineato a `preventivi-view` (archivio). */
const _prevTableTd = gestionaleListTableTd;
const prevTableTdText = `${gestionaleListTableTd} min-w-0 text-sm text-zinc-800 dark:text-zinc-100`;

type LavorazionePreventiviHubListProps = {
  listSurface: ListSurface;
  rows: PreventivoRecord[];
  /** Evidenzia i preventivi collegati a questa lavorazione. */
  lavorazioneId?: string;
  onApriNeiPreventivi: (p: PreventivoRecord) => void;
  onCreaPreventivo?: () => void;
};

function isPreventivoCollegato(p: PreventivoRecord, lavorazioneId?: string): boolean {
  return Boolean(lavorazioneId && p.lavorazioneId === lavorazioneId);
}

function PreventivoCollegatoBadge() {
  return <span className={dsHubModalMetaChip}>Collegato</span>;
}

function PreventivoIdentCell({ p }: { p: PreventivoRecord }) {
  const targa = p.targa?.trim() || "—";
  const matricola = p.matricola?.trim() || "—";
  const scuderia = p.nScuderia?.trim();
  return (
    <div className="min-w-0 text-left leading-tight">
      <div className="truncate font-mono text-xs font-medium text-zinc-800 dark:text-zinc-100">{targa}</div>
      <div className="truncate font-mono text-[10px] text-zinc-500 dark:text-zinc-400">{matricola}</div>
      {scuderia ? (
        <div className="truncate text-[10px] text-zinc-500 dark:text-zinc-400">N. {scuderia}</div>
      ) : null}
    </div>
  );
}

function PreventiviHubEmptyState({ onCreaPreventivo }: { onCreaPreventivo?: () => void }) {
  return (
    <div className="rounded-[var(--ds-radius-lg)] border border-dashed border-[color:var(--cab-border)] bg-[color:color-mix(in_srgb,var(--cab-surface-2)_55%,var(--cab-card))] px-3 py-4 text-center">
      <p className="text-sm font-medium text-[color:var(--cab-text)]">Nessun preventivo per questo mezzo</p>
      <p className="mt-1 text-[11px] leading-snug text-[color:var(--cab-text-muted)]">
        I preventivi creati con targa, matricola o scuderia uguali compariranno qui.
      </p>
      {onCreaPreventivo ? <CreaPreventivoButton className="mt-3" onClick={onCreaPreventivo} /> : null}
    </div>
  );
}

/** Pulsante primario condiviso (tab Preventivi empty state, footer tab Schede). */
function IconPreventivo({ className = "h-4 w-4 shrink-0" }: { className?: string }) {
  return (
    <svg className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2} aria-hidden>
      <path
        strokeLinecap="round"
        strokeLinejoin="round"
        d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
      />
    </svg>
  );
}

export function CreaPreventivoButton({
  onClick,
  disabled,
  disabledTitle,
  className = "",
}: {
  onClick: () => void;
  disabled?: boolean;
  disabledTitle?: string;
  className?: string;
}) {
  return (
    <OptionalTooltip content={disabled ? disabledTitle : undefined}>
      <button
        type="button"
        className={`inline-flex items-center justify-center gap-1.5 ${dsBtnPrimary} min-h-11${className ? ` ${className}` : ""}`}
        disabled={disabled}
        onClick={onClick}
      >
        <IconPreventivo />
        Crea preventivo
      </button>
    </OptionalTooltip>
  );
}

export function LavorazionePreventiviHubList({
  listSurface,
  rows,
  lavorazioneId,
  onApriNeiPreventivi,
  onCreaPreventivo,
}: LavorazionePreventiviHubListProps) {
  if (rows.length === 0) {
    return <PreventiviHubEmptyState onCreaPreventivo={onCreaPreventivo} />;
  }

  return (
    <div className="min-w-0 max-w-full">
    <>
      {listSurface === "table" ? (
      <GestionaleListTable
        masterScrollScope={false}
        className="w-full min-w-0 text-sm text-zinc-900 dark:text-zinc-100"
        colgroup={
          <>
            <col className="w-[5.25rem]" />
            <col className="w-[5.75rem]" />
            <col className="w-[12%]" />
            <col className="w-[10%]" />
            <col className="w-[10%]" />
            <col className="w-[14%]" />
            <col className="w-[9.75rem]" />
            <col className="w-[10.5rem]" />
          </>
        }
        headRow={
          <>
            <GlobalTableHeadLabel label="N." thClassName="w-[5.25rem] min-w-[5.25rem]" />
            <GlobalTableHeadLabel label="Data" thClassName="w-[5.75rem] min-w-[5.75rem]" />
            <GlobalTableHeadLabel label="Cliente" thClassName="min-w-0" />
            <GlobalTableHeadLabel label="Cantiere" thClassName="min-w-0" />
            <GlobalTableHeadLabel label="Utilizzatore" thClassName="min-w-0" />
            <GlobalTableHeadLabel label="Attrezzatura" thClassName="min-w-0" />
            <GlobalTableHeadLabel label="Targa / Matricola" thClassName="w-[9.75rem] min-w-[9.75rem]" />
            <GestionaleListTableActionsHead />
          </>
        }
        empty={false}
        colSpan={8}
      >
        {rows.map((p) => (
          <tr key={p.id} className={`${dsTableRow} h-14 bg-white dark:bg-zinc-900/40`}>
            <td
              className={`whitespace-nowrap ${gestionaleListTableTd} font-mono text-xs font-semibold tabular-nums text-zinc-900 dark:text-zinc-100`}
            >
              <div className="flex flex-col items-center gap-1">
                <span>{p.numero}</span>
                {isPreventivoCollegato(p, lavorazioneId) ? <PreventivoCollegatoBadge /> : null}
              </div>
            </td>
            <td className={`whitespace-nowrap ${gestionaleListTableTd} text-xs tabular-nums text-zinc-600 dark:text-zinc-300`}>
              {fmtPreventivoDataTabella(p.dataCreazione)}
            </td>
            <td className={prevTableTdText}>
              <span className="line-clamp-2 break-words text-sm leading-snug">{p.cliente || "—"}</span>
            </td>
            <td className={`min-w-0 ${gestionaleListTableTd} text-zinc-700 dark:text-zinc-200`}>
              <span className="line-clamp-2 break-words text-xs leading-snug">{p.cantiere || "—"}</span>
            </td>
            <td className={`min-w-0 ${gestionaleListTableTd} text-zinc-700 dark:text-zinc-200`}>
              <span className="line-clamp-2 break-words text-xs leading-snug">{p.utilizzatore || "—"}</span>
            </td>
            <td className={`min-w-0 max-w-[1px] ${gestionaleListTableTd} text-zinc-700 dark:text-zinc-200`}>
              <span className="line-clamp-2 break-words text-sm leading-snug">{fmtPreventivoMarcaModello(p)}</span>
            </td>
            <td className={`min-w-0 ${gestionaleListTableTd}`}>
              <PreventivoIdentCell p={p} />
            </td>
            <td className={dsTableTdActions}>
              <div className={dsTableActionsGroup}>
                <IconActionButton label="Apri" className={dsTableActionBtnPrimary} onClick={() => onApriNeiPreventivi(p)}>
                  <svg className={dsTableActionGlyph} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2} aria-hidden>
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      d="M13.5 6H5.25A2.25 2.25 0 003 8.25v10.5A2.25 2.25 0 005.25 21h10.5A2.25 2.25 0 0018 18.75V10.5m-10.5 0L21 3m0 0h-5.25M21 3v5.25"
                    />
                  </svg>
                </IconActionButton>
              </div>
            </td>
          </tr>
        ))}
      </GestionaleListTable>
      ) : (
      <div className={`space-y-3 ${dsScrollbar}`}>
        {rows.map((p) => (
          <CardMobile key={p.id}>
            <div className="flex items-start justify-between gap-3">
              <div className="min-w-0 flex-1">
                <div className="flex items-center gap-2 min-w-0 flex-nowrap sm:flex-wrap">
                  <p className="font-mono text-xs font-semibold tabular-nums text-[color:var(--cab-text-muted)]">{p.numero}</p>
                  {isPreventivoCollegato(p, lavorazioneId) ? <PreventivoCollegatoBadge /> : null}
                </div>
                <p className="mt-1 text-sm font-semibold text-[color:var(--cab-text)]">{p.cliente || "—"}</p>
                <p className="mt-1 text-xs text-[color:var(--cab-text-muted)]">{fmtPreventivoMarcaModello(p)}</p>
              </div>
              <p className="shrink-0 text-xs tabular-nums text-[color:var(--cab-text-muted)]">
                {fmtPreventivoDataTabella(p.dataCreazione)}
              </p>
            </div>
            <dl className="mt-3 grid grid-cols-2 gap-x-3 gap-y-2 text-xs">
              <div>
                <dt className="text-[color:var(--cab-text-muted)]">Cantiere</dt>
                <dd className="font-medium text-[color:var(--cab-text)]">{p.cantiere || "—"}</dd>
              </div>
              <div>
                <dt className="text-[color:var(--cab-text-muted)]">Utilizzatore</dt>
                <dd className="font-medium text-[color:var(--cab-text)]">{p.utilizzatore || "—"}</dd>
              </div>
              <div className="col-span-2">
                <dt className="text-[color:var(--cab-text-muted)]">Targa / Matricola</dt>
                <dd className="mt-0.5">
                  <PreventivoIdentCell p={p} />
                </dd>
              </div>
            </dl>
            <CardMobileActions>
              <button
                type="button"
                className={dsTableActionTextBtnPrimary}
                onClick={() => onApriNeiPreventivi(p)}
              >
                Apri
              </button>
            </CardMobileActions>
          </CardMobile>
        ))}
      </div>
      )}
    </>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useId, useMemo, useRef, useState, type KeyboardEvent, type PointerEvent } from "react";
import { createPortal } from "react-dom";
import {
  useDropdownOutsideDismiss,
  useGlobalDropdownPortal,
} from "@/components/gestionale/global-input/use-global-dropdown-portal";
import { GestionaleSearchableSheetSelect } from "@/components/gestionale/global-input/gestionale-searchable-sheet-select";
import { HighlightSearchMatch } from "@/components/gestionale/global-input/highlight-search-match";
import {
  findExactMezzoForIngressoIdent,
  mezzoIngressoSuggestSecondaryLabel,
  suggestMezziForIngressoIdent,
  type SchedaIngressoIdentField,
} from "@/lib/schede/scheda-ingresso-ident-suggest";
import type { MezzoGestito } from "@/lib/mezzi/types";
import {
  globalAutocompleteAddBtnClass,
  globalAutocompleteDropdownPortalPanel,
  globalAutocompleteOptionClass,
  globalInputComboboxClearBtn,
  globalInputFieldDefault,
} from "@/lib/ui/global-input";
import { useClientHydrated } from "@/lib/ui/use-client-hydrated";
import { useDropdownFocusRestore } from "@/lib/ui/use-dropdown-focus-restore";
import { createSelectorSheetTapSelectHandlers } from "@/lib/selector-interaction/selector-sheet-tap-select";
import { useSelectorExclusiveGroup } from "@/lib/selector-interaction/use-selector-exclusive-group";
import { useSelectorFocusChain } from "@/lib/selector-interaction/use-selector-focus-chain";
import { useMaxMdDown } from "@/lib/ui/use-max-md-down";
import { scheduleFocusNextGestionaleField } from "@/lib/ui/gestionale-focus-navigation";

function identPlaceholder(field: SchedaIngressoIdentField): string {
  if (field === "targa") return "Cerca targa…";
  if (field === "matricola") return "Cerca matricola…";
  if (field === "vin") return "Cerca VIN…";
  return "Cerca scuderia…";
}

function normalizeIdentInput(field: SchedaIngressoIdentField, raw: string): string {
  return field === "vin" ? raw.trim().toUpperCase() : raw;
}

export function SchedaIngressoIdentAutocompleteField({
  field,
  label,
  value,
  siblingIdent = {},
  mezzi,
  readOnly,
  disabled,
  className = "",
  id: idProp,
  exclusiveGroup,
  onChange,
  onExactMezzoMatch,
}: {
  field: SchedaIngressoIdentField;
  label: string;
  value: string;
  siblingIdent?: { targa?: string; matricola?: string; nScuderia?: string; vin?: string };
  mezzi: readonly MezzoGestito[];
  readOnly?: boolean;
  disabled?: boolean;
  className?: string;
  id?: string;
  exclusiveGroup?: string;
  onChange: (value: string) => void;
  /** Chiamato quando targa/matricola/scuderia corrisponde a un mezzo registrato. */
  onExactMezzoMatch: (mezzo: MezzoGestito) => void;
}) {
  const autoId = useId();
  const inputId = idProp ?? autoId;
  const listboxId = `${inputId}-listbox`;
  const wrapRef = useRef<HTMLDivElement>(null);
  const dropdownRef = useRef<HTMLUListElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const sheetListScrollRef = useRef<HTMLDivElement>(null);
  const sheetSearchRef = useRef<HTMLInputElement>(null);
  const blurTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const skipBlurMatch = useRef(false);
  const skipSheetOpenOnFocusRef = useRef(false);
  const sheetQueryRef = useRef("");

  const hydrated = useClientHydrated();
  const isMobile = useMaxMdDown();
  const useMobileSheet = hydrated && isMobile && !readOnly;
  const placeholder = identPlaceholder(field);

  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const [focused, setFocused] = useState(false);
  const [sheetQuery, setSheetQuery] = useState("");

  useEffect(() => {
    sheetQueryRef.current = sheetQuery;
  }, [sheetQuery]);

  const { restoreFocus, captureFocus } = useDropdownFocusRestore(open);

  const desktopQuery = focused ? value : value;
  const suggestions = useMemo(
    () => suggestMezziForIngressoIdent(mezzi, field, useMobileSheet && open ? sheetQuery : desktopQuery),
    [mezzi, field, useMobileSheet, open, sheetQuery, desktopQuery],
  );

  const showDesktopDropdown = open && !readOnly && !disabled && !useMobileSheet && suggestions.length > 0;
  const sheetOpen = open && useMobileSheet;

  const { style: portalStyle, scrollInside, placementOriginClass } = useGlobalDropdownPortal({
    open: showDesktopDropdown,
    anchorRef: wrapRef,
    contentRef: dropdownRef,
    repositionDeps: [suggestions.length, value],
  });

  const closeUiOnly = useCallback(() => {
    if (blurTimer.current) clearTimeout(blurTimer.current);
    setOpen(false);
    setActiveIndex(-1);
    setFocused(false);
    setSheetQuery("");
  }, []);

  const resetUi = useCallback(() => {
    closeUiOnly();
    skipSheetOpenOnFocusRef.current = true;
    restoreFocus();
    requestAnimationFrame(() => {
      skipSheetOpenOnFocusRef.current = false;
    });
  }, [closeUiOnly, restoreFocus]);

  const { notifyOpening } = useSelectorExclusiveGroup(exclusiveGroup, closeUiOnly);

  const onFocusIn = useCallback((el: HTMLElement) => {
    void el;
  }, []);

  const captureTriggerFocus = useSelectorFocusChain({
    sheetOpen,
    sheetSearchRef,
    triggerRef: inputRef,
    onFocusIn,
  });

  useDropdownOutsideDismiss(showDesktopDropdown, wrapRef, dropdownRef, resetUi);

  const identPreview = useCallback(
    (mezzo: MezzoGestito) => {
      const ident =
        field === "targa"
          ? mezzo.targa?.trim() ?? ""
          : field === "matricola"
            ? mezzo.matricola?.trim() ?? ""
            : field === "vin"
              ? mezzo.vin?.trim() ?? ""
              : mezzo.numeroScuderia?.trim() ?? "";
      return ident || "—";
    },
    [field],
  );

  const tryExactMatch = useCallback(
    (nextValue: string) => {
      const hit = findExactMezzoForIngressoIdent(mezzi, field, nextValue, siblingIdent);
      if (hit) onExactMezzoMatch(hit);
    },
    [field, mezzi, onExactMezzoMatch, siblingIdent],
  );

  const commitFreeText = useCallback(
    (raw: string) => {
      const next = normalizeIdentInput(field, raw.trim());
      skipBlurMatch.current = true;
      onChange(next);
      resetUi();
      tryExactMatch(next);
    },
    [field, onChange, resetUi, tryExactMatch],
  );

  const closeSheetWithCommit = useCallback(() => {
    const pending = sheetQueryRef.current.trim();
    if (pending && pending !== value.trim()) {
      commitFreeText(pending);
      return;
    }
    // ponytail: no restoreFocus — il focus è già sul campo successivo (Enter / tap altrove).
    closeUiOnly();
  }, [closeUiOnly, commitFreeText, value]);

  const pickMezzo = useCallback(
    (mezzo: MezzoGestito) => {
      skipBlurMatch.current = true;
      const ident = identPreview(mezzo);
      onChange(ident === "—" ? "" : ident);
      resetUi();
      onExactMezzoMatch(mezzo);
    },
    [identPreview, onChange, onExactMezzoMatch, resetUi],
  );

  const pickMezzoFromSuggestion = useCallback(
    (mezzo: MezzoGestito) => {
      if (blurTimer.current) clearTimeout(blurTimer.current);
      pickMezzo(mezzo);
    },
    [pickMezzo],
  );

  const tryExactMatchOnBlur = useCallback(() => {
    if (skipBlurMatch.current) {
      skipBlurMatch.current = false;
      return;
    }
    tryExactMatch(value);
  }, [tryExactMatch, value]);

  const openSheet = useCallback(() => {
    if (disabled || readOnly) return;
    if (blurTimer.current) clearTimeout(blurTimer.current);
    if (open) return;
    notifyOpening();
    captureFocus();
    captureTriggerFocus();
    setSheetQuery("");
    setActiveIndex(-1);
    setOpen(true);
  }, [captureFocus, captureTriggerFocus, disabled, notifyOpening, open, readOnly]);

  const renderSuggestion = (mezzo: MezzoGestito, idx: number, variant: "dropdown" | "sheet") => (
    <SchedaIngressoIdentSuggestionItem
      key={mezzo.id}
      mezzo={mezzo}
      variant={variant}
      active={idx === activeIndex}
      ident={identPreview(mezzo)}
      query={variant === "sheet" ? sheetQuery : value}
      field={field}
      onPick={pickMezzoFromSuggestion}
      onHover={() => setActiveIndex(idx)}
    />
  );

  const onInputKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (useMobileSheet) return;
    if (e.key === "Escape") {
      resetUi();
      return;
    }
    if (!open && (e.key === "ArrowDown" || e.key === "ArrowUp")) {
      notifyOpening();
      setOpen(true);
      setActiveIndex(suggestions.length ? 0 : -1);
      e.preventDefault();
      return;
    }
    if (e.key === "ArrowDown" && suggestions.length) {
      e.preventDefault();
      setOpen(true);
      setActiveIndex((i) => (i + 1) % suggestions.length);
      return;
    }
    if (e.key === "ArrowUp" && suggestions.length) {
      e.preventDefault();
      setOpen(true);
      setActiveIndex((i) => (i <= 0 ? suggestions.length - 1 : i - 1));
      return;
    }
    if (e.key === "Enter" && open) {
      e.preventDefault();
      if (activeIndex < 0 && !value.trim()) {
        closeUiOnly();
        scheduleFocusNextGestionaleField(inputRef.current);
        return;
      }
      if (suggestions.length) {
        const idx = activeIndex >= 0 ? activeIndex : 0;
        pickMezzo(suggestions[idx]!);
      }
    }
  };

  const onSheetSearchKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Escape") {
      closeSheetWithCommit();
      return;
    }
    if (!suggestions.length) return;
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setActiveIndex((i) => (i + 1) % suggestions.length);
      return;
    }
    if (e.key === "ArrowUp") {
      e.preventDefault();
      setActiveIndex((i) => (i <= 0 ? suggestions.length - 1 : i - 1));
      return;
    }
    if (e.key === "Enter") {
      e.preventDefault();
      const q = sheetQuery.trim();
      if (activeIndex < 0 && !q) {
        closeSheetWithCommit();
        scheduleFocusNextGestionaleField(inputRef.current);
        return;
      }
      if (activeIndex >= 0 && activeIndex < suggestions.length) {
        pickMezzo(suggestions[activeIndex]!);
        return;
      }
      if (q) commitFreeText(q);
    }
  };

  const dropdownPortal =
    showDesktopDropdown && portalStyle ? (
      <ul
        ref={dropdownRef}
        id={listboxId}
        role="listbox"
        style={portalStyle}
        className={`${globalAutocompleteDropdownPortalPanel} p-1 ${placementOriginClass} ${
          scrollInside ? "overflow-y-auto" : "overflow-hidden"
        }`}
      >
        {suggestions.map((mezzo, idx) => renderSuggestion(mezzo, idx, "dropdown"))}
      </ul>
    ) : null;

  const sheetFreeText = sheetQuery.trim();
  const showClearBtn = Boolean(value.trim()) && !disabled && !readOnly;
  const triggerClassName = useMobileSheet
    ? `${globalInputFieldDefault} gestionale-combobox-trigger font-mono cursor-pointer caret-transparent${showClearBtn ? " pr-10" : ""}`
    : `${globalInputFieldDefault} font-mono${showClearBtn ? " pr-10" : ""}`;

  const handleClear = useCallback(() => {
    if (blurTimer.current) clearTimeout(blurTimer.current);
    skipBlurMatch.current = true;
    closeUiOnly();
    onChange("");
  }, [closeUiOnly, onChange]);

  return (
    <label htmlFor={inputId} className={`block text-xs ${className}`.trim()}>
      <span className="text-zinc-500 dark:text-zinc-400">{label}</span>
      <div ref={wrapRef} className="relative mt-1">
        <input
          ref={inputRef}
          id={inputId}
          className={triggerClassName}
          readOnly={readOnly || useMobileSheet || undefined}
          disabled={disabled}
          value={value}
          onChange={(e) => {
            if (useMobileSheet) return;
            onChange(normalizeIdentInput(field, e.target.value));
            notifyOpening();
            setOpen(true);
            setActiveIndex(-1);
          }}
          onMouseDown={useMobileSheet ? (e) => e.preventDefault() : undefined}
          onFocus={() => {
            if (useMobileSheet) {
              if (!skipSheetOpenOnFocusRef.current) openSheet();
              return;
            }
            notifyOpening();
            setFocused(true);
            setOpen(true);
          }}
          onBlur={() => {
            if (useMobileSheet) return;
            if (blurTimer.current) clearTimeout(blurTimer.current);
            blurTimer.current = setTimeout(() => {
              closeUiOnly();
              tryExactMatchOnBlur();
            }, 140);
          }}
          onClick={() => {
            if (useMobileSheet) openSheet();
          }}
          onKeyDown={onInputKeyDown}
          placeholder={placeholder}
          autoComplete="off"
          role={useMobileSheet ? "button" : "combobox"}
          aria-haspopup={useMobileSheet ? "listbox" : undefined}
          aria-expanded={useMobileSheet ? sheetOpen : showDesktopDropdown}
          aria-controls={listboxId}
          aria-autocomplete={useMobileSheet ? "none" : "list"}
          aria-readonly={useMobileSheet || undefined}
          enterKeyHint={useMobileSheet ? "search" : undefined}
        />
        {showClearBtn ? (
          <button
            type="button"
            className={globalInputComboboxClearBtn}
            aria-label={`Svuota ${label}`}
            tabIndex={-1}
            onMouseDown={(e) => e.preventDefault()}
            onClick={handleClear}
          >
            <svg className="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} aria-hidden>
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        ) : null}
        {typeof document !== "undefined" && dropdownPortal ? createPortal(dropdownPortal, document.body) : null}
        <GestionaleSearchableSheetSelect
          open={sheetOpen}
          onOpenChange={(next) => {
            if (!next) closeSheetWithCommit();
            else {
              notifyOpening();
              setOpen(true);
            }
          }}
          title={label}
          showSearch
          searchValue={sheetQuery}
          onSearchChange={(v) => {
            setSheetQuery(v);
            setActiveIndex(-1);
          }}
          searchPlaceholder={placeholder}
          searchAriaLabel={`Cerca in ${label}`}
          listScrollRef={sheetListScrollRef}
          searchInputRef={sheetSearchRef}
          onSearchKeyDown={onSheetSearchKeyDown}
          footer={
            sheetFreeText ? (
              <button
                type="button"
                className={globalAutocompleteAddBtnClass}
                onClick={() => commitFreeText(sheetFreeText)}
              >
                Usa «{sheetFreeText}»
              </button>
            ) : (
              <p className="px-1 text-center text-[11px] leading-snug text-[color:var(--cab-text-muted)]">
                Seleziona un mezzo dai suggerimenti o digita un valore nuovo
              </p>
            )
          }
        >
          <ul id={listboxId} role="listbox" aria-label={label}>
            {suggestions.length === 0 && sheetFreeText ? (
              <li className="px-3 py-2 text-xs text-[color:var(--cab-text-muted)]" role="presentation">
                Nessun mezzo corrispondente — puoi usare il valore digitato.
              </li>
            ) : null}
            {suggestions.map((mezzo, idx) => renderSuggestion(mezzo, idx, "sheet"))}
          </ul>
        </GestionaleSearchableSheetSelect>
      </div>
    </label>
  );
}

function SchedaIngressoIdentSuggestionItem({
  mezzo,
  variant,
  active,
  ident,
  query,
  field,
  onPick,
  onHover,
}: {
  mezzo: MezzoGestito;
  variant: "dropdown" | "sheet";
  active: boolean;
  ident: string;
  query: string;
  field: SchedaIngressoIdentField;
  onPick: (mezzo: MezzoGestito) => void;
  onHover: () => void;
}) {
  const touchClass = variant === "sheet" ? "min-h-11 touch-pan-y py-2.5 sm:min-h-0 sm:py-1.5" : "";
  const sheetTap =
    variant === "sheet" ? createSelectorSheetTapSelectHandlers(() => onPick(mezzo)) : null;

  return (
    <li role="presentation" className={variant === "sheet" ? "px-2 py-0.5" : "py-0.5"}>
      <button
        type="button"
        role="option"
        aria-selected={active}
        className={`${globalAutocompleteOptionClass(active)} ${touchClass}`.trim()}
        onPointerDown={
          sheetTap
            ? sheetTap.onPointerDown
            : (e: PointerEvent<HTMLButtonElement>) => {
                e.preventDefault();
                e.stopPropagation();
                onPick(mezzo);
              }
        }
        onPointerMove={sheetTap?.onPointerMove}
        onPointerUp={sheetTap?.onPointerUp}
        onPointerCancel={sheetTap?.onPointerCancel}
        onClick={(e) => {
          if (variant === "sheet") {
            e.preventDefault();
            e.stopPropagation();
          }
        }}
        onMouseEnter={onHover}
      >
        <span className="block font-medium text-[color:var(--cab-text)]">
          <HighlightSearchMatch text={ident} query={query} />
        </span>
        <span className="mt-0.5 block text-[10px] font-normal text-[color:var(--cab-text-muted)]">
          {mezzoIngressoSuggestSecondaryLabel(mezzo, field)}
        </span>
      </button>
    </li>
  );
}

