                    bundle: hub,
                    doc: hub.ingresso,
                    autore: currentUser,
                  });
                }}
              />
              <SchedaSectionHub
                title="Scheda lavorazioni"
                stato={statoUiSchedaLavorazioni(hub)}
                doc={hub.lavorazioni}
                canEdit={canEditWorkOrders}
                formatAutore={resolveSchedaAutore}
                onApri={apriSchedaLavorazioni}
                onCrea={() => startCreate("lavorazioni")}
