function RicambiPanel({
  doc,
  setDoc,
  lav,
  identLine,
  identParts,
  currentUser,
  addettiLista,
  onImmediatePersist,
}: {
  doc: SchedaRicambiDoc;
  setDoc: Dispatch<SetStateAction<SchedaRicambiDoc>>;
  lav: LavRow;
  identLine: string;
  identParts?: MezzoIdentificazioneParts | null;
  currentUser: string;
  addettiLista: string[];
  onImmediatePersist: (d: SchedaRicambiDoc) => void;
}) {
  const gestToast = useGestionaleToast();
  const { confirm: askConfirm, confirmDialog: ricambiConfirmDialog } = useGestionaleConfirm();
  const ro = doc.sorgente === "file_esterno";
  const qc = useQueryClient();
  const magazzinoQ = useMagazzinoRicambiUIQuery();
  const prodotti = magazzinoQ.data ?? [];

  async function applyRowMagazzino(r: RigaRicambioScheda) {
    if (!r.ricambioId) {
      gestToast.validation("Seleziona un ricambio dall'anagrafica magazzino o dai suggerimenti.");
      return;
    }
    if (r.scaricoMagazzinoApplicato) {
      gestToast.validation("Scarico già effettuato per questa riga.");
      return;
    }
    const ok = await askConfirm({
      title: "Confermare scarico magazzino?",
      message: `Scarico di ${r.quantita} pz. per ${r.ricambioNome}.`,
      confirmLabel: "Conferma scarico",
    });
    if (!ok) return;
    try {
      const res = await applyMagazzinoScaricoDaScheda({
        ricambioId: r.ricambioId!,
        lavorazioneId: lav.id,
        quantita: r.quantita,
        autore: currentUser,
        riepilogo: `Scheda ricambi · ${identLine}`,
        qc,
      });
      if (!res.ok) {
        gestToast.error(res.error, { module: "magazzino" });
        return;
      }
      const righe = doc.campi.righe.map((x) => (x.id === r.id ? { ...x, scaricoMagazzinoApplicato: true } : x));
      const now = new Date().toISOString();
      const u = currentUser.trim() || "Operatore";
      const nextDoc: SchedaRicambiDoc = {
        ...doc,
        campi: { ...doc.campi, righe },
        updatedAt: now,
        updatedBy: u,
      };
      setDoc(nextDoc);
      onImmediatePersist(nextDoc);
      gestToast.successOnce("scheda-scarico", GESTIONALE_TOAST.successDone);
    } catch (e) {
      gestToast.errorOnce("scheda-scarico", e, { module: "magazzino" });
    }
  }

  return (
    <div className="space-y-4">
      <SchedaRicambiFormBody
        value={{
          ...doc.campi,
          identificazioneMacchina: doc.campi.identificazioneMacchina.trim() || identLine,
        }}
        onChange={(campi) => setDoc((d) => ({ ...d, campi }))}
        readonly={ro}
        variant="editor"
        identParts={identParts}
        hubAutocomplete
        globalOpts={{ addettiLista, magazzino: prodotti, defaultAddetto: lav.addetto }}
        onScaricaMagazzino={applyRowMagazzino}
        confirmDestructive={(opts) =>
          askConfirm({
            title: opts.title,
            message: opts.message,
            destructive: true,
            confirmLabel: opts.confirmLabel ?? "Conferma",
          })
        }
      />
      {ricambiConfirmDialog}
    </div>
  );
}

"use client";

import { useCallback, useRef } from "react";
import { createPortal } from "react-dom";
import { GestionaleSearchField } from "@/components/gestionale/gestionale-search-field";
import {
  useDropdownOutsideDismiss,
  useGlobalDropdownPortal,
} from "@/components/gestionale/global-input/use-global-dropdown-portal";
import { globalAutocompleteDropdownPortalPanel } from "@/lib/ui/global-input";
import { dsInput } from "@/lib/ui/design-system";
import type { RicambioMagazzino } from "@/lib/magazzino/types";
import { ricambioCodiceForUi } from "@/lib/magazzino/ricambio-codice";

type RicambiMagSearchPortalProps = {
  value: string;
  onChange: (value: string) => void;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  hits: RicambioMagazzino[];
  onSelect: (p: RicambioMagazzino) => void;
  placeholder: string;
  ariaLabel: string;
};

export function RicambiMagSearchPortal({
  value,
  onChange,
  open,
  onOpenChange,
  hits,
  onSelect,
  placeholder,
  ariaLabel,
}: RicambiMagSearchPortalProps) {
  const wrapRef = useRef<HTMLDivElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const trimmed = value.trim();
  const showDropdown = open && trimmed.length > 0;
  const hasHits = hits.length > 0;

  const { style: portalStyle, scrollInside, placementOriginClass } = useGlobalDropdownPortal({
    open: showDropdown,
    anchorRef: wrapRef,
    contentRef: panelRef,
    repositionDeps: [hits.length, value],
  });

  const dismiss = useCallback(() => onOpenChange(false), [onOpenChange]);
  useDropdownOutsideDismiss(showDropdown, wrapRef, panelRef, dismiss);

  const portalPanel =
    showDropdown && portalStyle ? (
      <div ref={panelRef} style={portalStyle}>
        {hasHits ? (
          <ul
            role="listbox"
            className={`${globalAutocompleteDropdownPortalPanel} py-1 text-[11px] ${placementOriginClass} ${
              scrollInside ? "overflow-y-auto" : "overflow-hidden"
            }`}
          >
            {hits.map((p) => (
              <li key={p.id} role="presentation">
                <button
                  type="button"
                  role="option"
                  className="flex w-full min-w-0 flex-col px-3 py-2 text-left hover:bg-[color:color-mix(in_srgb,var(--cab-primary)_10%,var(--cab-surface))] dark:hover:bg-orange-950/30"
                  onPointerDown={(e) => {
                    e.preventDefault();
                    onSelect(p);
                  }}
                >
                  <span className="font-medium text-[color:var(--cab-text)]">{p.descrizione || "—"}</span>
                  <span className="text-[color:var(--cab-text-muted)]">
                    {(() => {
                      const codiceUi = ricambioCodiceForUi(p.codiceFornitoreOriginale);
                      const marca = p.marca?.trim() || "—";
                      return codiceUi ? `${codiceUi} · ${marca}` : marca;
                    })()}
                  </span>
                </button>
              </li>
            ))}
          </ul>
        ) : (
          <p
            role="status"
            className={`${globalAutocompleteDropdownPortalPanel} px-3 py-2 text-[11px] text-[color:var(--cab-text-muted)]`}
          >
            Nessun ricambio trovato.
          </p>
        )}
      </div>
    ) : null;

  return (
    <div ref={wrapRef} className="relative max-w-xl max-md:overflow-visible" data-ricambi-mag-search="1">
      <GestionaleSearchField
        wrapperClassName="w-full"
        placeholder={placeholder}
        value={value}
        onChange={(e) => {
          onChange(e.target.value);
          onOpenChange(true);
        }}
        onFocus={() => onOpenChange(true)}
        autoComplete="off"
        aria-label={ariaLabel}
      />
      {typeof document !== "undefined" && portalPanel ? createPortal(portalPanel, document.body) : null}
    </div>
  );
}

