                      <p className="mt-1 text-sm text-zinc-700 dark:text-zinc-200">{p.macchinaRiassunto || "—"}</p>
                      {(() => {
                        const telaioSub = preventivoOggettoTelaioSubline(p);
                        return telaioSub ? (
