"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useId,
  useRef,
  useState,
  useSyncExternalStore,
  type ReactNode,
  type RefObject,
} from "react";
import { GlobalLoadingOverlay } from "@/components/design-system/loading";
import { GLOBAL_LOADING_MESSAGES } from "@/lib/ui/global-loading-messages";
import { isBootInvestigationEnabled } from "@/lib/observability/boot-investigation-gate";
import { lazyTrackStoreUpdate } from "@/lib/observability/boot-investigation-lazy";
import { useBootInvestigationMount } from "@/lib/observability/use-boot-investigation-mount";
import {
  claimKey,
  isClaimWinning,
  isSurfaceActive,
  resolveOverlayMessage,
  resolveWinningSurface,
  type LoadingClaimRecord,
  type LoadingSurface,
} from "@/lib/ui/loading-manager";

const SHOW_DELAY_MS = 300;

type StackEntry = { id: number; message: string };

type LoadingManagerContextValue = {
  /** Stack overlay legacy (push imperativo). */
  message: string;
  active: boolean;
  push: (message: string) => () => void;
  setTopMessage: (message: string) => void;
  /** LoadingManager — claim per surface. */
  winningSurface: LoadingSurface | null;
  registerClaim: (surface: LoadingSurface, id: string, message?: string) => void;
  unregisterClaim: (surface: LoadingSurface, id: string) => void;
};

const LoadingManagerContext = createContext<LoadingManagerContextValue | null>(null);
const LoadingClaimsRefContext = createContext<RefObject<Map<string, LoadingClaimRecord>> | null>(null);
const LoadingClaimsSubscribeContext = createContext<((onStoreChange: () => void) => () => void) | null>(null);

function useDelayedActive(active: boolean, delayMs = SHOW_DELAY_MS): boolean {
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    if (!active) {
      // eslint-disable-next-line react-hooks/set-state-in-effect -- sync state in effect lifecycle
      setVisible(false);
      return;
    }
    const t = window.setTimeout(() => setVisible(true), delayMs);
    return () => window.clearTimeout(t);
  }, [active, delayMs]);
  return visible;
}

/** @deprecated Alias — stesso provider LoadingManager. */
export const GlobalLoadingProvider = LoadingManagerProvider;

export function LoadingManagerProvider({ children }: { children: ReactNode }) {
  useBootInvestigationMount("LoadingManagerProvider");
  const [stack, setStack] = useState<StackEntry[]>([]);
  const [winningSurface, setWinningSurface] = useState<LoadingSurface | null>(null);
  const [message, setMessage] = useState<string>(GLOBAL_LOADING_MESSAGES.default);
  const claimsRef = useRef<Map<string, LoadingClaimRecord>>(new Map());
  const claimListenersRef = useRef(new Set<() => void>());
  const idRef = useRef(0);
  const pushClaimIdRef = useRef(0);

  const notifyClaimListeners = useCallback(() => {
    claimListenersRef.current.forEach((listener) => listener());
  }, []);

  const syncDerivedFromClaims = useCallback(() => {
    const claimList = [...claimsRef.current.values()];
    setWinningSurface(resolveWinningSurface(claimList));
    setMessage(resolveOverlayMessage(claimList, GLOBAL_LOADING_MESSAGES.default));
    notifyClaimListeners();
  }, [notifyClaimListeners]);

  const subscribeClaims = useCallback((onStoreChange: () => void) => {
    claimListenersRef.current.add(onStoreChange);
    return () => {
      claimListenersRef.current.delete(onStoreChange);
    };
  }, []);

  const push = useCallback(
    (pushMessage: string) => {
      const stackId = ++idRef.current;
      const claimId = `push:${++pushClaimIdRef.current}`;
      const normalized = pushMessage.trim() || GLOBAL_LOADING_MESSAGES.default;
      setStack((s) => [...s, { id: stackId, message: normalized }]);
      claimsRef.current.set(claimKey("overlay", claimId), {
        surface: "overlay",
        id: claimId,
        message: normalized,
      });
      syncDerivedFromClaims();
      return () => {
        setStack((s) => s.filter((e) => e.id !== stackId));
        claimsRef.current.delete(claimKey("overlay", claimId));
        syncDerivedFromClaims();
      };
    },
    [syncDerivedFromClaims],
  );

  const setTopMessage = useCallback(
    (pushMessage: string) => {
      const normalized = pushMessage.trim() || GLOBAL_LOADING_MESSAGES.default;
      setStack((s) => {
        if (s.length === 0) return s;
        const next = [...s];
        next[next.length - 1] = { ...next[next.length - 1]!, message: normalized };
        return next;
      });
      const overlayClaims = [...claimsRef.current.values()].filter((c) => c.surface === "overlay");
      const last = overlayClaims[overlayClaims.length - 1];
      if (!last) return;
      claimsRef.current.set(claimKey("overlay", last.id), { ...last, message: normalized });
      syncDerivedFromClaims();
    },
    [syncDerivedFromClaims],
  );

  const registerClaim = useCallback(
    (surface: LoadingSurface, id: string, claimMessage?: string) => {
      claimsRef.current.set(claimKey(surface, id), {
        surface,
        id,
        message: claimMessage?.trim() || undefined,
      });
      syncDerivedFromClaims();
    },
    [syncDerivedFromClaims],
  );

  const unregisterClaim = useCallback(
    (surface: LoadingSurface, id: string) => {
      const key = claimKey(surface, id);
      if (!claimsRef.current.has(key)) return;
      claimsRef.current.delete(key);
      syncDerivedFromClaims();
    },
    [syncDerivedFromClaims],
  );

  const overlayActive = winningSurface === "overlay";
  const overlayVisible = useDelayedActive(overlayActive);

  const stackActive = stack.length > 0;
  const prevActiveRef = useRef(overlayActive);
  useEffect(() => {
    if (!isBootInvestigationEnabled()) return;
    if (prevActiveRef.current === overlayActive) return;
    lazyTrackStoreUpdate("globalLoading", prevActiveRef.current, overlayActive, {
      message,
      stackDepth: stack.length,
      winningSurface,
    });
    prevActiveRef.current = overlayActive;
  }, [overlayActive, message, stack.length, winningSurface]);

  const value = useMemo<LoadingManagerContextValue>(
    () => ({
      message,
      active: stackActive || overlayActive,
      push,
      setTopMessage,
      winningSurface,
      registerClaim,
      unregisterClaim,
    }),
    [message, stackActive, overlayActive, push, setTopMessage, winningSurface, registerClaim, unregisterClaim],
  );

  return (
    <LoadingClaimsSubscribeContext.Provider value={subscribeClaims}>
      <LoadingClaimsRefContext.Provider value={claimsRef}>
        <LoadingManagerContext.Provider value={value}>
          {children}
          <GlobalLoadingOverlay visible={overlayVisible} message={message} />
        </LoadingManagerContext.Provider>
      </LoadingClaimsRefContext.Provider>
    </LoadingClaimsSubscribeContext.Provider>
  );
}

export function useGlobalLoadingState(): { active: boolean; visible: boolean; message: string } {
  const ctx = useContext(LoadingManagerContext);
  const overlayActive = ctx?.winningSurface === "overlay";
  const visible = useDelayedActive(Boolean(overlayActive));
  if (!ctx) {
    return { active: false, visible: false, message: GLOBAL_LOADING_MESSAGES.default };
  }
  return {
    active: overlayActive,
    visible,
    message: ctx.message,
  };
}

/** API imperativa: `const release = show('…');` … `release()`. */
export function useShowGlobalLoading(): (message: string) => () => void {
  const ctx = useContext(LoadingManagerContext);
  if (!ctx) {
    return () => () => {};
  }
  return ctx.push;
}

/**
 * Registra un claim loading; auto-release on unmount / quando `active` è false.
 */
export function useLoadingClaim(
  surface: LoadingSurface,
  id: string,
  active: boolean,
  opts?: { message?: string },
): void {
  const ctx = useContext(LoadingManagerContext);
  const claimMessage = opts?.message;
  const registerClaim = ctx?.registerClaim;
  const unregisterClaim = ctx?.unregisterClaim;

  useEffect(() => {
    if (!registerClaim || !unregisterClaim || !active) return;
    registerClaim(surface, id, claimMessage);
    return () => unregisterClaim(surface, id);
  }, [registerClaim, unregisterClaim, surface, id, active, claimMessage]);
}

/** true se la surface vince la competizione globale. */
export function useLoadingSurfaceActive(surface: LoadingSurface): boolean {
  const ctx = useContext(LoadingManagerContext);
  return isSurfaceActive(ctx?.winningSurface ?? null, surface);
}

/** true se questo claim specifico è attivo e la sua surface vince. */
export function useIsWinningClaim(surface: LoadingSurface, id: string, active: boolean): boolean {
  const ctx = useContext(LoadingManagerContext);
  const claimsRef = useContext(LoadingClaimsRefContext);
  const subscribeClaims = useContext(LoadingClaimsSubscribeContext);
  const winningSurface = ctx?.winningSurface ?? null;

  const claimPresent = useSyncExternalStore(
    subscribeClaims ?? (() => () => {}),
    () => claimsRef?.current.has(claimKey(surface, id)) ?? false,
    () => false,
  );

  if (!active) return false;
  return isClaimWinning(winningSurface, claimsRef?.current ?? new Map(), surface, id) && claimPresent;
}

/**
 * Registra loading globale (overlay) mentre `message` è valorizzato (null/undefined = off).
 * Ritardo 300ms gestito dal provider overlay.
 */
export function useGlobalLoading(message: string | null | undefined): void {
  const claimId = useId();
  useLoadingClaim("overlay", claimId, Boolean(message?.trim()), { message: message?.trim() });
}

/** Sincronizza un singolo slot loading da bridge esterni (es. React Query opt-in). */
export function useGlobalLoadingContextBridge(): (message: string | null) => void {
  const ctx = useContext(LoadingManagerContext);
  const bridgeIdRef = useRef("rq-bridge");
  const activeRef = useRef(false);

  const registerClaim = ctx?.registerClaim;
  const unregisterClaim = ctx?.unregisterClaim;

  return useCallback(
    (bridgeMessage: string | null) => {
      if (!registerClaim || !unregisterClaim) return;
      if (activeRef.current) {
        unregisterClaim("overlay", bridgeIdRef.current);
        activeRef.current = false;
      }
      if (bridgeMessage?.trim()) {
        registerClaim("overlay", bridgeIdRef.current, bridgeMessage.trim());
        activeRef.current = true;
      }
    },
    [registerClaim, unregisterClaim],
  );
}

import "server-only";

import { aiService } from "@/lib/ai/runtime/service";
import { loadActiveKeys } from "@/lib/ai/runtime/config-store";
import { buildNoSelectableKeyError, selectBestKey } from "@/lib/ai/runtime/key-manager";
import { aiErrorMessage, classifyAiError } from "@/lib/ai/runtime/errors";
import { readRuntimeProviderDefault, readRuntimeTimeoutMs } from "@/lib/ai/runtime/env-reader";
import { getPdfPageCount, splitPdfIntoPageRangeChunks } from "@/lib/ai/pdf-page-ranges.server";
import { extractPdfTextPages, pageHasSufficientNativeText } from "@/lib/ai/pdf-text-pages.server";
import {
  listinoImportAiRowsSchema,
  listinoImportColumnMapSchema,
} from "@/lib/magazzino/listino-import/listino-import-schema";
import type { z } from "zod";
import {
  applyListinoColumnMap,
} from "@/lib/magazzino/listino-import/parse-listino-column-map";
import type { ListinoImportRawRow } from "@/lib/magazzino/listino-import/listino-import-types";
import {
  formatCaptureAnalyzeErrorMessage,
  isGeminiQuotaErrorMessage,
  resolveGeminiAnalyzeRetryDelayMs,
  GEMINI_API_USAGE_URL,
} from "@/lib/ai/gemini-retry-after";
import {
  LISTINO_PDF_CHUNK_DELAY_MS,
  LISTINO_PDF_MAX_CHUNKS,
  LISTINO_PDF_SINGLE_CALL_MAX_PAGES,
  resolveListinoPdfPagesPerChunk,
} from "@/lib/magazzino/listino-import/listino-import-types";
import { AI_PROMPT_BOUNDARY_GUARD } from "@/lib/ai/prompt-boundary-guard";

const LISTINO_PDF_SYSTEM = `Sei un assistente per officina meccanica. Estrai righe ricambi da listini fornitore PDF.
Per ogni riga restituisci codice articolo, descrizione, prezzo listino numerico (EUR), marca opzionale se presente.
Ignora intestazioni, totali, note legali.${AI_PROMPT_BOUNDARY_GUARD}`;

const LISTINO_COLUMNS_SYSTEM = `Mappa le colonne di un listino Excel/CSV italiano o inglese.
Indica indice colonna (0-based) per codice, descrizione, prezzo listino, marca opzionale.
headerRowIndex = riga intestazioni, dataStartRowIndex = prima riga dati.${AI_PROMPT_BOUNDARY_GUARD}`;

export type ListinoAiParseResult =
  | { ok: true; rows: ListinoImportRawRow[]; warnings: string[]; stats: ListinoPdfParseStats }
  | { ok: false; code: "not_configured" | "quota_exceeded" | "failed"; message: string };

export type ListinoPdfParseOptions = {
  /** Meno chiamate Gemini (es. indicizzazione Ricambi AI su listini lunghi). */
  pagesPerChunkMin?: number;
  chunkDelayMs?: number;
  maxQuotaRetriesPerChunk?: number;
};

export type ListinoPdfParseStats = {
  pageCount: number;
  chunkCount: number;
  chunksSucceeded: number;
  chunksFailed: number;
};

/** Stima chiamate Gemini prima dell'avvio — fail fast su listini troppo grandi per quota free. */
export async function estimateListinoPdfGeminiCalls(
  bytes: Uint8Array,
  options?: ListinoPdfParseOptions,
): Promise<{ pageCount: number; chunkCount: number; estimatedApiCalls: number }> {
  const pageCount = await getPdfPageCount(bytes);
  if (pageCount <= 0) return { pageCount: 0, chunkCount: 0, estimatedApiCalls: 0 };
  if (pageCount <= LISTINO_PDF_SINGLE_CALL_MAX_PAGES) {
    return { pageCount, chunkCount: 1, estimatedApiCalls: 1 };
  }
  const pagesPerChunk = resolveListinoPdfPagesPerChunk(pageCount, options);
  const chunkCount = Math.ceil(pageCount / pagesPerChunk);
  return { pageCount, chunkCount, estimatedApiCalls: chunkCount };
}

export const LISTINO_PREFLIGHT_MAX_ESTIMATED_CALLS = 18;

const LISTINO_CHUNK_QUOTA_RETRIES_DEFAULT = 4;

function formatListinoQuotaErrorMessage(raw: string): string {
  return `${formatCaptureAnalyzeErrorMessage(raw)} Piano free Gemini: limite basso su PDF multipagina — attendi 1–2 minuti tra i tentativi, verifica utilizzo su ${GEMINI_API_USAGE_URL}, oppure importa il listino via Excel in Magazzino.`;
}

type PdfChunkInput = {
  bytes: Uint8Array;
  fromPage: number;
  toPage: number;
};

type PdfChunkOutcome =
  | { ok: true; rows: ListinoImportRawRow[]; warnings: string[] }
  | { ok: false; timedOut: boolean; message: string };

function listinoAiFailureMessage(error: unknown, fallback: string): string {
  if (error instanceof Error && error.name === "TimeoutError") {
    return aiErrorMessage("AI_TIMEOUT");
  }
  const code = classifyAiError(error);
  return aiErrorMessage(code);
}

function isRetryableListinoChunkMessage(message: string): boolean {
  const upper = message.toUpperCase();
  return (
    upper.includes("TIMEOUT") ||
    upper.includes("429") ||
    upper.includes("QUOTA") ||
    upper.includes("RESOURCE_EXHAUSTED") ||
    upper.includes("RATE LIMIT")
  );
}

function summarizeListinoPdfFailures(failedRanges: string[], failureMessages: string[]): string {
  const unique = [...new Set(failureMessages.map((m) => m.trim()).filter(Boolean))];
  const reason = unique[0] ?? "Servizio IA non ha estratto righe dal PDF.";
  if (failedRanges.length === 0) return reason;
  const preview = failedRanges.slice(0, 4).join(", ");
  const extra = failedRanges.length > 4 ? ` (+${failedRanges.length - 4} blocchi)` : "";
  return `${reason} Blocchi non analizzati: ${preview}${extra}.`;
}

async function sleep(ms: number): Promise<void> {
  await new Promise((resolve) => setTimeout(resolve, ms));
}

function isTimeoutError(error: unknown): boolean {
  return error instanceof Error && error.name === "TimeoutError";
}

function normalizeListinoRow(
  row: { codice: string; descrizione: string; costo: number; marca?: string },
  marcaDefault: string,
): ListinoImportRawRow | null {
  const codice = row.codice.trim();
  const descrizione = row.descrizione.trim();
  if (!codice || !descrizione || !Number.isFinite(row.costo)) return null;
  return {
    codice,
    descrizione,
    costo: row.costo,
    marca: row.marca?.trim() || marcaDefault || undefined,
  };
}

function mergeListinoRows(chunks: ListinoImportRawRow[][]): ListinoImportRawRow[] {
  const seen = new Set<string>();
  const merged: ListinoImportRawRow[] = [];
  for (const rows of chunks) {
    for (const row of rows) {
      const key = row.codice.trim().toUpperCase();
      if (!key || seen.has(key)) continue;
      seen.add(key);
      merged.push(row);
    }
  }
  return merged;
}

function chunkPrompt(marcaDefault: string, fromPage: number, toPage: number, totalPages: number): string {
  const range =
    fromPage === toPage
      ? `pagina ${fromPage} di ${totalPages}`
      : `pagine ${fromPage}-${toPage} di ${totalPages}`;
  return `Marca listino: ${marcaDefault || "non specificata"}. Estrai righe ricambio (codice, descrizione, prezzo) da questo estratto PDF (${range}). Solo righe presenti in questo blocco.`;
}

function isFatalListinoChunkError(message: string): boolean {
  return (
    message.includes("AI_KEY") ||
    isGeminiQuotaErrorMessage(message) ||
    message.includes(aiErrorMessage("AI_CONFIG_MISSING"))
  );
}

/** ponytail: testo nativo → meno quota Gemini vs PDF multimodale; upgrade path: OCR bridge. */
async function buildListinoChunkUserContent(
  chunk: PdfChunkInput,
  marcaDefault: string,
  totalPages: number,
): Promise<Array<{ type: "text"; text: string } | { type: "file"; data: Buffer; mediaType: string }>> {
  const prompt = chunkPrompt(marcaDefault, chunk.fromPage, chunk.toPage, totalPages);
  try {
    const pages = await extractPdfTextPages(chunk.bytes);
    const sufficient = pages.filter((p) => pageHasSufficientNativeText(p.text)).length;
    const text = pages.map((p) => p.text).join("\n").trim();
    if (pages.length > 0 && sufficient >= Math.ceil(pages.length * 0.6) && text.length >= 200) {
      return [{ type: "text", text: `${prompt}\n\nTesto estratto dal PDF:\n${text}` }];
    }
  } catch {
    // fallback PDF multimodale
  }
  return [
    { type: "text", text: prompt },
    { type: "file", data: Buffer.from(chunk.bytes), mediaType: "application/pdf" },
  ];
}

async function parseListinoPdfChunkWithAi(
  chunk: PdfChunkInput,
  marcaDefault: string,
  totalPages: number,
  maxQuotaRetries: number,
): Promise<PdfChunkOutcome> {
  let lastMessage = "Analisi listino non riuscita.";
  for (let attempt = 0; attempt <= maxQuotaRetries; attempt += 1) {
    if (attempt > 0) {
      const delayMs = resolveGeminiAnalyzeRetryDelayMs(new Error(lastMessage), attempt - 1);
      await sleep(delayMs);
    }
    try {
      const userContent = await buildListinoChunkUserContent(chunk, marcaDefault, totalPages);
      const aiResult = await aiService.generateObject<z.infer<typeof listinoImportAiRowsSchema>>({
        schema: listinoImportAiRowsSchema,
        system: LISTINO_PDF_SYSTEM,
        messages: [
          {
            role: "user",
            content: userContent,
          },
        ],
        temperature: 0.2,
        timeoutMs: readRuntimeTimeoutMs(),
        operation: "listino_pdf_chunk",
        maxRetries: 0,
      });
      if (!aiResult.ok) {
        lastMessage = aiResult.message;
        if (aiResult.code === "AI_QUOTA_EXCEEDED" || isRetryableListinoChunkMessage(aiResult.message)) {
          if (attempt < maxQuotaRetries) continue;
          if (isGeminiQuotaErrorMessage(aiResult.message)) {
            return { ok: false, timedOut: false, message: formatListinoQuotaErrorMessage(aiResult.message) };
          }
        }
        return { ok: false, timedOut: aiResult.code === "AI_TIMEOUT", message: aiResult.message };
      }
      const object = aiResult.data.object;

      const rows = object.rows
        .map((r) => normalizeListinoRow(r, marcaDefault))
        .filter((r): r is ListinoImportRawRow => r != null);

      return { ok: true, rows, warnings: object.warnings ?? [] };
    } catch (error) {
      lastMessage = listinoAiFailureMessage(error, "Analisi listino non riuscita.");
      if (isRetryableListinoChunkMessage(lastMessage) && attempt < maxQuotaRetries) continue;
      if (isGeminiQuotaErrorMessage(lastMessage)) {
        return { ok: false, timedOut: false, message: formatListinoQuotaErrorMessage(lastMessage) };
      }
      return {
        ok: false,
        timedOut: isTimeoutError(error),
        message: lastMessage,
      };
    }
  }
  return {
    ok: false,
    timedOut: false,
    message: isGeminiQuotaErrorMessage(lastMessage)
      ? formatListinoQuotaErrorMessage(lastMessage)
      : lastMessage,
  };
}

async function parseChunkWithSplitRetry(
  chunk: PdfChunkInput,
  marcaDefault: string,
  totalPages: number,
  maxQuotaRetries: number,
): Promise<PdfChunkOutcome> {
  const first = await parseListinoPdfChunkWithAi(chunk, marcaDefault, totalPages, maxQuotaRetries);
  if (first.ok || !first.timedOut || chunk.fromPage >= chunk.toPage) return first;

  const pageCount = chunk.toPage - chunk.fromPage + 1;
  if (pageCount <= 1) return first;

  const subChunks = await splitPdfIntoPageRangeChunks(chunk.bytes, 1);
  if (subChunks.length <= 1) return first;

  const warnings: string[] = [];
  const rowBatches: ListinoImportRawRow[][] = [];
  for (const sub of subChunks) {
    const subOutcome = await parseListinoPdfChunkWithAi(sub, marcaDefault, totalPages, maxQuotaRetries);
    if (!subOutcome.ok) {
      return {
        ok: false,
        timedOut: subOutcome.timedOut,
        message: subOutcome.message,
      };
    }
    rowBatches.push(subOutcome.rows);
    warnings.push(...subOutcome.warnings);
  }

  warnings.push(
    `Blocco pagine ${chunk.fromPage}-${chunk.toPage} analizzato in sotto-blocchi dopo timeout.`,
  );
  return { ok: true, rows: mergeListinoRows(rowBatches), warnings };
}

async function runChunksSequential(
  chunks: PdfChunkInput[],
  marcaDefault: string,
  totalPages: number,
  chunkDelayMs: number,
  maxQuotaRetries: number,
): Promise<{ rows: ListinoImportRawRow[]; warnings: string[]; failedRanges: string[]; failureMessages: string[]; quotaExceeded: boolean }> {
  const warnings: string[] = [];
  const failedRanges: string[] = [];
  const failureMessages: string[] = [];
  const rowBatches: ListinoImportRawRow[][] = [];
  let quotaExceeded = false;

  for (let index = 0; index < chunks.length; index += 1) {
    const chunk = chunks[index]!;
    const outcome = await parseChunkWithSplitRetry(chunk, marcaDefault, totalPages, maxQuotaRetries);

    if (outcome.ok) {
      rowBatches.push(outcome.rows);
      warnings.push(...outcome.warnings);
    } else {
      failedRanges.push(
        chunk.fromPage === chunk.toPage ? `pagina ${chunk.fromPage}` : `pagine ${chunk.fromPage}-${chunk.toPage}`,
      );
      failureMessages.push(outcome.message);
      warnings.push(outcome.message);
      if (process.env.NODE_ENV === "development") {
        console.error("[listino-import] chunk failed", {
          fromPage: chunk.fromPage,
          toPage: chunk.toPage,
          message: outcome.message,
        });
      }
      if (isFatalListinoChunkError(outcome.message)) {
        quotaExceeded = isGeminiQuotaErrorMessage(outcome.message);
        break;
      }
    }

    if (index < chunks.length - 1) {
      await sleep(chunkDelayMs);
    }
  }

  return {
    rows: mergeListinoRows(rowBatches),
    warnings,
    failedRanges,
    failureMessages,
    quotaExceeded,
  };
}

export async function parseListinoPdfWithAi(
  bytes: Uint8Array,
  marcaDefault: string,
  options?: ListinoPdfParseOptions,
): Promise<ListinoAiParseResult> {
  const chunkDelayMs = options?.chunkDelayMs ?? LISTINO_PDF_CHUNK_DELAY_MS;
  const maxQuotaRetries = options?.maxQuotaRetriesPerChunk ?? LISTINO_CHUNK_QUOTA_RETRIES_DEFAULT;
  const provider = readRuntimeProviderDefault() as "google";
  const { keys } = await loadActiveKeys(provider);
  if (!selectBestKey(keys)) {
    const err = buildNoSelectableKeyError(keys);
    return {
      ok: false,
      code:
        err.code === "AI_QUOTA_EXCEEDED" || err.code === "AI_RATE_LIMIT"
          ? "quota_exceeded"
          : err.code === "AI_CONFIG_MISSING"
            ? "not_configured"
            : "failed",
      message: err.message,
    };
  }

  let pageCount: number;
  try {
    pageCount = await getPdfPageCount(bytes);
  } catch {
    return { ok: false, code: "failed", message: "PDF listino non leggibile o protetto." };
  }

  if (pageCount <= 0) {
    return { ok: false, code: "failed", message: "PDF listino senza pagine." };
  }

  if (pageCount <= LISTINO_PDF_SINGLE_CALL_MAX_PAGES) {
    const single = await parseChunkWithSplitRetry(
      { bytes, fromPage: 1, toPage: pageCount },
      marcaDefault,
      pageCount,
      maxQuotaRetries,
    );
    if (!single.ok) {
      return {
        ok: false,
        code: isGeminiQuotaErrorMessage(single.message) ? "quota_exceeded" : "failed",
        message: single.message,
      };
    }
    return {
      ok: true,
      rows: single.rows,
      warnings: single.warnings,
      stats: { pageCount, chunkCount: 1, chunksSucceeded: 1, chunksFailed: 0 },
    };
  }

  const pagesPerChunk = resolveListinoPdfPagesPerChunk(pageCount, options);
  const ranges = await splitPdfIntoPageRangeChunks(bytes, pagesPerChunk);
  if (ranges.length > LISTINO_PDF_MAX_CHUNKS) {
    return {
      ok: false,
      code: "failed",
      message: `Listino troppo grande (${pageCount} pagine). Suddividi il PDF o usa formato Excel/CSV.`,
    };
  }

  const { rows, warnings, failedRanges, failureMessages, quotaExceeded } = await runChunksSequential(
    ranges.map((r) => ({ bytes: r.bytes, fromPage: r.fromPage, toPage: r.toPage })),
    marcaDefault,
    pageCount,
    chunkDelayMs,
    maxQuotaRetries,
  );

  if (!rows.length) {
    return {
      ok: false,
      code: quotaExceeded || failureMessages.some((m) => isGeminiQuotaErrorMessage(m)) ? "quota_exceeded" : "failed",
      message: summarizeListinoPdfFailures(failedRanges, failureMessages),
    };
  }

  if (failedRanges.length > 0) {
    warnings.unshift(
      `Alcuni blocchi non analizzati: ${failedRanges.join(", ")}. Verifica le righe estratte.`,
    );
  } else if (ranges.length > 1) {
    warnings.unshift(`PDF analizzato in ${ranges.length} blocchi (${pageCount} pagine).`);
  }

  const chunkCount = ranges.length;
  const chunksFailed = failedRanges.length;
  return {
    ok: true,
    rows,
    warnings,
    stats: {
      pageCount,
      chunkCount,
      chunksSucceeded: chunkCount - chunksFailed,
      chunksFailed,
    },
  };
}

export async function mapListinoColumnsWithAi(
  matrix: unknown[][],
  marcaDefault: string,
): Promise<ListinoAiParseResult> {
  if (!(await aiService.getConfigurationStatus()).configured) {
    return {
      ok: false,
      code: "not_configured",
      message: "Servizio IA non configurato per mapping colonne.",
    };
  }

  const sample = JSON.stringify(matrix.slice(0, 12));

  try {
    const aiResult = await aiService.generateObject<z.infer<typeof listinoImportColumnMapSchema>>({
      schema: listinoImportColumnMapSchema,
      system: LISTINO_COLUMNS_SYSTEM,
      prompt: `Marca default: ${marcaDefault}. Sample: ${sample}`,
      temperature: 0.1,
      timeoutMs: readRuntimeTimeoutMs(),
      operation: "listino_column_map",
    });
    if (!aiResult.ok) {
      return { ok: false, code: "failed", message: aiResult.message };
    }
    const object = aiResult.data.object;

    if (object.codiceColumn == null || object.descrizioneColumn == null || object.costoColumn == null) {
      return { ok: false, code: "failed", message: "IA non ha identificato colonne codice/descrizione/prezzo." };
    }

    const rows = applyListinoColumnMap(matrix, {
      codiceColumn: object.codiceColumn,
      descrizioneColumn: object.descrizioneColumn,
      costoColumn: object.costoColumn,
      marcaColumn: object.marcaColumn,
      dataStartRowIndex: object.dataStartRowIndex,
    }).map((r) => ({ ...r, marca: r.marca || marcaDefault || undefined }));

    return { ok: true, rows, warnings: object.warnings ?? ["Mapping colonne via IA."] };
  } catch (error) {
    return {
      ok: false,
      code: "failed",
      message: listinoAiFailureMessage(error, "Mapping colonne IA non riuscito."),
    };
  }
}

import { profileDisplayName } from "@/lib/auth/profile-display-name";
import type { SupabaseClient } from "@/src/lib/supabase/browser-client";
import {
  auditContext,
  buildLogModificaSummary,
  mergePayloadWithSummary,
  type AuditLogContext,
} from "@/lib/gestionale-log/log-summary";
import { auditDiff, auditSnapshot } from "@/lib/audit/build-diff";
import { getOrCreateUndoSessionId } from "@/lib/gestionale-log/undo-session";
import { emitCabSyncEvent } from "@/lib/sync/cab-sync-bus";
import { AuditLogWriteError } from "@/lib/audit/errors";
import {
  buildDescriptionFromInput,
  buildTitleFromInput,
  mergePayloadWithSnapshot,
} from "@/lib/audit/build-message";
import { resolveAuditActor, requireUserActor } from "@/lib/audit/resolve-actor";
import { resolveRequestId } from "@/lib/audit/resolve-request-context";
import { rbacLogEntitaModule } from "@/lib/audit/resolve-module";
import type { AuditEventInput, AuditEventType } from "@/lib/audit/types";
import { errMessageFromSupabase } from "@/src/utils/supabaseErrorHandler";

function enrichPayloadWithUndoSession(payload: Record<string, unknown>): Record<string, unknown> {
  if (typeof window === "undefined") return payload;
  const sessionId = getOrCreateUndoSessionId();
  if (!sessionId) return payload;
  return { ...payload, undo_session_id: sessionId };
}

function buildPayloadFromInput(input: AuditEventInput): Record<string, unknown> {
  let payload: Record<string, unknown> = {};

  if (input.before != null && input.after != null) {
    payload = auditDiff(input.before, input.after, input.context as AuditLogContext) as Record<
      string,
      unknown
    >;
  } else if (input.after != null) {
    payload = auditSnapshot(input.after, input.context as AuditLogContext) as Record<string, unknown>;
  } else if (input.payload != null && typeof input.payload === "object" && !Array.isArray(input.payload)) {
    payload = { ...(input.payload as Record<string, unknown>) };
  } else if (input.payload != null) {
    payload = { data: input.payload };
  }

  if (input.context?.oggetto) {
    payload.context = { ...(payload.context as Record<string, unknown> | undefined), oggetto: input.context.oggetto };
  }

  return mergePayloadWithSnapshot(payload, input.snapshot);
}

async function resolveAutoreNomeSnapshot(
  client: SupabaseClient,
  autoreId: string | null,
): Promise<string | null> {
  if (!autoreId) return null;
  const { data } = await client
    .from("profiles")
    .select("nome, cognome")
    .eq("id", autoreId)
    .maybeSingle();
  if (!data) return null;
  const name = profileDisplayName({
    nome: (data as { nome?: string | null }).nome ?? "",
    cognome: (data as { cognome?: string | null }).cognome,
  });
  return name || null;
}

export async function recordAuditEvent(
  client: SupabaseClient,
  input: AuditEventInput,
): Promise<void> {
  const actor = await resolveAuditActor(client, {
    autoreId: input.autoreId,
    actorType: input.actorType,
    companyId: input.companyId,
  });

  const eventType: AuditEventType = input.eventType ?? "DATA_CHANGE";
  const autoreId =
    actor.actorType === "USER" ? requireUserActor(actor, `${input.entityType}/${input.entityId}`) : actor.autoreId;

  const payload = enrichPayloadWithUndoSession(buildPayloadFromInput(input));
  const summary = buildLogModificaSummary({
    entita: input.entityType,
    entita_id: input.entityId,
    azione: input.action,
    payload,
  });
  const mergedPayload = mergePayloadWithSummary(payload, summary);

  const title = buildTitleFromInput(input);
  const description = buildDescriptionFromInput(input);
  const module = input.module ?? rbacLogEntitaModule(input.entityType);
  const requestId = resolveRequestId(input.requestId);
  const autoreNomeSnapshot =
    actor.actorType === "USER" && autoreId
      ? await resolveAutoreNomeSnapshot(client, autoreId)
      : null;

  const row: Record<string, unknown> = {
    entita: input.entityType,
    entita_id: input.entityId,
    azione: input.action,
    autore_id: autoreId,
    autore_nome_snapshot: autoreNomeSnapshot,
    payload: mergedPayload,
    event_type: eventType,
    actor_type: actor.actorType,
    title,
    description,
    severity: input.severity ?? "info",
    module,
  };

  if (actor.companyId) row.company_id = actor.companyId;
  if (input.correlationId) row.correlation_id = input.correlationId;
  if (requestId) row.request_id = requestId;
  if (input.category) row.category = input.category;

  const { data, error } = await client.from("log_modifiche").insert(row).select("id").single();

  if (error) {
    throw new AuditLogWriteError(errMessageFromSupabase(error, { action: "create" }));
  }

  const logId = data?.id;
  if (typeof logId === "string" && logId && typeof window !== "undefined") {
    emitCabSyncEvent({
      type: "entity_created",
      entity: "log_modifiche",
      id: logId,
      table: "log_modifiche",
    });
  }
}

