import { buildGestionaleNav, type GestionaleNavHref } from "@/components/gestionale/gestionale-nav-config";
import { isStagingBlockedPathname, isStagingPublicSlice } from "@/lib/env/staging-public";
import {
  ACCESS_DENIED_PATH,
  CLIENTE_HOME_PATH,
  defaultHomePathForRole,
  isClienteRole,
  resolveFirstAccessiblePageHrefFromResolved,
  type RbacUser,
} from "@/lib/auth/rbac";
import type { RbacNavAccess, RbacSnapshotBound } from "@/src/lib/rbac/rbac-snapshot-access";

/** Normalizza path `from` (sicurezza base, senza default). */
export function sanitizePostLoginRequestedPath(raw: string | null | undefined): string | null {
  if (!raw) return null;
  const trimmed = raw.trim();
  if (!trimmed.startsWith("/") || trimmed.startsWith("//")) return null;
  if (trimmed.startsWith("/login")) return null;
  if (trimmed === ACCESS_DENIED_PATH || trimmed.startsWith(`${ACCESS_DENIED_PATH}/`)) return null;
  return trimmed;
}

function stagingBlocksRedirect(path: string): boolean {
  if (!isStagingPublicSlice()) return false;
  const pathOnly = path.split("?")[0] ?? path;
  return isStagingBlockedPathname(pathOnly);
}

/** Prima voce menu accessibile (ordine `GESTIONALE_NAV`), esclusi staging disabilitati. */
export function resolveFirstAccessibleNavHref(
  navAccess: RbacNavAccess,
  snapshot: RbacSnapshotBound,
): string {
  const items = buildGestionaleNav(snapshot.resolved, {
    hidePageKey: (pageKey) => navAccess.shouldHidePageKey(pageKey),
  });
  const first = items.find((item) => !item.disabled && navAccess.canAccessHref(item.href));
  return first?.href ?? resolveFirstAccessiblePageHrefFromResolved(snapshot.resolved);
}

export type ResolvePostLoginRedirectInput = {
  user: RbacUser | null;
  navAccess: RbacNavAccess | null;
  /** Query `from` o deep link esplicito post-login. */
  requestedPath?: string | null;
} & { snapshot?: RbacSnapshotBound | null };

/**
 * Destinazione post-login: deep link consentito, altrimenti prima pagina del menu,
 * fallback home per ruolo.
 */
export function resolvePostLoginRedirectPath(input: ResolvePostLoginRedirectInput): string {
  if (!input.user) return ACCESS_DENIED_PATH;

  if (isClienteRole(input.user)) {
    const requested = sanitizePostLoginRequestedPath(input.requestedPath);
    if (
      requested &&
      !stagingBlocksRedirect(requested) &&
      (requested === CLIENTE_HOME_PATH || requested.startsWith(`${CLIENTE_HOME_PATH}/`)) &&
      (!input.navAccess || input.navAccess.canAccessRoute(requested))
    ) {
      return requested;
    }
    return CLIENTE_HOME_PATH;
  }

  if (!input.navAccess || !input.snapshot) {
    return defaultHomePathForRole(input.user);
  }

  const requested = sanitizePostLoginRequestedPath(input.requestedPath);
  if (
    requested &&
    !stagingBlocksRedirect(requested) &&
    input.navAccess.canAccessRoute(requested)
  ) {
    return requested;
  }

  return resolveFirstAccessibleNavHref(input.navAccess, input.snapshot);
}

import type { GestionalePermissionModule } from "@/src/lib/permissions/gestionale-modules";
import type { ResolvedPageAccess } from "@/src/lib/rbac/resolve-page-access";

export type DashboardWidgetSection =
  | "kpi-header"
  | "health-score"
  | "activity"
  | "optional";

export const DASHBOARD_SECTION_ORDER: readonly DashboardWidgetSection[] = [
  "health-score",
  "kpi-header",
  "activity",
  "optional",
] as const;

export type DashboardWidgetId =
  | "operational-kpi-header"
  | "health-score"
  | "recent-activity"
  | "local-notes"
  | "recent-lavorazioni"
  | "recent-ricambi"
  | "operational-calendar";

export type DashboardWidgetDefinition = {
  id: DashboardWidgetId;
  section: DashboardWidgetSection;
  order: number;
  layout: "half" | "full";
  title: string;
  subtitle?: string;
  defaultCollapsed: boolean;
  requiredModule?: GestionalePermissionModule;
  hideInStaging?: boolean;
};

// ponytail: visibility = hideInStaging | moduleAllows(read) | always-on (local-notes, kpi-header)
export const DASHBOARD_WIDGET_REGISTRY: readonly DashboardWidgetDefinition[] = [
  {
    id: "operational-kpi-header",
    section: "kpi-header",
    order: 5,
    layout: "full",
    title: "Brief operativo",
    defaultCollapsed: false,
  },
  {
    id: "health-score",
    section: "health-score",
    order: 10,
    layout: "full",
    title: "Stato operativo",
    defaultCollapsed: false,
  },
  {
    id: "recent-activity",
    section: "activity",
    order: 50,
    layout: "full",
    title: "Attività recenti",
    defaultCollapsed: true,
    hideInStaging: true,
  },
  {
    id: "local-notes",
    section: "optional",
    order: 70,
    layout: "full",
    title: "Diario operativo",
    defaultCollapsed: true,
  },
] as const;

export function getDashboardWidgetDef(id: DashboardWidgetId): DashboardWidgetDefinition | undefined {
  return DASHBOARD_WIDGET_REGISTRY.find((w) => w.id === id);
}

const LEGACY_WIDGET_IDS: readonly DashboardWidgetId[] = [
  "recent-lavorazioni",
  "recent-ricambi",
  "operational-calendar",
];

function isWidgetVisible(
  def: DashboardWidgetDefinition,
  modules: ResolvedPageAccess["modules"],
  staging: boolean,
): boolean {
  if (def.hideInStaging && staging) return false;
  if (!def.requiredModule) return true;
  return modules[def.requiredModule].canRead;
}

export function isKnownDashboardWidgetId(id: string): id is DashboardWidgetId {
  return DASHBOARD_WIDGET_REGISTRY.some((w) => w.id === id) || LEGACY_WIDGET_IDS.includes(id as DashboardWidgetId);
}

export function resolveVisibleDashboardWidgets(input: {
  modules: ResolvedPageAccess["modules"] | null | undefined;
  staging: boolean;
}): DashboardWidgetDefinition[] {
  if (!input?.modules) return [];
  return DASHBOARD_WIDGET_REGISTRY.filter((def) => isWidgetVisible(def, input.modules!, input.staging)).sort(
    (a, b) => a.order - b.order,
  );
}

export function dashboardWidgetIds(widgets: readonly DashboardWidgetDefinition[]): DashboardWidgetId[] {
  return widgets.map((w) => w.id);
}

export function groupVisibleWidgetsBySection(
  widgets: readonly DashboardWidgetDefinition[],
  sectionOrder: readonly DashboardWidgetSection[] = DASHBOARD_SECTION_ORDER,
): Map<DashboardWidgetSection, DashboardWidgetDefinition[]> {
  const map = new Map<DashboardWidgetSection, DashboardWidgetDefinition[]>();
  for (const section of sectionOrder) {
    map.set(section, []);
  }
  for (const w of widgets) {
    const list = map.get(w.section) ?? [];
    list.push(w);
    map.set(w.section, list);
  }
  return map;
}

/** Stato operativo sopra brief operativo (tutti i breakpoint). */
export function resolveDashboardSectionOrder(__compactShell?: boolean): readonly DashboardWidgetSection[] {
  return DASHBOARD_SECTION_ORDER;
}

