export function getEntityCapabilities(entity: ImportEntity): EntityCapabilities {
  return IMPORT_ENTITY_CAPABILITIES[entity];
}

export function isImportExcelActive(entity: ImportEntity): boolean {
  return IMPORT_ENTITY_CAPABILITIES[entity].importExcel === "active";
}

export function isImportExcelExportOnly(entity: ImportEntity): boolean {
  return IMPORT_ENTITY_CAPABILITIES[entity].importExcel === "export_only";
}

export function isImportEntityStub(entity: ImportEntity): boolean {
  const cap = IMPORT_ENTITY_CAPABILITIES[entity].importExcel;
  return cap === "disabled" || cap === "export_only";
}

export function canExportEntity(entity: ImportEntity): boolean {
  return IMPORT_ENTITY_CAPABILITIES[entity].exportModes.length > 0;
}

export function defaultImportStrategyForEntity(
  entity: ImportEntity,
): import("@/lib/data-import/core/import-plugin").ImportStrategy {
  const mode = IMPORT_ENTITY_CAPABILITIES[entity].importWriteMode;
  if (mode === "merge") return "merge";
  if (mode === "insert") return "initial";
  if (mode === "update") return "incremental";
  return "incremental";
}

/** Matrice operativa per docs / supporto. */
export function operationalStatusMatrix(): Array<{
  entity: ImportEntity;
  label: string;
  slug: string;
  templateExport: string;
  importExcel: string;
  recovery: string;
}> {
  return (Object.keys(IMPORT_ENTITY_CAPABILITIES) as ImportEntity[]).map((entity) => {
    const cap = IMPORT_ENTITY_CAPABILITIES[entity];
    const importStatus =
      cap.importExcel === "active"
        ? "PROD"
        : cap.importExcel === "export_only"
          ? "ROADMAP"
          : "N/A";
    const exportStatus = cap.exportModes.length ? "PROD" : "N/A";
    return {
      entity,
      label: IMPORT_ENTITY_LABELS[entity],
      slug: routeSlugForEntity(entity),
      templateExport: exportStatus,
      importExcel: importStatus,
      recovery: cap.recovery === "CREATE_ONLY" ? "CREATE_ONLY" : cap.recovery,
    };
  });
}

import { formatPeriodMonthLabel } from "@/lib/report/report-manual-entries-map";
import type { TimesheetMonthKey } from "@/lib/dipendenti/types";

export function monthKeyFromDate(d: Date): TimesheetMonthKey {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  return `${y}-${m}`;
}

export function parseMonthKey(key: TimesheetMonthKey): { year: number; month: number } {
  const [y, m] = key.split("-").map(Number);
  return { year: y, month: m };
}

export function monthKeyToFirstDay(key: TimesheetMonthKey): string {
  return `${key}-01`;
}

export function formatMonthLabel(key: TimesheetMonthKey): string {
  return formatPeriodMonthLabel(monthKeyToFirstDay(key));
}

export function daysInMonth(key: TimesheetMonthKey): number {
  const { year, month } = parseMonthKey(key);
  return new Date(year, month, 0).getDate();
}

export type TimesheetDayInfo = {
  day: number;
  dateYmd: string;
  weekdayShort: string;
  weekdayLong: string;
  isWeekend: boolean;
};

const WEEKDAY_SHORT = ["dom", "lun", "mar", "mer", "gio", "ven", "sab"] as const;
const WEEKDAY_LONG = [
  "domenica",
  "lunedì",
  "martedì",
  "mercoledì",
  "giovedì",
  "venerdì",
  "sabato",
] as const;

export function buildMonthDays(key: TimesheetMonthKey): TimesheetDayInfo[] {
  const { year, month } = parseMonthKey(key);
  const count = daysInMonth(key);
  const out: TimesheetDayInfo[] = [];
  for (let day = 1; day <= count; day++) {
    const d = new Date(year, month - 1, day, 12, 0, 0, 0);
    const dow = d.getDay();
    const dateYmd = `${key}-${String(day).padStart(2, "0")}`;
    out.push({
      day,
      dateYmd,
      weekdayShort: WEEKDAY_SHORT[dow] ?? "",
      weekdayLong: WEEKDAY_LONG[dow] ?? "",
      isWeekend: dow === 0 || dow === 6,
    });
  }
  return out;
}

export function shiftMonthKey(key: TimesheetMonthKey, delta: number): TimesheetMonthKey {
  const { year, month } = parseMonthKey(key);
  const d = new Date(year, month - 1 + delta, 1);
  return monthKeyFromDate(d);
}

export function monthOptions(count = 24, anchor: Date = new Date()): { value: TimesheetMonthKey; label: string }[] {
  const out: { value: TimesheetMonthKey; label: string }[] = [];
  const d = new Date(anchor.getFullYear(), anchor.getMonth(), 1);
  for (let i = 0; i < count; i++) {
    const key = monthKeyFromDate(d);
    out.push({ value: key, label: formatMonthLabel(key) });
    d.setMonth(d.getMonth() - 1);
  }
  return out;
}

export function monthDateRange(key: TimesheetMonthKey): { from: string; to: string } {
  const from = monthKeyToFirstDay(key);
  const last = daysInMonth(key);
  const to = `${key}-${String(last).padStart(2, "0")}`;
  return { from, to };
}

export function monthKeyFromParts(year: number, month: number): TimesheetMonthKey {
  return `${year}-${String(month).padStart(2, "0")}`;
}

export function yearFromMonthKey(key: TimesheetMonthKey): number {
  return parseMonthKey(key).year;
}

export function yearDateRange(year: number): { from: string; to: string } {
  return { from: `${year}-01-01`, to: `${year}-12-31` };
}

const MONTH_NAMES_IT = [
  "Gennaio",
  "Febbraio",
  "Marzo",
  "Aprile",
  "Maggio",
  "Giugno",
  "Luglio",
  "Agosto",
  "Settembre",
  "Ottobre",
  "Novembre",
  "Dicembre",
] as const;

export function yearOptions(count = 5, anchor: Date = new Date()): { value: number; label: string }[] {
  const startYear = anchor.getFullYear();
  const out: { value: number; label: string }[] = [];
  for (let i = 0; i < count; i++) {
    const y = startYear - i;
    out.push({ value: y, label: String(y) });
  }
  return out;
}

export function monthOptionsForYear(_year: number): { value: number; label: string }[] {
  return MONTH_NAMES_IT.map((label, i) => ({ value: i + 1, label }));
}

export function setMonthKeyParts(key: TimesheetMonthKey, year: number, month: number): TimesheetMonthKey {
  return monthKeyFromParts(year, month);
}

export type TimesheetPeriodMode = "day" | "week" | "month";

export function dateYmdFromDate(d: Date): string {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

export function todayDateYmd(): string {
  return dateYmdFromDate(new Date());
}

export function currentMonthKey(): TimesheetMonthKey {
  return monthKeyFromDate(new Date());
}

export function isDateInMonthKey(dateYmd: string, monthKey: TimesheetMonthKey): boolean {
  return dateYmd.startsWith(`${monthKey}-`);
}

export function parseDateYmd(ymd: string): Date {
  const [y, m, d] = ymd.split("-").map(Number);
  return new Date(y, m - 1, d, 12, 0, 0, 0);
}

export function weekRangeFromAnchor(anchorYmd: string): { from: string; to: string } {
  const d = parseDateYmd(anchorYmd);
  const dow = d.getDay();
  const mondayOffset = dow === 0 ? -6 : 1 - dow;
  const monday = new Date(d);
  monday.setDate(d.getDate() + mondayOffset);
  const sunday = new Date(monday);
  sunday.setDate(monday.getDate() + 6);
  return { from: dateYmdFromDate(monday), to: dateYmdFromDate(sunday) };
}

export function dayRange(dayYmd: string): { from: string; to: string } {
  return { from: dayYmd, to: dayYmd };
}

export function resolvePeriodRange(
  periodMode: TimesheetPeriodMode,
  monthKey: TimesheetMonthKey,
  weekAnchor?: string,
  dayDate?: string,
): { from: string; to: string } {
  if (periodMode === "month") return monthDateRange(monthKey);
  if (periodMode === "week") {
    return weekRangeFromAnchor(weekAnchor ?? monthKeyToFirstDay(monthKey));
  }
  return dayRange(dayDate ?? monthKeyToFirstDay(monthKey));
}

export function buildPeriodDays(
  periodMode: TimesheetPeriodMode,
  monthKey: TimesheetMonthKey,
  weekAnchor?: string,
  dayDate?: string,
): TimesheetDayInfo[] {
  const { from, to } = resolvePeriodRange(periodMode, monthKey, weekAnchor, dayDate);
  const start = parseDateYmd(from);
  const end = parseDateYmd(to);
  const out: TimesheetDayInfo[] = [];
  const cursor = new Date(start);
  while (cursor <= end) {
    const dateYmd = dateYmdFromDate(cursor);
    const dow = cursor.getDay();
    out.push({
      day: cursor.getDate(),
      dateYmd,
      weekdayShort: WEEKDAY_SHORT[dow] ?? "",
      weekdayLong: WEEKDAY_LONG[dow] ?? "",
      isWeekend: dow === 0 || dow === 6,
    });
    cursor.setDate(cursor.getDate() + 1);
  }
  return out;
}

export function shiftWeekAnchor(anchorYmd: string, deltaWeeks: number): string {
  const d = parseDateYmd(anchorYmd);
  d.setDate(d.getDate() + deltaWeeks * 7);
  return dateYmdFromDate(d);
}

export function shiftDayDate(dayYmd: string, deltaDays: number): string {
  const d = parseDateYmd(dayYmd);
  d.setDate(d.getDate() + deltaDays);
  return dateYmdFromDate(d);
}

/** Giorni del mese che cadono nella settimana lun-dom ancorata a `weekAnchor`. */
export function filterMonthDaysByWeek(
  monthDays: readonly TimesheetDayInfo[],
  weekAnchor: string,
): TimesheetDayInfo[] {
  const { from, to } = weekRangeFromAnchor(weekAnchor);
  return monthDays.filter((d) => d.dateYmd >= from && d.dateYmd <= to);
}

/** `true` se spostare l'anchor di `delta` settimane lascia almeno un giorno nel mese. */
export function canShiftWeekAnchorInMonth(
  monthKey: TimesheetMonthKey,
  weekAnchor: string,
  deltaWeeks: number,
): boolean {
  const shifted = shiftWeekAnchor(weekAnchor, deltaWeeks);
  const monthDays = buildMonthDays(monthKey);
  return filterMonthDaysByWeek(monthDays, shifted).length > 0;
}

/** Anchor iniziale: oggi se nel mese, altrimenti primo giorno. */
export function resolveWeekAnchorForMonth(
  monthKey: TimesheetMonthKey,
  referenceDate: Date = new Date(),
): string {
  const today = dateYmdFromDate(referenceDate);
  return today.startsWith(`${monthKey}-`) ? today : monthKeyToFirstDay(monthKey);
}

import "server-only";

import sharp from "sharp";
import type { AnalyzeTraceEmitter } from "@/lib/document-capture/pipeline/analyze-trace-emitter";

type OcrMode = "single_line" | "block";

let workerPromise: Promise<import("tesseract.js").Worker | null> | null = null;

const TESSERACT_INIT_TIMEOUT_MS = 20_000;
const TESSERACT_RECOGNIZE_TIMEOUT_MS = 12_000;

async function initTesseractWorker(): Promise<import("tesseract.js").Worker | null> {
  try {
    const { createWorker, PSM } = await import("tesseract.js");
    const worker = await createWorker("ita+eng", 1, {
      logger: () => {},
    });
    await worker.setParameters({
      tessedit_pageseg_mode: PSM.SINGLE_LINE,
    });
    return worker;
  } catch {
    return null;
  }
}

async function getTesseractWorker(): Promise<import("tesseract.js").Worker | null> {
  if (!workerPromise) {
    workerPromise = Promise.race([
      initTesseractWorker(),
      new Promise<null>((resolve) => {
        setTimeout(() => resolve(null), TESSERACT_INIT_TIMEOUT_MS);
      }),
    ]);
  }
  return workerPromise;
}

/** ponytail: avvia init worker in background — riduce cold-start primo OCR. */
export function warmTesseractWorker(): void {
  void getTesseractWorker();
}

function mapTesseractConfidence(raw: number): number {
  const normalized = Math.max(0, Math.min(1, raw / 100));
  return Math.min(0.75, normalized);
}

async function preprocessForOcr(png: Buffer, mode: OcrMode): Promise<Buffer> {
  let pipeline = sharp(png).grayscale().normalize().sharpen({ sigma: 0.8 });
  if (mode === "single_line") {
    pipeline = pipeline.resize({ height: 48, fit: "contain", background: "#ffffff" });
  }
  return pipeline.png().toBuffer();
}

/** OCR locale Tesseract su crop PNG. */
export async function recognizePngBuffer(
  png: Buffer,
  mode: OcrMode = "single_line",
): Promise<{ text: string; confidence: number }> {
  const worker = await getTesseractWorker();
  if (!worker) return { text: "", confidence: 0 };
  const { PSM } = await import("tesseract.js");
  const preprocessed = await preprocessForOcr(png, mode);
  await worker.setParameters({
    tessedit_pageseg_mode: mode === "block" ? PSM.SINGLE_BLOCK : PSM.SINGLE_LINE,
  });
  let result: Awaited<ReturnType<typeof worker.recognize>>;
  try {
    result = await Promise.race([
      worker.recognize(preprocessed),
      new Promise<never>((_, reject) => {
        setTimeout(() => reject(new Error("tesseract_recognize_timeout")), TESSERACT_RECOGNIZE_TIMEOUT_MS);
      }),
    ]);
  } catch {
    return { text: "", confidence: 0 };
  }
  const text =
    mode === "block"
      ? result.data.text
          .replace(/\r\n/g, "\n")
          .split("\n")
          .map((line) => line.replace(/[^\S\n]+/g, " ").trim())
          .filter((line) => line.length > 0)
          .join("\n")
          .trim()
      : result.data.text.replace(/\s+/g, " ").trim();
  const confidence = mapTesseractConfidence(result.data.confidence);
  return { text, confidence };
}

export async function recognizePngBuffersPool(
  items: Array<{ id: string; png: Buffer; mode?: OcrMode }>,
  _concurrency = 1,
  trace?: AnalyzeTraceEmitter,
): Promise<Map<string, { text: string; confidence: number }>> {
  const out = new Map<string, { text: string; confidence: number }>();
  // ponytail: worker Tesseract singleton — recognize() non è concorrente; pool sequenziale
  if (items.length > 0) {
    trace?.emit("OCR_RECOGNIZE_START", "ok", { fieldCount: items.length });
  }
  for (const current of items) {
    const result = await recognizePngBuffer(current.png, current.mode ?? "single_line");
    out.set(current.id, result);
  }
  if (items.length > 0) {
    trace?.emit("OCR_RECOGNIZE_OK", "ok", { fieldCount: items.length });
  }
  return out;
}

