const RETRY_BACKOFF_MS = [1_000, 3_000] as const;
const HYBRID_MAX_MS = 35_000;

export type AnalyzeCaptureV41Result =
  | {
      ok: true;
      attemptId: string;
      durationMs: number;
      reused: boolean;
      documentModelVersionHash: string;
      fieldCount: number;
      traceId: string;
    }
  | {
      ok: false;
      code: "not_configured" | "auth_invalid" | "unreachable" | "not_finalized" | "failed" | "no_fields";
      message: string;
      errorType?: string;
      phase?: string;
      detail?: string;
      traceId?: string;
      correlationId?: string;
    };

async function countCaptureFields(captureId: string): Promise<number> {
  const sb = await createSupabaseServerUserClient();
  const { count } = await sb
    .from("document_capture_fields")
    .select("id", { count: "exact", head: true })
    .eq("document_capture_id", captureId);
  return count ?? 0;
}

function legacyToExtractionResult(
  attemptId: string,
  legacy: CaptureExtractionResult,
  meta: ExtractionResult["modelMetadata"],
): ExtractionResult {
  const fields = listCaptureExtractionFields(legacy.fields).map((field, idx) => ({
    key: field.key,
    value: field.value,
    confidence: field.confidence,
    pageIndex: Math.min(idx, Math.max(0, (meta.pageCount ?? 1) - 1)),
  }));
  return {
    attemptId,
    promptContractId: schedaOfficinaPromptContract.id,
    outputSchemaVersion: schedaOfficinaPromptContract.outputSchemaVersion,
    fields,
    modelMetadata: meta,
  };
}

async function sleep(ms: number): Promise<void> {
  await new Promise((resolve) => setTimeout(resolve, ms));
}

function buildAnalyzeFailure(input: {
  code: Extract<AnalyzeCaptureV41Result, { ok: false }>["code"];
  aiCode?: AiErrorCode;
  errorType?: string;
  message: string;
  detail: string;
  phase?: string;
  traceId?: string;
  correlationId?: string;
}): Extract<AnalyzeCaptureV41Result, { ok: false }> {
  return {
    ok: false,
    code: input.code,
    message: input.message,
    errorType: input.errorType ?? (input.aiCode ? mapAiErrorToLegacyErrorType(input.aiCode) : undefined),
    phase: input.phase,
    detail: input.detail,
    traceId: input.traceId,
    correlationId: input.correlationId,
  };
}

export type AnalyzeDocumentCaptureV41Options = {
  correlationId?: string;
  bytes?: Uint8Array;
  mime?: string;
  onPhase?: AnalyzeTraceListener;
  trace?: AnalyzeTrace;
};

export async function analyzeDocumentCaptureV41(
  captureId: string,
  userId: string,
  options?: AnalyzeDocumentCaptureV41Options,
): Promise<AnalyzeCaptureV41Result> {
  const correlationId = options?.correlationId;
  const trace =
    options?.trace ??
    createAnalyzeTrace({
      captureId,
      correlationId,
      companyId: null,
      pipelineVersion: CAPTURE_PIPELINE_VERSION,
      onPhase: options?.onPhase,
    });
  if (!options?.trace) {
    trace.emit("START", "ok");
  }

  const budget = new AnalyzeTimeoutBudget();
  const hybridEnabled = isDocumentCaptureHybridExtractionEnabled();

  const sb = await createSupabaseServerUserClient();
  const { data: capture, error } = await sb
    .from("document_capture")
    .select("id, company_id, storage_path, finalized_at, mime, capture_version, status")
    .eq("id", captureId)
    .maybeSingle();

  if (error || !capture?.finalized_at) {
    trace.emit("END_FAIL", "fail", { errorCode: "not_finalized", detail: "Documento non finalizzato." });
    return { ok: false, code: "not_finalized", message: "Documento non finalizzato.", traceId: trace.traceId };
  }

  const idempotencyKey = buildPipelineIdempotencyKey(
    "ai_extract",
    captureId,
    buildPipelineIdempotencySuffix({
      pipelineVersion: CAPTURE_PIPELINE_VERSION,
      captureVersion: capture.capture_version,
    }),
  );
  const existing = await findPipelineExecution(idempotencyKey);
  if (existing?.status === "completed" && existing.resultRef) {
    const fieldCount = await countCaptureFields(captureId);
    if (fieldCount > 0) {
      const doc = await sb
        .from("document_capture")
        .select("document_model")
        .eq("id", captureId)
        .maybeSingle();
      const hash =
        (doc.data?.document_model as { metadata?: { contentHash?: string } } | null)?.metadata?.contentHash ?? "";
      trace.emit("END_OK", "ok", { fieldCount, detail: "reused_pipeline_execution" });
      return {
        ok: true,
        attemptId: existing.resultRef,
        durationMs: 0,
        reused: true,
        documentModelVersionHash: hash,
        fieldCount,
        traceId: trace.traceId,
      };
    }
  }

  trace.emit("PREREQUISITES_START", "ok", { companyId: capture.company_id });
  let prereq: Awaited<ReturnType<typeof validateRuntimePrerequisites>> | null = null;
  const prereqPromise = validateRuntimePrerequisites({ requireGemini: true, requireOcr: false })
    .then((value) => {
      prereq = value;
      trace.setProviderMeta({
        providerModel: value.modelId,
        providerKeyId: value.keyId,
        providerKeySlot: value.keySlot,
      });
      if (value.ocrWarning) {
        trace.emit("HYBRID_SKIP", "skip", { detail: value.ocrWarning });
      }
      trace.emit("PREREQUISITES_OK", "ok", {
        providerModel: value.modelId,
        providerKeyId: value.keyId,
        providerKeySlot: value.keySlot,
      });
      return value;
    })
    .catch((e) => {
      if (e instanceof PrerequisitesAnalyzeError) {
        trace.fail("PREREQUISITES_FAIL", e);
        trace.emit("END_FAIL", "fail", { errorCode: "not_configured", detail: e.detail });
        throw e;
      }
      throw e;
    });

  let bytes = options?.bytes;
  let mime = options?.mime;

  if (!bytes) {
    trace.emit("DOWNLOAD_STORAGE_START", "ok", {
      storagePath: capture.storage_path,
      companyId: capture.company_id,
    });
    const downloadPromise = sb.storage.from(STORAGE_BUCKETS.documentCapture).download(capture.storage_path);
    try {
      const [, fileResult] = await Promise.all([prereqPromise, downloadPromise]);
      const { data: fileData, error: dlError } = fileResult;
      if (dlError || !fileData) {
        const classified = classifyStorageDownloadError(
          dlError,
          Boolean(fileData),
          STORAGE_BUCKETS.documentCapture,
          "analisi documento",
        );
        trace.fail("DOWNLOAD_STORAGE_FAIL", dlError ?? new Error(classified.message), {
          errorCode: classified.code,
          storagePath: capture.storage_path,
        });
        await mutateCaptureWithEvent({
          captureId,
          eventType: "analyze_failed",
          idempotencyKey: `analyze_failed:download:${capture.capture_version}`,
          payload: {
            errorCode: classified.code,
            traceId: trace.traceId,
            detail: classified.message,
            phase: "DOWNLOAD_STORAGE_FAIL",
          },
          newStatus: "failed",
        });
        trace.emit("END_FAIL", "fail", { errorCode: classified.code });
        return buildAnalyzeFailure({
          code: "failed",
          aiCode: "AI_STORAGE_ERROR",
          message: classified.message,
          detail: classified.message,
          phase: "DOWNLOAD_STORAGE_FAIL",
          traceId: trace.traceId,
          correlationId,
        });
      }
      bytes = new Uint8Array(await fileData.arrayBuffer());
      mime = normalizeCaptureMime({
        mime: capture.mime ?? fileData.type,
        fileName: capture.storage_path.split("/").pop(),
        bytes,
      });
      trace.emit("DOWNLOAD_STORAGE_OK", "ok", {
        fileMime: mime,
        fileSize: bytes.byteLength,
        storagePath: capture.storage_path,
      });
    } catch (e) {
      if (e instanceof PrerequisitesAnalyzeError) {
        return buildAnalyzeFailure({
          code: "not_configured",
          aiCode: "AI_CONFIG_MISSING",
          errorType: "AI_CONFIG_MISSING",
          message: e.userMessage,
          detail: e.detail,
          phase: e.phase,
          traceId: trace.traceId,
          correlationId,
        });
      }
      throw e;
    }
  } else {
    try {
      await prereqPromise;
      mime =
        mime ??
        normalizeCaptureMime({
          mime: capture.mime ?? "application/octet-stream",
          fileName: capture.storage_path.split("/").pop(),
          bytes,
        });
      if (!options?.trace) {
        trace.emit("DOWNLOAD_STORAGE_OK", "ok", {
          fileMime: mime,
          fileSize: bytes.byteLength,
          storagePath: capture.storage_path,
          detail: "bytes_provided",
        });
      }
    } catch (e) {
      if (e instanceof PrerequisitesAnalyzeError) {
        return buildAnalyzeFailure({
          code: "not_configured",
          aiCode: "AI_CONFIG_MISSING",
          errorType: "AI_CONFIG_MISSING",
          message: e.userMessage,
          detail: e.detail,
          phase: e.phase,
          traceId: trace.traceId,
          correlationId,
        });
      }
      throw e;
    }
  }

  const geminiReady = Boolean(prereq);
  if (!prereq) {
    try {
      prereq = await prereqPromise;
    } catch {
      // handled by geminiReady guard below
    }
  }

  await mutateCaptureWithEvent({
    captureId,
    eventType: "analyze_started",
    idempotencyKey: `analyze_started:${capture.capture_version}`,
    payload: { captureVersion: capture.capture_version, pipeline: "v4.1", traceId: trace.traceId },
    newStatus: "analyzing",
  });

  const plugin = ensureSchedaOfficinaPluginRegistered();
  const t0 = performance.now();

  let pipelineState = markUploadUploaded({ ...INITIAL_PIPELINE_STATE });

  trace.emit("PARSE_START", "ok", { fileMime: mime });
  let pageObjects: Awaited<ReturnType<typeof parsePhysicalPages>>;
  try {
    pageObjects = await parsePhysicalPages(bytes, mime);
  } catch (e) {
    const detail = errorDetailFromUnknown(e);
    trace.fail("PARSE_FAIL", e, { fileMime: mime });
    await mutateCaptureWithEvent({
      captureId,
      eventType: "analyze_failed",
      idempotencyKey: `analyze_failed:parse:${capture.capture_version}`,
      payload: { errorCode: "physical_parse_failed", mime, traceId: trace.traceId, detail, phase: "PARSE_FAIL" },
      newStatus: "failed",
    });
    trace.emit("END_FAIL", "fail", { errorCode: "physical_parse_failed" });
    return buildAnalyzeFailure({
      code: "failed",
      message: detail,
      detail,
      phase: "PARSE_FAIL",
      traceId: trace.traceId,
      correlationId,
    });
  }
  trace.emit("PARSE_OK", "ok", { fileMime: mime });

  trace.emit("PRELOAD_START", "ok");
  const preloadPromise = (async () => {
    const [magazzino, mezzi, loadedPipelineState] = await Promise.all([
      fetchCaptureMagazzinoCatalog(),
      fetchCaptureMezziCatalog(),
      loadPipelineState(captureId),
    ]);
    const resolutionContext = await loadResolutionRuntimeContext(sb, capture.company_id, {
      magazzino,
      mezzi,
    });
    trace.emit("PRELOAD_OK", "ok");
    return { magazzino, mezzi, resolutionContext, pipelineState: loadedPipelineState };
  })();

  let hybridResult: HybridExtractionResult | null = null;

  if (hybridEnabled) {
    trace.emit("HYBRID_START", "ok");
    budget.assertRemaining("hybrid");
    const hybridMs = budget.allocate("hybrid", HYBRID_MAX_MS);
    const hybridRun = await runHybridExtractionWithTimeout({
      bytes,
      mime,
      pageObjects,
      timeoutMs: hybridMs,
      trace,
    });
    if (hybridRun.status === "ok") {
      hybridResult = hybridRun.data;
      trace.emit("HYBRID_OK", "ok", {
        fieldCount: hybridRun.data.mergedPrefill.length,
        detail: hybridRun.data.needsGemini ? "needs_gemini" : "prefill_sufficient",
      });
    } else if (hybridRun.status === "skip") {
      trace.emit("HYBRID_SKIP", "skip", { detail: hybridRun.reason });
    } else {
      trace.emit("HYBRID_FAIL", "fail", { detail: hybridRun.error });
    }
  } else {
    trace.emit("HYBRID_SKIP", "skip", { detail: "hybrid_disabled" });
  }

  if (!geminiReady && (!hybridResult || hybridResult.mergedPrefill.length === 0)) {
    trace.emit("END_FAIL", "fail", { errorCode: "AI_CONFIG_MISSING" });
    return buildAnalyzeFailure({
      code: "not_configured",
      aiCode: "AI_CONFIG_MISSING",
      errorType: "AI_CONFIG_MISSING",
      message: userMessageForAiError("AI_CONFIG_MISSING"),
      detail: "Gemini non configurato e hybrid senza prefill",
      phase: "PREREQUISITES_FAIL",
      traceId: trace.traceId,
      correlationId,
    });
  }

  let lastError: unknown;
  let attemptId = "";
  let usage: { inputTokens?: number; outputTokens?: number; totalTokens?: number } | undefined;
  let geminiUsed = false;
  let hybridMetadata: Record<string, unknown> | undefined;
  const retryCount = RETRY_BACKOFF_MS.length;

  for (let retryAttempt = 0; retryAttempt <= RETRY_BACKOFF_MS.length; retryAttempt += 1) {
    try {
      let object: CaptureExtractionResult;

      if (hybridResult && !hybridResult.needsGemini && hybridResult.mergedPrefill.length > 0) {
        object = hybridFieldsToCaptureExtraction(hybridResult.mergedPrefill, hybridResult.schedaTipo);
        hybridMetadata = {
          hybrid: {
            geminiUsed: false,
            schedaTipoDetected: hybridResult.schedaTipo,
            pdfTextFieldCount: hybridResult.pdfTextFields.length,
            templateOcrFieldCount: hybridResult.templateOcrFields.length,
          },
        };
      } else if (prereq) {
        geminiUsed = true;
        trace.setRetry(retryAttempt, retryCount);
        const userPrompt =
          hybridResult?.geminiUserPrompt ??
          schedaOfficinaPromptContract.userPromptTemplate ??
          SCHEDA_OFFICINA_EXTRACTION_USER;
        const documentPart = buildGeminiCaptureDocumentPart(bytes, mime);
        trace.emit("GEMINI_PAYLOAD_OK", "ok", { fileSize: bytes.byteLength, fileMime: mime });
        trace.emit("GEMINI_REQUEST", "ok", {
          retryAttempt,
          providerModel: prereq.modelId,
          providerKeyId: prereq.keyId,
          providerKeySlot: prereq.keySlot,
        });

        budget.assertRemaining("gemini");
        const geminiTimeoutMs = budget.allocate("gemini", budget.remainingMs());

        const aiResult = await aiService.analyzeDocument<CaptureExtractionResult>({
          schema: captureExtractionSchema,
          system: schedaOfficinaPromptContract.systemPrompt,
          userContent: [
            {
              role: "user",
              content: [{ type: "text", text: userPrompt }, documentPart],
            },
          ],
          temperature: 0.2,
          timeoutMs: geminiTimeoutMs,
        });
        if (!aiResult.ok) {
          throw new GeminiAnalyzeError(aiResult.code, aiResult.message);
        }

        const parsed = captureExtractionSchema.safeParse(aiResult.data.object);
        if (!parsed.success) {
          throw new ValidationAnalyzeError(parsed.error.message);
        }

        const geminiObject = parsed.data;
        usage = aiResult.data.usage;
        const response = aiResult.data.response;
        trace.emit("GEMINI_RESPONSE", "ok", {
          retryAttempt,
          inputTokens: usage?.inputTokens,
          outputTokens: usage?.outputTokens,
          totalTokens: usage?.totalTokens,
        });

        const geminiFields = captureResultToHybridFields(listCaptureExtractionFields(geminiObject.fields));
        const merged = mergeWithGeminiFields(hybridResult?.mergedPrefill ?? [], geminiFields);
        object = hybridFieldsToCaptureExtraction(merged, geminiObject.schedaTipo ?? hybridResult?.schedaTipo ?? null);
        if (geminiObject.schedaTipo) object.schedaTipo = geminiObject.schedaTipo;
        if (geminiObject.warnings?.length) object.warnings = geminiObject.warnings;
        hybridMetadata = {
          hybrid: {
            geminiUsed: true,
            schedaTipoDetected: hybridResult?.schedaTipo ?? geminiObject.schedaTipo ?? null,
            pdfTextFieldCount: hybridResult?.pdfTextFields.length ?? 0,
            templateOcrFieldCount: hybridResult?.templateOcrFields.length ?? 0,
            prefillFieldCount: hybridResult?.mergedPrefill.length ?? 0,
          },
          providerRequestId:
            response && typeof response === "object" && "id" in response
              ? String((response as { id?: string }).id ?? "")
              : null,
        };
      } else if (hybridResult && hybridResult.mergedPrefill.length > 0) {
        object = hybridFieldsToCaptureExtraction(hybridResult.mergedPrefill, hybridResult.schedaTipo);
        hybridMetadata = {
          hybrid: {
            geminiUsed: false,
            schedaTipoDetected: hybridResult.schedaTipo,
            pdfTextFieldCount: hybridResult.pdfTextFields.length,
            templateOcrFieldCount: hybridResult.templateOcrFields.length,
          },
        };
      } else {
        trace.emit("END_FAIL", "fail", { errorCode: "no_fields" });
        return {
          ok: false,
          code: "no_fields",
          message: "Nessun dato letto dalla scheda. Verifica che foto o PDF siano nitidi e riprova.",
          traceId: trace.traceId,
          correlationId,
        };
      }

      const { count } = await sb
        .from("document_capture_attempts")
        .select("id", { count: "exact", head: true })
        .eq("document_capture_id", captureId);
      const attemptNumber = (count ?? 0) + 1;
      const providerRequestId =
        hybridMetadata && "providerRequestId" in hybridMetadata
          ? String(hybridMetadata.providerRequestId ?? "")
          : null;

      const durationMs = Math.round(performance.now() - t0);
      const extractionResult = legacyToExtractionResult("pending", object, {
        modelId: geminiUsed ? prereq?.modelId ?? "gemini" : "hybrid",
        promptContractId: schedaOfficinaPromptContract.id,
        promptVersion: schedaOfficinaPromptContract.version,
        outputSchemaVersion: schedaOfficinaPromptContract.outputSchemaVersion,
        projectorVersion: schedaOfficinaPromptContract.projectorVersion,
        inputTokens: usage?.inputTokens,
        outputTokens: usage?.outputTokens,
        totalTokens: usage?.totalTokens,
        latencyMs: durationMs,
        pageCount: pageObjects.length,
      });

      const document = plugin.projectToModel({
        captureId,
        pageObjects,
        extraction: extractionResult,
        updatedBy: userId,
      });
      const flatFields = projectDocumentModelToFlatFields(document);
      const baseFieldRows = flatFields.map((f) => ({
        company_id: capture.company_id,
        document_capture_id: captureId,
        field_key: normalizeCaptureExtractedFieldKey(f.fieldKey),
        raw_value: f.value,
        normalized_value: f.value,
        confidence: f.confidence,
        value_source: "ai" as const,
      }));

      const [{ validation }, preload, resolution] = await Promise.all([
        Promise.resolve(runSchedaPipelineViews(document)),
        preloadPromise,
        baseFieldRows.length > 0
          ? preloadPromise.then(({ magazzino, mezzi, resolutionContext }) => {
              trace.emit("ENTITY_RESOLUTION_START", "ok");
              return applyEntityResolutionToCaptureFields(sb, {
                companyId: capture.company_id,
                captureId,
                fields: baseFieldRows.map((f) => ({ field_key: f.field_key, raw_value: f.raw_value })),
                magazzino,
                mezzi,
                resolutionContext,
              }).then((result) => {
                trace.emit("ENTITY_RESOLUTION_OK", "ok", { fieldCount: result.fields.length });
                return result;
              });
            })
          : Promise.resolve(null),
      ]);

      pipelineState = markUploadUploaded(preload.pipelineState ?? { ...INITIAL_PIPELINE_STATE });

      trace.emit("DB_PERSIST_START", "ok");
      trace.emit("UPSERT_FIELDS_START", "ok");

      const { data: attemptRow, error: insError } = await sb
        .from("document_capture_attempts")
        .insert({
          company_id: capture.company_id,
          document_capture_id: captureId,
          attempt_number: attemptNumber,
          provider: geminiUsed ? "google" : "hybrid",
          model: geminiUsed ? prereq?.modelId ?? "gemini" : "tesseract+pdfjs",
          structured_response: object,
          extraction_result: { ...extractionResult, attemptId: "pending" },
          prompt_contract_id: schedaOfficinaPromptContract.id,
          prompt_version: schedaOfficinaPromptContract.version,
          metadata: { ...extractionResult.modelMetadata, ...hybridMetadata, traceId: trace.traceId },
          status: "completed",
          input_tokens: usage?.inputTokens ?? null,
          output_tokens: usage?.outputTokens ?? null,
          total_tokens: usage?.totalTokens ?? null,
          duration_ms: durationMs,
          provider_request_id: providerRequestId,
          completed_at: new Date().toISOString(),
        })
        .select("id")
        .single();

      if (insError || !attemptRow) {
        throw new CompileAnalyzeError(insError?.message ?? "Salvataggio attempt fallito.");
      }
      attemptId = attemptRow.id;
      extractionResult.attemptId = attemptId;

      let fieldRows = baseFieldRows.map((f) => ({
        ...f,
        attempt_id: attemptId,
      }));
      const resolutionAudit = resolution?.audit;
      if (resolution) {
        fieldRows = mergeResolutionIntoFieldRows(fieldRows, resolution);
        const { error: upsertError } = await sb.from("document_capture_fields").upsert(fieldRows, {
          onConflict: "document_capture_id,field_key",
        });
        if (upsertError) {
          throw new CompileAnalyzeError(upsertError.message);
        }
      }


      pipelineState = advancePipelineStateForPhase(pipelineState, "ai_extract", true);
      pipelineState = advancePipelineStateForPhase(pipelineState, "validate", validation.status !== "blocked");
      await saveDocumentModelAndPipelineState({ captureId, document, pipelineState });
      trace.emit("DB_PERSIST_OK", "ok");

      if (fieldRows.length === 0) {
        trace.emit("UPSERT_FIELDS_FAIL", "fail", { errorCode: "no_fields" });
        await mutateCaptureWithEvent({
          captureId,
          eventType: "analyze_failed",
          idempotencyKey: `analyze_failed:empty:${capture.capture_version}`,
          payload: { errorCode: "no_fields", pipeline: "v4.1", traceId: trace.traceId },
          newStatus: "failed",
        });
        trace.emit("END_FAIL", "fail", { errorCode: "no_fields" });
        return {
          ok: false,
          code: "no_fields",
          message: "Nessun dato letto dalla scheda. Verifica che foto o PDF siano nitidi e riprova.",
          traceId: trace.traceId,
          correlationId,
        };
      }

      trace.emit("UPSERT_FIELDS_OK", "ok", { fieldCount: fieldRows.length });

      await savePipelineExecution({
        id: crypto.randomUUID(),
        captureId,
        phase: "ai_extract",
        idempotencyKey,
        status: "completed",
        completedAt: new Date().toISOString(),
        resultRef: attemptId,
      });

      await mutateCaptureWithEvent({
        captureId,
        eventType: "analyze_completed",
        idempotencyKey: `analyze_completed:${attemptId}`,
        payload: {
          attemptId,
          durationMs,
          fieldCount: fieldRows.length,
          pipeline: "v4.1",
          documentModelVersionHash: document.metadata.contentHash,
          entityResolution: resolutionAudit,
          traceId: trace.traceId,
        },
        newStatus: "review",
      });

      trace.emit("END_OK", "ok", { fieldCount: fieldRows.length, durationMs });

      return {
        ok: true,
        attemptId,
        durationMs,
        reused: false,
        documentModelVersionHash: document.metadata.contentHash,
        fieldCount: fieldRows.length,
        traceId: trace.traceId,
      };
    } catch (e) {
      lastError = e;
      if (isCaptureAnalyzeError(e)) {
        trace.fail(e.phase, e, { errorCode: e.code });
      } else if (geminiUsed) {
        trace.fail("GEMINI_FAIL", e, { retryAttempt });
      }
      if (retryAttempt < RETRY_BACKOFF_MS.length && isTransientAnalyzeRetryError(e)) {
        await sleep(resolveGeminiAnalyzeRetryDelayMs(e, retryAttempt, RETRY_BACKOFF_MS));
      } else {
        break;
      }
    }
  }

  const detail = errorDetailFromUnknown(lastError);
  const aiCode = isCaptureAnalyzeError(lastError)
    ? (lastError.code as AiErrorCode)
    : classifyAiError(lastError);
  if (aiCode === "AI_UNKNOWN_ERROR") {
    logUnclassifiedAiError(lastError, { captureId, traceId: trace.traceId, correlationId: correlationId ?? null });
  }
  const code = mapAiErrorToAnalyzeCode(aiCode);
  const userMessage = isCaptureAnalyzeError(lastError) ? lastError.userMessage : userMessageForAiError(aiCode);
  const phase = isCaptureAnalyzeError(lastError) ? lastError.phase : trace.lastRecordedPhase();

  await mutateCaptureWithEvent({
    captureId,
    eventType: "analyze_failed",
    idempotencyKey: `analyze_failed:${capture.capture_version}`,
    payload: {
      errorCode: code,
      errorType: aiCode,
      message: userMessage,
      detail,
      phase,
      traceId: trace.traceId,
      pipeline: "v4.1",
      stack: lastError instanceof Error ? lastError.stack?.slice(0, 800) : undefined,
    },
    newStatus: "failed",
  });
  trace.emit("END_FAIL", "fail", { errorCode: code, errorType: aiCode, detail });

  return buildAnalyzeFailure({
    code,
    aiCode,
    errorType: aiCode,
    message: userMessage,
    detail,
    phase,
    traceId: trace.traceId,
    correlationId,
  });
}

import type { CatalogMarca } from "@/lib/documenti/documenti-catalog-types";
import type { DocumentoAssocRef, DocumentoGestionale, DocumentoApplicabilita } from "@/lib/types/gestionale";

/** Tutte le categorie supportano marca intera o modello specifico. */
export function allowedApplicabilitaForCategoria(
  _c: DocumentoGestionale["categoria"],
): DocumentoApplicabilita[] {
  return ["marca", "modello"];
}

/** Categorie che ammettono solo applicabilità «tutta la marca» (no modello in UI). */
export function isDocumentoMarcaOnlyCategoria(c: DocumentoGestionale["categoria"]): boolean {
  return c === "listini" || c === "certificazioni";
}

export function defaultApplicabilitaForCategoria(c: DocumentoGestionale["categoria"]): DocumentoApplicabilita {
  if (c === "listini" || c === "cataloghi" || c === "certificazioni") return "marca";
  return "modello";
}

function inferApplicabilitaFromRow(doc: DocumentoGestionale, marcaNome: string, modelloLegacy: string): DocumentoApplicabilita {
  if (doc.categoria === "listini") return "marca";
  const hasModel = modelloLegacy.length > 0 && modelloLegacy !== "—";
  if (doc.categoria === "cataloghi") return hasModel ? "modello" : "marca";
  if (doc.categoria === "manuali") return hasModel ? "modello" : "marca";
  return hasModel ? "modello" : "marca";
}

const MARCA_NON_ASSEGNATA = new Set(["", "—", "-", "n/a", "na"]);

function marcaAssegnataText(raw: string): boolean {
  const t = raw.trim().toLowerCase();
  return t.length > 0 && !MARCA_NON_ASSEGNATA.has(t);
}

/** Risolve applicabilità e chiavi testuali (marca / modello) con fallback legacy. */
export function resolveDocumentoApplicazione(doc: DocumentoGestionale, catalog?: CatalogMarca[]): DocumentoGestionale {
  const marcaNome = (doc.marcaKey ?? doc.marca).trim() || doc.marca?.trim() || "";
  const modelloLegacy = (doc.modelloKey ?? doc.macchina).trim();

  if (!marcaAssegnataText(marcaNome)) {
    return {
      ...doc,
      applicabilita: doc.applicabilita,
      marcaKey: undefined,
      modelloKey: undefined,
      mezzoId: undefined,
      marca: "",
      macchina: "—",
    };
  }

  let applicabilita = doc.applicabilita;
  const legacyApp = (doc as { applicabilita?: string }).applicabilita;
  if (legacyApp === "macchina") {
    applicabilita = modelloLegacy && modelloLegacy !== "—" ? "modello" : "marca";
  }

  if (applicabilita && marcaNome) {
    const mk = marcaNome;
    const mod = applicabilita === "marca" ? undefined : modelloLegacy || undefined;
    return {
      ...doc,
      applicabilita,
      marcaKey: mk,
      modelloKey: mod,
      mezzoId: undefined,
      marca: mk,
      macchina: applicabilita === "marca" ? "—" : mod ?? "—",
    };
  }

  const inferred = inferApplicabilitaFromRow(doc, marcaNome, modelloLegacy);

  if (doc.categoria === "listini") {
    return {
      ...doc,
      applicabilita: "marca",
      marcaKey: marcaNome,
      modelloKey: undefined,
      mezzoId: undefined,
      marca: marcaNome,
      macchina: "—",
    };
  }

  if (doc.categoria === "cataloghi") {
    const hasModel = modelloLegacy.length > 0 && modelloLegacy !== "—";
    if (hasModel) {
      return {
        ...doc,
        applicabilita: "modello",
        marcaKey: marcaNome,
        modelloKey: modelloLegacy,
        mezzoId: undefined,
        marca: marcaNome,
        macchina: modelloLegacy,
      };
    }
    return {
      ...doc,
      applicabilita: "marca",
      marcaKey: marcaNome,
      modelloKey: undefined,
      mezzoId: undefined,
      marca: marcaNome,
      macchina: "—",
    };
  }

  if (doc.categoria === "manuali") {
    const hasModel = modelloLegacy.length > 0 && modelloLegacy !== "—";
    return {
      ...doc,
      applicabilita: hasModel ? "modello" : inferred,
      marcaKey: marcaNome,
      modelloKey: hasModel ? modelloLegacy : undefined,
      mezzoId: undefined,
      marca: marcaNome,
      macchina: hasModel ? modelloLegacy : "—",
    };
  }

  const hasAssoc = doc.associazioni && doc.associazioni.length > 0 && catalog?.length;
  if (hasAssoc && catalog) {
    const first = doc.associazioni![0]!;
    const mar = catalog.find((m) => m.id === first.marcaId);
    const mac = mar?.macchine.find((x) => x.id === first.macchinaId);
    if (mar && mac) {
      return {
        ...doc,
        applicabilita: "modello",
        marcaKey: mar.nome,
        modelloKey: mac.nome,
        mezzoId: undefined,
        marca: mar.nome,
        macchina: mac.nome,
      };
    }
  }

  const hasModel = modelloLegacy.length > 0 && modelloLegacy !== "—";
  return {
    ...doc,
    applicabilita: inferred,
    marcaKey: marcaNome || "—",
    modelloKey: hasModel ? modelloLegacy : undefined,
    mezzoId: undefined,
    marca: marcaNome || "—",
    macchina: hasModel ? modelloLegacy : "—",
  };
}

export function labelApplicabilitaBreve(a: DocumentoApplicabilita): string {
  switch (a) {
    case "marca":
      return "MARCA";
    case "modello":
      return "MODELLO";
    default:
      return a;
  }
}

const DOC_RIGA_SYNTH_SEP = " · ";

/** Riga sintetica tipo "LISTINO · MERCEDES" o "MANUALE · MERCEDES ACTROS". */
export function formatDocumentoRigaSintetica(doc: DocumentoGestionale): string {
  const cat =
    doc.categoria === "listini"
      ? "LISTINO"
      : doc.categoria === "cataloghi"
        ? "CATALOGO"
        : doc.categoria === "manuali"
          ? "MANUALE"
          : doc.categoria === "certificazioni"
            ? "CERTIFICAZIONE"
            : "ALTRO";
  const r = resolveDocumentoApplicazione(doc);
  const m = r.marcaKey?.trim() || r.marca.trim();
  if (!marcaAssegnataText(m)) {
    if (doc.categoria === "certificazioni") return cat;
    return `${cat}${DOC_RIGA_SYNTH_SEP}Senza marca`;
  }
  if (r.applicabilita === "marca") return `${cat}${DOC_RIGA_SYNTH_SEP}${m}`;
  const mod = r.modelloKey?.trim() || r.macchina.trim();
  return `${cat}${DOC_RIGA_SYNTH_SEP}${m} ${mod}`.replace(/\s+/g, " ").trim();
}

export function legacyAssocRefs(doc: DocumentoGestionale, catalog: CatalogMarca[]): DocumentoAssocRef[] {
  if (doc.associazioni && doc.associazioni.length > 0) return doc.associazioni;
  const mar = catalog.find((m) => m.nome === doc.marca);
  if (!mar) return [];
  const mac = mar.macchine.find((x) => x.nome === doc.macchina);
  if (!mac) return [];
  return [{ marcaId: mar.id, macchinaId: mac.id }];
}

import { mezzoGestitoFromRow } from "@/lib/domain/mezzo-attrezzatura/compose-mezzo-gestito";
import type { MezzoGestito } from "@/lib/mezzi/types";
import type { LavorazioneArchiviata, LavorazioneAttiva } from "@/lib/lavorazioni/types";
import {
  auditInterventoContext,
  buildIdentDeltaFromContext,
} from "@/lib/domain/intervento-context/intervento-audit";
import {
  interventoIdentEquals,
  resolveIdentFromLayers,
} from "@/lib/domain/intervento-context/intervento-ident";
import type {
  InterventoContext,
  InterventoContextFetchDeps,
  InterventoContextInputs,
  InterventoIdent,
  InterventoTargetSnapshot,
  InterventoTargetType,
  LavorazioneSnapshot,
  MezzoSnapshot,
  SchedaIngressoSnapshot,
} from "@/lib/domain/intervento-context/intervento-context.types";
import { resolveTargetTypeFromScheda } from "@/lib/domain/mezzo-attrezzatura/intervento-target";
import { attrezzaturaRowFromEnrichedMezzo, composeMezzoGestitoFromRows, pickAttrezzaturaForContext } from "@/lib/domain/mezzo-attrezzatura/compose-mezzo-gestito";
import { fetchSchedeBundleForLavorazione } from "@/lib/schede/schede-sync-adapter";
import { lavorazioniService } from "@/src/services/lavorazioni.service";
import { mezziService } from "@/src/services/mezzi.service";
import { fetchAttrezzatureForMezzoIds } from "@/lib/mezzi/mezzi-attrezzature-batch";
import { getBrowserSupabase } from "@/src/lib/supabase/browser-client";
import type { LavorazioneListRow } from "@/src/services/lavorazioni.service";
import type { LavorazioneRow, MezzoRow } from "@/src/types/supabase-tables";
import type { LavorazioneSchedeBundle, LavorazioneSchedeStore, SchedaIngressoFields } from "@/types/schede";

function emptySchedaIngressoFields(): SchedaIngressoFields {
  return {
    targetType: "attrezzatura",
    attrezzaturaId: null,
    interventoSuAttrezzatura: true,
    interventoSuTelaio: false,
    dataIngresso: "",
    cliente: "",
    cantiere: "",
    utilizzatore: "",
    tipoAttrezzatura: "",
    marcaAttrezzatura: "",
    modelloAttrezzatura: "",
    matricola: "",
    nScuderia: "",
    oreLavoro: "",
    tipoTelaio: "",
    marcaTelaio: "",
    modelloTelaio: "",
    vin: "",
    targa: "",
    km: "",
    descrizioneAnomalia: "",
    livelloCarburante: "",
    addettoAccettazione: "",
    richiedente: "",
    richiedenteTelefono: "",
  };
}

function safeMezzoText(v: string | null | undefined): string {
  return typeof v === "string" ? v.trim() : "";
}

function mezzoSnapshotFromRow(row: MezzoRow | null | undefined, gestito?: MezzoGestito | null): MezzoSnapshot {
  const g = gestito ?? (row ? mezzoGestitoFromRow(row) : null);
  if (!g) {
    return {
      id: null,
      cliente: "",
      utilizzatore: "",
      marca: "",
      modello: "",
      targa: "",
      matricola: "",
      nScuderia: "",
      tipoAttrezzatura: "",
      cantiere: "",
      present: false,
    };
  }
  return {
    id: g.id,
    cliente: safeMezzoText(g.cliente),
    utilizzatore: safeMezzoText(g.utilizzatore),
    marca: safeMezzoText(g.marca),
    modello: safeMezzoText(g.modello),
    targa: safeMezzoText(g.targa),
    matricola: safeMezzoText(g.matricola),
    nScuderia: safeMezzoText(g.numeroScuderia),
    tipoAttrezzatura: safeMezzoText(g.tipoAttrezzatura),
    cantiere: safeMezzoText(g.cantiere),
    present: true,
  };
}

function lavorazioneSnapshotFromInputs(
  lavorazioneId: string,
  row?: LavorazioneRow | null,
  legacy?: LavorazioneAttiva | LavorazioneArchiviata | null,
): LavorazioneSnapshot {
  return {
    id: lavorazioneId,
    mezzoId:
      row?.mezzo_id?.trim() ||
      (legacy && "mezzoId" in legacy ? legacy.mezzoId?.trim() : null) ||
      null,
    dataIngresso: row?.data_ingresso ?? legacy?.dataIngresso ?? null,
    note: row?.note ?? legacy?.note ?? null,
    targa: legacy?.targa?.trim() ?? "",
    matricola: legacy?.matricola?.trim() ?? "",
    nScuderia: legacy?.nScuderia?.trim() ?? "",
    cliente: legacy?.cliente?.trim() ?? "",
    utilizzatore: legacy?.utilizzatore?.trim() ?? "",
    cantiere: legacy?.cantiere?.trim() ?? "",
  };
}

function schedaIngressoSnapshotFromInputs(
  campi?: SchedaIngressoFields | null,
  sorgente?: "generata" | "file_esterno" | null,
  updatedAt?: string | null,
): SchedaIngressoSnapshot {
  const present = Boolean(campi && sorgente !== "file_esterno");
  return {
    present,
    sorgente: sorgente ?? null,
    updatedAt: updatedAt ?? null,
    campi: present ? { ...campi! } : campi ? { ...campi } : null,
  };
}

function detectIdentMismatch(
  scheda: SchedaIngressoSnapshot,
  mezzo: MezzoSnapshot,
  ident: InterventoIdent,
): boolean {
  if (!scheda.present || !mezzo.present || !scheda.campi) return false;
  const fromScheda: InterventoIdent = {
    targa: scheda.campi.targa,
    matricola: scheda.campi.matricola,
    nScuderia: scheda.campi.nScuderia,
  };
  const fromMezzo: InterventoIdent = {
    targa: mezzo.targa,
    matricola: mezzo.matricola,
    nScuderia: mezzo.nScuderia,
  };
  const schedaHasIdent = Boolean(
    (fromScheda.targa?.trim() ?? "") ||
      (fromScheda.matricola?.trim() ?? "") ||
      (fromScheda.nScuderia?.trim() ?? ""),
  );
  const mezzoHasIdent = Boolean(
    (fromMezzo.targa?.trim() ?? "") ||
      (fromMezzo.matricola?.trim() ?? "") ||
      (fromMezzo.nScuderia?.trim() ?? ""),
  );
  if (!schedaHasIdent || !mezzoHasIdent) return false;
  return !interventoIdentEquals(fromScheda, fromMezzo);
}

function targetSnapshotFromInputs(inputs: InterventoContextInputs): InterventoTargetSnapshot {
  const row = inputs.lavorazioneRow;
  const att = inputs.attrezzaturaRow;
  const scheda = inputs.ingressoCampi;
  const targetType: InterventoTargetType =
    row?.target_type ??
    scheda?.targetType ??
    resolveTargetTypeFromScheda({
      targetType: scheda?.targetType,
      marcaAttrezzatura: scheda?.marcaAttrezzatura,
      attrezzaturaId: scheda?.attrezzaturaId,
    });

  if (targetType === "telaio") {
    return {
      targetType: "telaio",
      attrezzatura: { id: null, marca: "", modello: "", matricola: "", present: false },
    };
  }

  const marca =
    att?.marca?.trim() ||
    scheda?.marcaAttrezzatura?.trim() ||
    inputs.mezzoGestito?.marca?.trim() ||
    "";
  const modello =
    att?.modello?.trim() ||
    scheda?.modelloAttrezzatura?.trim() ||
    inputs.mezzoGestito?.modello?.trim() ||
    "";

  return {
    targetType: "attrezzatura",
    attrezzatura: {
      id: row?.attrezzatura_id ?? att?.id ?? scheda?.attrezzaturaId ?? null,
      marca,
      modello,
      matricola:
        att?.matricola?.trim() ||
        scheda?.matricola?.trim() ||
        inputs.mezzoGestito?.matricola?.trim() ||
        "",
      present: Boolean(marca || modello || att?.id),
    },
  };
}

export function composeInterventoContext(inputs: InterventoContextInputs): InterventoContext {
  const lavorazioneId = inputs.lavorazioneId.trim();
  const mezzo = mezzoSnapshotFromRow(inputs.mezzoRow, inputs.mezzoGestito);
  const lavorazione = lavorazioneSnapshotFromInputs(
    lavorazioneId,
    inputs.lavorazioneRow,
    inputs.legacyLavorazione,
  );
  const schedaIngresso = schedaIngressoSnapshotFromInputs(
    inputs.ingressoCampi,
    inputs.ingressoSorgente,
    inputs.ingressoUpdatedAt,
  );

  const schedaIdent = schedaIngresso.present
    ? {
        targa: schedaIngresso.campi?.targa ?? "",
        matricola: schedaIngresso.campi?.matricola ?? "",
        nScuderia: schedaIngresso.campi?.nScuderia ?? "",
      }
    : null;
  const lavIdent = {
    targa: lavorazione.targa,
    matricola: lavorazione.matricola,
    nScuderia: lavorazione.nScuderia,
  };
  const mezzoIdent = mezzo.present
    ? { targa: mezzo.targa, matricola: mezzo.matricola, nScuderia: mezzo.nScuderia }
    : null;

  const ident = resolveIdentFromLayers(schedaIdent, lavIdent, mezzoIdent);

  const ctx: InterventoContext = {
    contextId: lavorazioneId,
    lavorazioneId,
    mezzo,
    lavorazione,
    schedaIngresso,
    ident,
    target: targetSnapshotFromInputs(inputs),
    meta: {
      schedaMissing: !schedaIngresso.present,
      mezzoUnlinked: !lavorazione.mezzoId,
      hasIdentMismatch: detectIdentMismatch(schedaIngresso, mezzo, ident),
    },
  };

  auditInterventoContext(ctx, "build", {
    identDelta: buildIdentDeltaFromContext(ctx),
  });

  return ctx;
}

export function composeInterventoContextFromBundle(
  lavorazioneId: string,
  bundle: LavorazioneSchedeBundle | null | undefined,
  options?: {
    lavorazioneRow?: LavorazioneRow | null;
    mezzoRow?: MezzoRow | null;
    mezzoGestito?: MezzoGestito | null;
    legacyLavorazione?: LavorazioneAttiva | LavorazioneArchiviata | null;
  },
): InterventoContext {
  const ing = bundle?.ingresso ?? null;
  return composeInterventoContext({
    lavorazioneId,
    lavorazioneRow: options?.lavorazioneRow,
    mezzoRow: options?.mezzoRow,
    mezzoGestito: options?.mezzoGestito,
    legacyLavorazione: options?.legacyLavorazione,
    ingressoCampi: ing?.campi ?? null,
    ingressoSorgente: ing?.sorgente ?? null,
    ingressoUpdatedAt: ing?.updatedAt ?? null,
  });
}

export function composeInterventoContextFromListRow(
  row: LavorazioneListRow,
  schedeStore?: LavorazioneSchedeStore,
): InterventoContext {
  const bundle = schedeStore?.[row.id];
  const ing = bundle?.ingresso ?? null;
  const attrezzaturaRow =
    row.attrezzatura_id && row.mezzo
      ? attrezzaturaRowFromEnrichedMezzo(
          row.mezzo,
          row.attrezzatura_id,
          row.mezzo_id ?? row.mezzo.id,
        )
      : null;
  return composeInterventoContext({
    lavorazioneId: row.id,
    lavorazioneRow: row,
    mezzoRow: row.mezzo,
    attrezzaturaRow,
    ingressoCampi: ing?.campi ?? null,
    ingressoSorgente: ing?.sorgente ?? null,
    ingressoUpdatedAt: ing?.updatedAt ?? null,
  });
}

export function composeInterventoContextFromDraft({
  lavorazioneId = "draft",
  fields,
  mezzo,
  lavorazioneRow,
  legacyLavorazione,
}: {
  lavorazioneId?: string;
  fields: SchedaIngressoFields;
  mezzo?: MezzoGestito | null;
  lavorazioneRow?: LavorazioneRow | null;
  legacyLavorazione?: LavorazioneAttiva | LavorazioneArchiviata | null;
}): InterventoContext {
  return composeInterventoContext({
    lavorazioneId,
    lavorazioneRow,
    mezzoGestito: mezzo,
    legacyLavorazione,
    ingressoCampi: { ...fields },
    ingressoSorgente: "generata",
    ingressoUpdatedAt: null,
  });
}

const defaultFetchDeps = (): InterventoContextFetchDeps => ({
  async getLavorazioneById(id) {
    const res = await lavorazioniService.getById(id);
    return res.success ? res.data : null;
  },
  async getMezzoById(id) {
    const res = await mezziService.getById(id);
    return res.success ? res.data : null;
  },
  async fetchAttrezzaturesForMezzo(mezzoId) {
    const sb = getBrowserSupabase();
    return fetchAttrezzatureForMezzoIds(sb, [mezzoId]);
  },
  async fetchSchedeBundle(lavorazioneId) {
    const bundle = await fetchSchedeBundleForLavorazione(lavorazioneId);
    if (!bundle?.ingresso) return { ingresso: null };
    return {
      ingresso: {
        campi: bundle.ingresso.campi,
        sorgente: bundle.ingresso.sorgente,
        updatedAt: bundle.ingresso.updatedAt,
      },
    };
  },
});

export async function fetchInterventoContextInputs(
  lavorazioneId: string,
  deps: InterventoContextFetchDeps = defaultFetchDeps(),
): Promise<InterventoContextInputs> {
  const id = lavorazioneId.trim();
  const lavRow = await deps.getLavorazioneById(id);
  let mezzoRow: MezzoRow | null = null;
  let mezzoGestito: MezzoGestito | null = null;
  let attrezzaturaRow: import("@/src/types/supabase-tables").AttrezzaturaRow | null = null;
  if (lavRow?.mezzo_id?.trim()) {
    const mid = lavRow.mezzo_id.trim();
    mezzoRow = await deps.getMezzoById(mid);
    if (mezzoRow) {
      const attRows = await deps.fetchAttrezzaturesForMezzo(mid);
      attrezzaturaRow = pickAttrezzaturaForContext(attRows, mid, lavRow.attrezzatura_id);
      mezzoGestito = composeMezzoGestitoFromRows(mezzoRow, attrezzaturaRow);
    }
  }
  const bundle = await deps.fetchSchedeBundle(id);
  return {
    lavorazioneId: id,
    lavorazioneRow: lavRow,
    mezzoRow,
    mezzoGestito,
    attrezzaturaRow,
    ingressoCampi: bundle?.ingresso?.campi ?? null,
    ingressoSorgente: bundle?.ingresso?.sorgente ?? null,
    ingressoUpdatedAt: bundle?.ingresso?.updatedAt ?? null,
  };
}

export async function buildInterventoContext(
  lavorazioneId: string,
  deps?: InterventoContextFetchDeps,
): Promise<InterventoContext> {
  const inputs = await fetchInterventoContextInputs(lavorazioneId, deps);
  return composeInterventoContext(inputs);
}

