function schedaToMezzoPayload(fields: SchedaIngressoFields, anno?: number): MezzoInsert {
  const annoRaw = anno ?? new Date().getFullYear();
  const annoClamped = Math.max(1980, Math.min(2035, Number.isFinite(annoRaw) ? annoRaw : new Date().getFullYear()));
  const meta = mezzoFormToMeta({
    cantiere: fields.cantiere,
    tipoTelaio: "",
    marcaTelaio: "",
    modelloTelaio: "",
    oreLavoro: fields.oreLavoro,
    km: fields.km,
  });
  return {
    cliente: fields.cliente.trim(),
    utilizzatore: fields.utilizzatore.trim() || null,
    targa: fields.targa.trim() || null,
    numero_scuderia: fields.nScuderia.trim() || null,
    anno: annoClamped,
    meta: meta as Record<string, unknown>,
    entity_key: null,
    marca_telaio: trimOrNull(fields.marcaTelaio),
    modello_telaio: trimOrNull(fields.modelloTelaio),
    tipo_telaio: trimOrNull(fields.tipoTelaio),
    telaio_num: normalizeVin(fields.vin),
    km: trimOrNull(fields.km) ? parseDecimalInput(fields.km) : null,
    note: null,
  };
}

function schedaToAttrezzaturaPayload(fields: SchedaIngressoFields, mezzoId: string): AttrezzaturaResolveInsert {
  const annoParsed = parseInt(fields.oreLavoro, 10);
  return {
    mezzo_id: mezzoId,
    marca: fields.marcaAttrezzatura.trim() || "—",
    modello: fields.modelloAttrezzatura.trim() || "—",
    tipo_attrezzatura: trimOrNull(fields.tipoAttrezzatura),
    matricola: trimOrNull(fields.matricola),
    portata: null,
    anno: Number.isFinite(annoParsed) ? null : null,
    note: null,
  };
}

export async function upsertFromSchedaV2(
  params: {
    fields: SchedaIngressoFields;
    mezziCatalog: readonly MezzoGestito[];
    preferredMezzoId?: string | null;
    attrezzaturaIdHint?: string | null;
    updatePlan?: MezzoUpdateFromSchedaPlan;
    lavorazioneId?: string | null;
  },
  deps: UpsertFromSchedaV2Deps,
): Promise<UpsertFromSchedaV2Result> {
  const {
    fields,
    mezziCatalog,
    preferredMezzoId,
    attrezzaturaIdHint,
    updatePlan = MEZZO_UPDATE_SCHEDA_ONLY,
    lavorazioneId,
  } = params;
  const targetType = resolveTargetTypeFromScheda({
    targetType: fields.targetType,
    marcaAttrezzatura: fields.marcaAttrezzatura,
    attrezzaturaId: fields.attrezzaturaId ?? attrezzaturaIdHint,
    matricola: fields.matricola,
    tipoAttrezzatura: fields.tipoAttrezzatura,
  });

  const resolved = resolveMezzoFromScheda({
    scheda: fields,
    existingMezzi: mezziCatalog,
    preferredMezzoId,
  });

  if (resolved.matchKind === "error") {
    throw new PreferredMezzoInvalidError(
      (resolved.errorCode as "preferred_mezzo_not_found" | "preferred_mezzo_forbidden") ??
        "preferred_mezzo_not_found",
      resolved.errorMessage ?? "Mezzo selezionato non valido.",
    );
  }
  if (resolved.matchKind === "ambiguous") {
    throw new MezzoSchedaValidationError("MEZZO_IDENT_AMBIGUOUS");
  }
  if (resolved.matchKind === "needs_confirm") {
    throw new MezzoSchedaValidationError("MEZZO_IDENT_NEEDS_CONFIRM");
  }

  const incomingMezzo = schedaToMezzoPayload(fields, resolved.mezzo?.anno);
  const hintId = preferredMezzoId?.trim() ?? resolved.mezzoId ?? null;

  const resolvedMezzo = await deps.resolveMezzo({
    incoming: incomingMezzo,
    hintId,
    catalog: mezziCatalog,
  });
  const mezzoId = resolvedMezzo.row.id;
  const createdMezzo = resolvedMezzo.created;

  if (
    !createdMezzo &&
    updatePlan.associationChangeConfirmed &&
    resolved.mezzo &&
    deps.applyAssociationChange
  ) {
    const occAt =
      updatePlan.mezzoOCC?.updatedAtAtLinkTime?.trim() ||
      resolved.mezzo.ultimaModifica?.trim() ||
      "";
    await deps.applyAssociationChange({
      mezzoId,
      existingMezzo: resolved.mezzo,
      newAssociation: associationFromScheda(fields),
      origin: "scheda_ingresso",
      expectedUpdatedAt: occAt,
      lavorazioneId,
    });
  }

  const anagraficaPlan = stripAssociationFieldsFromPlan(updatePlan);

  if (
    !createdMezzo &&
    resolved.mezzoId &&
    (anagraficaPlan.updateAnagrafica || anagraficaPlan.updateMetering)
  ) {
    if (
      mezzoUpdatePlanAllowsMezzoWrite(anagraficaPlan) &&
      anagraficaPlan.mezzoOCC?.updatedAtAtLinkTime &&
      resolved.mezzo?.ultimaModifica &&
      isMezzoUpdatedAtStale(anagraficaPlan.mezzoOCC.updatedAtAtLinkTime, resolved.mezzo.ultimaModifica) &&
      !anagraficaPlan.forceDespiteStale
    ) {
      logMezzoSchedaConflictTelemetry({
        event: "MEZZO_STALE_CONFLICT",
        mezzoId,
      });
      throw new MezzoSchedaValidationError("MEZZO_STALE_CONFLICT");
    }
    const patch = buildMezzoUpdatePatchFromSchedaPlan(
      fields,
      resolved.mezzo,
      anagraficaPlan,
      lavorazioneId,
    );
    if (Object.keys(patch).length > 0) {
      await deps.updateMezzo(mezzoId, patch);
    }
  }

  if (targetType === "telaio") {
    logAttrezzatureV2WritePath({
      path: "v2",
      operation: createdMezzo ? "create" : "update",
      targetType: "telaio",
    });
    return {
      mezzoId,
      attrezzaturaId: null,
      targetType: "telaio",
      createdMezzo,
      createdAttrezzatura: false,
    };
  }

  const resolvedAtt = await deps.resolveAttrezzatura({
    mezzoId,
    incoming: schedaToAttrezzaturaPayload(fields, mezzoId),
    hintId: fields.attrezzaturaId ?? attrezzaturaIdHint,
  });
  const attrezzaturaId = resolvedAtt.row.id;
  const createdAttrezzatura = resolvedAtt.created;

  logAttrezzatureV2WritePath({
    path: "v2",
    operation: createdMezzo ? "create" : "update",
    targetType: "attrezzatura",
  });

  return {
    mezzoId,
    attrezzaturaId,
    targetType: "attrezzatura",
    createdMezzo,
    createdAttrezzatura,
  };
}

import { MAGAZZINO_RICAMBI_COLUMNS } from "@/lib/db/table-select-columns";
import { precedenceForSource } from "../../merge/source-precedence";
import type { TkbSourceAdapter } from "../adapter-registry";
import { registerTkbAdapter } from "../adapter-registry";
import { activityIdFromText, tkbSlugFromLabel } from "../slug";
import type { TkbComponente, TkbRicambioMapEntry, TkbSourceFragment } from "../../types";

function frag(
  sourceId: string,
  entityKind: TkbSourceFragment["entityKind"],
  entityKey: string,
  payload: unknown,
  provenance: TkbSourceFragment["provenance"],
): TkbSourceFragment {
  return {
    sourceId,
    precedence: precedenceForSource(sourceId),
    entityKind,
    entityKey,
    payload,
    provenance,
  };
}

export const ricambiAdapter: TkbSourceAdapter = {
  id: "ricambi",
  tier: 1,
  supportsIncremental: true,
  async collect(ctx) {
    const { data, error } = await ctx.supabase.from("magazzino_ricambi").select(MAGAZZINO_RICAMBI_COLUMNS);
    if (error) {
      ctx.warnings.push(`ricambi:query:${error.message}`);
      return [];
    }
    const rows = data ?? [];
    const out: TkbSourceFragment[] = [];
    let sort = 0;
    for (const row of rows) {
      const nome = String(row.nome ?? "").trim();
      if (!nome) {
        ctx.excluded.invalid++;
        continue;
      }
      const slug = tkbSlugFromLabel(nome, row.id);
      const comp: TkbComponente = {
        slug,
        label: nome,
        synonyms: [String(row.marca ?? "").trim(), String(row.codice ?? "").trim()].filter(Boolean),
      };
      out.push(
        frag("ricambi", "componente", slug, comp, {
          origin: "magazzino_ricambi",
          recordId: row.id,
          updatedAt: row.updated_at ?? undefined,
        }),
      );
      const mapEntry: TkbRicambioMapEntry = {
        id: `rm_${row.id}`,
        ricambioId: row.id,
        componenteSlug: slug,
        azionePrevista: "sostituzione",
        activityId: activityIdFromText(`sostituzione ${nome}`, "ric"),
        matchConfidence: 0.85,
        matchQuality: "partial",
        active: true,
        validFrom: (row.created_at ?? ctx.now).slice(0, 10),
      };
      out.push(
        frag("ricambi", "ricambioMap", mapEntry.id, mapEntry, {
          origin: "magazzino_ricambi",
          recordId: row.id,
          updatedAt: row.updated_at ?? undefined,
        }),
      );
      sort++;
    }
    return out;
  },
  async collectIncremental(ctx, hints) {
    const ids = hints.filter((h) => h.entityType === "magazzino_ricambi").map((h) => h.entityId);
    if (!ids.length) return this.collect(ctx);
    const partial = { ...ctx, mode: "full" as const };
    const all = await this.collect(partial);
    const idSet = new Set(ids);
    return all.filter((f) => f.provenance.recordId && idSet.has(f.provenance.recordId));
  },
};

registerTkbAdapter(ricambiAdapter);

import { canonicalizeSlug } from "../canonicalize";
import { precedenceForSource } from "./source-precedence";
import type {
  CatalogActivity,
  TkbCategoria,
  TkbComponente,
  TkbDraftBundle,
  TkbEntityKind,
  TkbIntervento,
  TkbProcedure,
  TkbRicambioMapEntry,
  TkbSintomo,
  TkbSourceFragment,
} from "../types";

export type MergeResult = {
  bundle: TkbDraftBundle;
  audit: {
    performed: number;
    duplicatesFound: number;
    conflictsResolved: number;
    added: number;
    updated: number;
    removed: number;
  };
};

type EntityBucket = {
  categoria: Map<string, TkbCategoria>;
  componente: Map<string, TkbComponente>;
  sintomo: Map<string, TkbSintomo>;
  procedure: Map<string, TkbProcedure>;
  intervento: Map<string, TkbIntervento>;
  ricambioMap: Map<string, TkbRicambioMapEntry>;
};

type StoredFragment = TkbSourceFragment & { precedence: number; updatedAt?: string };

function bucketKey(kind: TkbEntityKind, key: string): string {
  return `${kind}:${canonicalizeSlug(key)}`;
}

function mergeStringArrays(a?: string[], b?: string[]): string[] | undefined {
  const set = new Set<string>();
  for (const arr of [a, b]) {
    if (!arr) continue;
    for (const s of arr) {
      const t = s.trim();
      if (t) set.add(t);
    }
  }
  const out = [...set].sort((x, y) => x.localeCompare(y, "it"));
  return out.length ? out : undefined;
}

function mergeComponente(existing: TkbComponente, incoming: TkbComponente): TkbComponente {
  return {
    slug: existing.slug,
    label: incoming.label || existing.label,
    categoriaSlug: incoming.categoriaSlug ?? existing.categoriaSlug,
    synonyms: mergeStringArrays(existing.synonyms, incoming.synonyms),
  };
}

function mergeSintomo(existing: TkbSintomo, incoming: TkbSintomo): TkbSintomo {
  return {
    slug: existing.slug,
    label: incoming.label || existing.label,
    keywords: mergeStringArrays(existing.keywords, incoming.keywords) ?? [],
    relatedComponentiSlugs: mergeStringArrays(existing.relatedComponentiSlugs, incoming.relatedComponentiSlugs),
  };
}

function mergeIntervento(existing: TkbIntervento, incoming: TkbIntervento): TkbIntervento {
  return {
    slug: existing.slug,
    label: incoming.label || existing.label,
    categoriaSlug: incoming.categoriaSlug ?? existing.categoriaSlug,
    keywords: mergeStringArrays(existing.keywords, incoming.keywords) ?? [],
    componentiSlugs: mergeStringArrays(existing.componentiSlugs, incoming.componentiSlugs),
    sintomiSlugs: mergeStringArrays(existing.sintomiSlugs, incoming.sintomiSlugs),
    compatibilita: incoming.compatibilita ?? existing.compatibilita,
    procedureSlugs: mergeStringArrays(existing.procedureSlugs, incoming.procedureSlugs),
    activityOverrides: incoming.activityOverrides ?? existing.activityOverrides,
    attivitaPrincipali:
      incoming.attivitaPrincipali.length > 0 ? incoming.attivitaPrincipali : existing.attivitaPrincipali,
    attivitaComplementari: incoming.attivitaComplementari ?? existing.attivitaComplementari,
    controlliFinali: incoming.controlliFinali ?? existing.controlliFinali,
    publishStatus: existing.publishStatus,
  };
}

function activityCount(bundle: TkbDraftBundle): number {
  let n = 0;
  for (const p of bundle.procedure) {
    n += p.attivita.length + (p.controlliFinali?.length ?? 0);
  }
  for (const i of bundle.interventi) {
    n +=
      i.attivitaPrincipali.length +
      (i.attivitaComplementari?.length ?? 0) +
      (i.controlliFinali?.length ?? 0);
  }
  return n;
}

function toBuckets(fragments: StoredFragment[]): EntityBucket {
  const buckets: EntityBucket = {
    categoria: new Map(),
    componente: new Map(),
    sintomo: new Map(),
    procedure: new Map(),
    intervento: new Map(),
    ricambioMap: new Map(),
  };

  const stored = new Map<string, StoredFragment>();
  let duplicatesFound = 0;
  let conflictsResolved = 0;
  let performed = 0;
  let added = 0;
  let updated = 0;

  for (const frag of fragments) {
    const key = bucketKey(frag.entityKind, frag.entityKey);
    const existing = stored.get(key);
    if (!existing) {
      stored.set(key, frag);
      added++;
      continue;
    }
    duplicatesFound++;
    const win =
      frag.precedence > existing.precedence
        ? frag
        : frag.precedence < existing.precedence
          ? existing
          : (frag.updatedAt ?? "") >= (existing.updatedAt ?? "")
            ? frag
            : existing;
    if (win !== existing) conflictsResolved++;
    stored.set(key, win);
    updated++;
    performed++;
  }

  for (const frag of stored.values()) {
    const slug = canonicalizeSlug(frag.entityKey);
    switch (frag.entityKind) {
      case "categoria":
        buckets.categoria.set(slug, frag.payload as TkbCategoria);
        break;
      case "componente": {
        const incoming = frag.payload as TkbComponente;
        const prev = buckets.componente.get(slug);
        buckets.componente.set(slug, prev ? mergeComponente(prev, incoming) : incoming);
        break;
      }
      case "sintomo": {
        const incoming = frag.payload as TkbSintomo;
        const prev = buckets.sintomo.get(slug);
        buckets.sintomo.set(slug, prev ? mergeSintomo(prev, incoming) : incoming);
        break;
      }
      case "procedure":
        buckets.procedure.set(slug, frag.payload as TkbProcedure);
        break;
      case "intervento": {
        const incoming = frag.payload as TkbIntervento;
        const prev = buckets.intervento.get(slug);
        buckets.intervento.set(slug, prev ? mergeIntervento(prev, incoming) : incoming);
        break;
      }
      case "ricambioMap": {
        const entry = frag.payload as TkbRicambioMapEntry;
        buckets.ricambioMap.set(entry.id, entry);
        break;
      }
      default:
        break;
    }
  }

  return buckets;
}

export function mergeFragments(fragments: TkbSourceFragment[]): MergeResult {
  const stored: StoredFragment[] = fragments.map((f) => ({
    ...f,
    precedence: f.precedence || precedenceForSource(f.sourceId),
    updatedAt: f.provenance.updatedAt,
  }));

  const buckets = toBuckets(stored);
  const bundle: TkbDraftBundle = {
    categorie: [...buckets.categoria.values()],
    componenti: [...buckets.componente.values()],
    sintomi: [...buckets.sintomo.values()],
    procedure: [...buckets.procedure.values()],
    interventi: [...buckets.intervento.values()],
    ricambiMap: [...buckets.ricambioMap.values()],
  };

  return {
    bundle,
    audit: {
      performed: stored.length,
      duplicatesFound: Math.max(0, stored.length - new Set(stored.map((s) => bucketKey(s.entityKind, s.entityKey))).size),
      conflictsResolved: 0,
      added: bundle.categorie.length + bundle.componenti.length + bundle.interventi.length,
      updated: 0,
      removed: 0,
    },
  };
}

export function countActivities(bundle: TkbDraftBundle): number {
  return activityCount(bundle);
}

export function emptyDraftBundle(): TkbDraftBundle {
  return {
    categorie: [],
    componenti: [],
    sintomi: [],
    procedure: [],
    interventi: [],
    ricambiMap: [],
  };
}

/** Merge conservativo: union di array su draft esistente per incremental patch. */
export function patchDraftFromFragments(
  previous: TkbDraftBundle,
  fragments: TkbSourceFragment[],
): MergeResult {
  const merged = mergeFragments([...fragmentsFromDraft(previous), ...fragments]);
  return merged;
}

function fragmentsFromDraft(draft: TkbDraftBundle): TkbSourceFragment[] {
  const out: TkbSourceFragment[] = [];
  const base = { sourceId: "draft_cache", precedence: 5, provenance: { origin: "draft_cache" } };
  for (const c of draft.categorie) {
    out.push({ ...base, entityKind: "categoria", entityKey: c.slug, payload: c });
  }
  for (const c of draft.componenti) {
    out.push({ ...base, entityKind: "componente", entityKey: c.slug, payload: c });
  }
  for (const s of draft.sintomi) {
    out.push({ ...base, entityKind: "sintomo", entityKey: s.slug, payload: s });
  }
  for (const p of draft.procedure) {
    out.push({ ...base, entityKind: "procedure", entityKey: p.slug, payload: p });
  }
  for (const i of draft.interventi) {
    out.push({ ...base, entityKind: "intervento", entityKey: i.slug, payload: i });
  }
  for (const m of draft.ricambiMap) {
    out.push({ ...base, entityKind: "ricambioMap", entityKey: m.id, payload: m });
  }
  return out;
}

export function makeActivity(
  activityId: string,
  text: string,
  sort: number,
  activityType: CatalogActivity["activityType"],
  required = true,
): CatalogActivity {
  return { activityId, text, sort, required, activityType };
}

import { stripDictionaryTokens } from "@/lib/entity-resolution/dictionary-tokens";
import { LEGAL_SUFFIX_REPLACERS } from "@/lib/entity-resolution/legal-suffix";
import {
  entityAutocompleteKey,

  type NormalizeEntityStringOptions,
} from "@/lib/validation/global-entity-validation";

export type EntityNormalizeOptions = {
  unicode?: boolean;
  stripLegalSuffix?: boolean;
  stripGeographic?: boolean;
  punctuation?: boolean;
  dictionary?: boolean;
};

function baseNormalize(value: string, options?: EntityNormalizeOptions): string {
  const _opts: NormalizeEntityStringOptions = {
    standardizeLegalSuffix: options?.stripLegalSuffix ?? false,
  };
  let s = value.trim();
  if (!s) return "";

  if (options?.stripLegalSuffix !== false) {
    for (const [re, repl] of LEGAL_SUFFIX_REPLACERS) {
      s = s.replace(re, repl);
    }
  }

  if (options?.punctuation !== false) {
    s = s.replace(/[.,;:'"!?()[\]{}\\/|@#$%^&*+=~`<>]/g, " ");
  }

  s = s.replace(/\s+/g, " ").trim();

  if (options?.unicode !== false) {
    s = s.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  } else {
    s = s.toLowerCase();
  }

  if (options?.stripGeographic !== false) {
    s = s
      .replace(/\b(italia|italy|europa|europe)\b/gi, " ")
      .replace(/\s+/g, " ")
      .trim();
  }

  return s;
}

export function normalizeEntityInput(value: string, options?: EntityNormalizeOptions): string {
  return baseNormalize(value, options);
}

export function entityNormKey(value: string, options?: EntityNormalizeOptions): string {
  return entityAutocompleteKey(value, { standardizeLegalSuffix: options?.stripLegalSuffix ?? false });
}

export function canonicalizeEntityName(
  value: string,
  pool: readonly string[],
  options?: EntityNormalizeOptions,
): string {
  const trimmed = value.trim();
  if (!trimmed) return "";

  const dictStripped = options?.dictionary ? stripDictionaryTokens(trimmed) : trimmed;
  const normalized = baseNormalize(dictStripped, options);
  if (!normalized) return trimmed;

  const poolNorm = pool.map((p) => ({
    label: p,
    norm: baseNormalize(p, options),
    key: entityNormKey(p, options),
  }));

  const inputKey = entityNormKey(dictStripped, options);
  const exact = poolNorm.find((p) => p.key === inputKey || p.norm === normalized);
  if (exact) return exact.label;

  const tokens = normalized.split(/\s+/).filter(Boolean);
  for (let len = tokens.length; len >= 1; len -= 1) {
    const prefix = tokens.slice(0, len).join(" ");
    const hit = poolNorm.find((p) => p.norm === prefix || p.norm.startsWith(`${prefix} `));
    if (hit) return hit.label;
  }

  return dictStripped.trim();
}

export function ocrNormKey(value: string, entityType: string): string {
  return `${entityType}:${entityNormKey(value, { stripLegalSuffix: true, stripGeographic: true })}`;
}

