import {
  IMPORT_FILE_KIND_MODULE,
  type ImportFileKind,
} from "@/lib/import-files/import-file-types";
import type { GestionalePermissionModule } from "@/src/lib/permissions/gestionale-modules";
import { verifyServerModuleCan } from "@/src/lib/auth/server-permission-guards";
import { createSupabaseServerUserClient } from "@/src/lib/supabase/server-user-client";

export class ImportFileAccessError extends Error {
  readonly code: "NOT_FOUND" | "FORBIDDEN" = "FORBIDDEN";

  constructor(message: string, code: "NOT_FOUND" | "FORBIDDEN" = "FORBIDDEN") {
    super(message);
    this.name = "ImportFileAccessError";
    this.code = code;
  }
}

type ImportFileAccessRow = {
  id: string;
  kind: ImportFileKind;
  uploaded_by: string;
  status: string;
};

export async function loadImportFileForAccess(fileId: string): Promise<ImportFileAccessRow> {
  const sb = await createSupabaseServerUserClient();
  const { data: userData } = await sb.auth.getUser();
  const userId = userData.user?.id;
  if (!userId) throw new ImportFileAccessError("Non autenticato");

  const { data, error } = await sb
    .from("import_files")
    .select("id, kind, uploaded_by, status")
    .eq("id", fileId)
    .maybeSingle();

  if (error) throw new ImportFileAccessError(error.message);
  if (!data) throw new ImportFileAccessError("Import file non trovato", "NOT_FOUND");

  return data as ImportFileAccessRow;
}

export async function assertImportFileOwner(fileId: string, userId: string): Promise<ImportFileAccessRow> {
  const row = await loadImportFileForAccess(fileId);
  if (row.uploaded_by !== userId) {
    throw new ImportFileAccessError("Solo il caricatore può annullare questo import");
  }
  return row;
}

export async function assertImportFileProcessAccess(
  fileId: string,
  userId: string,
): Promise<ImportFileAccessRow> {
  const row = await loadImportFileForAccess(fileId);
  if (row.uploaded_by === userId) return row;

  const module = IMPORT_FILE_KIND_MODULE[row.kind] as GestionalePermissionModule;
  const allowed = await verifyServerModuleCan(module, "write");
  if (!allowed) {
    throw new ImportFileAccessError("Permesso negato");
  }
  return row;
}

import "server-only";

import { CompanyNotConfiguredError, getCompanyIdForUserOrNull } from "@/lib/document-capture/company-id.server";
import {
  IMPORT_FILE_KIND_MODULE,
  IMPORT_FILE_KINDS,
  type ImportFileKind,
} from "@/lib/import-files/import-file-types";
import {
  IMPORT_SOURCES_MAX_BYTES,
  isAllowedImportFileMime,
} from "@/lib/import-files/import-file-mime.server";
import { createImportFileUploadPolicy } from "@/lib/import-files/upload-policy.server";
import type { GestionalePermissionModule } from "@/src/lib/permissions/gestionale-modules";
import { verifyServerModuleCan } from "@/src/lib/auth/server-permission-guards";
import { createSupabaseServerUserClient } from "@/src/lib/supabase/server-user-client";
import { NextResponse } from "next/server";

export function isImportFileKind(value: string): value is ImportFileKind {
  return (IMPORT_FILE_KINDS as readonly string[]).includes(value);
}

export async function requireImportFileModuleWrite(kind: ImportFileKind): Promise<NextResponse | null> {
  const module = IMPORT_FILE_KIND_MODULE[kind] as GestionalePermissionModule;
  const allowed = await verifyServerModuleCan(module, "write");
  if (!allowed) {
    return NextResponse.json({ error: "Permesso negato", code: "UNAUTHORIZED" }, { status: 403 });
  }
  return null;
}

export async function requireImportFileAuthUser(): Promise<
  { userId: string } | NextResponse
> {
  const sb = await createSupabaseServerUserClient();
  const { data } = await sb.auth.getUser();
  const userId = data.user?.id;
  if (!userId) {
    return NextResponse.json({ error: "Non autenticato", code: "UNAUTHORIZED" }, { status: 401 });
  }
  return { userId };
}

export type ImportFileUploadPolicyBody = {
  kind?: string;
  fileName?: string;
  expectedMime?: string;
  expectedSizeBytes?: number;
  importSessionId?: string;
};

export async function handleImportFileUploadPolicy(body: ImportFileUploadPolicyBody) {
  const kindRaw = body.kind?.trim() ?? "";
  const fileName = body.fileName?.trim() ?? "";
  const expectedMime = body.expectedMime?.trim().toLowerCase() ?? "";
  const expectedSizeBytes = Number(body.expectedSizeBytes ?? 0);

  if (!isImportFileKind(kindRaw)) {
    return NextResponse.json({ error: "kind non valido" }, { status: 400 });
  }
  if (!fileName) {
    return NextResponse.json({ error: "fileName richiesto" }, { status: 400 });
  }
  if (!isAllowedImportFileMime(expectedMime)) {
    return NextResponse.json({ error: "MIME non consentito" }, { status: 400 });
  }
  if (!Number.isFinite(expectedSizeBytes) || expectedSizeBytes <= 0) {
    return NextResponse.json({ error: "expectedSizeBytes non valido" }, { status: 400 });
  }
  if (expectedSizeBytes > IMPORT_SOURCES_MAX_BYTES) {
    return NextResponse.json({ error: "File troppo grande" }, { status: 413 });
  }

  const auth = await requireImportFileAuthUser();
  if (auth instanceof NextResponse) return auth;

  const perm = await requireImportFileModuleWrite(kindRaw);
  if (perm) return perm;

  try {
    const policy = await createImportFileUploadPolicy({
      kind: kindRaw,
      fileName,
      expectedMime,
      expectedSizeBytes,
      importSessionId: body.importSessionId,
    });
    void getCompanyIdForUserOrNull();
    return NextResponse.json(policy);
  } catch (e) {
    if (e instanceof CompanyNotConfiguredError) {
      return NextResponse.json({ error: e.message, code: "TENANT_MISSING" }, { status: 403 });
    }
    const message = e instanceof Error ? e.message : "Errore policy upload";
    return NextResponse.json({ error: message, code: "UPLOAD_FAILED" }, { status: 400 });
  }
}

import type { LabelPayload } from "@/lib/inventory-labels/domain/types";

const PLACEHOLDER_MARCA = new Set(["—", "-", "–", "nessuna marca"]);

function normMarcaToken(value: string | undefined | null): string {
  return (value ?? "").trim().replace(/\s+/g, " ");
}

export function labelMarcaToken(value: string | undefined | null): string {
  const t = normMarcaToken(value);
  if (!t) return "";
  if (PLACEHOLDER_MARCA.has(t.toLowerCase())) return "";
  return t;
}

export function labelDisplayCaps(text: string): string {
  const t = text.trim();
  return t ? t.toLocaleUpperCase("it-IT") : "";
}

/** Riga marca principale (senza secondaria). */
export function formatLabelMarcaLine(marca: string, _marcaSecondaria?: string): string {
  return labelDisplayCaps(labelMarcaToken(marca));
}

/** Doppia marca: `BTE / OMB` sulla prima riga. */
export function formatLabelMarcaCombinedLine(marca: string, marcaSecondaria: string): string {
  const primary = labelMarcaToken(marca);
  const secondary = labelMarcaToken(marcaSecondaria);
  if (!primary) return labelDisplayCaps(secondary);
  if (!secondary || secondary === primary) return labelDisplayCaps(primary);
  return labelDisplayCaps(`${primary} / ${secondary}`);
}

/** Riga marca secondaria / alternativa commerciale. */
export function formatLabelMarcaSecondariaLine(marcaSecondaria?: string): string {
  return labelDisplayCaps(labelMarcaToken(marcaSecondaria ?? ""));
}

export function shouldRenderMarcaSecondaria(
  payload: Pick<LabelPayload, "marca" | "marcaSecondaria" | "fornitoreAlternativo">,
): boolean {
  const sec = labelMarcaToken(payload.marcaSecondaria);
  if (!sec) return false;
  const primary = labelMarcaToken(payload.marca);
  const fornitore = labelMarcaToken(payload.fornitoreAlternativo);
  return sec !== primary && sec !== fornitore;
}

/** Riga codice cliente: solo codice OE, senza suffisso marca. */
export function formatLabelCodiceCliente(codice: string): string {
  return labelDisplayCaps(codice.trim());
}

export type LabelCodiceLineOptions = {
  /** Marca anagrafica del ricambio (payload.marca). */
  ricambioMarca?: string;
  /** Doppia marca OE visibile sull'etichetta. */
  multipleMarche?: boolean;
};

function shouldShowCodiceMarcaSuffix(
  marcaCodice: string,
  options?: LabelCodiceLineOptions,
): boolean {
  const m = labelMarcaToken(marcaCodice);
  if (!m) return false;
  if (options?.multipleMarche) return true;
  const ricambio = labelMarcaToken(options?.ricambioMarca);
  if (!ricambio) return false;
  return m.toLocaleLowerCase("it-IT") !== ricambio.toLocaleLowerCase("it-IT");
}

/** Riga codice: `XXXX (BTE)` solo se più marche o marca codice ≠ marca ricambio. */
export function formatLabelCodiceLine(
  codice: string,
  marca?: string,
  options?: LabelCodiceLineOptions,
): string {
  const c = codice.trim();
  if (!c) return "";
  const m = labelMarcaToken(marca);
  if (!m || !shouldShowCodiceMarcaSuffix(marca ?? "", options)) {
    return labelDisplayCaps(c);
  }
  return labelDisplayCaps(`${c} (${m})`);
}

