/** Palette base gestionale — 12 colori frequenti (assegnazione automatica + picker impostazioni). */
export const ADDETTO_COLOR_POOL = [
  "#dc2626", // rosso
  "#ea580c", // arancione
  "#ca8a04", // giallo
  "#16a34a", // verde
