  "#2563eb", // blu
  "#4f46e5", // indigo
  "#7c3aed", // viola
  "#c026d3", // fucsia
  "#db2777", // rosa
  "#64748b", // grigio
] as const;

function hslToHex(h: number, s: number, l: number): string {
  const s1 = s / 100;
  const l1 = l / 100;
  const a = s1 * Math.min(l1, 1 - l1);
  const f = (n: number) => {
    const k = (n + h / 30) % 12;
    const col = l1 - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
    return Math.min(255, Math.max(0, Math.round(255 * col)));
  };
  return `#${[f(0), f(8), f(4)]
    .map((x) => x.toString(16).padStart(2, "0"))
    .join("")}`;
}

function usedHexSet(map: Record<string, string>): Set<string> {
  const u = new Set<string>();
  for (const v of Object.values(map)) {
    const n = normalizeHex(v);
    if (n) u.add(n);
  }
  return u;
}

/** Colore univoco non ancora in `used` (palette mescolata da salt, poi varianti HSL). */
export function nextUniqueAddettoColor(used: Set<string>, salt: number): string {
  const pool = [...ADDETTO_COLOR_POOL];
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.abs((salt + i * 31) >>> 0) % (i + 1);
    const t = pool[i]!;
    pool[i] = pool[j]!;
    pool[j] = t;
  }
  for (const c of pool) {
    const n = normalizeHex(c);
    if (n && !used.has(n)) return n;
  }
  for (let step = 0; step < 500; step++) {
    const hue = ((salt >>> 0) + step * 19) % 360;
    const sat = 46 + (step % 6) * 2.5;
    const light = 43 + ((step >> 2) % 5) * 2.2;
    const hex = hslToHex(hue, sat, light);
    const n = normalizeHex(hex);
    if (n && !used.has(n)) return n;
  }
  const fallback = `#${((salt >>> 0) & 0xffffff).toString(16).padStart(6, "0")}`;
  return normalizeHex(fallback) ?? "#52525b";
}

/**
 * Allinea la mappa ai nomi correnti: mantiene colori validi, elimina orfani,
 * assegna colori univoci ai nomi senza voce (o con collisione su stesso hex).
 */
export function syncAddettoColorMap(
  addetti: string[],
  existing: Record<string, string> | undefined,
): Record<string, string> {
  const out: Record<string, string> = {};
  const used = new Set<string>();

  for (const name of addetti) {
    const nh = normalizeHex(existing?.[name]);
    if (nh && !used.has(nh)) {
      out[name] = nh;
      used.add(nh);
    }
  }

  for (const name of addetti) {
    if (out[name]) continue;
    const hex = nextUniqueAddettoColor(used, (name.length + 1) * 1315423911 + addetti.indexOf(name) * 97);
    const n = normalizeHex(hex)!;
    out[name] = n;
    used.add(n);
  }

  return out;
}

/**
 * Allinea mappa colori ai record per chiave stabile (colorKey / id).
 * Migra colori legacy keyed per nome se presenti in `existing`.
 */
export function syncAddettoColorMapById(
  records: readonly AddettoRecord[],
  existing: Record<string, string> | undefined,
): Record<string, string> {
  const out: Record<string, string> = {};
  const used = new Set<string>();

  for (const rec of records) {
    const key = addettoColorKey(rec);
    const fromKey = normalizeHex(existing?.[key]) ?? normalizeHex(existing?.[rec.id]);
    const fromNome = normalizeHex(existing?.[rec.nome.trim()]);
    const nh = fromKey ?? fromNome;
    if (nh && !used.has(nh)) {
      out[key] = nh;
      used.add(nh);
    }
  }

  for (const rec of records) {
    const key = addettoColorKey(rec);
    if (out[key]) continue;
    const hex = nextUniqueAddettoColor(
      used,
      (key.length + 1) * 1315423911 + records.indexOf(rec) * 97,
    );
    const n = normalizeHex(hex)!;
    out[key] = n;
    used.add(n);
  }

  return out;
}

/** Migra mappa legacy nome → id; mantiene hex per record matchati. */
export function migrateAddettoColorMapNomeToId(
  records: readonly AddettoRecord[],
  existing: Record<string, string> | undefined,
): Record<string, string> {
  return syncAddettoColorMapById(records, existing);
}

function addettoColorLookupKeys(
  colorKey: string,
  records?: readonly AddettoRecord[],
): string[] {
  const k = colorKey.trim();
  if (!k) return [];
  const keys = new Set<string>([k]);
  if (records?.length) {
    const rec = findAddettoById(records, k) ?? findAddettoByStoredName(records, k);
    if (rec) {
      keys.add(addettoColorKey(rec));
      keys.add(rec.id);
      const nome = rec.nome.trim();
      if (nome) keys.add(nome);
    }
  }
  return [...keys];
}

/** Colore per UI da chiave stabile id/colorKey (con fallback nome legacy se `records` è fornito). */
export function addettoDisplayColorById(
  colorKey: string,
  map: Record<string, string>,
  records?: readonly AddettoRecord[],
): string {
  const k = colorKey.trim();
  if (!k) return addettoThemeColorFromId("empty");
  for (const key of addettoColorLookupKeys(k, records)) {
    const n = normalizeHex(map[key]);
    if (n) return n;
  }
  const rec = records?.length
    ? findAddettoById(records, k) ?? findAddettoByStoredName(records, k)
    : undefined;
  return addettoThemeColorFromId(rec ? addettoColorKey(rec) : k);
}

export function assignColorForNewAddettoById(
  prev: Record<string, string>,
  record: Pick<AddettoRecord, "id" | "colorKey">,
): Record<string, string> {
  const key = addettoColorKey(record);
  const used = usedHexSet(prev);
  const salt = (Date.now() + Math.floor(Math.random() * 0x7fffffff)) >>> 0;
  const hex = nextUniqueAddettoColor(used, salt);
  return { ...prev, [key]: hex };
}

export function removeAddettoFromColorMapById(
  prev: Record<string, string>,
  record: Pick<AddettoRecord, "id" | "colorKey">,
): Record<string, string> {
  const key = addettoColorKey(record);
  const { [key]: _, ...rest } = prev;
  return rest;
}

/** Colore per UI: da mappa persistita, altrimenti fallback deterministico (righe legacy). */
export function addettoDisplayColor(
  nome: string,
  map: Record<string, string>,
  records?: readonly AddettoRecord[],
): string {
  return addettoDisplayColorById(nome, map, records);
}

export function assignColorForNewAddetto(prev: Record<string, string>, newName: string): Record<string, string> {
  const used = usedHexSet(prev);
  const salt = (Date.now() + Math.floor(Math.random() * 0x7fffffff)) >>> 0;
  const hex = nextUniqueAddettoColor(used, salt);
  return { ...prev, [newName]: hex };
}

export function renameAddettoInColorMap(
  prev: Record<string, string>,
  previousName: string,
  nextName: string,
): Record<string, string> {
  const col = normalizeHex(prev[previousName]);
  const { [previousName]: _, ...rest } = prev;
  if (col) return { ...rest, [nextName]: col };
  const used = usedHexSet(rest);
  return { ...rest, [nextName]: nextUniqueAddettoColor(used, nextName.length * 999983) };
}

export function removeAddettoFromColorMap(prev: Record<string, string>, name: string): Record<string, string> {
  const { [name]: _, ...rest } = prev;
  return rest;
}

import type { NotificationIntent } from "@/lib/lavorazioni/lavorazione-created-notification-mapper";
import {
  notificationCreatedAt,
  notificationStoreKey,
  wrapLavorazioneNotification,
  type AdminDashboardNotification,
} from "@/lib/notifications/admin-dashboard-notifications";

export type AdminNotificationStoreState = {
  lastSeenAt: string | null;
  items: Record<string, AdminDashboardNotification>;
};

/** Limite voci in localStorage — evita quota exceeded e liste infinite (fase 10 audit). */
/** ponytail: DEPRECATED — sunset quando notifications_v2_mode=on stabile ≥7gg prod; rollback via flag off. */
export const ADMIN_NOTIFICATION_STORE_MAX_ITEMS = 150;

const STORAGE_PREFIX = "cab:admin-dashboard-notifications:";
const LEGACY_STORAGE_PREFIX = "cab:admin-lav-notifications:";

type StoreListener = (userId: string) => void;
const listeners = new Set<StoreListener>();

let storageBridgeAttached = false;

function dispatchStorageKey(key: string): void {
  if (key.startsWith(STORAGE_PREFIX)) {
    const userId = key.slice(STORAGE_PREFIX.length);
    for (const fn of listeners) fn(userId);
    return;
  }
  if (key.startsWith(LEGACY_STORAGE_PREFIX)) {
    const userId = key.slice(LEGACY_STORAGE_PREFIX.length);
    for (const fn of listeners) fn(userId);
  }
}

function onCrossTabStorage(e: StorageEvent): void {
  if (!e.key) return;
  dispatchStorageKey(e.key);
}

function ensureStorageBridgeListener(): void {
  if (storageBridgeAttached || typeof window === "undefined") return;
  storageBridgeAttached = true;
  window.addEventListener("storage", onCrossTabStorage);
}

function storageKey(userId: string): string {
  return `${STORAGE_PREFIX}${userId}`;
}

function legacyStorageKey(userId: string): string {
  return `${LEGACY_STORAGE_PREFIX}${userId}`;
}

function normalizeItem(raw: unknown): AdminDashboardNotification | null {
  if (!raw || typeof raw !== "object") return null;
  const obj = raw as Record<string, unknown>;
  if (obj.kind === "admin_dashboard_test") {
    const id = typeof obj.id === "string" && obj.id.trim() ? obj.id.trim() : `admin-test:${Date.now()}`;
    return {
      kind: "admin_dashboard_test",
      id,
      message: typeof obj.message === "string" ? obj.message : "Notifica di test",
      createdAt: typeof obj.createdAt === "string" ? obj.createdAt : new Date().toISOString(),
    };
  }

  if (obj.kind === "dipendenti_presenze_reminder") {
    const dateYmd = typeof obj.dateYmd === "string" ? obj.dateYmd.trim() : "";
    if (!dateYmd) return null;
    const id =
      typeof obj.id === "string" && obj.id.trim() ? obj.id.trim() : `dip-presenze:${dateYmd}`;
    return {
      kind: "dipendenti_presenze_reminder",
      id,
      dateYmd,
      count: typeof obj.count === "number" && obj.count > 0 ? obj.count : 1,
      createdAt: typeof obj.createdAt === "string" ? obj.createdAt : new Date().toISOString(),
    };
  }

  if (obj.kind === "magazzino_sotto_scorta") {
    const ricambioId = typeof obj.ricambioId === "string" ? obj.ricambioId.trim() : "";
    if (!ricambioId) return null;
    return {
      kind: "magazzino_sotto_scorta",
      id: typeof obj.id === "string" && obj.id.trim() ? obj.id.trim() : ricambioId,
      ricambioId,
      marca: typeof obj.marca === "string" ? obj.marca : "—",
      descrizione: typeof obj.descrizione === "string" ? obj.descrizione : "—",
      scorta: typeof obj.scorta === "number" ? obj.scorta : 0,
      scortaMinima: typeof obj.scortaMinima === "number" ? obj.scortaMinima : 0,
      createdAt: typeof obj.createdAt === "string" ? obj.createdAt : new Date().toISOString(),
    };
  }

  const lavorazioneId =
    typeof obj.lavorazioneId === "string"
      ? obj.lavorazioneId.trim()
      : typeof obj.id === "string"
        ? obj.id.trim()
        : "";
  if (!lavorazioneId) return null;

  const intent: NotificationIntent = {
    lavorazioneId,
    titolo: typeof obj.titolo === "string" ? obj.titolo : lavorazioneId,
    cliente: typeof obj.cliente === "string" ? obj.cliente : "",
    mezzo: typeof obj.mezzo === "string" ? obj.mezzo : "",
    targa: typeof obj.targa === "string" ? obj.targa : null,
    createdBy: typeof obj.createdBy === "string" ? obj.createdBy : null,
    createdAt: typeof obj.createdAt === "string" ? obj.createdAt : new Date().toISOString(),
  };
  return wrapLavorazioneNotification(intent);
}

function parseStoreItems(rawItems: unknown): Record<string, AdminDashboardNotification> {
  if (!rawItems || typeof rawItems !== "object") return {};
  const items: Record<string, AdminDashboardNotification> = {};
  for (const [key, value] of Object.entries(rawItems as Record<string, unknown>)) {
    const item = normalizeItem(value);
    if (!item) continue;
    items[notificationStoreKey(item)] = item;
  }
  return items;
}

function migrateLegacyStore(userId: string): AdminNotificationStoreState | null {
  if (typeof window === "undefined" || !userId.trim()) return null;
  try {
    const raw = window.localStorage.getItem(legacyStorageKey(userId));
    if (!raw) return null;
    const parsed = JSON.parse(raw) as AdminNotificationStoreState;
    if (!parsed || typeof parsed !== "object") return null;
    const migrated: AdminNotificationStoreState = {
      lastSeenAt: typeof parsed.lastSeenAt === "string" ? parsed.lastSeenAt : null,
      items: parseStoreItems(parsed.items),
    };
    saveAdminNotificationStore(userId, migrated);
    window.localStorage.removeItem(legacyStorageKey(userId));
    return migrated;
  } catch {
    return null;
  }
}

export function emptyAdminNotificationStore(): AdminNotificationStoreState {
  return { lastSeenAt: null, items: {} };
}

export function loadAdminNotificationStore(userId: string): AdminNotificationStoreState {
  if (typeof window === "undefined" || !userId.trim()) return emptyAdminNotificationStore();
  try {
    const raw = window.localStorage.getItem(storageKey(userId));
    if (!raw) {
      return migrateLegacyStore(userId) ?? emptyAdminNotificationStore();
    }
    const parsed = JSON.parse(raw) as AdminNotificationStoreState;
    if (!parsed || typeof parsed !== "object" || !parsed.items) return emptyAdminNotificationStore();
    return {
      lastSeenAt: typeof parsed.lastSeenAt === "string" ? parsed.lastSeenAt : null,
      items: parseStoreItems(parsed.items),
    };
  } catch {
    return emptyAdminNotificationStore();
  }
}

export function saveAdminNotificationStore(userId: string, state: AdminNotificationStoreState): void {
  if (typeof window === "undefined" || !userId.trim()) return;
  try {
    window.localStorage.setItem(storageKey(userId), JSON.stringify(state));
  } catch {
    /* ignore quota */
  }
  for (const fn of listeners) {
    try {
      fn(userId);
    } catch {
      /* ignore */
    }
  }
}

export function isNotificationUnread(
  state: AdminNotificationStoreState,
  notification: AdminDashboardNotification,
): boolean {
  if (!state.lastSeenAt) return true;
  const seen = new Date(state.lastSeenAt).getTime();
  const created = new Date(notificationCreatedAt(notification)).getTime();
  if (Number.isNaN(seen) || Number.isNaN(created)) return true;
  return created > seen;
}

export function getUnreadCount(state: AdminNotificationStoreState): number {
  return listNotifications(state).filter((item) => isNotificationUnread(state, item)).length;
}

export function listNotifications(state: AdminNotificationStoreState): AdminDashboardNotification[] {
  return Object.values(state.items).sort(
    (a, b) => new Date(notificationCreatedAt(b)).getTime() - new Date(notificationCreatedAt(a)).getTime(),
  );
}

function pruneNotificationStoreItems(state: AdminNotificationStoreState): AdminNotificationStoreState {
  const count = Object.keys(state.items).length;
  if (count <= ADMIN_NOTIFICATION_STORE_MAX_ITEMS) return state;

  const dropCount = count - ADMIN_NOTIFICATION_STORE_MAX_ITEMS;
  const oldestFirst = [...listNotifications(state)].sort(
    (a, b) => new Date(notificationCreatedAt(a)).getTime() - new Date(notificationCreatedAt(b)).getTime(),
  );
  const items = { ...state.items };
  let dropped = 0;

  for (const notification of oldestFirst) {
    if (dropped >= dropCount) break;
    if (isNotificationUnread(state, notification)) continue;
    delete items[notificationStoreKey(notification)];
    dropped++;
  }

  if (dropped < dropCount) {
    for (const notification of oldestFirst) {
      if (dropped >= dropCount) break;
      const key = notificationStoreKey(notification);
      if (!items[key]) continue;
      delete items[key];
      dropped++;
    }
  }

  return { ...state, items };
}

/** Garantisce che un nuovo inserimento risulti non letto anche se createdAt coincide con lastSeenAt (stesso ms). */
function withCreatedAtAfterLastSeen(
  state: AdminNotificationStoreState,
  notification: AdminDashboardNotification,
): AdminDashboardNotification {
  if (!state.lastSeenAt) return notification;
  const seen = new Date(state.lastSeenAt).getTime();
  const created = new Date(notificationCreatedAt(notification)).getTime();
  if (Number.isNaN(seen) || Number.isNaN(created) || created > seen) return notification;
  const bumped = new Date(seen + 1).toISOString();
  return { ...notification, createdAt: bumped };
}

export function upsertAdminNotification(
  userId: string,
  notification: AdminDashboardNotification,
): AdminNotificationStoreState {
  const state = loadAdminNotificationStore(userId);
  const key = notificationStoreKey(notification);
  if (state.items[key]) return state;
  const item = withCreatedAtAfterLastSeen(state, notification);
  const next: AdminNotificationStoreState = {
    ...state,
    items: { ...state.items, [key]: item },
  };
  const pruned = pruneNotificationStoreItems(next);
  saveAdminNotificationStore(userId, pruned);
  return pruned;
}

export function markAllAdminNotificationsRead(userId: string): AdminNotificationStoreState {
  const state = loadAdminNotificationStore(userId);
  const next: AdminNotificationStoreState = {
    ...state,
    lastSeenAt: new Date().toISOString(),
  };
  saveAdminNotificationStore(userId, next);
  return next;
}

/** Segna letta una singola notifica (avanza lastSeenAt fino al suo createdAt). */
export function markAdminNotificationRead(
  userId: string,
  notification: AdminDashboardNotification,
): AdminNotificationStoreState {
  const state = loadAdminNotificationStore(userId);
  if (!isNotificationUnread(state, notification)) return state;
  const createdMs = new Date(notificationCreatedAt(notification)).getTime();
  if (Number.isNaN(createdMs)) return state;
  const seenMs = state.lastSeenAt ? new Date(state.lastSeenAt).getTime() : 0;
  const nextSeenMs = Math.max(Number.isNaN(seenMs) ? 0 : seenMs, createdMs);
  const next: AdminNotificationStoreState = {
    ...state,
    lastSeenAt: new Date(nextSeenMs).toISOString(),
  };
  saveAdminNotificationStore(userId, next);
  return next;
}

export function removeAdminNotification(
  userId: string,
  notification: AdminDashboardNotification,
): AdminNotificationStoreState {
  const state = loadAdminNotificationStore(userId);
  const key = notificationStoreKey(notification);
  if (!state.items[key]) return state;
  const items = { ...state.items };
  delete items[key];
  const next: AdminNotificationStoreState = { ...state, items };
  saveAdminNotificationStore(userId, next);
  return next;
}

export function removeReadAdminNotifications(userId: string): AdminNotificationStoreState {
  const state = loadAdminNotificationStore(userId);
  const items: Record<string, AdminDashboardNotification> = {};
  for (const [key, item] of Object.entries(state.items)) {
    if (isNotificationUnread(state, item)) {
      items[key] = item;
    }
  }
  const next: AdminNotificationStoreState = { ...state, items };
  saveAdminNotificationStore(userId, next);
  return next;
}

export function countReadAdminNotifications(state: AdminNotificationStoreState): number {
  return listNotifications(state).filter((item) => !isNotificationUnread(state, item)).length;
}

export function clearMagazzinoNotifications(userId: string): AdminNotificationStoreState {
  const state = loadAdminNotificationStore(userId);
  const items: Record<string, AdminDashboardNotification> = {};
  for (const [key, item] of Object.entries(state.items)) {
    if (item.kind !== "magazzino_sotto_scorta") items[key] = item;
  }
  const next: AdminNotificationStoreState = { ...state, items };
  saveAdminNotificationStore(userId, next);
  return next;
}

export function subscribeAdminNotificationStore(listener: StoreListener): () => void {
  listeners.add(listener);
  ensureStorageBridgeListener();
  return () => listeners.delete(listener);
}

import { formatClientPortalAttrezzatura } from "@/lib/lavorazioni/client-portal-attrezzatura-format";
import { formatClientPortalDay } from "@/lib/lavorazioni/format-client-portal-day";
import { lavorazioneDisplayCodice } from "@/lib/lavorazioni/lavorazione-codice";
import {
  buildLatestLogAutoreByEntitaId,
  sanitizeClientPortalAutore,
} from "@/lib/lavorazioni/lavorazione-ultima-modifica";
import { parseMezzoMeta } from "@/lib/mezzi/mezzi-meta";
import { statoLavorazioneLabel } from "@/src/shared/selectors";
import type { LavorazioneListRow } from "@/src/services/lavorazioni.service";
import type { LogModificaRow, LogModificaWithProfileRow, LavorazioneRow } from "@/src/types/supabase-tables";
import type { LavorazioneTimelineItem } from "@/src/services/domain/lavorazioni-domain.service";

export type ClientIngressoSummary = {
  cliente: string;
  attrezzatura: string;
  descrizione: string;
  dataIngresso: string;
};

export type ClientVisibleNote = {
  text: string;
};


function fmtWhen(iso: string): string {
  try {
    return new Date(iso).toLocaleString("it-IT", { dateStyle: "short", timeStyle: "short" });
  } catch {
    return iso;
  }
}

export function lavorazioneRefLabel(id: string, codice?: string | null): string {
  return lavorazioneDisplayCodice({ id, codice });
}

export function macchinaClienteLabel(row: LavorazioneListRow): string {
  const m = row.mezzo;
  if (!m) return "—";
  const brand = `${m.marca ?? ""} ${m.modello ?? ""}`.trim();
  return brand || "—";
}

/** Raggruppa log lavorazioni per `entita_id` (lookup O(1) in lista archivio). */
export function groupLavorazioniLogsById(
  logs: readonly LogModificaRow[],
): ReadonlyMap<string, readonly LogModificaRow[]> {
  const map = new Map<string, LogModificaRow[]>();
  for (const row of logs) {
    if (row.entita !== "lavorazioni") continue;
    const id = row.entita_id?.trim();
    if (!id) continue;
    const list = map.get(id);
    if (list) list.push(row);
    else map.set(id, [row]);
  }
  return map;
}

/** Autore ultima modifica da log (portale clienti — risolve profili lazy, no UUID in UI). */
export function buildClientPortalLogAutoreByLavorazioneId(
  logs: readonly LogModificaRow[],
  opts: {
    lazyProfileNames: ReadonlyMap<string, string>;
    currentUserId?: string | null;
    currentUserDisplayName?: string | null;
    /** Portale clienti: non esporre UUID o fallback tecnico. */
    omitUnresolvedAutore?: boolean;
  },
): ReadonlyMap<string, string> {
  const { lazyProfileNames, currentUserId, currentUserDisplayName, omitUnresolvedAutore } = opts;
  return buildLatestLogAutoreByEntitaId(logs, (row) => {
    const id = row.autore_id?.trim();
    if (id) {
      const lazy = lazyProfileNames.get(id);
      if (lazy) return omitUnresolvedAutore ? sanitizeClientPortalAutore(lazy) : lazy;
      if (currentUserId && id === currentUserId && currentUserDisplayName?.trim()) {
        const name = currentUserDisplayName.trim();
        return omitUnresolvedAutore ? sanitizeClientPortalAutore(name) : name;
      }
    }
    const profileNome = (row as LogModificaWithProfileRow).profiles?.nome?.trim();
    if (profileNome) return sanitizeClientPortalAutore(profileNome);
    return "";
  });
}

/** Addetto da log UPDATE/UNDO (payload addetto o addettoAccettazione), più recente per primo. */
export function latestAddettoFromLogs(logs: readonly LogModificaRow[]): string {
  const sorted = [...logs].sort((a, b) => b.created_at.localeCompare(a.created_at));
  for (const lg of sorted) {
    if (lg.azione !== "UPDATE" && lg.azione !== "UNDO") continue;
    const payload = lg.payload as {
      after?: { addetto?: unknown; addettoAccettazione?: unknown };
    } | null | undefined;
    for (const raw of [payload?.after?.addetto, payload?.after?.addettoAccettazione]) {
      if (typeof raw === "string") {
        const addetto = raw.trim();
        if (addetto && addetto !== "—") return addetto;
      }
    }
  }
  return "—";
}

export function buildClientIngressoSummary(row: LavorazioneListRow): ClientIngressoSummary {
  const m = row.mezzo;
  const attrezzatura = formatClientPortalAttrezzatura({
    marca: m?.marca,
    modello: m?.modello,
  });
  const targa = m?.targa?.trim();
  const attDisplay = targa && targa !== "—" ? `${attrezzatura} (${targa})` : attrezzatura;

  return {
    cliente: m?.cliente?.trim() || "—",
    attrezzatura: attDisplay,
    descrizione: row.note?.trim() || "—",
    dataIngresso: formatClientPortalDay(row.data_ingresso ?? row.created_at),
  };
}

export function buildClientVisibleNotes(row: LavorazioneRow): ClientVisibleNote[] {
  const note = row.note?.trim();
  if (!note) return [];
  return [{ text: note }];
}

/** Timeline cliente: solo cambi stato e ripristino. */
export function buildClientTimeline(
  logs: readonly LogModificaRow[],
  statiOpts: { id: string; label: string; color?: string }[] = [],
): LavorazioneTimelineItem[] {
  const items: LavorazioneTimelineItem[] = [];

  for (const lg of logs) {
    if (lg.azione === "RESTORE") {
      items.push({
        id: `restore-${lg.id}`,
        kind: "log",
        at: lg.created_at,
        title: "Lavorazione ripristinata",
      });
      continue;
    }
    if (lg.azione !== "UPDATE") continue;
    const payload = lg.payload as { before?: Record<string, unknown>; after?: Record<string, unknown> } | null | undefined;
    const before = payload?.before;
    const after = payload?.after;
    if (before?.stato !== after?.stato && typeof after?.stato === "string") {
      const statoLabel = statoLavorazioneLabel(after.stato, statiOpts);
      items.push({
        id: `stato-${lg.id}`,
        kind: "log",
        at: lg.created_at,
        title: `Stato · ${statoLabel}`,
      });
    }
  }

  items.sort((a, b) => b.at.localeCompare(a.at));
  return items;
}

export function fmtClientUpdatedAt(iso: string | null | undefined): string {
  if (!iso?.trim()) return "—";
  return fmtWhen(iso);
}

