"use client";

import { useMemo } from "react";
import { enrichLavorazioneListRowsWithMezzi } from "@/lib/db/dto-mappers";
import { mezziGestitiToEmbedMap } from "@/lib/mezzi/mezzi-attrezzature-batch";
import type { MezzoGestito } from "@/lib/mezzi/types";
import type { ListQueryResult } from "@/lib/domain/list-types";
import { useLavorazioniList } from "@/src/services/domain/lavorazioni-domain.queries";
import type { LavorazioneFilters, LavorazioneListRow } from "@/src/services/lavorazioni.service";

export type UseLavorazioniReportSliceOpts = {
  archived?: boolean;
  mezziRows?: readonly MezzoGestito[];
  enabled?: boolean;
  staleTime?: number;
};

/** PR-4 — report-mode slice; mezzo embed deferred to caller mezzi cache when provided. */
export function useLavorazioniReportSlice(
  opts?: UseLavorazioniReportSliceOpts,
): ListQueryResult<LavorazioneListRow> {
  const filters = useMemo((): LavorazioneFilters => {
    const f: LavorazioneFilters = { fetchMode: "report", includeMezzo: false };
    if (opts?.archived !== undefined) f.archived = opts.archived;
    return f;
  }, [opts?.archived]);

  const listQ = useLavorazioniList(filters, {
    enabled: opts?.enabled !== false,
    staleTime: opts?.staleTime,
  });

  const data = useMemo(() => {
    const rows = listQ.data ?? [];
    const mezziRows = opts?.mezziRows;
    if (!mezziRows?.length) return rows;
    const needsEnrich = rows.some((row) => Boolean(row.mezzo_id?.trim()) && row.mezzo == null);
    if (!needsEnrich) return rows;
    return enrichLavorazioneListRowsWithMezzi(rows, mezziGestitiToEmbedMap(mezziRows));
  }, [listQ.data, opts?.mezziRows]);

  return { ...listQ, data };
}

import { resolveListinoMarkupBase } from "@/lib/magazzino/calculations";
import {
  resolveRicambioCodiceForPersist,
  ricambioCodiceForUi,
} from "@/lib/magazzino/ricambio-codice";
import type { RicambioMagazzino } from "@/lib/magazzino/types";
import {
  metaFieldsToRicambioUi,
  parseMagazzinoRicambioMeta,
  ricambioUiToMagazzinoMeta,
} from "@/lib/magazzino/magazzino-meta";
import type { MezziListePrefs } from "@/lib/mezzi/mezzi-liste-prefs-storage";
import type { MagazzinoInsert, MagazzinoUpdate } from "@/src/services/magazzino.service";
import type { MagazzinoRicambioRow } from "@/src/types/supabase-tables";

const UUID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function isMagazzinoUuid(id: string): boolean {
  return UUID_RE.test(id.trim());
}

function num(v: unknown, fallback = 0): number {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
}

/** Riga Supabase → modello UI magazzino. */
export function magazzinoRowToRicambioUI(
  row: MagazzinoRicambioRow,
  autore = "Sistema",
  mezziListe?: MezziListePrefs,
): RicambioMagazzino {
  const meta = parseMagazzinoRicambioMeta(row.meta ?? {});
  const fromMeta = metaFieldsToRicambioUi(meta);
  const listino = num(row.costo, 0);
  const vendita = num(row.prezzo_vendita, listino);
  const markupBase = resolveListinoMarkupBase(listino, fromMeta.fornitoriAlternativi ?? []);
  const markup =
    markupBase > 0 ? Math.round(((vendita - markupBase) / markupBase) * 1000) / 10 : 0;
  const autoreSalvato = meta.autoreUltimaModifica?.trim();

  return {
    id: row.id,
    marca: row.marca?.trim() || "—",
    codiceFornitoreOriginale: ricambioCodiceForUi(row.codice),
    codiceFornitoreOriginaleSecondario: fromMeta.codiceFornitoreOriginaleSecondario,
    marcaOriginaleSecondaria: fromMeta.marcaOriginaleSecondaria,
    usatoInTagliandi: fromMeta.usatoInTagliandi,
    unitaMisura: fromMeta.unitaMisura,
    descrizione: row.nome,
    note: fromMeta.note,
    categoria: fromMeta.categoria,
    compatibilitaMezzi: fromMeta.compatibilitaMezzi,
    compatibilitaRefs: fromMeta.compatibilitaRefs,
    scorta: Math.max(0, Math.round(num(row.quantita, 0))),
    scortaMinima: fromMeta.scortaMinima,
    dataUltimaModifica: row.updated_at ?? row.created_at,
    autoreUltimaModifica: autoreSalvato || autore,
    prezzoFornitoreOriginale: listino,
    scontoFornitoreOriginale: fromMeta.scontoFornitoreOriginale,
    markupPercentuale: markup,
    prezzoVendita: vendita,
    fornitoriAlternativi: fromMeta.fornitoriAlternativi,
    fornitoreNonOriginale: fromMeta.fornitoreNonOriginale,
    codiceFornitoreNonOriginale: fromMeta.codiceFornitoreNonOriginale,
    prezzoFornitoreNonOriginale: fromMeta.prezzoFornitoreNonOriginale,
    scontoFornitoreNonOriginale: fromMeta.scontoFornitoreNonOriginale,
    listinoImport: meta.listinoImport,
  };
}

/** Modello UI → insert Supabase. */
export function ricambioUiToMagazzinoInsert(
  r: RicambioMagazzino,
  mezziListe?: MezziListePrefs,
  metaPatch?: Record<string, unknown>,
): MagazzinoInsert {
  const row: MagazzinoInsert = {
    codice: resolveRicambioCodiceForPersist(r.codiceFornitoreOriginale),
    nome: r.descrizione.trim(),
    marca: r.marca.trim() || null,
    quantita: Math.max(0, Math.round(r.scorta)),
    costo: r.prezzoFornitoreOriginale > 0 ? r.prezzoFornitoreOriginale : null,
    prezzo_vendita: r.prezzoVendita > 0 ? r.prezzoVendita : null,
    consumo_medio_mensile: null,
    meta: { ...(ricambioUiToMagazzinoMeta(r, mezziListe) as Record<string, unknown>), ...(metaPatch ?? {}) },
  };
  if (isMagazzinoUuid(r.id)) {
    return { ...row, id: r.id } as MagazzinoInsert & { id: string };
  }
  return row;
}

export function ricambioUiToMagazzinoUpdate(r: RicambioMagazzino, mezziListe?: MezziListePrefs): MagazzinoUpdate {
  const insert = ricambioUiToMagazzinoInsert(r, mezziListe) as MagazzinoInsert & { id?: string };
  const { ...patch } = insert;
  return patch;
}

import { documentoMatchesMarcaModello } from "@/lib/documenti/documenti-match";
import type { LavorazioneArchiviata, LavorazioneAttiva } from "@/lib/lavorazioni/types";
import { lavorazioneMatchesMezzo } from "@/lib/mezzi/lavorazioni-sync";
import type { MezzoGestito } from "@/lib/mezzi/types";
import type { PreventivoRecord } from "@/lib/preventivi/types";
import type { DocumentoGestionale } from "@/lib/types/gestionale";

function norm(s: string): string {
  return s.trim().toLowerCase().replace(/\s+/g, " ");
}

function splitMarcaModello(macchina: string): { marca: string; modello: string } {
  const t = macchina.trim();
  if (!t) return { marca: "—", modello: "—" };
  const parts = t.split(/\s+/);
  if (parts.length === 1) return { marca: parts[0]!, modello: "—" };
  return { marca: parts[0]!, modello: parts.slice(1).join(" ") };
}

function lavSynthKey(lav: LavorazioneAttiva | LavorazioneArchiviata): string {
  const nt = norm(lav.targa);
  if (nt && nt !== "—") return `t:${nt}`;
  const nm = norm(lav.matricola);
  if (nm && nm !== "—") return `m:${nm}`;
  return `id:${lav.id}`;
}

/** Mezzo sintetico per filtri hub quando l'anagrafica non è collegata. */
export function mezzoFromLavorazione(lav: LavorazioneAttiva | LavorazioneArchiviata): MezzoGestito {
  const { marca, modello } = splitMarcaModello(lav.macchina);
  const ing = lav.dataIngresso.slice(0, 10);
  return {
    id: `hub-lav-${lav.id}`,
    lavorazioneMezzoId: lav.id,
    cliente: lav.cliente?.trim() || "—",
    utilizzatore: lav.utilizzatore?.trim() || "—",
    marca,
    modello,
    targa: lav.targa?.trim() || "—",
    matricola: lav.matricola?.trim() || "—",
    numeroScuderia: lav.nScuderia?.trim() || undefined,
    tipoAttrezzatura: "—",
    anno: 0,
    oreKm: 0,
    statoAttuale: "Solo lavorazioni",
    dataUltimaUscita: ing,
    note: `Collegato a lavorazione ${lav.id}. Completa l'anagrafica mezzi per unificare il parco.`,
    priorita: "normale",
    hubSynthetic: true,
  };
}

function fakeLavFromPreventivo(pv: PreventivoRecord): LavorazioneAttiva {
  const mac =
    pv.macchinaRiassunto?.trim() ||
    `${pv.marcaAttrezzatura ?? ""} ${pv.modelloAttrezzatura ?? ""}`.trim() ||
    "—";
  return {
    id: pv.lavorazioneId,
    macchina: mac,
    targa: pv.targa ?? "",
    matricola: pv.matricola ?? "",
    nScuderia: pv.nScuderia ?? "",
    cliente: pv.cliente,
    utilizzatore: pv.utilizzatore,
    cantiere: pv.cantiere ?? "",
    statoId: "",
    priorita: "media",
    addetto: "",
    note: "",
    dataIngresso: pv.dataCreazione,
    dataCompletamento: null,
  };
}

export function preventivoMatchesMezzo(m: MezzoGestito, pv: PreventivoRecord): boolean {
  return lavorazioneMatchesMezzo(m, fakeLavFromPreventivo(pv));
}

export function documentoRelevantePerMezzo(doc: DocumentoGestionale, m: MezzoGestito): boolean {
  return documentoMatchesMarcaModello(doc, m.marca, m.modello);
}

function mezzoFromPreventivo(pv: PreventivoRecord): MezzoGestito {
  const fake = fakeLavFromPreventivo(pv);
  const { marca, modello } = splitMarcaModello(fake.macchina);
  const ing = pv.dataCreazione.slice(0, 10);
  return {
    id: `hub-pv-${pv.id}`,
    cliente: pv.cliente,
    utilizzatore: pv.utilizzatore,
    marca,
    modello,
    targa: pv.targa?.trim() || "—",
    matricola: pv.matricola?.trim() || "—",
    numeroScuderia: pv.nScuderia?.trim() || undefined,
    tipoAttrezzatura: "—",
    anno: 0,
    oreKm: 0,
    statoAttuale: "Solo preventivi",
    dataUltimaUscita: ing,
    note: `Collegato a preventivo ${pv.numero} (${pv.id}).`,
    priorita: "normale",
    hubSynthetic: true,
  };
}

/**
 * Unisce anagrafica mezzi con veicoli emersi solo da lavorazioni o preventivi (nessun duplicato se già coperto da match).
 */
export function mergeMezziHubRows(
  baseMezzi: MezzoGestito[],
  attive: LavorazioneAttiva[],
  storico: LavorazioneArchiviata[],
  preventivi: PreventivoRecord[],
  _documenti: DocumentoGestionale[],
): MezzoGestito[] {
  const rows: MezzoGestito[] = baseMezzi.map((m) => ({ ...m }));

  function coveredByRow(lav: LavorazioneAttiva | LavorazioneArchiviata): boolean {
    return rows.some((m) => lavorazioneMatchesMezzo(m, lav));
  }

  const synthLavKeys = new Set<string>();
  const lavAll = [...storico, ...attive];
  for (const lav of lavAll) {
    if (coveredByRow(lav)) continue;
    const k = lavSynthKey(lav);
    if (synthLavKeys.has(k)) continue;
    synthLavKeys.add(k);
    rows.push(mezzoFromLavorazione(lav));
  }

  for (const pv of preventivi) {
    if (rows.some((m) => preventivoMatchesMezzo(m, pv))) continue;
    rows.push(mezzoFromPreventivo(pv));
  }

  return rows;
}

import { parseDecimalInput } from "@/lib/core/decimal-input";

export type MezzoAnagraficaMeta = {
  cantiere?: string;
  tipoTelaio?: string;
  marcaTelaio?: string;
  modelloTelaio?: string;
  oreLavoro?: number;
  km?: number;
  /** Se true il mezzo compare nella matrice tagliandi. */
  tagliandi?: boolean;
};

function str(v: unknown): string {
  return typeof v === "string" ? v.trim() : "";
}

function num(v: unknown): number | undefined {
  const n = Number(v);
  return Number.isFinite(n) ? n : undefined;
}

function bool(v: unknown): boolean | undefined {
  if (v === true || v === "true" || v === 1 || v === "1") return true;
  if (v === false || v === "false" || v === 0 || v === "0") return false;
  return undefined;
}

export function parseMezzoMeta(raw: unknown): MezzoAnagraficaMeta {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return {};
  const m = raw as Record<string, unknown>;
  const oreLavoro = num(m.oreLavoro);
  const km = num(m.km);
  return {
    cantiere: str(m.cantiere) || undefined,
    tipoTelaio: str(m.tipoTelaio) || undefined,
    marcaTelaio: str(m.marcaTelaio) || undefined,
    modelloTelaio: str(m.modelloTelaio) || undefined,
    oreLavoro: oreLavoro != null && oreLavoro >= 0 ? oreLavoro : undefined,
    km: km != null && km >= 0 ? km : undefined,
    tagliandi: bool(m.tagliandi),
  };
}

/** @deprecated ponytail: v1 matrice tagliandi disabilitata — sempre false. */
export function mezzoTagliandiEnabled(__m: { tagliandi?: boolean }): boolean {
  return false;
}

export function mergeMezzoMetaPatch(
  raw: unknown,
  patch: Partial<MezzoAnagraficaMeta>,
): Record<string, unknown> {
  const base =
    raw && typeof raw === "object" && !Array.isArray(raw) ? { ...(raw as Record<string, unknown>) } : {};
  return { ...base, ...patch };
}

export function mezzoFormToMeta(f: {
  cantiere: string;
  tipoTelaio: string;
  marcaTelaio: string;
  modelloTelaio: string;
  oreLavoro: string;
  km: string;
}): MezzoAnagraficaMeta {
  const ore = parseDecimalInput(f.oreLavoro);
  const kmN = parseDecimalInput(f.km);
  return {
    cantiere: f.cantiere.trim() || undefined,
    tipoTelaio: f.tipoTelaio.trim() || undefined,
    marcaTelaio: f.marcaTelaio.trim() || undefined,
    modelloTelaio: f.modelloTelaio.trim() || undefined,
    oreLavoro: ore != null && ore >= 0 ? ore : undefined,
    km: kmN != null && kmN >= 0 ? kmN : undefined,
  };
}

export function metaToMezzoFormFields(meta: MezzoAnagraficaMeta): {
  cantiere: string;
  tipoTelaio: string;
  marcaTelaio: string;
  modelloTelaio: string;
  oreLavoro: string;
  km: string;
} {
  return {
    cantiere: meta.cantiere ?? "",
    tipoTelaio: meta.tipoTelaio ?? "",
    marcaTelaio: meta.marcaTelaio ?? "",
    modelloTelaio: meta.modelloTelaio ?? "",
    oreLavoro: meta.oreLavoro != null ? String(meta.oreLavoro) : "",
    km: meta.km != null ? String(meta.km) : "",
  };
}

import { buildBrowserAttrezzaturaResolveDeps } from "@/lib/domain/mezzo-attrezzatura/build-browser-attrezzatura-resolve-deps";
import { buildBrowserMezzoResolveDeps } from "@/lib/domain/mezzo/build-browser-mezzo-resolve-deps";
import { resolveMezzoFromScheda } from "@/lib/domain/mezzo/resolve-mezzo-from-scheda";
import {
  resolveOrCreateAttrezzatura,
  type ResolveOrCreateAttrezzaturaDeps,
} from "@/lib/domain/mezzo-attrezzatura/resolve-or-create-attrezzatura";
import {
  resolveOrCreateMezzo,
  type ResolveOrCreateMezzoDeps,
} from "@/lib/domain/mezzo/resolve-or-create-mezzo";
import { upsertFromSchedaV2 } from "@/lib/domain/mezzo-attrezzatura/upsert-from-scheda-v2";
import type { MezzoGestito } from "@/lib/mezzi/types";
import type { MezzoInsert, MezzoUpdate, ApplyAssociationChangeInput } from "@/src/services/mezzi.service";
import { schedaFieldsToAnagraficaSnapshot, mezzoGestitoToAnagraficaSnapshot } from "@/lib/domain/mezzo/mezzo-anagrafica-snapshot";
import {
  anagraficaHistoryOrigineFromWriteContext,
  resolveInterventoWriteContext,
  resolveMezzoUpdatePlanFromContext,
} from "@/lib/domain/intervento-context/intervento-write-context";
import { recordMezzoAnagraficaDiff } from "@/src/services/mezzo-anagrafica-history.service";
import type { MezzoRow, InterventoTargetType } from "@/src/types/supabase-tables";
