/**
 * Flag migrazione inbox notifiche v2.
 * SSOT DB: app_settings module system, key notifications_v2_mode.
 * Override env: NEXT_PUBLIC_NOTIFICATIONS_V2=off|create-only|on
 */

export type NotificationsV2Mode = "off" | "create-only" | "on";

export const NOTIFICATIONS_V2_MODULE = "system" as const;
export const NOTIFICATIONS_V2_KEY = "notifications_v2_mode" as const;

const VALID_MODES: NotificationsV2Mode[] = ["off", "create-only", "on"];

export function parseNotificationsV2Mode(value: unknown): NotificationsV2Mode | null {
  if (typeof value !== "string") return null;
  const t = value.trim() as NotificationsV2Mode;
  return VALID_MODES.includes(t) ? t : null;
}

type AppSettingsRowLike = { module?: string | null; key?: string | null; value?: unknown };

export function readNotificationsV2ModeFromRows(rows: AppSettingsRowLike[] | undefined): NotificationsV2Mode | null {
  if (!rows?.length) return null;
  const row = rows.find((r) => r.module === NOTIFICATIONS_V2_MODULE && r.key === NOTIFICATIONS_V2_KEY);
  if (!row) return null;
  if (typeof row.value === "string") return parseNotificationsV2Mode(row.value);
  if (row.value != null && typeof row.value === "object" && "mode" in row.value) {
    return parseNotificationsV2Mode((row.value as { mode?: unknown }).mode);
  }
  return null;
}

export function resolveNotificationsV2Mode(dbMode: NotificationsV2Mode | null | undefined): NotificationsV2Mode {
  const env = process.env.NEXT_PUBLIC_NOTIFICATIONS_V2?.trim();
  if (env === "off" || env === "create-only" || env === "on") return env;
  if (dbMode) return dbMode;
  return "on";
}

export function notificationsV2ReadsDb(mode: NotificationsV2Mode): boolean {
  void mode;
  return true;
}

export function notificationsV2WritesLegacy(__mode: NotificationsV2Mode): boolean {
  return false;
}

export function notificationsV2WritesDb(mode: NotificationsV2Mode): boolean {
  return mode === "on" || mode === "create-only";
}

import { resolveRole, type AppRole } from "@/lib/auth/rbac";
import type { RbacEvaluationContext } from "@/lib/auth/rbac";
import { canReadPage } from "@/src/lib/rbac/resolve-page-access";

/** Policy A: guest e cliente esclusi dall'inbox. */
export function isStaffInboxEligible(
  user: import("@/lib/auth/rbac").RbacUser,
  ctx?: RbacEvaluationContext,
): boolean {
  const role = resolveRole(user);
  if (role === "guest" || role === "cliente") return false;
  if (!ctx?.resolved) return false;
  return canReadPage(ctx.resolved, "dashboard") || canReadPage(ctx.resolved, "lavorazioni");
}

/**
 * Feature-flag SSOT for boot investigation — zero import from boot-investigation.ts.
 * Enable: NEXT_PUBLIC_BOOT_INVESTIGATION=1 or NEXT_PUBLIC_PERF_DIAGNOSTICS=1
 */

export function isBootInvestigationEnabled(): boolean {
  if (
    process.env.NEXT_PUBLIC_BOOT_INVESTIGATION === "1" ||
    process.env.NEXT_PUBLIC_PERF_DIAGNOSTICS === "1"
  ) {
    return true;
  }
  if (typeof window !== "undefined") {
    return (window as Window & { __cabForceNavDiagnostics?: boolean }).__cabForceNavDiagnostics === true;
  }
  return false;
}

/** No-op in critical graph — real mount logging lives in diagnostics pack. */
export function useBootInvestigationMount(
  _name: string,
  _meta?: Record<string, unknown>,
): void {
  /* ponytail: gate-only hook avoids static edge to boot-investigation.ts */
}

/**
 * Feature flag Maintenance Engine v2.
 * SSOT DB: app_settings module `system`, key `maintenance_engine_v2`.
 * Kill switch env: NEXT_PUBLIC_MAINTENANCE_ENGINE_V2=0
 */

export const MAINTENANCE_ENGINE_V2_MODULE = "system" as const;
export const MAINTENANCE_ENGINE_V2_KEY = "maintenance_engine_v2" as const;

export type MaintenanceEngineV2Flags = {
  enabled: boolean;
  percentage: number;
  allowedRoles: string[];
};

export const MAINTENANCE_ENGINE_V2_DEFAULT: MaintenanceEngineV2Flags = {
  enabled: true,
  percentage: 100,
  allowedRoles: [],
};

export function parseMaintenanceEngineV2Flags(value: unknown): MaintenanceEngineV2Flags {
  if (value == null || typeof value !== "object") return { ...MAINTENANCE_ENGINE_V2_DEFAULT };
  const o = value as Record<string, unknown>;
  const percentage =
    typeof o.percentage === "number" && o.percentage >= 0 && o.percentage <= 100
      ? o.percentage
      : MAINTENANCE_ENGINE_V2_DEFAULT.percentage;
  const allowedRoles = Array.isArray(o.allowed_roles)
    ? o.allowed_roles.filter((r): r is string => typeof r === "string")
    : [];
  return {
    enabled: o.enabled !== false,
    percentage,
    allowedRoles,
  };
}

type AppSettingsRowLike = { module?: string | null; key?: string | null; value?: unknown };

export function readMaintenanceEngineV2FromRows(
  rows: AppSettingsRowLike[] | undefined,
): MaintenanceEngineV2Flags {
  if (!rows?.length) return { ...MAINTENANCE_ENGINE_V2_DEFAULT };
  const row = rows.find((r) => r.module === MAINTENANCE_ENGINE_V2_MODULE && r.key === MAINTENANCE_ENGINE_V2_KEY);
  return parseMaintenanceEngineV2Flags(row?.value);
}

export function isMaintenanceEngineV2EnvDisabled(): boolean {
  return process.env.NEXT_PUBLIC_MAINTENANCE_ENGINE_V2?.trim() === "0";
}

/** Hash stabile userId → bucket 0-99 per percentage rollout. */
export function maintenanceEngineV2UserBucket(userId: string): number {
  let h = 0;
  for (let i = 0; i < userId.length; i++) {
    h = (h * 31 + userId.charCodeAt(i)) % 100;
  }
  return Math.abs(h) % 100;
}

export function resolveMaintenanceEngineV2Enabled(__input?: {
  dbFlags?: MaintenanceEngineV2Flags | null;
  userId?: string | null;
  userRole?: string | null;
}): boolean {
  // ponytail: v2 always on post-rollout; only env kill switch can disable.
  return !isMaintenanceEngineV2EnvDisabled();
}

/** @deprecated Usare useMaintenanceEngineV2Enabled / resolveMaintenanceEngineV2EnabledClient */
export function isMaintenanceEngineV2Enabled(): boolean {
  return resolveMaintenanceEngineV2Enabled({});
}

/** Profilo operativo officina — settings `system.officina_profilo_operativo`. */

export type OfficinaProfiloOperativo = "attrezzature" | "telai" | "misto";

export const OFFICINA_PROFILO_MODULE = "system" as const;
export const OFFICINA_PROFILO_KEY = "officina_profilo_operativo" as const;

const VALID: OfficinaProfiloOperativo[] = ["attrezzature", "telai", "misto"];

export function parseOfficinaProfiloOperativo(value: unknown): OfficinaProfiloOperativo {
  if (typeof value === "string" && VALID.includes(value as OfficinaProfiloOperativo)) {
    return value as OfficinaProfiloOperativo;
  }
  return "attrezzature";
}

type AppSettingsRowLike = { module?: string | null; key?: string | null; value?: unknown };

export function readOfficinaProfiloFromRows(
  rows: AppSettingsRowLike[] | undefined,
): OfficinaProfiloOperativo {
  if (!rows?.length) return "attrezzature";
  const row = rows.find((r) => r.module === OFFICINA_PROFILO_MODULE && r.key === OFFICINA_PROFILO_KEY);
  return parseOfficinaProfiloOperativo(row?.value);
}

export function defaultTargetTypeForProfilo(profilo: OfficinaProfiloOperativo) {
  return profilo === "telai" ? ("telaio" as const) : ("attrezzatura" as const);
}

export type SchedaIngressoMezzoSectionKind = "attrezzatura" | "telaio";

export function showTelaioSections(__profilo: OfficinaProfiloOperativo): boolean {
  return true;
}

export function showAttrezzaturaSections(profilo: OfficinaProfiloOperativo): boolean {
  return profilo === "attrezzature" || profilo === "misto";
}

export function schedaIngressoMezzoSectionOrder(
  profilo: OfficinaProfiloOperativo,
): readonly SchedaIngressoMezzoSectionKind[] {
  switch (profilo) {
    case "telai":
      return ["telaio"];
    case "misto":
      return ["telaio", "attrezzatura"];
    default:
      return ["attrezzatura", "telaio"];
  }
}

export function showInterventoTargetToggle(profilo: OfficinaProfiloOperativo): boolean {
  return profilo === "misto";
}

