import type {
  AskReportCitation,
  AskReportFollowUp,
  AskReportResponse,
  AskReportToolResult,
  EffectiveAskContext,
} from "@/lib/report/ask-report/types";
import type { ReportMetricEnvelope } from "@/lib/report/metrics/report-metric-envelope";
import { formatMetricDeltaForAnswer, formatMetricValueForAnswer } from "@/lib/report/ask-report/tools/run-ask-report-tool.server";
import { getRegistryEntry } from "@/lib/report/metrics/report-metric-registry";
import type { InsightDto } from "@/lib/report/insights/types";
import type { ReportDecisionPoint } from "@/lib/report/decision-center/types";
import { ASK_REPORT_SCHEMA_VERSION } from "@/lib/report/ask-report/versions";
import { toConversationContext } from "@/lib/report/ask-report/context/resolve-effective-context.server";
import { formatAskRecidivitaAnswer } from "@/lib/report/ask-report/answer/format-ask-recidivita-answer";
import type { AskRecidivitaToolData } from "@/lib/report/ask-report/recidivita/load-ask-recidivita.server";

const TRUST_LABEL: Record<string, string> = {
  verified: "",
  estimated: " (stimato)",
  partial: " (dato parziale)",
  not_available: "",
};

export function buildDeterministicAnswer(
  toolResults: AskReportToolResult[],
  effective: EffectiveAskContext,
): { answer: string; citations: AskReportCitation[]; followUps: AskReportFollowUp[] } {
  const citations = toolResults.flatMap((r) => r.citations);
  const followUps: AskReportFollowUp[] = [];
  const lines: string[] = [];

  for (const result of toolResults) {
    if (!result.success || !result.data) continue;

    if (result.toolName === "get_metric" && !Array.isArray(result.data)) {
      const env = result.data as ReportMetricEnvelope;
      const reg = getRegistryEntry(env.metricId);
      const label = reg?.label ?? env.metricId;
      const value = formatMetricValueForAnswer(env);
      const delta = formatMetricDeltaForAnswer(env);
      const trust = TRUST_LABEL[env.trust] ?? "";
      lines.push(`${label}: ${value}${trust}${delta ? ` (${delta} vs confronto)` : ""}.`);
      if (env.metricId) {
        followUps.push({
          label: "Confronta periodo",
          message: `Confronta ${label.toLowerCase()} con il mese scorso`,
        });
      }
    }

    if (result.toolName === "get_insights" && Array.isArray(result.data)) {
      const insights = result.data as InsightDto[];
      if (insights.length) {
        lines.push("Segnali principali:");
        for (const i of insights.slice(0, 3)) {
          lines.push(`• ${i.message}`);
        }
      }
    }

    if (result.toolName === "get_decisions" && Array.isArray(result.data)) {
      const decisions = result.data as ReportDecisionPoint[];
      if (!decisions.length) {
        lines.push("Nessuna decisione aperta nel periodo selezionato.");
      } else {
        lines.push(`Decisioni (${decisions.length}):`);
        for (const d of decisions.slice(0, 5)) {
          lines.push(`• [${d.priority}] ${d.title} — ${d.status}`);
        }
      }
    }

    if (result.toolName === "get_operational_context" && result.data && !Array.isArray(result.data)) {
      const events = (result.data as { summaryEvents: { title: string }[] }).summaryEvents;
      if (events.length) {
        lines.push("Contesto operativo:");
        for (const e of events.slice(0, 3)) {
          lines.push(`• ${e.title}`);
        }
      }
    }

    if (result.toolName === "get_breakdown" && result.data && !Array.isArray(result.data)) {
      const breakdown = result.data as import("@/lib/report/analytics-engine/types").ReportDimensionBreakdown;
      if (breakdown.rows?.length) {
        lines.push(`Breakdown ${breakdown.dimension}:`);
        for (const row of breakdown.rows.slice(0, 5)) {
          lines.push(`• ${row.label}: ${row.value}`);
        }
      }
    }

    if (result.toolName === "get_series" && result.data && !Array.isArray(result.data)) {
      const { series, metricId } = result.data as {
        series: import("@/lib/report/analytics-engine/types").ReportMetricSeries[];
        metricId: string;
      };
      const reg = getRegistryEntry(metricId);
      const label = reg?.label ?? metricId;
      const points = series.flatMap((s) => s.points).filter((p) => p.value != null);
      if (points.length) {
        const tail = points.slice(-4);
        const formatted = tail
          .map((p) => {
            const v = formatMetricValueForAnswer({
              metricId,
              formulaId: "",
              trust: p.trust,
              metric: { value: p.value },
            } as ReportMetricEnvelope);
            return `${p.periodStart.slice(5)}: ${v}`;
          })
          .join(", ");
        const first = points[0]!.value ?? 0;
        const last = points[points.length - 1]!.value ?? 0;
        const dir = last > first ? "in crescita" : last < first ? "in calo" : "stabile";
        lines.push(`Andamento ${label} (${dir}): ${formatted}.`);
      }
    }

    if (result.toolName === "get_drilldown" && result.data && !Array.isArray(result.data)) {
      const { rows } = result.data as { rows: { label: string }[] };
      lines.push(`Record trovati: ${rows.length}. Usa le citazioni per approfondire.`);
    }

    if (result.toolName === "get_recidivita" && result.data && !Array.isArray(result.data)) {
      lines.push(formatAskRecidivitaAnswer(result.data as AskRecidivitaToolData));
    }
  }

  if (!lines.length) {
    return {
      answer: "Dato non disponibile per la domanda nel periodo selezionato.",
      citations,
      followUps,
    };
  }

  const metricLines = lines.filter((l) => !l.startsWith("Segnali") && !l.startsWith("Decisioni") && !l.startsWith("Contesto") && !l.startsWith("Breakdown") && !l.startsWith("Andamento") && !l.startsWith("Record"));
  const metricOnly =
    toolResults.length === 1 &&
    toolResults[0]?.toolName === "get_metric" &&
    toolResults[0]?.success;

  const recidivitaOnly =
    toolResults.length === 1 &&
    toolResults[0]?.toolName === "get_recidivita" &&
    toolResults[0]?.success;

  if (recidivitaOnly) {
    return {
      answer: lines[0] ?? lines.join("\n"),
      citations,
      followUps: [
        {
          label: "Top mezzi critici",
          message: "Quali sono i mezzi con più recidività nel periodo?",
        },
      ],
    };
  }

  if (metricOnly) {
    return {
      answer: lines[0] ?? lines.join(" "),
      citations,
      followUps,
    };
  }

  const multiMetric =
    toolResults.filter((r) => r.toolName === "get_metric" && r.success).length > 1;

  if (multiMetric && metricLines.length) {
    return {
      answer: metricLines.join("\n"),
      citations,
      followUps,
    };
  }

  const summary = lines.slice(0, 3).join(" ");
  return {
    answer: `${summary}\n\nDATI CHIAVE\n${lines.map((l) => (l.startsWith("•") ? l : `• ${l}`)).join("\n")}`,
    citations,
    followUps,
  };
}

export function buildAskReportResponse(input: {
  conversationId: string;
  effective: EffectiveAskContext;
  answer: string;
  citations: AskReportCitation[];
  toolResults: AskReportToolResult[];
  status: AskReportResponse["status"];
  clarificationQuestion?: string;
  planMode: "deterministic" | "llm";
  toolActivity: string[];
}): AskReportResponse {
  const { toolResults } = input;
  const metrics = toolResults
    .filter((r) => r.toolName === "get_metric" && r.success && r.data && !Array.isArray(r.data))
    .map((r) => r.data as ReportMetricEnvelope);

  const insights = toolResults
    .filter((r) => r.toolName === "get_insights" && Array.isArray(r.data))
    .flatMap((r) => r.data as InsightDto[]);

  const decisions = toolResults
    .filter((r) => r.toolName === "get_decisions" && Array.isArray(r.data))
    .flatMap((r) => r.data as ReportDecisionPoint[]);

  const drillDownContexts = toolResults
    .filter((r) => r.toolName === "get_drilldown" && r.data && !Array.isArray(r.data))
    .map((r) => (r.data as { context: import("@/lib/report/drilldown/types").ReportDrillDownContext }).context);

  const { followUps } = buildDeterministicAnswer(input.toolResults, input.effective);

  return {
    contractVersion: ASK_REPORT_SCHEMA_VERSION,
    conversationId: input.conversationId,
    conversationContext: toConversationContext(input.effective),
    answer: input.answer,
    citations: input.citations,
    metrics: metrics.length ? metrics : undefined,
    insights: insights.length ? insights : undefined,
    decisions: decisions.length ? decisions : undefined,
    drillDownContexts: drillDownContexts.length ? drillDownContexts : undefined,
    followUps: followUps.length ? followUps : undefined,
    status: input.status,
    clarificationQuestion: input.clarificationQuestion,
    toolActivity: input.toolActivity,
    planMode: input.planMode,
  };
}

import type { AssetComplianceRuleRow, AssetTimelineProjectionRow } from "@/src/types/supabase-tables";
import type { LavorazioneListRow } from "@/src/services/lavorazioni.service";
import { ymdFromDate } from "@/lib/report/date-ranges";

export type AssetLifecycleKpiModel = {
  mezziWithUpcomingCompliance: Array<{
    mezzoId: string;
    ruleKind: string;
    dueAt: string;
    daysUntil: number;
  }>;
  attrezzatureFrequentReassign: Array<{
    attrezzaturaId: string;
    changeCount90d: number;
  }>;
  mezziIdleDays: Array<{
    mezzoId: string;
    daysSinceLastLavorazione: number;
  }>;
  kmAnomalies: Array<{
    mezzoId: string;
    deltaKm30d: number;
    avgDailyKm: number;
  }>;
  suggestedMaintenance: Array<{
    mezzoId: string;
    ruleKind: string;
    reason: string;
  }>;
  deterministicInsights: string[];
};

export type BuildAssetLifecycleKpiInput = {
  anchor: Date;
  timelineRows: AssetTimelineProjectionRow[];
  complianceRules: AssetComplianceRuleRow[];
  lavorazioni: readonly LavorazioneListRow[];
};

function daysBetween(from: Date, to: Date): number {
  return Math.floor((to.getTime() - from.getTime()) / (86400000));
}

export function buildAssetLifecycleKpiModel(input: BuildAssetLifecycleKpiInput): AssetLifecycleKpiModel {
  const anchor = input.anchor;

  const mezziWithUpcomingCompliance = input.complianceRules
    .filter((r) => r.is_active && r.next_due_at)
    .map((r) => {
      const due = new Date(`${r.next_due_at}T12:00:00`);
      return {
        mezzoId: r.mezzo_id ?? "",
        ruleKind: r.rule_kind,
        dueAt: r.next_due_at!,
        daysUntil: daysBetween(anchor, due),
      };
    })
    .filter((x) => x.mezzoId)
    .sort((a, b) => a.daysUntil - b.daysUntil);

  const reassignCounts = new Map<string, number>();
  const cutoff = new Date(anchor);
  cutoff.setDate(cutoff.getDate() - 90);
  for (const row of input.timelineRows) {
    if (row.event_category !== "assignment_start" && row.event_category !== "assignment_end") continue;
    if (!row.attrezzatura_id) continue;
    if (new Date(row.event_at) < cutoff) continue;
    reassignCounts.set(row.attrezzatura_id, (reassignCounts.get(row.attrezzatura_id) ?? 0) + 1);
  }
  const attrezzatureFrequentReassign = [...reassignCounts.entries()]
    .filter(([, count]) => count >= 3)
    .map(([attrezzaturaId, changeCount90d]) => ({ attrezzaturaId, changeCount90d }));

  const lastLavByMezzo = new Map<string, string>();
  for (const lav of input.lavorazioni) {
    const at = lav.data_ingresso?.trim() || lav.created_at;
    if (!at) continue;
    const prev = lastLavByMezzo.get(lav.mezzo_id);
    if (!prev || at > prev) lastLavByMezzo.set(lav.mezzo_id, at);
  }
  const mezziIdleDays = [...lastLavByMezzo.entries()]
    .map(([mezzoId, at]) => ({
      mezzoId,
      daysSinceLastLavorazione: daysBetween(new Date(at), anchor),
    }))
    .filter((x) => x.daysSinceLastLavorazione >= 14)
    .sort((a, b) => b.daysSinceLastLavorazione - a.daysSinceLastLavorazione);

  const kmByMezzo = new Map<string, { first: number; last: number; firstAt: Date; lastAt: Date }>();
  for (const row of input.timelineRows) {
    if (row.event_category !== "mileage_reading" || !row.mezzo_id) continue;
    const km = Number.parseFloat(row.label.replace(/^Km\s+/i, ""));
    if (!Number.isFinite(km)) continue;
    const at = new Date(row.event_at);
    const cur = kmByMezzo.get(row.mezzo_id);
    if (!cur) {
      kmByMezzo.set(row.mezzo_id, { first: km, last: km, firstAt: at, lastAt: at });
    } else if (at < cur.firstAt) {
      kmByMezzo.set(row.mezzo_id, { ...cur, first: km, firstAt: at });
    } else if (at > cur.lastAt) {
      kmByMezzo.set(row.mezzo_id, { ...cur, last: km, lastAt: at });
    }
  }
  const kmAnomalies = [...kmByMezzo.entries()]
    .map(([mezzoId, v]) => {
      const spanDays = Math.max(1, daysBetween(v.firstAt, v.lastAt));
      const deltaKm30d = v.last - v.first;
      const avgDailyKm = deltaKm30d / spanDays;
      return { mezzoId, deltaKm30d, avgDailyKm };
    })
    .filter((x) => x.avgDailyKm > 800 || x.deltaKm30d < 0);

  const suggestedMaintenance = input.complianceRules
    .filter((r) => r.is_active && r.trigger_kind === "km_interval" && r.next_due_km != null && r.mezzo_id)
    .map((r) => ({
      mezzoId: r.mezzo_id!,
      ruleKind: r.rule_kind,
      reason: `Tagliando previsto a ${r.next_due_km} km`,
    }));

  const deterministicInsights: string[] = [];
  for (const c of mezziWithUpcomingCompliance.slice(0, 3)) {
    if (c.daysUntil <= 0) {
      deterministicInsights.push(`Revisione/compliance scaduta (${c.ruleKind}) — mezzo ${c.mezzoId.slice(0, 8)}…`);
    } else if (c.daysUntil <= 30) {
      deterministicInsights.push(`${c.ruleKind} tra ${c.daysUntil} giorni`);
    }
  }
  for (const idle of mezziIdleDays.slice(0, 2)) {
    deterministicInsights.push(`Mezzo fermo da ${idle.daysSinceLastLavorazione} giorni`);
  }
  for (const r of attrezzatureFrequentReassign.slice(0, 2)) {
    deterministicInsights.push(`Attrezzatura riassegnata ${r.changeCount90d} volte in 90 giorni`);
  }
  for (const k of kmAnomalies.slice(0, 2)) {
    deterministicInsights.push(`Chilometraggio anomalo su mezzo ${k.mezzoId.slice(0, 8)}… (${Math.round(k.avgDailyKm)} km/g)`);
  }

  return {
    mezziWithUpcomingCompliance,
    attrezzatureFrequentReassign,
    mezziIdleDays,
    kmAnomalies,
    suggestedMaintenance,
    deterministicInsights,
  };
}

export function lifecyclePriorityRank(p: string): number {
  if (p === "urgent") return 90;
  if (p === "high") return 75;
  if (p === "medium") return 55;
  return 30;
}

export function mapTimelineRowToCalendarEvent(row: AssetTimelineProjectionRow) {
  return {
    id: `life-${row.source_id}`,
    eventDomain: "lifecycle" as const,
    eventCategory: row.event_category,
    priority: row.priority,
    label: row.label,
    detail: row.event_subtype,
    at: row.event_at,
    assetRef: row.mezzo_id
      ? ({ kind: "mezzo" as const, id: row.mezzo_id })
      : row.attrezzatura_id
        ? ({ kind: "attrezzatura" as const, id: row.attrezzatura_id })
        : undefined,
    importance: lifecyclePriorityRank(row.priority),
  };
}

import "server-only";

import { capitaleImmobilizzato } from "@/lib/magazzino/calculations";
import { sottoScortaCount } from "@/lib/report/kpi-performance/kpi-performance-formulas";
import { aggregateMagazzinoQtyByProductInRange } from "@/lib/report/magazzino-period-aggregate";
import { isoInRange, type DateRange } from "@/lib/report/date-ranges";
import type { ReportAnalyticsSourceBundle } from "@/lib/report/analytics-engine/source-bundle";
import type { ReportDrillDownRow } from "@/lib/report/drilldown/types";
import { usciteQtyFromMagazzinoEntry } from "@/lib/magazzino/ricambio-consumo-from-log";
import type { RicambioMagazzino } from "@/lib/magazzino/types";

function isSottoScorta(r: RicambioMagazzino): boolean {
  const min = r.scortaMinima ?? 0;
  return min > 0 && (r.scorta ?? 0) < min;
}

function ricambioRow(r: RicambioMagazzino, amount?: number): ReportDrillDownRow {
  return {
    id: r.id,
    target: { entity: "ricambio", id: r.id },
    label: r.codiceFornitoreOriginale?.trim() || r.descrizione?.trim() || r.id,
    sublabel: r.marca ?? undefined,
    amount: amount ?? r.scorta ?? null,
    status: isSottoScorta(r) ? "sotto_scorta" : "ok",
  };
}

export function listRicambiSottoScorta(bundle: ReportAnalyticsSourceBundle): ReportDrillDownRow[] {
  void sottoScortaCount;
  const rows: ReportDrillDownRow[] = [];
  for (const r of bundle.integrity.magazzino) {
    if (isSottoScorta(r)) rows.push(ricambioRow(r));
  }
  return rows.sort((a, b) => String(a.label).localeCompare(String(b.label)));
}

export function listRicambiCapitale(bundle: ReportAnalyticsSourceBundle): ReportDrillDownRow[] {
  const rows: ReportDrillDownRow[] = [];
  for (const r of bundle.integrity.magazzino) {
    const cap = capitaleImmobilizzato(r);
    if (cap <= 0) continue;
    rows.push(ricambioRow(r, cap));
  }
  return rows.sort((a, b) => (b.amount ?? 0) - (a.amount ?? 0));
}

export function listMovimentiUscitaInRange(
  bundle: ReportAnalyticsSourceBundle,
  range: DateRange,
  ricambioId?: string,
): ReportDrillDownRow[] {
  const prodMap = new Map(bundle.integrity.magazzino.map((p) => [p.id, p]));
  const rows: ReportDrillDownRow[] = [];

  for (const entry of bundle.integrity.magLog) {
    const qty = usciteQtyFromMagazzinoEntry(entry);
    if (qty <= 0) continue;
    if (!isoInRange(entry.at, range)) continue;
    if (ricambioId && entry.ricambioId !== ricambioId) continue;
    const prod = prodMap.get(entry.ricambioId);
    rows.push({
      id: entry.id,
      target: { entity: "movimento", id: entry.id },
      label: prod?.codiceFornitoreOriginale?.trim() || prod?.descrizione?.trim() || entry.ricambioId,
      sublabel: entry.riepilogo ?? undefined,
      amount: qty,
      date: entry.at,
      status: entry.tipo,
    });
  }
  return rows.sort((a, b) => (b.date ?? "").localeCompare(a.date ?? ""));
}

export function resolveMagazzinoDrilldownRows(
  metricId: string,
  bundle: ReportAnalyticsSourceBundle,
  range: DateRange,
  filters?: Record<string, string | number | boolean>,
): ReportDrillDownRow[] {
  const ricambioId = filters?.ricambioId != null ? String(filters.ricambioId) : undefined;
  switch (metricId) {
    case "scorta":
      return listRicambiSottoScorta(bundle);
    case "cap":
      return listRicambiCapitale(bundle);
    case "ric-usati":
      return listMovimentiUscitaInRange(bundle, range, ricambioId);
    default:
      return [];
  }
}

