/**
 * Single source of truth per body scroll lock.
 * Nessun altro modulo deve scrivere overflow/touch-action su html/body per le modali.
 */

import { syncAppViewportFill } from "@/lib/ui/viewport-fill-sync";
import {
  BODY_LOCK_ATTR,
  MAIN_SCROLL_LOCK_ATTR,
  SCROLL_LOCK_GAP_VAR,
} from "@/lib/ui/scroll-lock-attrs";

const BODY_LOCK_SCROLL_Y = "data-cab-scroll-lock-y";
const MAIN_SCROLL_SELECTOR = "main.gestionale-scroll-y";

export { BODY_LOCK_ATTR, MAIN_SCROLL_LOCK_ATTR, SCROLL_LOCK_GAP_VAR } from "@/lib/ui/scroll-lock-attrs";

type LockEntry = { id: number; source: string; epoch: number };

let lockStack: LockEntry[] = [];
let lockEpoch = 0;
let nextLockId = 0;
let savedScrollY = 0;
let useFixedLock = false;
let healTimer: ReturnType<typeof setTimeout> | null = null;

let mainLockCount = 0;
let savedMainScrollTop = 0;
let savedMainOverflow = "";
let savedMainPaddingInlineEnd = "";
let lockedMainScrollbarPadPx = 0;

function measureElementScrollbarColumnWidth(el: HTMLElement): number {
  return Math.max(0, el.offsetWidth - el.clientWidth);
}

function mainHasVerticalScrollOverflow(main: HTMLElement): boolean {
  return main.scrollHeight > main.clientHeight + 1;
}

/** Padding su main solo se gutter non è stable e la colonna scrollbar occupa layout. */
function shouldPadMainForScrollbarLock(main: HTMLElement): boolean {
  if (typeof window === "undefined") return false;
  if (window.getComputedStyle(main).scrollbarGutter === "stable") return false;
  if (!mainHasVerticalScrollOverflow(main)) return false;
  return measureElementScrollbarColumnWidth(main) > 0;
}

function syncMainScrollbarLockCompensation(main: HTMLElement): void {
  lockedMainScrollbarPadPx = 0;
  const contentWidthBefore = main.clientWidth;

  if (shouldPadMainForScrollbarLock(main)) {
    const preGap = measureElementScrollbarColumnWidth(main);
    if (preGap > 0) {
      lockedMainScrollbarPadPx = preGap;
      main.style.paddingInlineEnd = `${preGap}px`;
    }
  }

  main.style.overflow = "hidden";

  // ponytail: fallback se stable gutter non trattiene la larghezza (browser edge case)
  const delta = main.clientWidth - contentWidthBefore;
  if (delta > 0) {
    const next = Math.max(lockedMainScrollbarPadPx, delta);
    if (next !== lockedMainScrollbarPadPx) {
      lockedMainScrollbarPadPx = next;
      main.style.paddingInlineEnd = `${next}px`;
    }
  }
}

function restoreMainScrollLockStyles(main: HTMLElement): void {
  main.style.overflow = savedMainOverflow;
  main.style.paddingInlineEnd = savedMainPaddingInlineEnd;
  main.scrollTop = savedMainScrollTop;
  main.removeAttribute(MAIN_SCROLL_LOCK_ATTR);
  lockedMainScrollbarPadPx = 0;
}

function setScrollLockGapVar(gapPx: number): void {
  if (typeof document === "undefined") return;
  const root = document.documentElement;
  if (gapPx <= 0) {
    root.style.removeProperty(SCROLL_LOCK_GAP_VAR);
    return;
  }
  root.style.setProperty(SCROLL_LOCK_GAP_VAR, `${gapPx}px`);
}

function clearScrollLockGapVar(): void {
  if (typeof document === "undefined") return;
  document.documentElement.style.removeProperty(SCROLL_LOCK_GAP_VAR);
}

/** true mentre almeno un lock tiene bloccato main.gestionale-scroll-y. */
export function isGestionaleMainScrollLockActive(): boolean {
  return mainLockCount > 0;
}

export function getGestionaleMainScrollLockCompensationPx(): number {
  return lockedMainScrollbarPadPx;
}

function isIosLikeSafari(): boolean {
  if (typeof navigator === "undefined") return false;
  const ua = navigator.userAgent;
  return (
    /iPad|iPhone|iPod/.test(ua) ||
    (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1)
  );
}

function isGestionaleAppShell(): boolean {
  if (typeof document === "undefined") return false;
  return Boolean(document.querySelector(".cab-app-shell"));
}

function syncLockAttr(): void {
  if (typeof document === "undefined") return;
  if (lockStack.length <= 0) {
    document.body.removeAttribute(BODY_LOCK_ATTR);
    return;
  }
  document.body.setAttribute(BODY_LOCK_ATTR, String(lockStack.length));
}

function isDomScrollLocked(): boolean {
  if (typeof document === "undefined") return false;
  return (
    document.documentElement.style.overflow === "hidden" ||
    document.body.style.overflow === "hidden" ||
    document.body.style.touchAction === "none" ||
    document.body.style.position === "fixed"
  );
}

/** Rimuove sempre tutti gli stili imposti dal lock — mai restore a "hidden". */
export function clearBodyScrollLockStyles(): void {
  if (typeof document === "undefined") return;

  const scrollY = savedScrollY;
  const hadFixed = useFixedLock;

  document.documentElement.style.overflow = "";
  document.documentElement.style.touchAction = "";
  document.body.style.overflow = "";
  document.body.style.touchAction = "";
  document.body.style.paddingRight = "";
  document.body.style.position = "";
  document.body.style.top = "";
  document.body.style.left = "";
  document.body.style.right = "";
  document.body.style.width = "";
  document.body.removeAttribute(BODY_LOCK_SCROLL_Y);
  clearScrollLockGapVar();

  if (hadFixed && Number.isFinite(scrollY)) {
    window.scrollTo(0, scrollY);
  }

  useFixedLock = false;
  savedScrollY = 0;
}

function clearMainScrollLockStyles(): void {
  if (typeof document === "undefined") return;
  const main = document.querySelector(MAIN_SCROLL_SELECTOR) as HTMLElement | null;
  if (!main) return;
  restoreMainScrollLockStyles(main);
  mainLockCount = 0;
}

function documentHasVerticalScroll(): boolean {
  const html = document.documentElement;
  return html.scrollHeight > html.clientHeight + 1;
}

function shouldCompensateScrollbarGap(): boolean {
  if (isGestionaleAppShell()) return false;
  const gap = Math.max(0, window.innerWidth - document.documentElement.clientWidth);
  if (gap <= 0) return false;
  return documentHasVerticalScroll();
}

function applyBodyScrollLock(): void {
  document.body.style.overflow = "hidden";
  if (shouldCompensateScrollbarGap()) {
    const gap = Math.max(0, window.innerWidth - document.documentElement.clientWidth);
    document.body.style.paddingRight = `${gap}px`;
    setScrollLockGapVar(gap);
  } else {
    clearScrollLockGapVar();
  }

  if (useFixedLock) {
    document.body.style.touchAction = "none";
    document.body.setAttribute(BODY_LOCK_SCROLL_Y, String(savedScrollY));
    document.body.style.position = "fixed";
    document.body.style.top = `-${savedScrollY}px`;
    document.body.style.left = "0";
    document.body.style.right = "0";
    document.body.style.width = "";
  }
}

function applyMainScrollLock(source?: string): void {
  const main = document.querySelector(MAIN_SCROLL_SELECTOR) as HTMLElement | null;
  if (!main) return;
  if (mainLockCount === 0) {
    savedMainScrollTop = main.scrollTop;
    savedMainOverflow = main.style.overflow;
    savedMainPaddingInlineEnd = main.style.paddingInlineEnd;
    if (source) main.setAttribute(MAIN_SCROLL_LOCK_ATTR, source);
    syncMainScrollbarLockCompensation(main);
  } else if (source) {
    main.setAttribute(MAIN_SCROLL_LOCK_ATTR, source);
  }
  mainLockCount += 1;
}

function releaseMainScrollLock(): void {
  const main = document.querySelector(MAIN_SCROLL_SELECTOR) as HTMLElement | null;
  if (!main || mainLockCount <= 0) return;
  mainLockCount -= 1;
  if (mainLockCount === 0) {
    restoreMainScrollLockStyles(main);
  }
}

function refreshMainScrollLockStyles(): void {
  const main = document.querySelector(MAIN_SCROLL_SELECTOR) as HTMLElement | null;
  if (!main || mainLockCount <= 0) return;
  if (lockedMainScrollbarPadPx > 0) {
    main.style.paddingInlineEnd = `${lockedMainScrollbarPadPx}px`;
  }
}

/** Lock scroll su main gestionale (ref-count). Scroll interno app shell, senza padding body. */
export function acquireMainScrollLock(source?: string): () => void {
  if (typeof document === "undefined") return () => {};
  applyMainScrollLock(source);
  let released = false;
  return () => {
    if (released) return;
    released = true;
    releaseMainScrollLock();
  };
}

function scheduleAutoHeal(): void {
  if (typeof window === "undefined") return;
  if (healTimer != null) clearTimeout(healTimer);
  healTimer = setTimeout(() => {
    healTimer = null;
    if (lockStack.length !== 0) return;
    if (!isDomScrollLocked()) return;
    clearBodyScrollLockStyles();
    syncLockAttr();
  }, 200);
}

/** Acquisisce un lock. Ritorna release idempotente (safe per double cleanup). */
export function acquireBodyScrollLock(source?: string): () => void {
  if (typeof document === "undefined") return () => {};

  const epoch = lockEpoch;
  const id = ++nextLockId;
  const lockMain = isGestionaleAppShell();

  if (lockStack.length === 0) {
    savedScrollY = window.scrollY;
    useFixedLock = isIosLikeSafari();
    applyBodyScrollLock();
    if (lockMain) applyMainScrollLock(source);
  } else if (lockMain) {
    applyMainScrollLock(source);
  }

  lockStack.push({ id, source: source ?? "unknown", epoch });
  syncLockAttr();

  let released = false;
  return () => {
    if (released) return;
    released = true;
    releaseBodyScrollLock(id, epoch, lockMain);
  };
}

function releaseBodyScrollLock(lockId: number, epoch: number, hadMainLock: boolean): void {
  if (epoch !== lockEpoch) return;

  lockStack = lockStack.filter((entry) => entry.id !== lockId);
  syncLockAttr();

  if (hadMainLock) releaseMainScrollLock();

  if (lockStack.length === 0) {
    clearBodyScrollLockStyles();
    scheduleAutoHeal();
  }
}

/** Pulisce lock fantasma: stack vuoto ma stili inline o attr residui. */
export function healBodyScrollLockState(__reason?: string): void {
  if (typeof document === "undefined") return;
  if (lockStack.length > 0) return;

  const attr = document.body.getAttribute(BODY_LOCK_ATTR);
  const wasDomLocked = isDomScrollLocked();
  if (attr) {
    document.body.removeAttribute(BODY_LOCK_ATTR);
  }
  if (wasDomLocked) {
    clearBodyScrollLockStyles();
  }
  const main = document.querySelector(MAIN_SCROLL_SELECTOR) as HTMLElement | null;
  const hadMainLock =
    mainLockCount === 0 &&
    main &&
    (main.style.overflow === "hidden" || main.hasAttribute(MAIN_SCROLL_LOCK_ATTR));
  if (hadMainLock && main) {
    main.style.overflow = "";
    main.style.paddingInlineEnd = "";
    main.removeAttribute(MAIN_SCROLL_LOCK_ATTR);
  }
  syncLockAttr();
}
/** Reset totale — route change, error boundary, stuck probe. */
export function forceReleaseAllBodyScrollLocks(__reason?: string): void {
  if (typeof document === "undefined") return;
  lockEpoch += 1;
  lockStack = [];
  clearBodyScrollLockStyles();
  clearMainScrollLockStyles();
  syncLockAttr();
  scheduleAutoHeal();
}

export function getBodyScrollLockCount(): number {
  return lockStack.length;
}

export function probeBodyScrollLockStuck(): boolean {
  if (typeof document === "undefined") return false;
  const attr = document.body.getAttribute(BODY_LOCK_ATTR);
  const stuck = lockStack.length === 0 && !attr && isDomScrollLocked();
  if (!stuck) return false;
  forceReleaseAllBodyScrollLocks("stuck-probe");
  return true;
}

/** Re-applica lock attivo o cura stili fantasma dopo resize/orientationchange. */
export function refreshBodyScrollLockOnViewportChange(reason = "viewport-resize"): void {
  if (typeof window === "undefined" || typeof document === "undefined") return;
  syncAppViewportFill();
  if (lockStack.length > 0) {
    applyBodyScrollLock();
    refreshMainScrollLockStyles();
    return;
  }
  healBodyScrollLockState(reason);
  probeBodyScrollLockStuck();
}

/**
 * SSOT larghezza colonna contenuto e tier shell (mobile / tablet / desktop).
 * Usuario IDE: misura min tra shell, colonna flex-1, main e viewport effettivo.
 */

import { MAIN_SCROLL_LOCK_ATTR } from "@/lib/ui/scroll-lock-attrs";

export type GestionaleShellTier = "mobile" | "tablet" | "desktop";

export const GESTIONALE_SHELL_TIER_ATTR = "data-gestionale-shell-tier";

export const GESTIONALE_SHELL_CONTENT_WIDTH_VAR = "--cab-shell-content-width";

/** Larghezza host misurata (min innerWidth, doc client, shell). */
export const CAB_HOST_LAYOUT_WIDTH_VAR = "--cab-host-layout-width";

/** Larghezza utile main (clientWidth, esclude colonna scrollbar). */
export const CAB_MAIN_CONTENT_WIDTH_VAR = "--cab-main-content-width";

/** Inset colonna scrollbar main — padding header mirror, evita max-width jump. */
export const CAB_MAIN_SCROLLBAR_INSET_VAR = "--cab-main-scrollbar-inset";

export function measureElementLayoutWidth(el: {
  clientWidth: number;
  getBoundingClientRect: () => { width: number; left?: number; right?: number };
}): number {
  const client = el.clientWidth;
  const rect = el.getBoundingClientRect().width;
  if (client <= 0 && rect <= 0) return 0;
  if (client <= 0) return rect;
  if (rect <= 0) return client;
  return Math.min(client, rect);
}

/** Larghezza visibile nel viewport (preview IDE con iframe più largo del pannello). */
export function resolveElementVisibleLayoutWidth(el: HTMLElement): number {
  const layout = measureElementLayoutWidth(el);
  if (typeof window === "undefined") return layout;
  const vv = window.visualViewport;
  if (!vv) return layout;
  const rect = el.getBoundingClientRect();
  const visibleRight = Math.min(rect.right, vv.offsetLeft + vv.width);
  const visibleLeft = Math.max(rect.left, vv.offsetLeft);
  const visible = Math.max(0, visibleRight - visibleLeft);
  if (visible <= 0) return layout;
  return Math.min(layout, visible);
}

function isLayoutMeasurable(el: unknown): el is HTMLElement {
  if (typeof el !== "object" || el === null) return false;
  const node = el as { clientWidth?: unknown; getBoundingClientRect?: unknown };
  return typeof node.clientWidth === "number" && typeof node.getBoundingClientRect === "function";
}

export type ResolveHostLayoutWidthOptions = {
  shellEl?: HTMLElement | null;
};

/** Larghezza host — min tra innerWidth, visualViewport e document client (no shell: evita feedback loop CSS). */
export function resolveHostLayoutWidth(_opts: ResolveHostLayoutWidthOptions = {}): number {
  if (typeof window === "undefined") return 0;

  const inner = window.innerWidth;
  const vv = window.visualViewport?.width ?? inner;
  const docClient = document.documentElement.clientWidth;
  return Math.max(0, Math.min(inner, vv, docClient > 0 ? docClient : inner));
}

export type SyncHostLayoutWidthCssVarsOptions = {
  shellEl?: HTMLElement | null;
  mainEl?: HTMLElement | null;
};

const CSS_VAR_WRITE_THRESHOLD_PX = 2;

function setPxVarIfChanged(root: HTMLElement, name: string, px: number | null): void {
  if (px == null || px <= 0) {
    if (root.style.getPropertyValue(name)) root.style.removeProperty(name);
    return;
  }
  const next = `${Math.round(px)}px`;
  const prev = root.style.getPropertyValue(name);
  const prevNum = prev ? parseInt(prev, 10) : NaN;
  if (!Number.isNaN(prevNum) && Math.abs(prevNum - Math.round(px)) < CSS_VAR_WRITE_THRESHOLD_PX) return;
  if (prev === next) return;
  root.style.setProperty(name, next);
}

function resolveFrozenMainScrollbarInset(main: HTMLElement, measured: number): number {
  if (!main.hasAttribute(MAIN_SCROLL_LOCK_ATTR)) return measured;
  const lockedPad = parseInt(main.style.paddingInlineEnd, 10);
  if (Number.isFinite(lockedPad) && lockedPad > 0) return lockedPad;
  const prev = parseInt(
    document.documentElement.style.getPropertyValue(CAB_MAIN_SCROLLBAR_INSET_VAR),
    10,
  );
  if (Number.isFinite(prev) && prev > 0) return prev;
  return measured;
}

/** Sincronizza --cab-main-content-width e --cab-main-scrollbar-inset (no host width su html). */
export function syncHostLayoutWidthCssVars(
  opts: SyncHostLayoutWidthCssVarsOptions = {},
): { hostWidth: number; mainContentWidth: number | null } {
  if (typeof document === "undefined" || typeof window === "undefined") {
    return { hostWidth: 0, mainContentWidth: null };
  }

  const hostWidth = resolveHostLayoutWidth();
  const root = document.documentElement;

  if (root.style.getPropertyValue(CAB_HOST_LAYOUT_WIDTH_VAR)) {
    root.style.removeProperty(CAB_HOST_LAYOUT_WIDTH_VAR);
  }

  const main =
    opts.mainEl ??
    (typeof document !== "undefined" ? document.querySelector("main.gestionale-scroll-y") : null);

  let mainContentWidth: number | null = null;
  if (isLayoutMeasurable(main) && main.clientWidth > 0) {
    mainContentWidth = main.clientWidth;
    setPxVarIfChanged(root, CAB_MAIN_CONTENT_WIDTH_VAR, mainContentWidth);
    const measuredInset = Math.max(0, Math.round(main.offsetWidth - main.clientWidth));
    const prevInset = parseInt(root.style.getPropertyValue(CAB_MAIN_SCROLLBAR_INSET_VAR), 10);
    const frozenPrev = Number.isFinite(prevInset) && prevInset > 0 ? prevInset : 0;
    const scrollbarInset = resolveFrozenMainScrollbarInset(main, Math.max(measuredInset, frozenPrev));
    setPxVarIfChanged(root, CAB_MAIN_SCROLLBAR_INSET_VAR, scrollbarInset > 0 ? scrollbarInset : null);
  } else {
    if (root.style.getPropertyValue(CAB_MAIN_CONTENT_WIDTH_VAR)) {
      root.style.removeProperty(CAB_MAIN_CONTENT_WIDTH_VAR);
    }
    if (root.style.getPropertyValue(CAB_MAIN_SCROLLBAR_INSET_VAR)) {
      root.style.removeProperty(CAB_MAIN_SCROLLBAR_INSET_VAR);
    }
  }

  return { hostWidth, mainContentWidth };
}

/** Viewport effettivo — preview IDE / visualViewport / host layout. */
export function resolveGestionaleShellViewportWidth(): number {
  return resolveHostLayoutWidth();
}

export type ResolveGestionaleShellContentWidthOptions = {
  shellEl?: HTMLElement | null;
  shellColEl?: HTMLElement | null;
  mainEl?: HTMLElement | null;
};

/** Larghezza utile colonna contenuto — min tra shell, colonna, main, viewport. */
export function resolveGestionaleShellContentWidth(
  opts: ResolveGestionaleShellContentWidthOptions = {},
): number {
  const hasExplicitEls = Boolean(opts.shellEl ?? opts.shellColEl ?? opts.mainEl);
  if (typeof document === "undefined" && !hasExplicitEls) return 0;

  const widths: number[] = [];

  if (typeof window !== "undefined") {
    const viewport = resolveGestionaleShellViewportWidth();
    if (viewport > 0) widths.push(viewport);
  }

  const shell =
    opts.shellEl ??
    (typeof document !== "undefined" ? document.querySelector(".cab-app-shell") : null);
  if (isLayoutMeasurable(shell)) {
    const w = resolveElementVisibleLayoutWidth(shell);
    if (w > 0) widths.push(w);
  }

  const shellCol =
    opts.shellColEl ??
    (typeof document !== "undefined" ? document.querySelector(".cab-app-shell > div.flex-1") : null);
  if (isLayoutMeasurable(shellCol)) {
    const w = resolveElementVisibleLayoutWidth(shellCol);
    if (w > 0) widths.push(w);
  }

  const main =
    opts.mainEl ??
    (typeof document !== "undefined" ? document.querySelector("main.gestionale-scroll-y") : null);
  if (isLayoutMeasurable(main)) {
    const w = resolveElementVisibleLayoutWidth(main);
    if (w > 0) widths.push(w);
  }

  if (typeof window !== "undefined") {
    const frame = window.frameElement;
    if (isLayoutMeasurable(frame)) {
      const w = resolveElementVisibleLayoutWidth(frame);
      if (w > 0) widths.push(w);
    }
  }

  if (widths.length === 0) return 0;
  return Math.max(0, Math.min(...widths));
}

export const GESTIONALE_SHELL_TABLET_MIN_WIDTH = 768;
/** Soglia desktop shell — preview IDE spesso ~1362px: sotto 1400 = layout compatto. */
export const GESTIONALE_SHELL_DESKTOP_MIN_WIDTH = 1400;

/** Tier shell — desktop solo >= 1400px host (non contentWidth: padding sidebar ~4.25rem). */
export function resolveGestionaleShellTier(hostOrContentWidth: number): GestionaleShellTier {
  if (hostOrContentWidth < GESTIONALE_SHELL_TABLET_MIN_WIDTH) return "mobile";
  if (hostOrContentWidth < GESTIONALE_SHELL_DESKTOP_MIN_WIDTH) return "tablet";
  return "desktop";
}

export function gestionaleShellContentGutterClass(tier: GestionaleShellTier): string {
  return tier === "mobile" ? "px-3" : "px-5";
}

export function readGestionaleShellTierFromDom(): GestionaleShellTier | null {
  if (typeof document === "undefined") return null;
  const shell = document.querySelector(".cab-app-shell");
  if (!(shell instanceof HTMLElement)) return null;
  const tier = shell.getAttribute(GESTIONALE_SHELL_TIER_ATTR);
  if (tier === "mobile" || tier === "tablet" || tier === "desktop") return tier;
  return null;
}

