const INTERNAL_ONLY_PREFIX = "trg_";

/** Explicit PUBLIC_SAFE: anon EXECUTE allowed (rare). */
const PUBLIC_SAFE = new Set(["resolve_auth_email_for_login"]);

const PORTALE = new Set([
