  "execute_rename_job_complete",
  "execute_rename_job_start",
  "cab_publish_notification",
]);

const REFRESH_SEARCH = /^refresh_.*_search_document$/;

function fnKey(name: string, args: string): string {
  return args ? `${name}(${args})` : `${name}()`;
}

function classify(fn: BaselineFn): ManifestEntry {
  const { name } = fn;

  if (PUBLIC_SAFE.has(name)) {
    return {
      classification: "PUBLIC_SAFE",
      grants: ["anon", "service_role"],
      anonAllow: true,
      requiresAuthUid: false,
      requiresRbac: false,
      notes: "Login email resolve only; body validates input",
      findingRefs: ["SEC-PUBLIC-SAFE"],
    };
  }

  if (name.startsWith(INTERNAL_ONLY_PREFIX)) {
    return {
      classification: "INTERNAL_ONLY",
      grants: ["service_role"],
      anonAllow: false,
      requiresAuthUid: false,
      requiresRbac: false,
      notes: "Trigger/pg internal; no PostgREST client",
      findingRefs: ["SEC-01"],
    };
  }

  if (CRON_ONLY.has(name) || REFRESH_SEARCH.test(name)) {
    return {
      classification: "CRON_ONLY",
      grants: ["service_role"],
      anonAllow: false,
      requiresAuthUid: false,
      requiresRbac: false,
      findingRefs: ["SEC-02", "SEC-06", "SEC-11"],
    };
  }

  if (SERVER_ONLY.has(name) || name.startsWith("cab_claim_") || name.startsWith("cab_complete_")) {
    return {
      classification: "SERVER_ONLY",
      grants: ["service_role"],
      anonAllow: false,
      requiresAuthUid: false,
      requiresRbac: false,
      findingRefs: ["SEC-02", "SEC-03", "SEC-06", "SEC-07"],
    };
  }

  if (PORTALE.has(name)) {
    return {
      classification: "PORTALE_CLIENT_CALLABLE",
      grants: ["authenticated"],
      anonAllow: false,
      requiresAuthUid: true,
      requiresRbac: true,
      notes: "Cliente portal visibility/ownership",
    };
  }

  if (STAFF_REPORTS.has(name)) {
    return {
      classification: "AUTHENTICATED_CLIENT_CALLABLE",
      grants: ["authenticated"],
      anonAllow: false,
      requiresAuthUid: true,
      requiresRbac: true,
      notes: "Staff fatturazione/report read",
      findingRefs: ["SEC-04"],
    };
  }

  if (STAFF_EVENT_RPC.has(name)) {
    const module =
      name.includes("preventivo") ? "preventivi" : name.includes("invoice") ? "fatturazione" : "impostazioni";
    return {
      classification: "AUTHENTICATED_CLIENT_CALLABLE",
      grants: ["authenticated"],
      anonAllow: false,
      requiresAuthUid: true,
      requiresRbac: true,
      notes: `Staff ${module} write`,
      findingRefs: ["SEC-05", "SEC-11"],
    };
  }

  if (name.startsWith("rbac_") || name === "user_effective_can" || name === "current_profile_role") {
    return {
      classification: "AUTHENTICATED_CLIENT_CALLABLE",
      grants: ["authenticated"],
      anonAllow: false,
      requiresAuthUid: true,
      requiresRbac: false,
      notes: "RBAC helper for RLS/policies",
    };
  }

  if (
    name.startsWith("notification_") ||
    name.startsWith("cab_list_") ||
    name.startsWith("cab_mark_") ||
    name.startsWith("cab_count_") ||
    name.startsWith("cab_create_") ||
    name.startsWith("cab_dismiss_") ||
    name.startsWith("cab_upsert_workshop") ||
    name.startsWith("cab_patch_workshop") ||
    name.startsWith("cab_detect_schedule") ||
    name.startsWith("cab_migrate_dashboard")
  ) {
    return {
      classification: "AUTHENTICATED_CLIENT_CALLABLE",
      grants: ["authenticated"],
      anonAllow: false,
      requiresAuthUid: true,
      requiresRbac: true,
    };
  }

  if (name.startsWith("cab_revoke_push") || name.startsWith("cab_touch_push") || name.startsWith("cab_upsert_push")) {
    return {
      classification: "AUTHENTICATED_CLIENT_CALLABLE",
      grants: ["authenticated"],
      anonAllow: false,
      requiresAuthUid: true,
      requiresRbac: false,
    };
  }

  if (name.startsWith("document_capture_")) {
    return {
      classification: "AUTHENTICATED_CLIENT_CALLABLE",
      grants: ["authenticated"],
      anonAllow: false,
      requiresAuthUid: true,
      requiresRbac: true,
    };
  }

  if (name.startsWith("import_file_")) {
    return {
      classification: "AUTHENTICATED_CLIENT_CALLABLE",
      grants: ["authenticated"],
      anonAllow: false,
      requiresAuthUid: true,
      requiresRbac: true,
    };
  }

  // Default: authenticated staff RPC (revoke anon)
  return {
    classification: "AUTHENTICATED_CLIENT_CALLABLE",
    grants: ["authenticated", "service_role"],
    anonAllow: false,
    requiresAuthUid: true,
    requiresRbac: true,
    notes: "Default staff callable; anon revoked",
    findingRefs: ["SEC-01"],
  };
}

const entries: Record<string, ManifestEntry> = {};
for (const fn of baseline.functions) {
  entries[fnKey(fn.name, fn.args)] = classify(fn);
}

// Enforce: anonAllow only for PUBLIC_SAFE
for (const [key, entry] of Object.entries(entries)) {
  if (entry.anonAllow && entry.classification !== "PUBLIC_SAFE") {
    throw new Error(`anonAllow only allowed for PUBLIC_SAFE: ${key}`);
  }
  if (entry.grants.includes("anon") && entry.classification !== "PUBLIC_SAFE") {
    throw new Error(`grants must not include anon except PUBLIC_SAFE: ${key}`);
  }
}

const manifest = {
  version: 1,
  generatedAt: new Date().toISOString(),
  sourceBaseline: "docs/security/baseline-pre-remediation-2026-08-26.json",
  policy:
    "SECURITY DEFINER + EXECUTE anon = DENY. Absent from manifest = no client EXECUTE.",
  entries,
};

const outPath = path.join(ROOT, "docs/security/rpc-access-manifest.json");
fs.writeFileSync(outPath, JSON.stringify(manifest, null, 2));
console.log(`manifest: ${Object.keys(entries).length} entries → ${outPath}`);

#!/usr/bin/env node
/**
 * Bootstrap Web Push su Vercel + vault Supabase (one-shot ops).
 * Legge .env.local (Supabase), genera VAPID/CRON se assenti, aggiorna env Vercel.
 *
 * Uso:
 *   node scripts/ops/bootstrap-pwa-push.mjs
 *   node scripts/ops/bootstrap-pwa-push.mjs --deploy
 */
import { execSync } from "node:child_process";
import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import webpush from "web-push";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");
const ENV_LOCAL = path.join(ROOT, ".env.local");
const PROJECT_REF = "oxmnuovsgenqkuwfolqh";
const SITE_URL = process.env.NEXT_PUBLIC_SITE_URL?.trim() || "https://gestionale-cab.vercel.app";
const VAPID_SUBJECT = process.env.VAPID_SUBJECT?.trim() || "mailto:service@autocompattatori.it";
const TARGET_ENVS = ["production", "preview"];

function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) return {};
  const out = {};
  for (const line of fs.readFileSync(filePath, "utf8").split(/\r?\n/)) {
    const t = line.trim();
    if (!t || t.startsWith("#")) continue;
    const i = t.indexOf("=");
    if (i < 1) continue;
    const key = t.slice(0, i).trim();
    let val = t.slice(i + 1).trim();
    if ((val.startsWith('"') && val.endsWith('"')) || (val.startsWith("'") && val.endsWith("'"))) {
      val = val.slice(1, -1);
    }
    out[key] = val;
  }
  return out;
}

function run(cmd, input) {
  execSync(cmd, {
    cwd: ROOT,
    stdio: input != null ? ["pipe", "inherit", "inherit"] : "inherit",
    input,
    env: process.env,
  });
}

function setVercelEnv(name, value, targets = TARGET_ENVS) {
  for (const target of targets) {
    try {
      run(`npx vercel env rm ${name} ${target} --yes`);
    } catch {
      /* missing */
    }
    try {
      run(`npx vercel env add ${name} ${target}`, `${value}\n`);
    } catch (err) {
      try {
        run(`npx vercel env rm ${name} ${target} --yes --all`);
        run(`npx vercel env add ${name} ${target}`, `${value}\n`);
      } catch {
        throw err;
      }
    }
    console.log(`[vercel] ${name} → ${target}`);
  }
}

async function setSupabaseEdgeSecrets(secrets) {
  const token = process.env.SUPABASE_ACCESS_TOKEN?.trim();
  if (!token) {
    console.warn("[supabase] skip edge secrets — SUPABASE_ACCESS_TOKEN assente");
    return false;
  }
  const res = await fetch(`https://api.supabase.com/v1/projects/${PROJECT_REF}/secrets`, {
    method: "POST",
    headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
    body: JSON.stringify(secrets),
  });
  if (!res.ok) {
    console.error(`[supabase] edge secrets failed ${res.status}: ${await res.text()}`);
    return false;
  }
  console.log("[supabase] edge secrets ok:", secrets.map((s) => s.name).join(", "));
  return true;
}

async function syncVaultCronSecret(serviceKey, cronSecret) {
  // vault update via SQL through Supabase Management — use execute_sql via fetch to pg not available.
  // ponytail: POST /database/query Management API
  const token = process.env.SUPABASE_ACCESS_TOKEN?.trim();
  if (!token) {
    console.warn("[vault] skip — imposta push_delivery_cron_secret manualmente o con SUPABASE_ACCESS_TOKEN");
    return false;
  }
  const sql = `
    delete from vault.secrets where name = 'push_delivery_cron_secret';
    select vault.create_secret(
      '${cronSecret.replace(/'/g, "''")}',
      'push_delivery_cron_secret',
      'Bearer auth for Vercel /api/cron/push-delivery'
    );
  `;
  const res = await fetch(`https://api.supabase.com/v1/projects/${PROJECT_REF}/database/query`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${token}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ query: sql }),
  });
  if (!res.ok) {
    console.error(`[vault] sync failed ${res.status}: ${await res.text()}`);
    return false;
  }
  console.log("[vault] push_delivery_cron_secret synced");
  return true;
}

function ensureVapidKeys(local) {
  let publicKey = process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY?.trim() || local.NEXT_PUBLIC_VAPID_PUBLIC_KEY?.trim();
  let privateKey = process.env.VAPID_PRIVATE_KEY?.trim() || local.VAPID_PRIVATE_KEY?.trim();
  if (!publicKey || !privateKey) {
    const keys = webpush.generateVAPIDKeys();
    publicKey = keys.publicKey;
    privateKey = keys.privateKey;
    console.log("[vapid] generated new key pair");
    const append = [
      "",
      "# Web Push (generato da scripts/ops/bootstrap-pwa-push.mjs)",
      `NEXT_PUBLIC_VAPID_PUBLIC_KEY=${publicKey}`,
      `VAPID_PRIVATE_KEY=${privateKey}`,
      `VAPID_SUBJECT=${VAPID_SUBJECT}`,
      "PWA_PUSH_ENABLED=true",
    ].join("\n");
    fs.appendFileSync(ENV_LOCAL, append, "utf8");
    console.log("[vapid] appended keys to .env.local for stable re-runs");
  } else {
    console.log("[vapid] reusing keys from env / .env.local");
  }
  return { publicKey, privateKey };
}

async function main() {
  const local = parseEnvFile(ENV_LOCAL);
  const supabaseUrl = local.NEXT_PUBLIC_SUPABASE_URL?.trim();
  const anonKey = local.NEXT_PUBLIC_SUPABASE_ANON_KEY?.trim();
  const serviceKey = local.SUPABASE_SERVICE_ROLE_KEY?.trim();
  if (!supabaseUrl || !anonKey || !serviceKey) {
    console.error("Missing NEXT_PUBLIC_SUPABASE_URL / ANON_KEY / SERVICE_ROLE_KEY in .env.local");
    process.exit(1);
  }

  const cronSecret =
    process.env.CRON_SECRET?.trim() ||
    local.CRON_SECRET?.trim() ||
    crypto.randomBytes(32).toString("hex");

  if (!local.CRON_SECRET?.trim() && !process.env.CRON_SECRET?.trim()) {
    fs.appendFileSync(
      ENV_LOCAL,
      `\nCRON_SECRET=${cronSecret}\n`,
      "utf8",
    );
    console.log("[cron] appended CRON_SECRET to .env.local");
  }

  const { publicKey, privateKey } = ensureVapidKeys(local);

  const bundle = {
    NEXT_PUBLIC_SUPABASE_URL: supabaseUrl,
    NEXT_PUBLIC_SUPABASE_ANON_KEY: anonKey,
    SUPABASE_SERVICE_ROLE_KEY: serviceKey,
    NEXT_PUBLIC_SITE_URL: SITE_URL,
    NEXT_PUBLIC_VAPID_PUBLIC_KEY: publicKey,
    VAPID_PRIVATE_KEY: privateKey,
    VAPID_SUBJECT,
    PWA_PUSH_ENABLED: "true",
    CRON_SECRET: cronSecret,
  };

  for (const [name, value] of Object.entries(bundle)) {
    if (!value) {
      console.error(`empty value for ${name}`);
      process.exit(1);
    }
    setVercelEnv(name, value);
  }

  await setSupabaseEdgeSecrets([
    { name: "VAPID_PUBLIC_KEY", value: publicKey },
    { name: "VAPID_PRIVATE_KEY", value: privateKey },
    { name: "VAPID_SUBJECT", value: VAPID_SUBJECT },
    { name: "PWA_PUSH_ENABLED", value: "true" },
  ]);

  const cronFile = path.join(ROOT, ".tmp-push-cron-secret");
  fs.writeFileSync(cronFile, cronSecret, { encoding: "utf8", mode: 0o600 });
  console.log(`[cron] secret written to ${cronFile} (sync vault via MCP/SQL, poi elimina file)`);

  if (process.argv.includes("--deploy-only")) {
    console.log("[vercel] production deploy only…");
    run("npx vercel deploy --prod --yes");
    return;
  }

  if (process.argv.includes("--deploy")) {
    console.log("[vercel] production deploy…");
    run("npx vercel deploy --prod --yes");
  } else {
    console.log("[done] env aggiornati. Esegui: node scripts/ops/bootstrap-pwa-push.mjs --deploy");
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

/**
 * Performance closure verify — final audit gate battery.
 * Usage: node scripts/ops/performance-closure-verify.mjs
 */
import { execFileSync } from "node:child_process";
import { existsSync } from "node:fs";
import { join } from "node:path";

const ROOT = process.cwd();

function run(label, cmd, args, { optional = false } = {}) {
  console.log(`\n[closure] ${label}...`);
  const r = execFileSync(cmd, args, { cwd: ROOT, stdio: "inherit", shell: true });
  return r;
}

function runTsx(testPath) {
  execFileSync("npx", ["tsx", testPath], { cwd: ROOT, stdio: "inherit", shell: true });
}

const failures = [];

try {
  if (!existsSync(join(ROOT, ".next", "diagnostics", "route-bundle-stats.json"))) {
    run("build (includes budget gate)", "npm", ["run", "build"]);
  } else {
    run("build-budget-gate", "npm", ["run", "ops:build-budget-gate"]);
  }

  const suite = JSON.parse(
    execFileSync("npx", ["tsx", "scripts/ops/print-governance-suite.ts"], {
      cwd: ROOT,
      encoding: "utf8",
      shell: true,
    }).trim(),
  );

  for (const test of suite) {
    runTsx(test);
  }

  run("performance-snapshot", "node", ["scripts/ops/performance-snapshot.mjs", "--refresh-baseline"]);
  run("performance-regression-check", "npm", ["run", "ops:performance-regression-check"]);
  run("performance-trend-report", "npm", ["run", "ops:performance-trend-report"]);

  try {
    run("lighthouse-budget", "npm", ["run", "ops:lighthouse-budget"]);
  } catch {
    console.warn("[closure] lighthouse-budget skipped or warned (non-fatal)");
  }
} catch (e) {
  failures.push(e instanceof Error ? e.message : String(e));
}

if (failures.length > 0) {
  console.error("\nperformance-closure-verify: FAIL");
  for (const f of failures) console.error(f);
  process.exit(1);
}

console.log("\nperformance-closure-verify: PASS");

#!/usr/bin/env npx tsx
/**
 * Selector System Final Hardening — import graph, dead code, runtime surface, barrel drift.
 * Outputs to lib/selector-core/generated/
 */
import fs from "node:fs";
import path from "node:path";

const ROOT = process.cwd();
const SELECTOR_CORE = "lib/selector-core";
const GENERATED_DIR = path.join(ROOT, SELECTOR_CORE, "generated");

const IMPORT_FROM_RE =
  /(?:import|export)\s+(?:type\s+)?(?:[\w*{}\s,]+\s+from\s+)?["']([^"']+)["']/g;
const REQUIRE_RE = /require\s*\(\s*["']([^"']+)["']\s*\)/g;

const REMOVED_SHIM_SEGMENTS = new Set([
  "selector-api-safe-legacy-registry",
  "selector-config-factory",
  "selector-decision-engine-config",
  "selector-rollout-config",
  "selector-explainability-observation-adapter",
  "selector-policy-runtime-convergence-check",
  "selector-convergence-ci-gate",
  "selector-observation-index",
  "selector-observation-doc-map",
  "selector-observation-trace-navigator",
  "selector-debug-dsl",
  "selector-unified-causal-index",
  "selector-causal-decision-graph",
  "selector-temporal-lineage-graph",
  "selector-explainability-facade",
  "selector-fallback-explainability-engine",
  "selector-pre-resolution-guard",
  "selector-determinism-integrity-check",
  "selector-system-complexity-audit",
]);

const HOT_PATH_ROOTS = [
  "lib/selector-core/selector-decision-engine.ts",
  "lib/selector-core/selector-config-runtime-loader.ts",
  "lib/selector-core/selector-fallback-trace.ts",
  "lib/selector-core/selector-engine-config.ts",
  "lib/selector-core/selector-explainability.ts",
  "lib/selector-core/selector-telemetry-bridge.ts",
  "components/gestionale/global-input/global-select.tsx",
];

const KNOWN_ADVISORY_CYCLES: string[][] = [
  [
    "lib/selector-core/selector-runtime-sanity-guard.ts",
    "lib/selector-core/selector-runtime-snapshot-revalidator.ts",
    "lib/selector-core/selector-runtime-sanity-guard.ts",
  ],
  [
    "lib/selector-core/selector-snapshot-lifecycle-manager.ts",
    "lib/selector-core/selector-snapshot-pruner.ts",
    "lib/selector-core/selector-snapshot-lifecycle-manager.ts",
  ],
  [
    "lib/selector-core/selector-snapshot-bundle-sync.ts",
    "lib/selector-core/selector-snapshot-registry.ts",
    "lib/selector-core/selector-snapshot-bundle-sync.ts",
  ],
  [
    "lib/selector-core/selector-api-enforcer-report.ts",
    "lib/selector-core/selector-api-surface-registry.ts",
    "lib/selector-core/selector-enforcement-ruleset.ts",
    "lib/selector-core/selector-api-enforcer-report.ts",
  ],
];

const RUNTIME_SYMBOLS: Record<
  string,
  { canonicalFile: string; forbiddenShimImports?: string[] }
> = {
  SelectorDecisionEngine: {
    canonicalFile: "lib/selector-core/selector-decision-engine.ts",
    forbiddenShimImports: ["selector-fallback-explainability-engine"],
  },
  loadLatestSelectorSnapshot: {
    canonicalFile: "lib/selector-core/selector-config-runtime-loader.ts",
  },
  resolveSelectorEngineConfig: {
    canonicalFile: "lib/selector-core/selector-config-runtime-loader.ts",
  },
  getExplanation: {
    canonicalFile: "lib/selector-core/selector-explainability.ts",
    forbiddenShimImports: ["selector-explanation-kernel"],
  },
};

const DO_NOT_TOUCH = [
  "lib/selector-core/selector-decision-engine.ts",
  "lib/selector-core/selector-config-runtime-loader.ts",
  "lib/selector-core/selector-explainability.ts",
  "lib/selector-core/selector-enforcement-ruleset.ts",
  "lib/selector-core/selector-build-orchestrator.ts",
  "lib/selector-core/selector-adaptive-analyzer.ts",
  "lib/selector-core/selector-ab-simulator.ts",
  "lib/selector-core/selector-insight-promotion-engine.ts",
];

type GraphNode = {
  file: string;
  imports: string[];
  importedBy: string[];
  brokenImports: { importPath: string; reason: string }[];
};

type DeadCodeEntry = {
  file: string;
  symbol: string;
  kind: "function" | "const" | "type" | "class";
  confidence: number;
  reason: string;
  onHotPath: boolean;
  smokeCovered: boolean;
};

function walkSelectorCoreSourceFiles(): string[] {
  const acc: string[] = [];
  const abs = path.join(ROOT, SELECTOR_CORE);
  for (const entry of fs.readdirSync(abs, { withFileTypes: true })) {
    if (entry.name === "generated" || entry.name === "node_modules") continue;
    const rel = path.join(SELECTOR_CORE, entry.name).replace(/\\/g, "/");
    if (entry.isDirectory()) continue;
    if (!entry.name.endsWith(".ts")) continue;
    if (entry.name.endsWith(".test.ts")) continue;
    acc.push(rel);
  }
  return acc.sort();
}

function collectImportPaths(source: string): string[] {
  const paths: string[] = [];
  for (const re of [IMPORT_FROM_RE, REQUIRE_RE]) {
    re.lastIndex = 0;
    let match: RegExpExecArray | null;
    while ((match = re.exec(source)) !== null) {
      paths.push(match[1]!);
    }
  }
  return paths;
}

function resolveSelectorCorePath(importPath: string): string | null {
  const normalized = importPath.replace(/\\/g, "/");
  if (normalized.startsWith("@/lib/selector-core/")) {
    const rest = normalized.slice("@/lib/selector-core/".length);
    if (rest.endsWith(".json")) {
      return `lib/selector-core/${rest}`;
    }
    const base = rest.replace(/\.tsx?$/, "");
    const candidate = `lib/selector-core/${base}.ts`;
    if (fs.existsSync(path.join(ROOT, candidate))) return candidate;
    const withPrefix = base.startsWith("selector-")
      ? candidate
      : `lib/selector-core/selector-${base}.ts`;
    if (fs.existsSync(path.join(ROOT, withPrefix))) return withPrefix;
    return candidate;
  }
  if (normalized.includes("selector-core/")) {
    const idx = normalized.indexOf("selector-core/");
    const rest = normalized.slice(idx + "selector-core/".length);
    const candidate = `lib/selector-core/${rest.replace(/\.tsx?$/, "")}.ts`;
    return candidate;
  }
  return null;
}

function moduleSegment(importPath: string): string | null {
  const resolved = resolveSelectorCorePath(importPath);
  if (!resolved) return null;
  return path.basename(resolved, ".ts");
}

function parseSmokeSelectorTests(): string[] {
  const source = fs.readFileSync(
    path.join(ROOT, "lib/regression/smoke-regression-lists.ts"),
    "utf8",
  );
  const tests = new Set<string>();
  const re = /["'](lib\/(?:regression|selector-core)\/selector-[^"']+\.test\.ts)["']/g;
  let match: RegExpExecArray | null;
  while ((match = re.exec(source)) !== null) {
    tests.add(match[1]!);
  }
  return [...tests].sort();
}

function walkRepoScanRoots(): string[] {
  const roots = ["components", "lib", "scripts", "app"];
  const files: string[] = [];
  function walk(dir: string): void {
    const abs = path.join(ROOT, dir);
    if (!fs.existsSync(abs)) return;
    for (const entry of fs.readdirSync(abs, { withFileTypes: true })) {
      if (entry.name === "node_modules" || entry.name === ".next" || entry.name === "generated") {
        continue;
      }
      const rel = path.join(dir, entry.name).replace(/\\/g, "/");
      if (entry.isDirectory()) {
        walk(rel);
      } else if (/\.(ts|tsx|mts|cts)$/.test(entry.name) && !entry.name.endsWith(".d.ts")) {
        files.push(rel);
      }
    }
  }
  for (const root of roots) walk(root);
  return files;
}

function buildImportGraph(files: string[]): Record<string, GraphNode> {
  const graph: Record<string, GraphNode> = {};
  for (const file of files) {
    graph[file] = { file, imports: [], importedBy: [], brokenImports: [] };
  }

  for (const file of files) {
    const source = fs.readFileSync(path.join(ROOT, file), "utf8");
    const importPaths = collectImportPaths(source);
    const seen = new Set<string>();

    for (const importPath of importPaths) {
      const segment = importPath.split("/").pop()?.replace(/\.tsx?$/, "") ?? "";
      if (REMOVED_SHIM_SEGMENTS.has(segment)) {
        graph[file]!.brokenImports.push({
          importPath,
          reason: "references_removed_shim",
        });
      }

      const resolved = resolveSelectorCorePath(importPath);
      if (!resolved) continue;
      if (resolved.endsWith(".json")) {
        if (!fs.existsSync(path.join(ROOT, resolved))) {
          graph[file]!.brokenImports.push({
            importPath,
            reason: "missing_json_artifact",
          });
        }
        continue;
      }
      if (!graph[resolved]) {
        if (fs.existsSync(path.join(ROOT, resolved))) {
          graph[resolved] = { file: resolved, imports: [], importedBy: [], brokenImports: [] };
        } else {
          graph[file]!.brokenImports.push({
            importPath,
            reason: "unresolved_selector_core_path",
          });
          continue;
        }
      }
      if (!seen.has(resolved)) {
        seen.add(resolved);
        graph[file]!.imports.push(resolved);
        graph[resolved]!.importedBy.push(file);
      }
    }
  }

  return graph;
}

function cycleKey(cycle: string[]): string {
  return [...cycle].sort().join("|");
}

function cycleTouchesHotPath(cycle: string[]): boolean {
  return cycle.some((f) => HOT_PATH_ROOTS.includes(f));
}

function isKnownAdvisoryCycle(cycle: string[]): boolean {
  const key = cycleKey(cycle);
  return KNOWN_ADVISORY_CYCLES.some((known) => cycleKey(known) === key);
}

function findCycles(graph: Record<string, GraphNode>): string[][] {
  const cycles: string[][] = [];
  const visiting = new Set<string>();
  const visited = new Set<string>();
  const stack: string[] = [];

  function dfs(node: string): void {
    if (visited.has(node)) return;
    if (visiting.has(node)) {
      const idx = stack.indexOf(node);
      if (idx >= 0) cycles.push(stack.slice(idx).concat(node));
      return;
    }
    visiting.add(node);
    stack.push(node);
    for (const dep of graph[node]?.imports ?? []) {
      if (graph[dep]) dfs(dep);
    }
    stack.pop();
    visiting.delete(node);
    visited.add(node);
  }

  for (const node of Object.keys(graph)) dfs(node);
  return cycles;
}

function bfsReachableFrom(roots: string[], graph: Record<string, GraphNode>): Set<string> {
  const reached = new Set<string>();
  const queue = [...roots];
  while (queue.length > 0) {
    const node = queue.shift()!;
    if (reached.has(node)) continue;
    reached.add(node);
    for (const dep of graph[node]?.imports ?? []) {
      if (!reached.has(dep)) queue.push(dep);
    }
  }
  return reached;
}

function extractExports(source: string): { symbol: string; kind: DeadCodeEntry["kind"] }[] {
  const exports: { symbol: string; kind: DeadCodeEntry["kind"] }[] = [];
  const fnRe = /export\s+(?:async\s+)?function\s+(\w+)/g;
  const constRe = /export\s+const\s+(\w+)/g;
  const typeRe = /export\s+type\s+(\w+)/g;
  const classRe = /export\s+class\s+(\w+)/g;
  let m: RegExpExecArray | null;
  while ((m = fnRe.exec(source)) !== null) exports.push({ symbol: m[1]!, kind: "function" });
  while ((m = constRe.exec(source)) !== null) exports.push({ symbol: m[1]!, kind: "const" });
  while ((m = typeRe.exec(source)) !== null) exports.push({ symbol: m[1]!, kind: "type" });
  while ((m = classRe.exec(source)) !== null) exports.push({ symbol: m[1]!, kind: "class" });
  return exports;
}

function countSymbolRefs(symbol: string, repoFiles: string[], excludeFile: string): number {
  const re = new RegExp(`\\b${symbol}\\b`, "g");
  let count = 0;
  for (const file of repoFiles) {
    if (file === excludeFile) continue;
    const source = fs.readFileSync(path.join(ROOT, file), "utf8");
    const matches = source.match(re);
    if (matches) count += matches.length;
  }
  return count;
}

function buildDeadCodeReport(
  files: string[],
  graph: Record<string, GraphNode>,
  hotReachable: Set<string>,
  smokeTests: string[],
  repoFiles: string[],
): DeadCodeEntry[] {
  const smokeSources = smokeTests.map((t) => fs.readFileSync(path.join(ROOT, t), "utf8"));
  const entries: DeadCodeEntry[] = [];

  for (const file of files) {
    const source = fs.readFileSync(path.join(ROOT, file), "utf8");
    const onHotPath = hotReachable.has(file);
    const smokeCovered = smokeSources.some((s) => s.includes(path.basename(file, ".ts")));

    for (const { symbol, kind } of extractExports(source)) {
      if (symbol.startsWith("__")) continue;
      const refs = countSymbolRefs(symbol, repoFiles, file);
      const indexSource = fs.readFileSync(path.join(ROOT, "lib/selector-core/index.ts"), "utf8");
      const inBarrelOnly =
        refs === 0 && new RegExp(`\\b${symbol}\\b`).test(indexSource) && !onHotPath;

      let confidence = 0;
      let reason = "referenced";
      if (onHotPath || smokeCovered) {
        confidence = Math.min(40, refs > 0 ? 30 : 20);
        reason = onHotPath ? "hot_path_reachable" : "smoke_test_covered";
      } else if (refs === 0 && !inBarrelOnly) {
        confidence = 95;
        reason = "zero_repo_references";
      } else if (refs === 0 && inBarrelOnly) {
        confidence = 88;
        reason = "barrel_only_export";
      } else if (refs <= 2) {
        confidence = 72;
        reason = "script_or_test_only";
      } else {
        confidence = 45;
        reason = "low_usage";
      }

      if (confidence >= 60) {
        entries.push({
          file,
          symbol,
          kind,
          confidence,
          reason,
          onHotPath,
          smokeCovered,
        });
      }
    }
  }

  return entries.sort((a, b) => b.confidence - a.confidence);
}

function parseBarrelExports(indexSource: string): { symbol: string; sourceModule: string }[] {
  const exports: { symbol: string; sourceModule: string }[] = [];
  const blockRe =
    /export\s*\{([^}]+)\}\s*from\s*["']@\/lib\/selector-core\/([^"']+)["']/g;
  let block: RegExpExecArray | null;
  while ((block = blockRe.exec(indexSource)) !== null) {
    const sourceModule = block[2]!;
    const inner = block[1]!;
    for (const part of inner.split(",")) {
      const trimmed = part.trim();
      if (!trimmed || trimmed.startsWith("/**") || trimmed.startsWith("*")) continue;
      const aliasMatch = trimmed.match(/(\w+)\s+as\s+(\w+)/);
      const sym = aliasMatch ? aliasMatch[2]! : trimmed.replace(/^type\s+/, "").split(/\s/)[0]!;
      if (sym && /^[A-Za-z_]/.test(sym)) {
        exports.push({ symbol: sym, sourceModule });
      }
    }
  }
  return exports;
}

function buildRuntimeSurfaceAudit(repoFiles: string[]): Record<string, unknown> {
  const surfaces: Record<string, unknown> = {};

  for (const [symbol, spec] of Object.entries(RUNTIME_SYMBOLS)) {
    const allImportPaths: string[] = [];
    const importRe = new RegExp(
      `from\\s+["']@/lib/selector-core/([^"']+)["'][^;]*\\b${symbol}\\b|import\\s*\\{[^}]*\\b${symbol}\\b`,
    );
    const directRe = new RegExp(`\\b${symbol}\\b`);

    for (const file of repoFiles) {
      const source = fs.readFileSync(path.join(ROOT, file), "utf8");
      if (directRe.test(source) && file.includes("selector-core")) {
        if (source.includes(symbol)) allImportPaths.push(file);
      }
    }

    const canonicalSource = fs.readFileSync(path.join(ROOT, spec.canonicalFile), "utf8");
    const definesSymbol = new RegExp(`export\\s+(?:const|function|type)?\\s*${symbol}\\b|export\\s*\\{[^}]*\\b${symbol}\\b`).test(
      canonicalSource,
    );

    const aliasChains: string[] = [];
    if (symbol === "SelectorDecisionEngine") {
      const surface = fs.readFileSync(
        path.join(ROOT, "lib/selector-core/resolve-selector-surface.ts"),
        "utf8",
      );
      if (surface.includes("SelectorDecisionEngine.resolve")) {
        aliasChains.push("resolve-selector-surface.ts → SelectorDecisionEngine.resolve");
      }
    }
    if (symbol === "getExplanation") {
      const explain = canonicalSource;
      if (explain.includes("getSelectorExplanation")) {
        aliasChains.push("getSelectorExplanation (deprecated alias in explainability.ts)");
      }
    }

    const duplicateFallbackPaths: string[] = [];
    if (symbol === "SelectorDecisionEngine") {
      if (canonicalSource.includes("selector-fallback-explainability-engine")) {
        duplicateFallbackPaths.push("selector-fallback-explainability-engine");
      }
    }

    const forbiddenHits = (spec.forbiddenShimImports ?? []).filter((shim) =>
      canonicalSource.includes(shim),
    );

    const globalSelect = fs.readFileSync(
      path.join(ROOT, "components/gestionale/global-input/global-select.tsx"),
      "utf8",
    );
    const uiUsesCanonical =
      symbol !== "SelectorDecisionEngine" ||
      globalSelect.includes("selector-decision-engine");

    surfaces[symbol] = {
      canonicalPath: spec.canonicalFile,
      definesSymbol,
      allImportPaths: [...new Set(allImportPaths)].sort(),
      aliasChains,
      duplicateFallbackPaths,
      forbiddenShimImports: forbiddenHits,
      stable:
        definesSymbol &&
        forbiddenHits.length === 0 &&
        duplicateFallbackPaths.length === 0 &&
        (symbol !== "SelectorDecisionEngine" || uiUsesCanonical),
    };
  }

  return {
    generatedAt: new Date().toISOString(),
    surfaces,
    allStable: Object.values(surfaces).every((s) => (s as { stable: boolean }).stable),
  };
}

function buildBarrelDriftReport(repoFiles: string[]): Record<string, unknown> {
  const indexSource = fs.readFileSync(path.join(ROOT, "lib/selector-core/index.ts"), "utf8");
  const barrelExports = parseBarrelExports(indexSource);
  const indexConsumers = repoFiles.filter((f) => {
    const s = fs.readFileSync(path.join(ROOT, f), "utf8");
    return /from\s+["']@\/lib\/selector-core\/index["']/.test(s);
  });

  const used: string[] = [];
  const unused: string[] = [];
  const risky: string[] = [];

  const moduleImportRe = (mod: string) =>
    new RegExp(`from\\s+["']@/lib/selector-core/${mod.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}["']`);

  for (const { symbol, sourceModule } of barrelExports) {
    let symbolRefs = 0;
    let moduleImported = false;
    let stringOnlyRefs = 0;
    const modRe = moduleImportRe(sourceModule);

    for (const file of repoFiles) {
      if (file === "lib/selector-core/index.ts") continue;
      const source = fs.readFileSync(path.join(ROOT, file), "utf8");
      if (modRe.test(source)) moduleImported = true;
      if (!new RegExp(`\\b${symbol}\\b`).test(source)) continue;
      if (modRe.test(source)) symbolRefs++;
      else stringOnlyRefs++;
    }

    if (symbolRefs > 0 || moduleImported) used.push(symbol);
    else if (stringOnlyRefs > 0) risky.push(symbol);
    else unused.push(symbol);
  }

  const total = barrelExports.length;
  const unusedPercent = total > 0 ? (unused.length / total) * 100 : 0;

  return {
    generatedAt: new Date().toISOString(),
    barrelExportCount: total,
    indexConsumerCount: indexConsumers.length,
    indexConsumers,
    used,
    unused,
    risky,
    unusedPercent: Math.round(unusedPercent * 100) / 100,
    unusedPercentPass: unusedPercent < 5,
  };
}

function collectSafeActions(
  graph: Record<string, GraphNode>,
  barrel: Record<string, unknown>,
  indexSource: string,
): string[] {
  const actions: string[] = [];
  const dupes = (indexSource.match(/assertSingleActiveSnapshot/g) ?? []).length;
  if (dupes > 1) {
    actions.push("Remove duplicate assertSingleActiveSnapshot export in index.ts");
  }
  const immutDupes = (indexSource.match(/assertSnapshotImmutability/g) ?? []).length;
  if (immutDupes > 1) {
    actions.push("Remove duplicate assertSnapshotImmutability export in index.ts");
  }

  const allBroken = Object.values(graph).flatMap((n) =>
    n.brokenImports.map((b) => `${n.file}: ${b.importPath} (${b.reason})`),
  );
  if (allBroken.length > 0) {
    actions.push(`Fix ${allBroken.length} broken import(s) — see import-graph report`);
  }

  if (!(barrel.unusedPercentPass as boolean)) {
    actions.push(
      `Barrel has ${barrel.unusedPercent}% UNUSED exports — trim advisory-only blocks when safe`,
    );
  }

  actions.push("Run: npx tsx scripts/selector-rebuild-observation-registry.ts");
  return actions;
}

function buildSummaryMd(input: {
  importGraph: Record<string, unknown>;
  runtime: Record<string, unknown>;
  barrel: Record<string, unknown>;
  deadCode: DeadCodeEntry[];
  safeActions: string[];
}): string {
  const ig = input.importGraph;
  const broken = (ig.brokenImportCount as number) ?? 0;
  const hotPathCycles = (ig.hotPathCycles as string[][]) ?? [];
  const unknownCycles = (ig.unknownCycles as string[][]) ?? [];
  const runtimeOk = input.runtime.allStable as boolean;
  const barrelOk = input.barrel.unusedPercentPass as boolean;

  const gates = [
    { name: "Import graph (zero broken)", pass: broken === 0 },
    { name: "Hot-path circular dependencies", pass: hotPathCycles.length === 0 },
    { name: "Unknown advisory cycles", pass: unknownCycles.length === 0 },
    { name: "Runtime surface stable", pass: runtimeOk },
    { name: "Barrel drift < 5% UNUSED", pass: barrelOk },
  ];

  const deadTop = input.deadCode.slice(0, 15);

  return `# Selector Hardening Audit Summary

Generated: ${new Date().toISOString()}

## Executive Status

| Gate | Status |
|------|--------|
${gates.map((g) => `| ${g.name} | ${g.pass ? "PASS" : "FAIL"} |`).join("\n")}

**Overall:** ${gates.every((g) => g.pass) ? "PASS" : "FAIL"}

## Metrics

- Broken imports: ${broken}
- Import cycles (total): ${(ig.cycleCount as number) ?? 0}
- Hot-path cycles: ${hotPathCycles.length}
- Unknown advisory cycles: ${unknownCycles.length}
- Barrel exports: ${input.barrel.barrelExportCount}
- Barrel UNUSED: ${(input.barrel.unused as string[]).length} (${input.barrel.unusedPercent}%)
- Barrel USED: ${(input.barrel.used as string[]).length}
- Barrel RISKY: ${(input.barrel.risky as string[]).length}
- Dead code candidates (confidence >= 60): ${input.deadCode.length}

## SAFE ACTIONS

${input.safeActions.map((a) => `- ${a}`).join("\n")}

## DO NOT TOUCH

${DO_NOT_TOUCH.map((f) => `- \`${f}\` — runtime/build contract or offline script dependency`).join("\n")}

## Dead Code Candidates (report only — do not auto-delete)

| Confidence | Symbol | File | Reason |
|------------|--------|------|--------|
${deadTop.map((d) => `| ${d.confidence} | ${d.symbol} | ${d.file} | ${d.reason} |`).join("\n")}

## Runtime Surface

${Object.entries(input.runtime.surfaces as Record<string, { stable: boolean; canonicalPath: string }>)
  .map(([sym, s]) => `- **${sym}**: ${s.stable ? "stable" : "UNSTABLE"} @ \`${s.canonicalPath}\``)
  .join("\n")}
`;
}

function main(): void {
  fs.mkdirSync(GENERATED_DIR, { recursive: true });

  const files = walkSelectorCoreSourceFiles();
  const repoFiles = walkRepoScanRoots();
  const smokeTests = parseSmokeSelectorTests();
  const graph = buildImportGraph(files);
  const cycles = findCycles(graph);
  const hotPathCycles = cycles.filter((c) => cycleTouchesHotPath(c));
  const advisoryCycles = cycles.filter((c) => !cycleTouchesHotPath(c));
  const unknownCycles = advisoryCycles.filter((c) => !isKnownAdvisoryCycle(c));
  const hotReachable = bfsReachableFrom(HOT_PATH_ROOTS, graph);

  const allBroken: { file: string; importPath: string; reason: string }[] = [];
  for (const node of Object.values(graph)) {
    for (const b of node.brokenImports) {
      allBroken.push({ file: node.file, ...b });
    }
  }

  const orphanModules = files.filter((f) => {
    const n = graph[f];
    if (!n) return false;
    return n.importedBy.length === 0 && n.imports.length === 0 && !hotReachable.has(f);
  });

  const importGraphReport = {
    generatedAt: new Date().toISOString(),
    fileCount: files.length,
    nodes: Object.fromEntries(
      Object.entries(graph).map(([k, v]) => [
        k,
        { imports: v.imports, importedBy: v.importedBy, brokenImports: v.brokenImports },
      ]),
    ),
    brokenImports: allBroken,
    brokenImportCount: allBroken.length,
    cycles,
    cycleCount: cycles.length,
    hotPathCycles,
    hotPathCycleCount: hotPathCycles.length,
    advisoryCycles,
    unknownCycles,
    orphanModules,
    hotPathReachable: [...hotReachable].sort(),
    deadCode: [] as DeadCodeEntry[],
  };

  const deadCode = buildDeadCodeReport(files, graph, hotReachable, smokeTests, repoFiles);
  importGraphReport.deadCode = deadCode;

  const runtimeReport = buildRuntimeSurfaceAudit(repoFiles);
  const barrelReport = buildBarrelDriftReport(repoFiles);
  const indexSource = fs.readFileSync(path.join(ROOT, "lib/selector-core/index.ts"), "utf8");
  const safeActions = collectSafeActions(graph, barrelReport, indexSource);
  const summaryMd = buildSummaryMd({
    importGraph: importGraphReport,
    runtime: runtimeReport,
    barrel: barrelReport,
    deadCode,
    safeActions,
  });

  fs.writeFileSync(
    path.join(GENERATED_DIR, "selector-import-graph-report.json"),
    JSON.stringify(importGraphReport, null, 2),
    "utf8",
  );
  fs.writeFileSync(
    path.join(GENERATED_DIR, "selector-runtime-surface-audit.json"),
    JSON.stringify(runtimeReport, null, 2),
    "utf8",
  );
  fs.writeFileSync(
    path.join(GENERATED_DIR, "selector-barrel-drift-report.json"),
    JSON.stringify(barrelReport, null, 2),
    "utf8",
  );
  fs.writeFileSync(
    path.join(GENERATED_DIR, "selector-hardening-audit-summary.md"),
    summaryMd,
    "utf8",
  );

  console.log(
    JSON.stringify(
      {
        brokenImports: allBroken.length,
        cycles: cycles.length,
        hotPathCycles: hotPathCycles.length,
        unknownCycles: unknownCycles.length,
        runtimeStable: runtimeReport.allStable,
        barrelUnusedPercent: barrelReport.unusedPercent,
        deadCodeCandidates: deadCode.length,
        outputs: [
          "lib/selector-core/generated/selector-import-graph-report.json",
          "lib/selector-core/generated/selector-runtime-surface-audit.json",
          "lib/selector-core/generated/selector-barrel-drift-report.json",
          "lib/selector-core/generated/selector-hardening-audit-summary.md",
        ],
      },
      null,
      2,
    ),
  );
}

main();

/**
 * Inventario statico Supabase: migration, oggetti SQL, cross-ref frontend.
 * Uso: npx tsx scripts/supabase-audit-inventory.ts [--json]
 */
import fs from "node:fs";
import path from "node:path";

const ROOT = process.cwd();
const MIGRATIONS_DIR = path.join(ROOT, "supabase", "migrations");
const RBAC_CORE = path.join(ROOT, "supabase", "rbac_core.sql");
const CONFIG_TOML = path.join(ROOT, "supabase", "config.toml");

const SCAN_DIRS = [
  path.join(ROOT, "src"),
  path.join(ROOT, "lib"),
  path.join(ROOT, "components"),
];

type MigrationRecord = {
  file: string;
  timestamp: string;
  slug: string;
  tags: string[];
  tables: string[];
  policies: string[];
  functions: string[];
  triggers: string[];
  views: string[];
  indexes: string[];
  publications: string[];
  buckets: string[];
};

type Inventory = {
  generatedAt: string;
  migrationCount: number;
  migrations: MigrationRecord[];
  aggregates: {
    tables: string[];
    policies: string[];
    functions: string[];
    triggers: string[];
    views: string[];
    indexes: string[];
    publications: string[];
    buckets: string[];
    repairChains: { name: string; files: string[] }[];
  };
  config: {
    seedPaths: string[];
    seedFilesExist: { path: string; exists: boolean }[];
    edgeFunctionsDir: boolean;
    postgresMajor: string | null;
  };
  frontend: {
    serviceTables: string[];
    allTables: string[];
    rpcs: string[];
    storageBuckets: string[];
    realtimeTables: string[];
    typeTables: string[];
  };
  gaps: {
    serviceTablesWithoutRlsInMigrations: string[];
    migrationTablesWithoutFrontendRef: string[];
    frontendTablesWithoutMigration: string[];
    rpcsInDbNotInFrontend: string[];
    rpcsInFrontendNotInMigrations: string[];
  };
};

const TAG_PATTERNS: { tag: string; re: RegExp }[] = [
  { tag: "rbac", re: /\b(rbac_|user_effective_can|user_permissions)\b/i },
  { tag: "storage", re: /\b(storage\.|storage_|bucket)\b/i },
  { tag: "soft_delete", re: /\b(soft_delete|deleted_at)\b/i },
  { tag: "repair", re: /\b(_fix|_ensure|consolidation|hardening|purge)\b/i },
  { tag: "deprecated", re: /\b(DEPRECATED|deprecate)\b/i },
  { tag: "realtime", re: /\b(realtime|publication)\b/i },
  { tag: "auth", re: /\b(auth_|handle_new_user|profiles)\b/i },
];

const TABLE_RE = /\.from\(\s*["']([a-z_][a-z0-9_]*)["']/g;

const REPAIR_CHAINS: { name: string; match: RegExp }[] = [
  { name: "schema_core_duplicate", match: /officina_gestionale_(core|schema)/ },
  { name: "rbac_has_capability", match: /rbac_(capabilities|has_capability|operator|user_permissions)/ },
  { name: "soft_delete_lavorazioni", match: /lavorazioni_(soft_delete|deleted_at)/ },
  { name: "mezzo_delete_rpc", match: /mezzo_delete/ },
  { name: "lavorazioni_clienti_view", match: /lavorazioni_(stati_text|client)/ },
  { name: "supporto_deprecated", match: /(segnalazioni|support_notes|deprecate_supporto)/ },
  { name: "realtime_publication", match: /(gestionale_realtime|sync_realtime)/ },
  { name: "schema_consolidation", match: /schema_consolidation/ },
];

function readDirRecursive(dir: string, ext: string): string[] {
  if (!fs.existsSync(dir)) return [];
  const out: string[] = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (entry.name === "node_modules" || entry.name === ".next") continue;
      out.push(...readDirRecursive(full, ext));
    } else if (entry.name.endsWith(ext)) {
      out.push(full);
    }
  }
  return out;
}

function uniqueSorted(values: Iterable<string>): string[] {
  return [...new Set(values)].sort();
}

function parseMigrationFile(file: string): MigrationRecord {
  const content = fs.readFileSync(path.join(MIGRATIONS_DIR, file), "utf8");
  const base = file.replace(/\.sql$/, "");
  const timestamp = base.slice(0, 14);
  const slug = base.slice(15);

  const tables = uniqueSorted(
    [
      ...content.matchAll(/create\s+table\s+(?:if\s+not\s+exists\s+)?(?:public\.)?([a-z_][a-z0-9_]*)/gi),
      ...content.matchAll(/alter\s+table\s+(?:only\s+)?(?:public\.)?([a-z_][a-z0-9_]*)/gi),
    ].map((m) => m[1]),
  );

  const policies = uniqueSorted(
    [...content.matchAll(/create\s+policy\s+["']?([a-z_][a-z0-9_]*)["']?/gi)].map((m) => m[1]),
  );

  const functions = uniqueSorted(
    [
      ...content.matchAll(
        /create\s+(?:or\s+replace\s+)?function\s+(?:public\.)?([a-z_][a-z0-9_]*)\s*\(/gi,
      ),
    ].map((m) => m[1]),
  );

  const triggers = uniqueSorted(
    [...content.matchAll(/create\s+trigger\s+([a-z_][a-z0-9_]*)/gi)].map((m) => m[1]),
  );

  const views = uniqueSorted(
    [...content.matchAll(/create\s+(?:or\s+replace\s+)?view\s+(?:public\.)?([a-z_][a-z0-9_]*)/gi)].map(
      (m) => m[1],
    ),
  );

  const indexes = uniqueSorted(
    [...content.matchAll(/create\s+(?:unique\s+)?index\s+(?:if\s+not\s+exists\s+)?([a-z_][a-z0-9_]*)/gi)].map(
      (m) => m[1],
    ),
  );

  const publications = uniqueSorted(
    [
      ...content.matchAll(/alter\s+publication\s+([a-z_][a-z0-9_]*)/gi),
      ...content.matchAll(/publication\s+([a-z_][a-z0-9_]*)\s+add\s+table/gi),
    ].map((m) => m[1]),
  );

  const buckets = uniqueSorted(
    [
      ...content.matchAll(/insert\s+into\s+storage\.buckets[^)]*'([a-z_][a-z0-9_]*)'/gi),
      ...content.matchAll(/update\s+storage\.buckets\s+set[^;]*where\s+id\s*=\s*'([a-z_][a-z0-9_]*)'/gi),
    ].map((m) => m[1]),
  );

  const tags = TAG_PATTERNS.filter(({ re }) => re.test(content)).map(({ tag }) => tag);

  return { file, timestamp, slug, tags, tables, policies, functions, triggers, views, indexes, publications, buckets };
}

function collectServiceTables(): Set<string> {
  const tables = new Set<string>();
  const servicesDir = path.join(ROOT, "src", "services");
  if (!fs.existsSync(servicesDir)) return tables;
  for (const file of fs.readdirSync(servicesDir).filter((f) => f.endsWith(".service.ts"))) {
    const content = fs.readFileSync(path.join(servicesDir, file), "utf8");
    let m: RegExpExecArray | null;
    TABLE_RE.lastIndex = 0;
    while ((m = TABLE_RE.exec(content)) !== null) {
      tables.add(m[1]);
    }
    const constTable = content.match(/const\s+TABLE\s*=\s*["']([a-z_][a-z0-9_]*)["']/);
    if (constTable) tables.add(constTable[1]);
  }
  return tables;
}

function collectFromSource(re: RegExp, dirs: string[]): string[] {
  const found = new Set<string>();
  for (const dir of dirs) {
    for (const file of readDirRecursive(dir, ".ts")) {
      if (file.endsWith(".test.ts")) continue;
      const content = fs.readFileSync(file, "utf8");
      let m: RegExpExecArray | null;
      re.lastIndex = 0;
      while ((m = re.exec(content)) !== null) {
        found.add(m[1]);
      }
    }
    for (const file of readDirRecursive(dir, ".tsx")) {
      const content = fs.readFileSync(file, "utf8");
      let m: RegExpExecArray | null;
      re.lastIndex = 0;
      while ((m = re.exec(content)) !== null) {
        found.add(m[1]);
      }
    }
  }
  return uniqueSorted(found);
}

function parseConfigToml(): Inventory["config"] {
  const config = fs.existsSync(CONFIG_TOML) ? fs.readFileSync(CONFIG_TOML, "utf8") : "";
  const seedMatch = config.match(/sql_paths\s*=\s*\[([^\]]+)\]/);
  const seedPaths = seedMatch
    ? [...seedMatch[1].matchAll(/"([^"]+)"/g)].map((m) => m[1])
    : [];
  const pgMatch = config.match(/major_version\s*=\s*(\d+)/);
  const seedsResolved = seedPaths.map((p) => {
    const rel = p.startsWith("./") ? p.slice(2) : p;
    const abs = path.join(ROOT, "supabase", rel);
    const globDir = rel.includes("*") ? path.dirname(abs) : null;
    let exists = false;
    if (globDir && fs.existsSync(globDir)) {
      exists = fs.readdirSync(globDir).some((f) => f.endsWith(".sql"));
    } else {
      exists = fs.existsSync(abs);
    }
    return { path: p, exists };
  });

  return {
    seedPaths,
    seedFilesExist: seedsResolved,
    edgeFunctionsDir: fs.existsSync(path.join(ROOT, "supabase", "functions")),
    postgresMajor: pgMatch?.[1] ?? null,
  };
}

function extractTypeTables(): string[] {
  const typesFile = path.join(ROOT, "src", "types", "supabase-tables.ts");
  if (!fs.existsSync(typesFile)) return [];
  const content = fs.readFileSync(typesFile, "utf8");
  return uniqueSorted(
    [...content.matchAll(/Tabella\s+`([a-z_][a-z0-9_]*)`/gi)].map((m) => m[1]),
  );
}

function extractRealtimeTables(): string[] {
  const targets = path.join(ROOT, "src", "lib", "react-query", "invalidate-targets.ts");
  if (!fs.existsSync(targets)) return [];
  const content = fs.readFileSync(targets, "utf8");
  const block = content.match(/GESTIONALE_TABLE_QUERY_KEYS[^=]*=\s*\{([\s\S]+?)\}/);
  if (!block) return [];
  return uniqueSorted([...block[1].matchAll(/^\s*([a-z_][a-z0-9_]*)\s*:/gm)].map((m) => m[1]));
}

function buildInventory(): Inventory {
  const migrationFiles = fs
    .readdirSync(MIGRATIONS_DIR)
    .filter((f) => f.endsWith(".sql"))
    .sort();
  const migrations = migrationFiles.map(parseMigrationFile);

  const allTables = uniqueSorted(migrations.flatMap((m) => m.tables));
  const allPolicies = uniqueSorted(migrations.flatMap((m) => m.policies));
  const allFunctions = uniqueSorted(migrations.flatMap((m) => m.functions));
  if (fs.existsSync(RBAC_CORE)) {
    const rbacContent = fs.readFileSync(RBAC_CORE, "utf8");
    for (const m of rbacContent.matchAll(/create\s+(?:or\s+replace\s+)?function\s+(?:public\.)?([a-z_][a-z0-9_]*)\s*\(/gi)) {
      allFunctions.push(m[1]);
    }
  }

  const repairChains = REPAIR_CHAINS.map(({ name, match }) => ({
    name,
    files: migrations.filter((m) => match.test(m.file)).map((m) => m.file),
  })).filter((c) => c.files.length > 0);

  const serviceTables = uniqueSorted(collectServiceTables());
  const allFrontendTables = collectFromSource(/\.from\(\s*["']([a-z_][a-z0-9_]*)["']/g, SCAN_DIRS);
  const rpcs = collectFromSource(/\.rpc\(\s*["']([a-z_][a-z0-9_]*)["']/g, SCAN_DIRS);
  const storageBuckets = collectFromSource(/\.from\(\s*["']([a-z_][a-z0-9_]*)["']/g, SCAN_DIRS).filter((b) =>
    ["images", "documenti"].includes(b),
  );
  // storage uses .storage.from('bucket')
  const storageFrom = collectFromSource(/\.storage\.from\(\s*["']([a-z_][a-z0-9_]*)["']/g, SCAN_DIRS);
  const buckets = uniqueSorted([...storageBuckets, ...storageFrom]);

  const rlsTables = new Set<string>();
  for (const m of migrations) {
    for (const t of m.tables) rlsTables.add(t);
    for (const p of m.policies) {
      /* policies reference tables via ON public.table — re-scan raw */
    }
  }
  for (const file of migrationFiles) {
    const content = fs.readFileSync(path.join(MIGRATIONS_DIR, file), "utf8");
    for (const m of content.matchAll(/on\s+public\.([a-z_][a-z0-9_]*)/gi)) {
      rlsTables.add(m[1]);
    }
    for (const m of content.matchAll(/alter\s+table\s+(?:public\.)?([a-z_][a-z0-9_]*)\s+enable\s+row\s+level\s+security/gi)) {
      rlsTables.add(m[1]);
    }
  }

  const migrationTables = new Set(allTables);
  const allFunctionsUnique = uniqueSorted(allFunctions);

  const internalOnlyTables = new Set([
    "lavorazioni_codice_counters",
    "preventivi_lavorazione_numero_counters",
    "preventivi_manuali_numero_counters",
  ]);

  return {
    generatedAt: new Date().toISOString(),
    migrationCount: migrations.length,
    migrations,
    aggregates: {
      tables: allTables,
      policies: allPolicies,
      functions: allFunctionsUnique,
      triggers: uniqueSorted(migrations.flatMap((m) => m.triggers)),
      views: uniqueSorted(migrations.flatMap((m) => m.views)),
      indexes: uniqueSorted(migrations.flatMap((m) => m.indexes)),
      publications: uniqueSorted(migrations.flatMap((m) => m.publications)),
      buckets: uniqueSorted(migrations.flatMap((m) => m.buckets)),
      repairChains,
    },
    config: parseConfigToml(),
    frontend: {
      serviceTables,
      allTables: allFrontendTables,
      rpcs,
      storageBuckets: buckets,
      realtimeTables: extractRealtimeTables(),
      typeTables: extractTypeTables(),
    },
    gaps: {
      serviceTablesWithoutRlsInMigrations: serviceTables.filter((t) => !rlsTables.has(t)),
      migrationTablesWithoutFrontendRef: allTables.filter(
        (t) =>
          !allFrontendTables.includes(t) &&
          !serviceTables.includes(t) &&
          !internalOnlyTables.has(t),
      ),
      frontendTablesWithoutMigration: allFrontendTables.filter((t) => !migrationTables.has(t) && !rlsTables.has(t)),
      rpcsInDbNotInFrontend: allFunctionsUnique.filter(
        (f) =>
          !rpcs.includes(f) &&
          [
            "bulk_upsert_app_settings",
            "soft_delete_lavorazione",
            "soft_delete_dashboard_promemoria",
            "count_mezzo_dependencies",
            "delete_mezzo",
            "check_username_available",
            "resolve_auth_email_for_login",
            "archive_lavorazione_client_portal",
            "current_profile_role",
          ].includes(f) === false &&
          !f.startsWith("rbac_") &&
          !f.startsWith("set_") &&
          !f.startsWith("log_app_settings") &&
          f !== "handle_new_user",
      ),
      rpcsInFrontendNotInMigrations: rpcs.filter((r) => !allFunctionsUnique.includes(r)),
    },
  };
}

function printSummary(inv: Inventory): void {
  console.log("=== Supabase Audit Inventory ===\n");
  console.log(`Generated: ${inv.generatedAt}`);
  console.log(`Migrations: ${inv.migrationCount}`);
  console.log(`Tables (migration refs): ${inv.aggregates.tables.length}`);
  console.log(`Policies: ${inv.aggregates.policies.length}`);
  console.log(`Functions: ${inv.aggregates.functions.length}`);
  console.log(`Triggers: ${inv.aggregates.triggers.length}`);
  console.log(`Views: ${inv.aggregates.views.join(", ") || "(none)"}`);
  console.log(`Storage buckets: ${inv.aggregates.buckets.join(", ")}`);
  console.log(`Publications: ${inv.aggregates.publications.join(", ")}`);

  console.log("\n--- Config ---");
  console.log(`Postgres major: ${inv.config.postgresMajor ?? "?"}`);
  console.log(`Edge functions dir: ${inv.config.edgeFunctionsDir ? "yes" : "no"}`);
  for (const s of inv.config.seedFilesExist) {
    console.log(`Seed ${s.path}: ${s.exists ? "OK" : "MISSING"}`);
  }

  console.log("\n--- Frontend ---");
  console.log(`Service tables (${inv.frontend.serviceTables.length}): ${inv.frontend.serviceTables.join(", ")}`);
  console.log(`RPCs (${inv.frontend.rpcs.length}): ${inv.frontend.rpcs.join(", ")}`);
  console.log(`Realtime tables: ${inv.frontend.realtimeTables.join(", ")}`);

  console.log("\n--- Repair chains ---");
  for (const c of inv.aggregates.repairChains) {
    console.log(`  ${c.name}: ${c.files.length} migration(s)`);
  }

  console.log("\n--- Gaps ---");
  if (inv.gaps.serviceTablesWithoutRlsInMigrations.length === 0) {
    console.log("OK: all service tables have RLS refs in migrations");
  } else {
    console.log(`Service tables missing RLS in migrations: ${inv.gaps.serviceTablesWithoutRlsInMigrations.join(", ")}`);
  }
  if (inv.gaps.rpcsInFrontendNotInMigrations.length > 0) {
    console.log(`RPCs in frontend not in migrations: ${inv.gaps.rpcsInFrontendNotInMigrations.join(", ")}`);
  }
  console.log(
    `Migration tables without frontend ref (${inv.gaps.migrationTablesWithoutFrontendRef.length}): ${inv.gaps.migrationTablesWithoutFrontendRef.slice(0, 15).join(", ")}${inv.gaps.migrationTablesWithoutFrontendRef.length > 15 ? "…" : ""}`,
  );

  const hasErrors =
    inv.gaps.serviceTablesWithoutRlsInMigrations.length > 0 ||
    inv.gaps.rpcsInFrontendNotInMigrations.length > 0 ||
    inv.config.seedFilesExist.some((s) => !s.exists);

  process.exit(hasErrors ? 1 : 0);
}

function main(): void {
  const inv = buildInventory();
  const jsonMode = process.argv.includes("--json");
  if (jsonMode) {
    const outPath = path.join(ROOT, "docs", ".supabase-audit-inventory.json");
    fs.mkdirSync(path.dirname(outPath), { recursive: true });
    fs.writeFileSync(outPath, JSON.stringify(inv, null, 2), "utf8");
    console.log(`Wrote ${outPath}`);
    process.exit(0);
  }
  printSummary(inv);
}

main();

