"use client";

import { useCallback, useMemo, useSyncExternalStore } from "react";
import { useAuth } from "@/context/auth-context";
import { isStaffInboxEligible } from "@/lib/notifications/staff-inbox-eligible";
import {
  clearMagazzinoNotifications,
  countReadAdminNotifications,
  emptyAdminNotificationStore,
  getUnreadCount,
  isNotificationUnread,
  listNotifications,
  loadAdminNotificationStore,
  markAllAdminNotificationsRead,
  markAdminNotificationRead,
  removeAdminNotification,
  removeReadAdminNotifications,
  subscribeAdminNotificationStore,
  type AdminNotificationStoreState,
} from "@/lib/lavorazioni/admin-notification-store";
import type { AdminDashboardNotification } from "@/lib/notifications/admin-dashboard-notifications";
import { useEffectivePermissions } from "@/src/lib/runtime/truth-layer/use-effective-permissions";
import { useNotificationsV2Mode } from "@/src/hooks/gestionale/use-notifications-v2-mode";

export function useAdminNotificationStore() {
  const { user } = useAuth();
  const { snapshot, isLoading: permsLoading } = useEffectivePermissions();
  const { readsDb, isLoading: flagLoading } = useNotificationsV2Mode();
  const userId = user?.id ?? "";
  const staffEligible =
    !permsLoading &&
    isStaffInboxEligible(snapshot ? { ruolo: snapshot.role } : user, snapshot?.rbacContext);
  const enabled = staffEligible && !flagLoading && !readsDb && userId.length > 0;

  // SSR/hydration: mai leggere localStorage nel render iniziale (vedi docs/bootstrap-hydration.md).
  const state = useSyncExternalStore(
    (onStoreChange) => {
      if (!enabled) return () => {};
      return subscribeAdminNotificationStore((changedUserId) => {
        if (changedUserId === userId) onStoreChange();
      });
    },
    () => (enabled ? loadAdminNotificationStore(userId) : emptyAdminNotificationStore()),
    () => emptyAdminNotificationStore(),
  );

  const notifications = useMemo(() => (enabled ? listNotifications(state) : []), [enabled, state]);
  const unreadCount = useMemo(() => (enabled ? getUnreadCount(state) : 0), [enabled, state]);
  const readCount = useMemo(() => (enabled ? countReadAdminNotifications(state) : 0), [enabled, state]);

  const markAllRead = useCallback(() => {
    if (!enabled) return;
    markAllAdminNotificationsRead(userId);
  }, [enabled, userId]);

  const markNotificationRead = useCallback(
    (notification: AdminDashboardNotification) => {
      if (!enabled) return;
      markAdminNotificationRead(userId, notification);
    },
    [enabled, userId],
  );

  const dismissNotification = useCallback(
    (notification: AdminDashboardNotification) => {
      if (!enabled) return;
      removeAdminNotification(userId, notification);
    },
    [enabled, userId],
  );

  const removeReadNotifications = useCallback(() => {
    if (!enabled) return;
    removeReadAdminNotifications(userId);
  }, [enabled, userId]);

  const clearMagazzinoNotifs = useCallback(() => {
    if (!enabled) return;
    clearMagazzinoNotifications(userId);
  }, [enabled, userId]);

  const isUnread = useCallback(
    (notification: AdminDashboardNotification) =>
      enabled ? isNotificationUnread(state, notification) : false,
    [enabled, state],
  );

  return {
    notifications,
    unreadCount,
    readCount,
    markAllRead,
    markNotificationRead,
    dismissNotification,
    removeReadNotifications,
    clearMagazzinoNotifications: clearMagazzinoNotifs,
    isUnread,
    canReadDashboard: enabled,
    permLoading: permsLoading || flagLoading,
    enabled,
  };
}

export type { AdminDashboardNotification };

"use client";

import { useQuery, type UseQueryResult } from "@tanstack/react-query";
import { useAuth } from "@/context/auth-context";
import { useRbac } from "@/src/hooks/use-rbac";
import { QK } from "@/src/lib/react-query/invalidate-related";
import {
  appSettingsAuditEntry,
  type AppSettingsAuditListParams,
} from "@/lib/domain/app-settings-audit-entry";
import type { AppSettingsAuditRow } from "@/src/types/supabase-tables";

/**
 * Pronto per una futura pagina log admin: esegue fetch solo se `ruolo === 'admin'`.
 */
export function useAppSettingsAuditQuery(
  params: AppSettingsAuditListParams = {},
): UseQueryResult<AppSettingsAuditRow[], Error> {
  const { user } = useAuth();
  const rbac = useRbac();
  const limit = params.limit ?? 200;
  const module = params.module ?? "";
  const key = params.key ?? "";

  return useQuery({
    queryKey: [...QK.settingsAudit, module, key, limit] as const,
    queryFn: async () => {
      const r = await appSettingsAuditEntry.list({ ...params, limit });
      if (!r.success) throw new Error(r.error ?? "Errore lettura audit impostazioni");
      return r.data ?? [];
    },
    enabled: !!user?.id && rbac.canWritePage("sicurezza"),
    staleTime: 60_000,
    gcTime: 300_000,
  });
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useSyncExternalStore } from "react";
import { useQueryClient } from "@tanstack/react-query";
import {
  acquireDebouncedScortaSubscriber,
  decrementDebouncedScorta,
  getDebouncedScortaSnapshot,
  getDebouncedScortaStoreVersion,
  incrementDebouncedScorta,
  releaseDebouncedScortaSubscriber,
  setDebouncedScortaQuantity,
  subscribeDebouncedScorta,
  syncDebouncedScortaServerQuantity,
  updateDebouncedScortaBindings,
  type DebouncedScortaCallbacks,
  type DebouncedScortaCommitDeps,
  type DebouncedScortaSnapshot,
} from "@/lib/magazzino/debounced-scorta-store";
import { getStockEntity } from "@/lib/magazzino/stock-entity-cache";
import { useStockAdjustMutation, useStockJournalVersion } from "@/src/hooks/gestionale/use-stock-adjust-mutation";

export type UseDebouncedInventoryQuantityOptions = {
  ricambioId: string;
  ricambioLabel: string;
  /** Scorta dalla riga lista quando entity cache non ancora popolata. */
  fallbackScorta?: number;
  contaStatistiche: boolean;
  enabled?: boolean;
  debounceMs?: number;
  onPersistLog: (logId: string, prima: number, dopo: number) => void;
  onRemoveLog: (logId: string) => void;
  onCommitSuccess?: () => void;
  onCommitError: (error: string) => void;
};

export type UseDebouncedInventoryQuantityResult = {
  displayQuantity: number;
  isDirty: boolean;
  isCommitting: boolean;
  showSuccess: boolean;
  increment: () => void;
  decrement: () => void;
  setQuantity: (target: number) => void;
};

function resolveServerQuantity(
  qc: ReturnType<typeof useQueryClient>,
  ricambioId: string,
  fallbackScorta: number,
): number {
  const entity = getStockEntity(qc, ricambioId);
  if (entity) return entity.quantita;
  return Math.max(0, Math.round(fallbackScorta));
}

export function useDebouncedInventoryQuantity(
  opts: UseDebouncedInventoryQuantityOptions,
): UseDebouncedInventoryQuantityResult {
  const qc = useQueryClient();
  const { adjustDelta } = useStockAdjustMutation();
  useStockJournalVersion();

  const {
    ricambioId,
    ricambioLabel,
    fallbackScorta = 0,
    contaStatistiche,
    enabled = true,
    debounceMs,
    onPersistLog,
    onRemoveLog,
    onCommitSuccess,
    onCommitError,
  } = opts;

  const id = ricambioId.trim();
  const serverQuantity = resolveServerQuantity(qc, id, fallbackScorta);

  const callbacksRef = useRef<DebouncedScortaCallbacks>({
    onPersistLog,
    onRemoveLog,
    onCommitSuccess,
    onCommitError,
  });
  callbacksRef.current = { onPersistLog, onRemoveLog, onCommitSuccess, onCommitError };

  const commitDeps = useMemo<DebouncedScortaCommitDeps>(
    () => ({ qc, adjustDelta }),
    [qc, adjustDelta],
  );

  const fallbackSnapshotRef = useRef<DebouncedScortaSnapshot | null>(null);

  const subscribe = useCallback(
    (cb: () => void) => subscribeDebouncedScorta(id, cb),
    [id],
  );

  const getSnapshot = useCallback(() => {
    void getDebouncedScortaStoreVersion();
    const snap = getDebouncedScortaSnapshot(id);
    if (snap) return snap;
    const q = serverQuantity;
    const cached = fallbackSnapshotRef.current;
    if (
      cached &&
      cached.displayQuantity === q &&
      cached.serverQuantity === q &&
      !cached.isDirty &&
      !cached.isCommitting &&
      !cached.showSuccess
    ) {
      return cached;
    }
    const next: DebouncedScortaSnapshot = {
      displayQuantity: q,
      serverQuantity: q,
      isDirty: false,
      isCommitting: false,
      showSuccess: false,
    };
    fallbackSnapshotRef.current = next;
    return next;
  }, [id, serverQuantity]);

  const state = useSyncExternalStore(subscribe, getSnapshot, getSnapshot);

  useEffect(() => {
    acquireDebouncedScortaSubscriber(id, serverQuantity, {
      ricambioLabel,
      contaStatistiche,
      debounceMs,
      enabled,
      callbacks: {
        onPersistLog: (...args) => callbacksRef.current.onPersistLog(...args),
        onRemoveLog: (...args) => callbacksRef.current.onRemoveLog(...args),
        onCommitSuccess: () => callbacksRef.current.onCommitSuccess?.(),
        onCommitError: (err) => callbacksRef.current.onCommitError(err),
      },
      commitDeps,
    });
    return () => releaseDebouncedScortaSubscriber(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- acquire once per id; bindings via update effect
  }, [id]);

  useEffect(() => {
    updateDebouncedScortaBindings(id, {
      ricambioLabel,
      contaStatistiche,
      debounceMs,
      enabled,
      callbacks: {
        onPersistLog: (...args) => callbacksRef.current.onPersistLog(...args),
        onRemoveLog: (...args) => callbacksRef.current.onRemoveLog(...args),
        onCommitSuccess: () => callbacksRef.current.onCommitSuccess?.(),
        onCommitError: (err) => callbacksRef.current.onCommitError(err),
      },
      commitDeps,
    });
  }, [id, ricambioLabel, contaStatistiche, debounceMs, enabled, commitDeps]);

  useEffect(() => {
    syncDebouncedScortaServerQuantity(id, serverQuantity);
  }, [id, serverQuantity]);

  const increment = useCallback(() => incrementDebouncedScorta(id), [id]);
  const decrement = useCallback(() => decrementDebouncedScorta(id), [id]);
  const setQuantity = useCallback((target: number) => setDebouncedScortaQuantity(id, target), [id]);

  return {
    displayQuantity: state.displayQuantity,
    isDirty: state.isDirty,
    isCommitting: state.isCommitting,
    showSuccess: state.showSuccess,
    increment,
    decrement,
    setQuantity,
  };
}

"use client";

/**
 * Percorso legacy emergenza — frozen, kill switch only.
 * @deprecated Usare stock-pipeline-execute quando v4 attivo.
 */

import { useCallback, useRef } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { QK } from "@/src/lib/react-query/query-keys";
import { stockAdjustFetch, type StockAdjustRequest, type StockAdjustResponse } from "@/lib/magazzino/stock-adjust-client";
import {
  getStockEntity,
  mergeStockEntity,
} from "@/lib/magazzino/stock-entity-cache";
import { applyOptimisticStockAdjust } from "@/lib/magazzino/apply-optimistic-stock-adjust";
import { markRecentLocalGestionaleMutation } from "@/lib/sync/recent-local-mutation";
import { scheduleReportBroadcastRefresh } from "@/lib/report/report-refresh";
import { movimentiListQueryKey } from "@/lib/render/query-key-factory";
import type {
  StockAdjustMutationInput,
  StockAdjustMutationContext,
  StockAdjustMutationOutcome,
} from "@/src/hooks/gestionale/use-stock-adjust-mutation-types";

const MAX_CONFLICT_RETRIES = 2;

async function invalidateStockSideEffects(
  qc: ReturnType<typeof useQueryClient>,
  ricambioId: string,
): Promise<void> {
  void qc.invalidateQueries({ queryKey: movimentiListQueryKey({ ricambio_id: ricambioId }) });
  void qc.invalidateQueries({ queryKey: ["movimenti", "ricambio", ricambioId] });
  scheduleReportBroadcastRefresh(qc);
  void qc.invalidateQueries({ queryKey: ["dashboard", "health-score"] });
}

export function useEmergencyLegacyStockAdjustMutation() {
  const qc = useQueryClient();
  const burstQueues = useRef(new Map<string, Promise<unknown>>());
  const pendingCtxRef = useRef(new Map<string, StockAdjustMutationContext[]>());

  const mutation = useMutation({
    mutationFn: async (input: StockAdjustMutationInput): Promise<StockAdjustMutationOutcome> => {
      const operationId = input.operationId ?? crypto.randomUUID();
      let expectedVersion = getStockEntity(qc, input.ricambioId)?.stockVersion ?? 0;
      let lastError = "Aggiornamento stock non riuscito";

      for (let attempt = 0; attempt <= MAX_CONFLICT_RETRIES; attempt++) {
        const result = await stockAdjustFetch({
          ...input,
          expectedVersion,
          operationId,
        });

        if (result.ok) return { ok: true, data: { ...result.data, operationId } };

        if (result.status === 409 && result.conflict?.current) {
          expectedVersion = result.conflict.current.stockVersion;
          mergeStockEntity(
            qc,
            {
              ricambioId: input.ricambioId,
              quantita: result.conflict.current.quantita,
              stockVersion: result.conflict.current.stockVersion,
              lastOperationId: null,
            },
            "refetch",
          );
          lastError = result.error;
          continue;
        }

        return { ok: false, error: result.error };
      }

      return { ok: false, error: lastError };
    },
    onMutate: async (input): Promise<StockAdjustMutationContext> => {
      void qc.cancelQueries({ queryKey: QK.magazzino });
      const stack = pendingCtxRef.current.get(input.ricambioId);
      const ctx = stack?.shift();
      if (ctx) return ctx;

      const operationId = input.operationId ?? crypto.randomUUID();
      const previous = applyOptimisticStockAdjust(qc, { ...input, operationId });
      return { previous, operationId };
    },
    onSuccess: (outcome, _input, ctx) => {
      if (!outcome.ok) {
        if (ctx?.previous) {
          mergeStockEntity(qc, ctx.previous, "rejected", { operationId: ctx.operationId });
        }
        return;
      }
      const data = outcome.data;
      mergeStockEntity(
        qc,
        {
          ricambioId: data.ricambioId,
          quantita: data.quantita,
          stockVersion: data.stockVersion,
          lastOperationId: data.operationId,
        },
        "mutation",
        {
          operationId: data.operationId,
          receivedVersion: data.stockVersion,
        },
      );
      markRecentLocalGestionaleMutation(["magazzino_ricambi", "movimenti_ricambi"], data.ricambioId);
      void qc.invalidateQueries({ queryKey: QK.log, refetchType: "active" });
      void invalidateStockSideEffects(qc, data.ricambioId);
    },
    onError: (_err, _input, ctx) => {
      if (ctx?.previous) {
        mergeStockEntity(qc, ctx.previous, "rejected", { operationId: ctx.operationId });
      }
    },
  });

  const adjustDelta = useCallback(
    (input: StockAdjustMutationInput): Promise<StockAdjustMutationOutcome> => {
      const ricambioId = input.ricambioId;
      const operationId = input.operationId ?? crypto.randomUUID();
      const previous = applyOptimisticStockAdjust(qc, { ...input, operationId });
      const stack = pendingCtxRef.current.get(ricambioId) ?? [];
      stack.push({ previous, operationId });
      pendingCtxRef.current.set(ricambioId, stack);

      const prev = burstQueues.current.get(ricambioId) ?? Promise.resolve();
      const next: Promise<StockAdjustMutationOutcome> = prev
        .catch(() => ({ ok: false as const, error: "Aggiornamento stock non riuscito" }))
        .then(() => mutation.mutateAsync({ ...input, operationId }));
      burstQueues.current.set(
        ricambioId,
        next.finally(() => {
          if (burstQueues.current.get(ricambioId) === next) {
            burstQueues.current.delete(ricambioId);
          }
        }),
      );
      return next;
    },
    [mutation, qc],
  );

  return {
    ...mutation,
    adjustDelta,
    isAdjusting: mutation.isPending,
    isPipelineV4: false as const,
  };
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useQueryClient } from "@tanstack/react-query";
import { useDipendentiTimesheetDerived } from "@/lib/dipendenti/use-dipendenti-timesheet-derived";
import type {
  DipendenteTimesheetEmployeeRow,
  DipendenteTimesheetEntryRow,
  TimesheetEntryUpsert,
  TimesheetMonthKey,
} from "@/lib/dipendenti/types";
import {
  buildPeriodDays,
  monthKeyFromDate,
  resolvePeriodRange,
  shiftMonthKey,
  type TimesheetPeriodMode,
} from "@/lib/dipendenti/timesheet-month";
import { RBAC_DENIED_MESSAGE } from "@/lib/rbac";
import type { DipendenteRecord } from "@/lib/dipendenti/dipendente-record";
import { getActiveDipendentiRecords } from "@/lib/dipendenti/dipendente-record";
import { useDipendentiRecords, useTipiAssenza } from "@/src/hooks/use-global-options";
import { useServiceMutation } from "@/src/hooks/use-service-mutation";
import { useServiceQuery } from "@/src/hooks/use-service-query";
import { usePwaUpdateGuard } from "@/lib/pwa/pwa-update-guard";
import { QK } from "@/src/lib/react-query/query-keys";
import { dipendentiTimesheetEntry } from "@/lib/domain/dipendenti-timesheet-entry";
import {
  dispatchTimesheetEmployeesChanged,
  dispatchTimesheetEntryChanged,
} from "@/lib/dipendenti/dipendenti-timesheet-sync-dispatch";
import {
  dipendentiEntriesQueryKey,
  useDipendentiEmployeesQuery,
  useDipendentiEntriesRangeQuery,
  useDipendentiMonthKeysQuery,
} from "@/src/hooks/gestionale/use-dipendenti-timesheet-queries";

const DEBOUNCE_MS = 400;

export type TimesheetLoadPhase = "settings" | "registry" | "entries" | "ready" | "error";
export type TimesheetErrorKind = "rbac" | "network" | "sync" | "unknown";

export type UseDipendentiTimesheetOptions = {
  monthKey: TimesheetMonthKey;
  periodMode?: TimesheetPeriodMode;
  weekAnchor?: string;
  dayDate?: string;
};

function normalizeOptions(
  monthKeyOrOptions: TimesheetMonthKey | UseDipendentiTimesheetOptions,
): Required<UseDipendentiTimesheetOptions> {
  if (typeof monthKeyOrOptions === "string") {
    return { monthKey: monthKeyOrOptions, periodMode: "month", weekAnchor: "", dayDate: "" };
  }
  return {
    monthKey: monthKeyOrOptions.monthKey,
    periodMode: monthKeyOrOptions.periodMode ?? "month",
    weekAnchor: monthKeyOrOptions.weekAnchor ?? "",
    dayDate: monthKeyOrOptions.dayDate ?? "",
  };
}

function classifyError(message: string | null): TimesheetErrorKind {
  if (!message) return "unknown";
  if (message === RBAC_DENIED_MESSAGE || /permess/i.test(message)) return "rbac";
  if (/fetch|network|failed/i.test(message)) return "network";
  return "unknown";
}

function queryErrorMessage(error: Error | null): string | null {
  if (!error) return null;
  return error.message || "Errore di caricamento.";
}

function canSyncFromDipendenti(dipendentiOpts: {
  source: "app_settings" | "fallback" | "unavailable";
  isLoading: boolean;
  records: readonly DipendenteRecord[];
}): boolean {
  return dipendentiOpts.source === "app_settings" && !dipendentiOpts.isLoading && dipendentiOpts.records.length > 0;
}

export function useDipendentiTimesheet(
  monthKeyOrOptions: TimesheetMonthKey | UseDipendentiTimesheetOptions,
) {
  const { monthKey, periodMode, weekAnchor, dayDate } = normalizeOptions(monthKeyOrOptions);
  const queryClient = useQueryClient();
  const dipendentiOpts = useDipendentiRecords();
  const tipiOpts = useTipiAssenza();
  const [saveStatus, setSaveStatus] = useState<"idle" | "pending" | "saved" | "error">("idle");
  const [syncError, setSyncError] = useState<string | null>(null);
  /** Solo durante mutateAsync sync (non include refetch post-invalidate). */
  const [syncInProgress, setSyncInProgress] = useState(false);
  const pendingRef = useRef<Map<string, ReturnType<typeof setTimeout>>>(new Map());
  const pendingInputsRef = useRef<Map<string, TimesheetEntryUpsert>>(new Map());
  const savedTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const autoSyncKeyRef = useRef<string | null>(null);
  usePwaUpdateGuard(
    saveStatus === "pending" || syncInProgress,
    "Attendi il completamento del salvataggio del timesheet prima di aggiornare l'app.",
  );

  const periodRange = useMemo(
    () =>
      resolvePeriodRange(
        periodMode,
        monthKey,
        weekAnchor || undefined,
        dayDate || undefined,
      ),
    [periodMode, monthKey, weekAnchor, dayDate],
  );

  const periodDays = useMemo(
    () => buildPeriodDays(periodMode, monthKey, weekAnchor || undefined, dayDate || undefined),
    [periodMode, monthKey, weekAnchor, dayDate],
  );

  const previousMonthKey = useMemo(() => shiftMonthKey(monthKey, -1), [monthKey]);

  const dipendentiReady = dipendentiOpts.source === "app_settings" && !dipendentiOpts.isLoading;
  const realDipendentiRecords = useMemo(
    () => (dipendentiReady ? dipendentiOpts.records : []),
    [dipendentiReady, dipendentiOpts.records],
  );

  const currentDipendentiIds = useMemo(
    () => new Set(getActiveDipendentiRecords(realDipendentiRecords).map((r) => r.id)),
    [realDipendentiRecords],
  );

  const employeesQuery = useDipendentiEmployeesQuery();

  const registryReady = employeesQuery.isSuccess && !employeesQuery.isError;

  const entriesQueryKey = dipendentiEntriesQueryKey(periodRange.from, periodRange.to);

  const entriesQuery = useDipendentiEntriesRangeQuery(
    periodRange.from,
    periodRange.to,
    registryReady && dipendentiReady,
    { expectedServerKey: periodMode === "month" ? entriesQueryKey : undefined },
  );

  const previousMonthQuery = useServiceQuery(
    [...QK.dipendentiTimesheetEntries, "prev", previousMonthKey] as const,
    () => dipendentiTimesheetEntry.listEntriesForMonth(previousMonthKey),
    { enabled: registryReady && dipendentiReady && periodMode === "month" },
  );

  const monthKeysWithDataQuery = useDipendentiMonthKeysQuery(registryReady);

  const syncMutation = useServiceMutation(
    (records: readonly DipendenteRecord[]) =>
      dipendentiTimesheetEntry.syncFromAddettiRecords(records),
    {
      onSuccess: (rows) => {
        queryClient.setQueryData(QK.dipendentiTimesheetEmployees, rows);
        dispatchTimesheetEmployeesChanged(queryClient);
      },
    },
  );

  const runSyncFromDipendenti = useCallback(
    async (records: readonly DipendenteRecord[]) => {
      setSyncInProgress(true);
      try {
        return await syncMutation.mutateAsync(records);
      } finally {
        setSyncInProgress(false);
      }
    },
    [syncMutation],
  );

  const bootstrapEmployees = useCallback(async () => {
    if (dipendentiOpts.isLoading) {
      setSyncError("Attendere il caricamento dei dipendenti dalle Impostazioni.");
      return false;
    }
    if (dipendentiOpts.source !== "app_settings") {
      setSyncError("Impossibile sincronizzare: dipendenti non disponibili dalle Impostazioni.");
      return false;
    }
    if (!dipendentiOpts.records.length) {
      setSyncError("Nessun dipendente configurato in Impostazioni.");
      return false;
    }
    setSyncError(null);
    try {
      await runSyncFromDipendenti(dipendentiOpts.records);
      return true;
    } catch (e) {
      const msg = e instanceof Error ? e.message : "Impossibile inizializzare il registro dipendenti.";
      setSyncError(msg);
      return false;
    }
  }, [dipendentiOpts.isLoading, dipendentiOpts.records, dipendentiOpts.source, runSyncFromDipendenti]);

  const dipendentiRecordsSyncKey = useMemo(
    () =>
      dipendentiOpts.records
        .map((r) => `${r.id}|${r.nome}|${r.cognome ?? ""}|${r.employeeType}|${r.attivo}`)
        .join(";"),
    [dipendentiOpts.records],
  );

  useEffect(() => {
    if (!canSyncFromDipendenti(dipendentiOpts)) return;
    if (autoSyncKeyRef.current === dipendentiRecordsSyncKey) return;
    autoSyncKeyRef.current = dipendentiRecordsSyncKey;
    void runSyncFromDipendenti(dipendentiOpts.records).catch((e: unknown) => {
      const msg = e instanceof Error ? e.message : "Sincronizzazione dipendenti non riuscita.";
      setSyncError(msg);
    });
  }, [dipendentiOpts, dipendentiRecordsSyncKey, runSyncFromDipendenti]);

  const upsertMutation = useServiceMutation(
    (input: TimesheetEntryUpsert) =>
      dipendentiTimesheetEntry.upsertEntry(input, tipiOpts.tipi),
    {
      onMutate: () => {
        setSaveStatus("pending");
        if (savedTimerRef.current) clearTimeout(savedTimerRef.current);
      },
      onSuccess: (row, input) => {
        if (savedTimerRef.current) clearTimeout(savedTimerRef.current);
        const updateList = (key: readonly unknown[]) => {
          queryClient.setQueryData<DipendenteTimesheetEntryRow[]>(key, (prev) => {
            const list = prev ?? [];
            if (!row) {
              return list.filter(
                (e) => !(e.dipendente_id === input.dipendenteId && e.work_date === input.workDate),
              );
            }
            const idx = list.findIndex(
              (e) => e.dipendente_id === row.dipendente_id && e.work_date === row.work_date,
            );
            if (idx >= 0) {
              const next = [...list];
              next[idx] = row;
              return next;
            }
            return [...list, row];
          });
        };
        updateList(entriesQueryKey);
        if (periodMode === "month") {
          updateList([...QK.dipendentiTimesheetEntries, "prev", previousMonthKey]);
        }
        if (row) {
          dispatchTimesheetEntryChanged(queryClient, row.id, "entity_updated");
        } else {
          dispatchTimesheetEntryChanged(
            queryClient,
            `${input.dipendenteId}|${input.workDate}`,
            "entity_deleted",
          );
        }
        setSaveStatus("saved");
        savedTimerRef.current = setTimeout(() => setSaveStatus("idle"), 2000);
      },
      onError: () => setSaveStatus("error"),
    },
  );

  const flushPending = useCallback(() => {
    for (const t of pendingRef.current.values()) clearTimeout(t);
    pendingRef.current.clear();
    for (const input of pendingInputsRef.current.values()) {
      void upsertMutation.mutateAsync(input);
    }
    pendingInputsRef.current.clear();
  }, [upsertMutation]);

  useEffect(() => {
    const onLeave = () => {
      for (const t of pendingRef.current.values()) clearTimeout(t);
      pendingRef.current.clear();
      for (const input of pendingInputsRef.current.values()) {
        void upsertMutation.mutate(input);
      }
      pendingInputsRef.current.clear();
    };
    window.addEventListener("beforeunload", onLeave);
    window.addEventListener("pagehide", onLeave);
    return () => {
      window.removeEventListener("beforeunload", onLeave);
      window.removeEventListener("pagehide", onLeave);
    };
  }, [upsertMutation]);

  useEffect(
    () => () => {
      flushPending();
      if (savedTimerRef.current) clearTimeout(savedTimerRef.current);
    },
    [flushPending],
  );

  const scheduleSave = useCallback(
    (input: TimesheetEntryUpsert) => {
      const key = `${input.dipendenteId}|${input.workDate}`;
      pendingInputsRef.current.set(key, input);
      const existing = pendingRef.current.get(key);
      if (existing) clearTimeout(existing);
      const timer = setTimeout(() => {
        pendingRef.current.delete(key);
        pendingInputsRef.current.delete(key);
        void upsertMutation.mutateAsync(input);
      }, DEBOUNCE_MS);
      pendingRef.current.set(key, timer);
    },
    [upsertMutation],
  );

  const saveNow = useCallback(
    (input: TimesheetEntryUpsert) => {
      const key = `${input.dipendenteId}|${input.workDate}`;
      const existing = pendingRef.current.get(key);
      if (existing) clearTimeout(existing);
      pendingRef.current.delete(key);
      pendingInputsRef.current.delete(key);
      return upsertMutation.mutateAsync(input);
    },
    [upsertMutation],
  );

  const employees = (employeesQuery.data ?? []) as DipendenteTimesheetEmployeeRow[];

  const { displayEmployees, employeeIdsWithEntriesInPeriod, getCellValue } = useDipendentiTimesheetDerived(
    employees,
    entriesQuery.data ?? [],
    realDipendentiRecords,
    dipendentiReady,
    currentDipendentiIds,
  );

  const employeesError = employeesQuery.isError ? queryErrorMessage(employeesQuery.error) : null;
  const entriesError = entriesQuery.isError ? queryErrorMessage(entriesQuery.error) : null;
  const entriesDegraded = entriesError != null && Boolean(entriesQuery.data?.length);

  const loadPhase = useMemo((): TimesheetLoadPhase => {
    if (employeesError) return "error";
    if (!dipendentiReady || dipendentiOpts.isLoading) return "settings";
    if (employeesQuery.isLoading) return "registry";
    if (entriesQuery.isLoading && entriesQuery.data == null) return "entries";
    if (entriesError && entriesQuery.data == null) return "error";
    return "ready";
  }, [
    employeesError,
    entriesError,
    entriesQuery.data,
    dipendentiReady,
    dipendentiOpts.isLoading,
    employeesQuery.isLoading,
    entriesQuery.isLoading,
  ]);

  const errorKind = useMemo((): TimesheetErrorKind | null => {
    if (syncError) return "sync";
    const msg = employeesError ?? entriesError;
    if (!msg) return null;
    return classifyError(msg);
  }, [syncError, employeesError, entriesError]);

  const isInitialLoading = loadPhase !== "ready" && loadPhase !== "error";
  const isSyncing = syncInProgress;
  /** Sync in background dopo il primo caricamento (es. addetti aggiornati in Impostazioni). */
  const showBackgroundSyncInToolbar = syncInProgress && loadPhase === "ready";

  return {
    monthKey,
    periodMode,
    periodRange,
    periodDays,
    weekAnchor,
    dayDate,
    employees,
    displayEmployees,
    employeeIdsWithEntriesInPeriod,
    entries: entriesQuery.data ?? [],
    previousMonthEntries: previousMonthQuery.data ?? [],
    tipiAssenza: tipiOpts.tipi,
    dipendentiRecords: realDipendentiRecords,
    dipendentiReady,
    dipendentiSource: dipendentiOpts.source,
    hasRealDipendenti: dipendentiReady && realDipendentiRecords.length > 0,
    loadPhase,
    errorKind,
    isInitialLoading,
    isSyncing,
    showBackgroundSyncInToolbar,
    employeesError,
    entriesError,
    entriesDegraded,
    syncError,
    bootstrapEmployees,
    monthKeysWithData: monthKeysWithDataQuery.data ?? [],
    refetch: () => {
      void employeesQuery.refetch();
      void entriesQuery.refetch();
      void previousMonthQuery.refetch();
      void monthKeysWithDataQuery.refetch();
    },
    refetchEmployees: () => {
      void employeesQuery.refetch();
    },
    refetchEntries: () => {
      void entriesQuery.refetch();
    },
    getCellValue,
    scheduleSave,
    saveNow,
    saveStatus,
    canWrite: !upsertMutation.isPending,
    upsertPending: upsertMutation.isPending,
  };
}

export function useDefaultTimesheetMonthKey(): TimesheetMonthKey {
  const [key, _setKey] = useState<TimesheetMonthKey>(() => monthKeyFromDate(new Date()));
  return key;
}

export type { DipendenteTimesheetEmployeeRow, DipendenteTimesheetEntryRow, TimesheetEntryUpsert, TimesheetPeriodMode };

