            ]
          : []),
        ...(dto.headerKpi.fatturazione
          ? [
              seedPrefetchedData(
                qc,
                fatturazioneListQueryKey(),
                dto.headerKpi.fatturazione,
                GESTIONALE_SEMI_STALE_MS,
                GESTIONALE_SEMI_GC_MS,
              ),
            ]
          : []),
        ...(dto.headerKpi.movimenti
          ? [
              seedPrefetchedData(
                qc,
                movimentiListQueryKey(null),
