    }
    case "lavorazioni": {
      const lav = resolveInitialLoad({ scopeKey: "lavorazioni.list.attive" });
      const archivioCountKey = lavorazioniListCountQueryKey(LAVORAZIONI_CHIUSE_COUNT_FILTERS);
      const dto = await fetchLavorazioniPageDTOServer();
      await Promise.all([
        seedPrefetchedData(
