"use client";

import { useEffect, useMemo, useState } from "react";
import { cabDevWarn } from "@/src/lib/observability/dev-warn";
import { useAuth } from "@/context/auth-context";
import { usePermissionsSnapshotContext } from "@/context/permissions-snapshot-context";
import { useOperatorGlobalSettings } from "@/src/context/operator-global-settings-context";
import { useUserPageOverridesQuery, useRolePageAccessQuery } from "@/src/hooks/use-permissions";
import { publishClientEffectivePermissionsSnapshot } from "@/src/lib/runtime/truth-layer/client-effective-permissions-cache";
import { resolveEffectivePermissions } from "@/src/lib/runtime/truth-layer/resolve-effective-permissions";
import type { EffectivePermissionsSnapshot } from "@/src/lib/runtime/truth-layer/types";
import { resolveRole } from "@/lib/auth/rbac";
import { isRbacSnapshotReady } from "@/src/lib/rbac/rbac-snapshot-access";
import { publishStickyRbacSnapshot } from "@/src/lib/rbac/sticky-rbac-snapshot";

const EMPTY_SNAPSHOT: EffectivePermissionsSnapshot | null = null;

function permissionsQueriesSettled(
  roleAccessQuery: ReturnType<typeof useRolePageAccessQuery>,
  overridesQuery: ReturnType<typeof useUserPageOverridesQuery>,
): boolean {
  return roleAccessQuery.isFetched && overridesQuery.isFetched;
}

/** Fonte unica query permessi — montata da `PermissionsSnapshotMount` sotto gestionale. */
export function useEffectivePermissionsSource(): {
  snapshot: EffectivePermissionsSnapshot | null;
  isLoading: boolean;
} {
  const { user, status } = useAuth();
  const operatorPilot = useOperatorGlobalSettings();
  const overridesQuery = useUserPageOverridesQuery();
  const roleAccessQuery = useRolePageAccessQuery();
  const [stickyGood, setStickyGood] = useState<EffectivePermissionsSnapshot | null>(null);

  const permissionsHydrated =
    Boolean(user?.id) &&
    roleAccessQuery.isSuccess &&
    overridesQuery.isSuccess &&
    permissionsQueriesSettled(roleAccessQuery, overridesQuery);

  const isLoading = status === "loading" || (Boolean(user?.id) && !permissionsHydrated);

  const snapshot = useMemo(() => {
    if (!user?.id) return EMPTY_SNAPSHOT;

    const roleBundle = roleAccessQuery.data;
    const snap = resolveEffectivePermissions({
      userId: user.id,
      roleKey: roleBundle?.roleKey ?? user.roleKey ?? user.ruolo,
      rolePageAccess: roleBundle?.rolePageAccess ?? {},
      userPageOverrideRows: overridesQuery.data,
      pilotDbEnabled: operatorPilot.dbEnabled,
      permissionsHydrated,
    });

    if (snap.permissionsHydrated) {
      publishClientEffectivePermissionsSnapshot(snap);
      publishStickyRbacSnapshot(snap);
    } else if (resolveRole(snap.roleKey ?? snap.role) === "admin") {
      publishStickyRbacSnapshot(snap);
    }
    return snap;
  }, [
    user?.id,
    user?.roleKey,
    user?.ruolo,
    roleAccessQuery.data,
    overridesQuery.data,
    operatorPilot.dbEnabled,
    permissionsHydrated,
  ]);

  useEffect(() => {
    if (!snapshot) return;
    if (snapshot.permissionsHydrated || resolveRole(snapshot.roleKey ?? snapshot.role) === "admin") {
      setStickyGood(snapshot);
    }
  }, [snapshot]);

  const displaySnapshot =
    snapshot && isRbacSnapshotReady(snapshot) ? snapshot : stickyGood;

  useEffect(() => {
    if (displaySnapshot && isRbacSnapshotReady(displaySnapshot)) {
      publishClientEffectivePermissionsSnapshot(displaySnapshot);
    }
  }, [displaySnapshot]);

  useEffect(() => {
    if (!overridesQuery.isError || !overridesQuery.dataUpdatedAt) return;
    const ageMs = Date.now() - overridesQuery.dataUpdatedAt;
    if (ageMs < 5 * 60_000) return;
    cabDevWarn(
      "rbac.stale_snapshot",
      "Permessi utente in errore con cache stale oltre 5 minuti",
      { ageMs, userId: user?.id },
      { oncePerSession: true },
    );
  }, [overridesQuery.isError, overridesQuery.dataUpdatedAt, user?.id]);

  return { snapshot: displaySnapshot, isLoading };
}

/** Hook canonico permessi runtime — legge snapshot dal provider gestionale. */
export function useEffectivePermissions(): {
  snapshot: EffectivePermissionsSnapshot | null;
  isLoading: boolean;
} {
  const ctx = usePermissionsSnapshotContext();
  return ctx ?? { snapshot: null, isLoading: true };
}

"use client";

import { normMatricola, pickCanonicalAttrezzatura, matricolaRowsForNorm } from "@/lib/domain/mezzo-attrezzatura/attrezzatura-identity";
import { ATTREZZATURE_COLUMNS } from "@/lib/db/table-select-columns";
import { resolveAssetLifecycleV1EnabledClient } from "@/lib/officina/resolve-asset-lifecycle-v1-client";
import { isAssetLifecycleSubFlagActive } from "@/lib/officina/asset-lifecycle-v1-flag";
import { getBrowserSupabase } from "@/src/lib/supabase/browser-client";
import { auditContext, auditDiff, auditSnapshot, writeModificaLog } from "@/src/services/internal/audit-log";
import { err, success, type ServiceResult } from "@/src/services/service-result";
import type { AssignmentChangeReason, AttrezzaturaRow } from "@/src/types/supabase-tables";
import { humanizeGestionaleError } from "@/src/utils/gestionale-error-messages";
import { serviceFailFromError } from "@/src/utils/supabaseErrorHandler";

const ENTITA = "attrezzature";

export type AttrezzaturaInsert = Omit<AttrezzaturaRow, "id" | "created_at" | "updated_at" | "created_by"> & {
  created_by?: string | null;
};
export type AttrezzaturaUpdate = Partial<Omit<AttrezzaturaInsert, "mezzo_id">> & {
  mezzo_id?: string;
};

async function sb() {
  return getBrowserSupabase();
}

function oggettoAttrezzatura(r: AttrezzaturaRow) {
  const parts = [r.marca?.trim(), r.modello?.trim(), r.matricola?.trim()].filter(Boolean);
  return parts.length ? auditContext(parts.join(" ")) : undefined;
}

async function openAssignmentIfEnabled(
  client: Awaited<ReturnType<typeof sb>>,
  attrezzaturaId: string,
  mezzoId: string,
  reason: AssignmentChangeReason = "installazione",
): Promise<void> {
  const flags = resolveAssetLifecycleV1EnabledClient();
  if (!isAssetLifecycleSubFlagActive(flags, "assignment_history")) return;
  const { data: user } = await client.auth.getUser();
  await client.rpc("open_attrezzatura_assignment", {
    p_attrezzatura_id: attrezzaturaId,
    p_mezzo_id: mezzoId,
    p_change_reason: reason,
    p_actor_id: user.user?.id ?? null,
  });
}

export const attrezzatureService = {
  async listByMezzo(mezzoId: string): Promise<ServiceResult<AttrezzaturaRow[]>> {
    try {
      const client = await sb();
      const { data, error } = await client
        .from("attrezzature")
        .select(ATTREZZATURE_COLUMNS)
        .eq("mezzo_id", mezzoId)
        .order("created_at", { ascending: true });
      if (error) return err(humanizeGestionaleError(error.message, { entity: "mezzo", action: "read" }));
      return success((data ?? []) as AttrezzaturaRow[]);
    } catch (e) {
      return serviceFailFromError<AttrezzaturaRow[]>(e, [], { entity: "mezzo", action: "read" });
    }
  },

  async getById(id: string): Promise<ServiceResult<AttrezzaturaRow | null>> {
    try {
      const client = await sb();
      const { data, error } = await client
        .from("attrezzature")
        .select(ATTREZZATURE_COLUMNS)
        .eq("id", id)
        .maybeSingle();
      if (error) return err(humanizeGestionaleError(error.message, { entity: "mezzo", action: "read" }));
      return success((data as AttrezzaturaRow | null) ?? null);
    } catch (e) {
      return serviceFailFromError<AttrezzaturaRow | null>(e, null, { entity: "mezzo", action: "read" });
    }
  },

  async findByMatricola(mezzoId: string, matricola: string): Promise<ServiceResult<AttrezzaturaRow | null>> {
    const norm = normMatricola(matricola);
    if (!norm) return success(null);
    try {
      const listRes = await this.listByMezzo(mezzoId);
      if (!listRes.success) return err(listRes.error ?? "Errore lettura attrezzature.");
      const hits = matricolaRowsForNorm(listRes.data ?? [], mezzoId, norm);
      if (hits.length === 0) return success(null);
      return success(pickCanonicalAttrezzatura(hits));
    } catch (e) {
      return serviceFailFromError<AttrezzaturaRow | null>(e, null, { entity: "mezzo", action: "read" });
    }
  },

  async update(id: string, patch: AttrezzaturaUpdate): Promise<ServiceResult<AttrezzaturaRow>> {
    try {
      const client = await sb();
      const beforeRes = await this.getById(id);
      if (!beforeRes.success || !beforeRes.data) {
        return err(beforeRes.error ?? "Attrezzatura non trovata.");
      }
      const before = beforeRes.data;

      if (patch.mezzo_id != null && patch.mezzo_id !== before.mezzo_id) {
        const flags = resolveAssetLifecycleV1EnabledClient();
        if (isAssetLifecycleSubFlagActive(flags, "assignment_history")) {
          const { data: user } = await client.auth.getUser();
          const { data: row, error } = await client.rpc("reassign_attrezzatura_mezzo", {
            p_attrezzatura_id: id,
            p_new_mezzo_id: patch.mezzo_id,
            p_change_reason: "spostamento",
            p_actor_id: user.user?.id ?? null,
          });
          if (error) return err(humanizeGestionaleError(error.message, { entity: "mezzo", action: "update" }));
          const { ...rest } = patch;
          if (Object.keys(rest).length === 0) {
            const updated = row as AttrezzaturaRow;
            await writeModificaLog(client, {
              entita: ENTITA,
              entita_id: id,
              azione: "UPDATE",
              payload: auditDiff(before, updated, oggettoAttrezzatura(updated)),
            });
            return success(updated);
          }
          patch = rest;
        }
      }

      const { data: row, error } = await client
        .from("attrezzature")
        .update(patch)
        .eq("id", id)
        .select(ATTREZZATURE_COLUMNS)
        .single();
      if (error) return err(humanizeGestionaleError(error.message, { entity: "mezzo", action: "update" }));
      const r = row as AttrezzaturaRow;
      await writeModificaLog(client, {
        entita: ENTITA,
        entita_id: id,
        azione: "UPDATE",
        payload: auditDiff(before, r, oggettoAttrezzatura(r)),
      });
      return success(r);
    } catch (e) {
      return serviceFailFromError<AttrezzaturaRow>(e, null as never, { entity: "mezzo", action: "update" });
    }
  },

  async remove(id: string): Promise<ServiceResult<void>> {
    try {
      const client = await sb();
      const beforeRes = await this.getById(id);
      const before = beforeRes.data;
      const flags = resolveAssetLifecycleV1EnabledClient();
      if (before && isAssetLifecycleSubFlagActive(flags, "assignment_history")) {
        await client.rpc("close_attrezzatura_assignment", {
          p_attrezzatura_id: id,
          p_change_reason: "smontaggio",
        });
      }
      const { error } = await client.from("attrezzature").delete().eq("id", id);
      if (error) return err(humanizeGestionaleError(error.message, { entity: "mezzo", action: "delete" }));
      if (before) {
        await writeModificaLog(client, {
          entita: ENTITA,
          entita_id: id,
          azione: "DELETE",
          payload: auditSnapshot(before, oggettoAttrezzatura(before)),
        });
      }
      return success(undefined);
    } catch (e) {
      return serviceFailFromError<void>(e, undefined, { entity: "mezzo", action: "delete" });
    }
  },
};

