        !lavorazioneMatchesClienteScope(row, clienteRef, {
          failClosedForClienteRole: true,
          role,
        })
      ) {
        return err("Lavorazione non trovata.");
      }

      return success({ row });
    } catch (e) {
      return serviceFailFromError(e);
    }
  },
};

